-- 20180718  KHSONG  기존 @TEMP TABLE 에서 INDEX적용 테이블로 변경 (START)
	-- #results_MST TEMP TABLE
	-- GTT 변환: GT_DMF0020_RESULTS_MST (별도 DDL 파일 PKG_DMF0020_GTT_DDL.sql 참조)
