PROCEDURE           "DMF0070_AUTO_PR_REQUEST" 
/*************************************************************************************************
* Program ID  : DMF0070_AUTO_PR_REQUEST
* Description : Procedure 작성 가이드
* Usage       : PR Request 자동 생성
* Parameter   :
*
* Program History
*------------------------------------------------------------------------------------------------
* Date        In Charge    Description
*------------------------------------------------------------------------------------------------
* 2024-01-25   kjj         신규생성
--EXEC DMF0070_AUTO_PR_REQUEST
   2024.07.10   P.C.I      NERP 대응 - PR Reqeust를 Interface Table 에 생성하는 프로시저 호출
* 2026-08-03   ZIONEX   [PJ202650304]  NextSCM Migration
***************************************************************************************************/
AS
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME                VARCHAR2(150 CHAR) := 'DMF0070_AUTO_PR_REQUEST';
    V_LOG_TYPE                    VARCHAR2(30 CHAR);          /* START/END/ERROR/... */
    N_LOG_COUNT                   NUMBER(10) := 0;
    V_LOG_MESSAGE                 VARCHAR2(1000 CHAR);
    V_LOG_DESCRIPTION             VARCHAR2(500 CHAR);
    D_EVENT_DATE                  DATE;
    N_DELETE_COUNT                NUMBER(10) := 0;
    N_INSERT_COUNT                NUMBER(10) := 0;
    N_INPUT_COUNT                 NUMBER(10) := 0;
    N_LOGO_COUNT                  NUMBER(10) := 0;
    N_INVALID_ITEM                VARCHAR2(50 CHAR);
    N_MSG                         VARCHAR2(1000 CHAR);
    V_BF_REQ_NO                   VARCHAR2(30 CHAR);
    V_BF_QTY                      NUMBER(10) := 0;
    V_THIS_QTY                    NUMBER(10) := 0;


    V_SUB_QRY                     CLOB;
    V_CUR_DIVISION                VARCHAR2(100 CHAR);
    V_CUR_INCOTERMS               VARCHAR2(100 CHAR);
    V_CUR_COUNTRY                 VARCHAR2(100 CHAR);
    V_CUR_BNP_WEEK                VARCHAR2(100 CHAR);         /* BNP IN 출하시점 */
    V_CUR_DATA_WEEK               VARCHAR2(150 CHAR);         /* DATA 생성 시점(대상추출 메일발송은 DATA 생성시점의 1주 전) */
    V_CUR_NOT_COND                VARCHAR2(1000 CHAR);        /* NOT 조건으로 지정된 건 */

    /* PR Request 채번 변수 */
    V_REQUEST_NO                  VARCHAR2(30 CHAR);
    V_MAX_NO                      VARCHAR2(30 CHAR);
    V_SUM_QTY                     NUMBER(10);
    V_MAX_SEQ                     NUMBER(10);
    V_SEQ                         NUMBER(10);

    /* 프로젝트 별 / 아이템ID별로 REQUEST_NO가 따로 채번되어야 함 */
    V_CURSSP_DIVISION_ID          VARCHAR2(500 CHAR);
    V_CURSSP_PROJECT_CODE         VARCHAR2(500 CHAR);
    V_CURSSP_SCM_SITE_ID          VARCHAR2(500 CHAR);
    V_CURSSP_ITEM_ID              VARCHAR2(500 CHAR);
    V_CURSSP_DOM_EXP              VARCHAR2(500 CHAR);
    V_CURSSP_FCST_TYPE            VARCHAR2(500 CHAR);
    V_CURSSP_INCOTERMS            VARCHAR2(500 CHAR);
    V_CURSSP_PLANT_SITE_ID        VARCHAR2(500 CHAR);
    V_CURSSP_BNP_YYYYMMDD         VARCHAR2(500 CHAR);         /* BNP IN YYYYMMDD */
    V_CURSSP_UOM                  VARCHAR2(500 CHAR);
    V_CURSSP_QTY                  NUMBER(30, 10);
    V_CURSSP_STORAGE_ID           VARCHAR2(500 CHAR);
    V_CURSSP_STORAGE_PLANT_ID     VARCHAR2(500 CHAR);
    V_CURSSP_PUCH_MGR             VARCHAR2(500 CHAR);
    V_CURSSP_PUCH_GROUP           VARCHAR2(500 CHAR);
    V_CURSSP_PR_HEADER            VARCHAR2(4000 CHAR);
    V_CURSSP_ITEM_DETAIL          VARCHAR2(4000 CHAR);        /* 원본 NVARCHAR(MAX), 실공급원 GTT ITEM_DETAIL 은 100 CHAR */

    /* MKT FCST 테이블 접근을 위한 변수 */
    V_DIVISION_ID                 VARCHAR2(30 CHAR);
    V_PROJECT_CODE                VARCHAR2(50 CHAR);
    V_SCM_SITE_ID                 VARCHAR2(30 CHAR);
    V_ITEM_ID                     VARCHAR2(50 CHAR);
    V_DOM_EXP                     VARCHAR2(3 CHAR);
    V_FCST_TYPE                   VARCHAR2(20 CHAR);
    V_INCOTERMS                   VARCHAR2(10 CHAR);
    V_MEASURE                     VARCHAR2(50 CHAR);
    V_YYYYMMDD                    VARCHAR2(8 CHAR);
    V_PLANT_SITE_ID               VARCHAR2(30 CHAR);
    V2_REQUEST_NO                 VARCHAR2(30 CHAR);

    V_MSG                         VARCHAR2(1000 CHAR);


    V_TABLE_BODY                  CLOB;
    V_BODY_CONTENTS               CLOB;
    V_HEAD_CONT                   CLOB;
    V_BODY_CONT                   CLOB;
    V_MAIL_TITLE                  VARCHAR2(100 CHAR);
    V_CNT                         NUMBER(10);
    V_I                           NUMBER(10);
    /* [사용자 결정 2026-08-03] 원본 NVARCHAR(150). MSSQL 은 151자에서 무음 절단이나 Oracle 은 ORA-06502 로
       상한 4000 = 하위 SCM_ADM_MAIL_SEND 내부 V_TO_MAIL VARCHAR2(4000 CHAR) 와 정합. */
    V_TO_MAIL                     VARCHAR2(4000 CHAR);

    V_ITEM_SEQ                    NUMBER(10);
    V_ITEM_NAME                   VARCHAR2(50 CHAR);
    V_UOM                         VARCHAR2(8 CHAR);
    V_PLAN_QTY                    NUMBER(30, 10);
    V_CREATED_BY                  VARCHAR2(150 CHAR);
    V_LAST_UPDATE_DATE            DATE;
    V_CURSOR_YYYYMMDD             VARCHAR2(10 CHAR);

    /* 변환 도입 변수 (MSSQL IF (SELECT COUNT(*) ...) 를 PL/SQL 로 옮기기 위한 수신 변수) */
    N_TMP_CNT                     NUMBER(10);
    V_IN_PARA_DATA                VARCHAR2(4000 CHAR);

BEGIN
/*

--대상추출 과 분리하여 PR_REQUEST만 생성


--전주 화요일에 추출된 것들 대상
--	-1:일요일, 0:월요일, 1:화요일, 2:수요일, 3:목요일, 4:금요일, 5:토요일
SELECT DATEADD(WK, DATEDIFF(WK,0, DATEADD(WEEK,-1,GETDATE())), 1)


--메인테이블 변경
DM_PLN_BNP_IN_PR_DETAIL_AUTO
=>DM_PLN_AUTO_PR_CHECK


--채번규칙 변경
프로젝트 별
=>프로젝트별 / 아이템별


--실제 반영시 주석해제해야할것
1.'전주 화요일에 발송된 것들만 대상'
2.데이터 가져올때 week+1 한 부분에서 +1 삭제


*/


    /* 시작 LOG  (START) */
    V_LOG_TYPE        := 'START';
    V_LOG_MESSAGE     := '########## Start of procedure @@@##########';
    V_LOG_DESCRIPTION := '';
    D_EVENT_DATE      := SYSDATE;
    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_BATCH');
    V_LOG_MESSAGE := NULL;      /* 변수 재사용을 위하여 초기화해야함 */


    /* -------------------------------------------------------------------------------------------- */
    BEGIN
    /* -------------------------------------------------------------------------------------------- */
            /* 메일발송 주기(케이스 별) */
            /*
            *1차
        (A) Incoterms= EXW => D-91(13주)
        (B) Incoterms = C* or F*, Country=KR => D-119(17주)
        (C) Incoterms = D*, Country=JP => D-119(17주)
        (D) Incoterms = D*, Country = not KR => D-175(25주)


            *2차
        (A) Incoterms= EXW => D-20 (3주 전)
        (B) Incoterms = C* or F*, Country=KR => D-48 (7주 전)
        (C) Incoterms = D*, Country=JP => D-48 (7주 전)
        (D) Incoterms = D*, Country = not KR => D-104 (15주 전)
            */
        V_SUB_QRY := '';

        /* ---------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### BNP IN 대상 가져오기');
        /* ---------------------------------------------------------------------------------------- */
        /* 원본 : IF OBJECT_ID('TEMPDB..#TMP_BNP_TARGET_LIST') IS NOT NULL DROP TABLE + CREATE TABLE #TMP_BNP_TARGET_LIST */
        DELETE
          FROM GT_DMF70PR_BNP_TARGET_LIST;

        V_SUB_QRY := '';

        FOR CUR_GUIDE_LIST IN ( SELECT SEGMENT1
                                     , SEGMENT2
                                     , SEGMENT3
                                     , SEGMENT4
                                     , SEGMENT5
                                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                 WHERE LOOKUP_TYPE = 'AUTO_PR_CHECK_CRITERIA'
                                   AND VALID_YN = 'Y'
                                 ORDER BY DISPLAY_SEQ ) LOOP

            V_CUR_DIVISION  := CUR_GUIDE_LIST.SEGMENT1;
            V_CUR_INCOTERMS := CUR_GUIDE_LIST.SEGMENT2;
            V_CUR_COUNTRY   := CUR_GUIDE_LIST.SEGMENT3;
            V_CUR_BNP_WEEK  := CUR_GUIDE_LIST.SEGMENT4;
            V_CUR_DATA_WEEK := CUR_GUIDE_LIST.SEGMENT5;

            IF V_SUB_QRY IS NOT NULL THEN
                V_SUB_QRY := V_SUB_QRY||'
                UNION
                ';
            END IF;

            V_SUB_QRY := V_SUB_QRY||'
                SELECT A.DIVISION_ID
                     , A.PROJECT_CODE
                     , A.SCM_SITE_ID
                     , A.ITEM_ID
                     , A.DOM_EXP
                     , A.FCST_TYPE
                     , A.INCOTERMS
                     , ''BNPIn'' AS MEASURE
                     , A.PLANT_SITE_ID
                     , A.YYYYMMDD
                     , A.QTY
                     , TO_CHAR(TO_DATE(A.YYYYMMDD, ''YYYYMMDD'') - 7 * ('||V_CUR_BNP_WEEK||'), ''YYYYMMDD'') AS BNP_YYYYMMDD
                     , (SELECT SEGMENT1
                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                         WHERE LOOKUP_TYPE = ''DM_PR_PUCH''
                           AND ROWNUM = 1) AS PUCH_MGR
                     , (SELECT SEGMENT2
                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                         WHERE LOOKUP_TYPE = ''DM_PR_PUCH''
                           AND ROWNUM = 1) AS PUCH_GROUP
                     , CASE WHEN (SELECT PROJECT_NAME
                                    FROM SCM_MST_PROJECT
                                   WHERE DIVISION_ID = A.DIVISION_ID
                                     AND PROJECT_CODE = A.PROJECT_CODE
                                     AND ROWNUM = 1) IS NULL
                            THEN NULL
                            ELSE '' ( ''||A.PROJECT_CODE||'' ) ''
                                 ||(SELECT PROJECT_NAME
                                      FROM SCM_MST_PROJECT
                                     WHERE DIVISION_ID = A.DIVISION_ID
                                       AND PROJECT_CODE = A.PROJECT_CODE
                                       AND ROWNUM = 1)
                                 ||B.SEGMENT2
                       END AS PR_HEADER  /* (Project Code) + Project + ''물량''(룩업관리) */
                    /* ,B.SEGMENT4 STORAGE_ID -- SLOC(룩업관리) */
                    /* , B.SEGMENT3 STORAGE_PLANT_ID--(룩업관리) => 별도 쿼리 해오다가 룩업관리로 변경함 */
                    /* , B.SEGMENT5 ITEM_DETAIL--(룩업관리) */
                     , D.STORAGE_ID
                     , D.STORAGE_PLANT_ID
                     , D.PR_ITEM_DETAIL AS ITEM_DETAIL
                     , (SELECT ITEM_UOM
                          FROM DM_MST_ITEM_SINGLE_V
                         WHERE DIVISION_ID = A.DIVISION_ID
                           AND ITEM_ID = A.ITEM_ID) AS UOM
                  FROM DM_PLN_MKT_FCST              A
                     , SCM_ADM_LOOKUP_MASTER_DETAIL B
                     , SCM_MST_SITE                 C
                     , DM_PLN_AUTO_PR_CHECK         D
                 WHERE B.SEGMENT1 = A.DIVISION_ID
                   AND C.DIVISION_ID = A.DIVISION_ID
                   AND C.SCM_SITE_ID = A.SCM_SITE_ID
                   AND D.DIVISION_ID = A.DIVISION_ID
                   AND D.PROJECT_CODE = A.PROJECT_CODE
                   AND D.SCM_SITE_ID = A.SCM_SITE_ID
                   AND D.ITEM_ID = A.ITEM_ID
                   AND D.DOM_EXP = A.DOM_EXP
                   AND D.INCOTERMS = A.INCOTERMS
                   AND D.PLANT_SITE_ID = A.PLANT_SITE_ID
                   AND D.MKT_FCST_DATE = A.YYYYMMDD
                   AND B.LOOKUP_TYPE = ''AUTO_PR_CHECK_TEXT''
                   AND B.VALID_YN = ''Y''
                   AND D.AUTO_FLAG = ''Y''
                   AND RTRIM(D.BNP_IN_DATE) IS NULL  /* BNP IN 데이터 생성 안된것만 */
                   AND D.MAIL_INFO_DATE = TO_CHAR(TRUNC(SYSDATE - 6, ''IW'') + 1, ''YYYYMMDD'')  /* 전주 화요일에 발송된 것들만 대상 */
                   AND RTRIM(D.STORAGE_PLANT_ID) IS NOT NULL  /* Plant Site 가 입력된 것들만 */
                   AND RTRIM(D.STORAGE_ID) IS NOT NULL  /* SLOC 가 입력된 것들만 */
                   AND A.MEASURE = ''MKT_FCST''
                   AND RTRIM(A.ATTRIBUTE9) IS NULL  /* 확정되지 않은 것들 */
                   AND ( ( A.YYYYMMDD >= (SELECT BASIS_START_DATE
                                            FROM SCM_SYS_CALENDAR_M
                                           WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + 7 * ('||V_CUR_DATA_WEEK||'), ''YYYYMMDD''))
                       AND A.YYYYMMDD <= (SELECT BASIS_END_DATE
                                            FROM SCM_SYS_CALENDAR_M
                                           WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + 7 * ('||V_CUR_DATA_WEEK||'), ''YYYYMMDD'')) )
                        OR ( A.YYYYMMDD >= (SELECT BASIS_START_DATE
                                             FROM SCM_SYS_CALENDAR_M
                                            WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + 7 * ('||TO_CHAR(TO_NUMBER(V_CUR_DATA_WEEK) - 10)||'), ''YYYYMMDD''))  /* 2차처리는 1차의 10주 뒤 */
                       AND A.YYYYMMDD <= (SELECT BASIS_END_DATE
                                            FROM SCM_SYS_CALENDAR_M
                                           WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + 7 * ('||V_CUR_DATA_WEEK||'), ''YYYYMMDD'')) ) )  /* To는 1차발송일과 동일 */
                ';

                /* INCOTERMS */
                IF V_CUR_INCOTERMS <> '-' THEN
                    IF INSTR(V_CUR_INCOTERMS, '*') > 0 THEN
                        V_SUB_QRY := V_SUB_QRY||'
                   AND A.INCOTERMS LIKE '''||REPLACE(V_CUR_INCOTERMS, '*', '%')||'''
                ';
                    ELSIF INSTR(UPPER(V_CUR_INCOTERMS), 'NOT_') > 0 THEN
                    /*
                    --Not 의 규칙
                    1)Not_로 등록
                    2)여러개일 경우는 ,로 구분
                    */
                        FOR CUR_NOT_COND IN ( SELECT TOKEN
                                                FROM TABLE(UF_FX_STRING_SPLIT(V_CUR_INCOTERMS, ',')) ) LOOP

                            V_CUR_NOT_COND := CUR_NOT_COND.TOKEN;

                            V_SUB_QRY := V_SUB_QRY||'
                   AND A.INCOTERMS <> '''||REGEXP_REPLACE(V_CUR_NOT_COND, 'NOT_', '', 1, 0, 'i')||'''
                ';

                        END LOOP;

                    ELSE
                        V_SUB_QRY := V_SUB_QRY||'
                   AND A.INCOTERMS = '''||V_CUR_INCOTERMS||'''
                ';
                    END IF;
                END IF;

                /* COUNTRY */
                IF V_CUR_COUNTRY <> '-' THEN
                    IF INSTR(V_CUR_COUNTRY, '*') > 0 THEN
                        V_SUB_QRY := V_SUB_QRY||'
                   AND C.COUNTRY LIKE '''||REPLACE(V_CUR_COUNTRY, '*', '%')||'''
                ';
                    ELSIF INSTR(UPPER(V_CUR_COUNTRY), 'NOT_') > 0 THEN

                    /*
                        SET @V_SUB_QRY = @V_SUB_QRY + N'
                            AND MS.COUNTRY <> ''' + REPLACE(@CUR_COUNTRY,'NOT ', '') + '''
                        '
                        */
                        /*
                        --Not 의 규칙
                        1)Not_로 등록
                        2)여러개일 경우는 ,로 구분
                        */
                        FOR CUR_NOT_COND IN ( SELECT TOKEN
                                                FROM TABLE(UF_FX_STRING_SPLIT(V_CUR_COUNTRY, ',')) ) LOOP

                            V_CUR_NOT_COND := CUR_NOT_COND.TOKEN;

                            V_SUB_QRY := V_SUB_QRY||'
                   AND C.COUNTRY <> '''||REGEXP_REPLACE(V_CUR_NOT_COND, 'NOT_', '', 1, 0, 'i')||'''
                ';

                        END LOOP;
                    ELSE
                        V_SUB_QRY := V_SUB_QRY||'
                   AND C.COUNTRY = '''||V_CUR_COUNTRY||'''
                ';
                    END IF;
                END IF;

        END LOOP;

        /* PRINT @V_SUB_QRY */
        /* [사용자 결정 2026-08-03] 유효 criteria 가 0건이면 V_SUB_QRY 가 NULL 이라 컬럼목록만 남은 */
        IF V_SUB_QRY IS NOT NULL THEN
        EXECUTE IMMEDIATE 'INSERT
  INTO GT_DMF70PR_BNP_TARGET_LIST
     ( DIVISION_ID
     , PROJECT_CODE
     , SCM_SITE_ID
     , ITEM_ID
     , DOM_EXP
     , FCST_TYPE
     , INCOTERMS
     , MEASURE
     , PLANT_SITE_ID
     , YYYYMMDD
     , QTY
     , BNP_YYYYMMDD
     , PUCH_MGR
     , PUCH_GROUP
     , PR_HEADER
     , STORAGE_ID
     , STORAGE_PLANT_ID
     , ITEM_DETAIL
     , UOM )
'||V_SUB_QRY;
        END IF;

        /* select * from #TMP_BNP_TARGET_LIST */

        /* ---------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### BNP IN 데이터 생성');
        /* ---------------------------------------------------------------------------------------- */

        /* 머지구문으로 변경
           기존에 있던 승인나지 않은 데이터 수량 업데이트 */
        MERGE INTO DM_PLN_MKT_FCST A
        USING GT_DMF70PR_BNP_TARGET_LIST B
           ON ( A.DIVISION_ID = B.DIVISION_ID
            AND A.PROJECT_CODE = B.PROJECT_CODE
            AND A.SCM_SITE_ID = B.SCM_SITE_ID
            AND A.ITEM_ID = B.ITEM_ID
            AND A.DOM_EXP = B.DOM_EXP
            AND A.FCST_TYPE = B.FCST_TYPE
            AND A.INCOTERMS = B.INCOTERMS
            AND A.MEASURE = B.MEASURE
            AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
            AND A.YYYYMMDD = B.BNP_YYYYMMDD          /* 룩업에 등록된BNPIN WEEK */
            AND RTRIM(A.ATTRIBUTE9) IS NULL )        /* 승인나지 않은 것 */
        WHEN MATCHED THEN
            UPDATE
               SET A.QTY = B.QTY
                 , A.LAST_UPDATED_BY = 'SCM_BATCH'
                 , A.LAST_UPDATE_DATE = SYSDATE
        WHEN NOT MATCHED THEN
            INSERT ( DIVISION_ID
                   , PROJECT_CODE
                   , SCM_SITE_ID
                   , ITEM_ID
                   , DOM_EXP
                   , FCST_TYPE
                   , INCOTERMS
                   , MEASURE
                   , PLANT_SITE_ID
                   , YYYYMMDD
                   , QTY
                   , CREATED_BY
                   , CREATION_DATE
                   , LAST_UPDATED_BY
                   , LAST_UPDATE_DATE )
            VALUES ( B.DIVISION_ID
                   , B.PROJECT_CODE
                   , B.SCM_SITE_ID
                   , B.ITEM_ID
                   , B.DOM_EXP
                   , B.FCST_TYPE
                   , B.INCOTERMS
                   , B.MEASURE
                   , B.PLANT_SITE_ID
                   , B.BNP_YYYYMMDD                  /* 룩업에 등록된BNPIN WEEK */
                   , B.QTY
                   , 'SCM_BATCH'
                   , SYSDATE
                   , 'SCM_BATCH'
                   , SYSDATE );

        /* ---------------------------------------------------------------------------------------- */
        DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### BNP IN YYYYMMDD를 메일발송 테이블의 BNP_IN_DATE에 저장');   /* 추후 BNP IN 생성여부 판단 수월하게 하기 위함 */
        /* ---------------------------------------------------------------------------------------- */

        /* 원본 UPDATE ATO SET ... FROM DM_PLN_AUTO_PR_CHECK ATO INNER JOIN #TMP_BNP_TARGET_LIST T_LIST ON ...
              상관 UPDATE + EXISTS(ROWNUM = 1) 로 옮긴다. */
        UPDATE DM_PLN_AUTO_PR_CHECK A
           SET A.BNP_IN_DATE = (SELECT B.BNP_YYYYMMDD
                                  FROM GT_DMF70PR_BNP_TARGET_LIST B
                                 WHERE A.DIVISION_ID = B.DIVISION_ID
                                   AND A.PROJECT_CODE = B.PROJECT_CODE
                                   AND A.SCM_SITE_ID = B.SCM_SITE_ID
                                   AND A.ITEM_ID = B.ITEM_ID
                                   AND A.DOM_EXP = B.DOM_EXP
                                   AND A.FCST_TYPE = B.FCST_TYPE
                                   AND A.INCOTERMS = B.INCOTERMS
                                   AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
                                   AND A.MKT_FCST_DATE = B.YYYYMMDD
                                   AND ROWNUM = 1)
         WHERE EXISTS (SELECT 1
                         FROM GT_DMF70PR_BNP_TARGET_LIST B
                        WHERE A.DIVISION_ID = B.DIVISION_ID
                          AND A.PROJECT_CODE = B.PROJECT_CODE
                          AND A.SCM_SITE_ID = B.SCM_SITE_ID
                          AND A.ITEM_ID = B.ITEM_ID
                          AND A.DOM_EXP = B.DOM_EXP
                          AND A.FCST_TYPE = B.FCST_TYPE
                          AND A.INCOTERMS = B.INCOTERMS
                          AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
                          AND A.MKT_FCST_DATE = B.YYYYMMDD);

        SELECT COUNT(*)
          INTO N_TMP_CNT
          FROM GT_DMF70PR_BNP_TARGET_LIST;

        IF N_TMP_CNT > 0 THEN

            /* ------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### PR Request 데이터 생성');
            /* ------------------------------------------------------------------------------------ */

            FOR CUR_BNP_PJT_LIST IN ( SELECT DIVISION_ID
                                           , PROJECT_CODE
                                           , SCM_SITE_ID
                                           , ITEM_ID
                                           , DOM_EXP
                                           , FCST_TYPE
                                           , INCOTERMS
                                           , PLANT_SITE_ID
                                           , BNP_YYYYMMDD          /* BNP IN YYYYMMDD */
                                           , UOM
                                           , QTY
                                           , STORAGE_ID
                                           , STORAGE_PLANT_ID
                                           , PUCH_MGR
                                           , PUCH_GROUP
                                           , PR_HEADER
                                           , ITEM_DETAIL
                                        FROM GT_DMF70PR_BNP_TARGET_LIST ) LOOP   /* 프로젝트 코드 */

                V_CURSSP_DIVISION_ID      := CUR_BNP_PJT_LIST.DIVISION_ID;
                V_CURSSP_PROJECT_CODE     := CUR_BNP_PJT_LIST.PROJECT_CODE;
                V_CURSSP_SCM_SITE_ID      := CUR_BNP_PJT_LIST.SCM_SITE_ID;
                V_CURSSP_ITEM_ID          := CUR_BNP_PJT_LIST.ITEM_ID;
                V_CURSSP_DOM_EXP          := CUR_BNP_PJT_LIST.DOM_EXP;
                V_CURSSP_FCST_TYPE        := CUR_BNP_PJT_LIST.FCST_TYPE;
                V_CURSSP_INCOTERMS        := CUR_BNP_PJT_LIST.INCOTERMS;
                V_CURSSP_PLANT_SITE_ID    := CUR_BNP_PJT_LIST.PLANT_SITE_ID;
                V_CURSSP_BNP_YYYYMMDD     := CUR_BNP_PJT_LIST.BNP_YYYYMMDD;      /* BNP IN YYYYMMDD */
                V_CURSSP_UOM              := CUR_BNP_PJT_LIST.UOM;
                V_CURSSP_QTY              := CUR_BNP_PJT_LIST.QTY;
                V_CURSSP_STORAGE_ID       := CUR_BNP_PJT_LIST.STORAGE_ID;
                V_CURSSP_STORAGE_PLANT_ID := CUR_BNP_PJT_LIST.STORAGE_PLANT_ID;
                V_CURSSP_PUCH_MGR         := CUR_BNP_PJT_LIST.PUCH_MGR;
                V_CURSSP_PUCH_GROUP       := CUR_BNP_PJT_LIST.PUCH_GROUP;
                V_CURSSP_PR_HEADER        := CUR_BNP_PJT_LIST.PR_HEADER;
                V_CURSSP_ITEM_DETAIL      := CUR_BNP_PJT_LIST.ITEM_DETAIL;

                /*
                V_REQUEST_NO 채번
                */
                SELECT MAX(REQUEST_NO)
                  INTO V_MAX_NO
                  FROM DM_PLN_PR_DETAIL
                 WHERE REQUEST_NO LIKE TO_CHAR(SYSDATE, 'YYYYMMDD')||'%'
                   AND PROJECT_CODE = V_CURSSP_PROJECT_CODE
                   AND ITEM_ID = V_CURSSP_ITEM_ID;

                IF V_MAX_NO IS NOT NULL THEN

                    /* 기존의 MAX 값 + 1 */
                    SELECT MAX(REQUEST_NO)
                      INTO V_MAX_NO
                      FROM DM_PLN_PR_DETAIL
                     WHERE REQUEST_NO LIKE TO_CHAR(SYSDATE, 'YYYYMMDD')||'%';

                    V_REQUEST_NO := TO_CHAR(SYSDATE, 'YYYYMMDD')||FN_ZERO_LPAD(TO_CHAR(TO_NUMBER(SUBSTR(V_MAX_NO, -6)) + 1), 6);
                ELSE
                    /* SET @V_REQUEST_NO = CONVERT(CHAR(8), GETDATE(), 112) + '000001' */

                    /* 없을 경우에는 기존의 MAX 값 + 1 */
                    SELECT MAX(REQUEST_NO)
                      INTO V_MAX_NO
                      FROM DM_PLN_PR_DETAIL
                     WHERE REQUEST_NO LIKE TO_CHAR(SYSDATE, 'YYYYMMDD')||'%';

                    IF V_MAX_NO IS NOT NULL THEN
                        V_REQUEST_NO := TO_CHAR(SYSDATE, 'YYYYMMDD')||FN_ZERO_LPAD(TO_CHAR(TO_NUMBER(SUBSTR(V_MAX_NO, -6)) + 1), 6);
                    ELSE
                        V_REQUEST_NO := TO_CHAR(SYSDATE, 'YYYYMMDD')||'000001';
                    END IF;

                END IF;

                /* ---------------------------------------------------------------- */

                /*
                ITEM_SEQ 채번
                */
                SELECT MAX(ITEM_SEQ)
                  INTO V_MAX_SEQ
                  FROM DM_PLN_PR_DETAIL
                 WHERE REQUEST_NO = V_REQUEST_NO;

                IF V_MAX_SEQ IS NOT NULL THEN
                    V_SEQ := V_SEQ + 1;
                ELSE
                    V_SEQ := 1;
                END IF;

                /* PR_ITEM_DETAIL 값이 없으면 PR 자동화 요청물량 입력 */
                IF ( RTRIM(V_CURSSP_ITEM_DETAIL) IS NULL ) THEN
                    V_CURSSP_ITEM_DETAIL := 'PR 자동화 요청물량';
                END IF;

                INSERT
                  INTO DM_PLN_PR_DETAIL
                     ( REQUEST_NO
                     , ITEM_SEQ
                     , DIVISION_ID
                     , PROJECT_CODE
                     , SCM_SITE_ID
                     , ITEM_ID
                     , DOM_EXP
                     , FCST_TYPE
                     , INCOTERMS
                     , PLANT_SITE_ID
                     , YYYYMMDD
                     , UOM
                     , PLAN_QTY
                     , STORAGE_ID
                     , STORAGE_PLANT_ID
                     , PUCH_MGR
                     , PUCH_GROUP
                     , PR_HEADER
                     , PR_ITEM_DETAIL
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE
                     , SSP_TRANSFER_FLAG
                     , ATTRIBUTE1 )
                VALUES ( V_REQUEST_NO
                       , V_SEQ                        /* row_number() OVER( ORDER BY PROJECT_CODE,SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE,INCOTERMS,YYYYMMDD ) */
                       , V_CURSSP_DIVISION_ID
                       , V_CURSSP_PROJECT_CODE
                       , V_CURSSP_SCM_SITE_ID
                       , V_CURSSP_ITEM_ID
                       , V_CURSSP_DOM_EXP
                       , V_CURSSP_FCST_TYPE
                       , V_CURSSP_INCOTERMS
                       , V_CURSSP_PLANT_SITE_ID
                       , V_CURSSP_BNP_YYYYMMDD        /* BNP IN YYYYMMDD */
                       , V_CURSSP_UOM
                       , V_CURSSP_QTY
                       , V_CURSSP_STORAGE_ID
                       , V_CURSSP_STORAGE_PLANT_ID
                       , V_CURSSP_PUCH_MGR
                       , V_CURSSP_PUCH_GROUP
                       , V_CURSSP_PR_HEADER
                       , V_CURSSP_ITEM_DETAIL
                       , 'SCM_BATCH'
                       , SYSDATE
                       , 'SCM_BATCH'
                       , SYSDATE
                       , 'N'
                       , 'SCM_BATCH' );

                /* -------------------------------------------------------------------------------- */
                DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### ESS 프로시저 호출');
                /* -------------------------------------------------------------------------------- */

                /*
                SELECT TOP 1 @V_DIVISION_ID	= DIVISION_ID
                    , @V_PROJECT_CODE	= PROJECT_CODE
                    , @V_SCM_SITE_ID	= SCM_SITE_ID
                    , @V_ITEM_ID		= ITEM_ID
                    , @V_DOM_EXP		= DOM_EXP
                    , @V_FCST_TYPE		= FCST_TYPE
                    , @V_INCOTERMS		= INCOTERMS
                    , @V_MEASURE		= 'BNPIn'
                    , @V_YYYYMMDD		= BNP_YYYYMMDD	--BNP IN YYYYMMDD
                    , @V_PLANT_SITE_ID	= PLANT_SITE_ID
                FROM #TMP_BNP_TARGET_LIST
                WHERE PROJECT_CODE = @V_CUR_PROJECT_CODE
                */
                /* ESS 프로시저 호출
                   트랜잭션 문제가 해결이 안된 관계로 여기서 처리하고, 문제 발생시 DM_PLN_PR_DETAIL 삭제 및 DM_PLN_MKT_FCST UPDATE 한다. */

                /* select @V_REQUEST_NO,@V_CURSSP_DIVISION_ID */

                /* 임시로 */
                PR_SSP_ANL_ESS_REQ(V_REQUEST_NO, V_CURSSP_DIVISION_ID, V_MSG);

                /* NERP 대응 - PR Reqeust를 Interface Table 에 생성하는 프로시저 호출 */
                PR_DM_XIF_ERP_PR_DETAIL_S(P_REQUEST_NO => V_REQUEST_NO);

            END LOOP;

            /* ------------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3')||' ### PR Request 메일발송');
            /* ------------------------------------------------------------------------------------ */

            V_TABLE_BODY    := '';
            V_BODY_CONTENTS := '';
            V_HEAD_CONT     := '';
            V_BODY_CONT     := '';
            V_MAIL_TITLE    := '';

            V_TO_MAIL := '';

            /* DECLARE @T_MAIL_ADDR TABLE ( ADDR NVARCHAR(150), SEQ INT IDENTITY(0,1) ) */
            DELETE
              FROM GT_DMF70PR_MAIL_ADDR;

            INSERT
              INTO GT_DMF70PR_MAIL_ADDR
                 ( ADDR
                 , SEQ )
            SELECT A.SEGMENT1
                 , ROW_NUMBER() OVER (ORDER BY A.SEGMENT1) - 1 AS SEQ
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
             WHERE A.LOOKUP_TYPE = 'DM_PR_MAIL_ADDR'
               AND A.VALID_YN = 'Y';

            SELECT COUNT(*)
              INTO V_CNT
              FROM GT_DMF70PR_MAIL_ADDR;

            V_I       := 0;
            V_TO_MAIL := '';

            WHILE ( V_I < V_CNT ) LOOP

                /* 원본 : @V_TO_MAIL + ADDR + ';'  (+ CASE WHEN @V_I <> 0 THEN ';' ELSE '' END + ADDR 는 원본에서 주석) */
                SELECT V_TO_MAIL||ADDR||';'
                  INTO V_TO_MAIL
                  FROM GT_DMF70PR_MAIL_ADDR
                 WHERE SEQ = V_I;

                V_I := V_I + 1;
            END LOOP;

            /* ----------------------------- */
            /* SET @v_mail_title = N'[GSCM] PR Requested' */
            V_MAIL_TITLE := '[SCM] PR Requested';     /* [E20230721-001841] 용어 수정  GSCM->SCM */
            V_BODY_CONTENTS := '하기와 같이 PR Request 가 접수 되었습니다. 기 확보된 재고 Allo 후 PR 생성 바랍니다.';
            V_BODY_CONT := '';
            V_HEAD_CONT := '<TR>
                <TH>Request No</TH>
                <TH>Div</TH>
                <TH>Project Code</TH>
                <TH>Seq.</TH>
                <TH>Model</TH>
                <TH>Model Name</TH>
                <TH>UOM</TH>
                <TH>To Site</TH>
                <TH>Request Date</TH>
                <TH>Request Qty</TH>
                <TH>Requestor</TH>
                <TH>Update date</TH>
                </TR>';

            FOR CUR_SEND IN ( SELECT A.REQUEST_NO
                                   , A.DIVISION_ID
                                   , A.PROJECT_CODE
                                   , A.ITEM_SEQ
                                   , A.ITEM_ID
                                   , B.ITEM_NAME
                                   , A.UOM
                                   , A.SCM_SITE_ID
                                   , A.YYYYMMDD
                                   , A.PLAN_QTY
                                   , A.CREATED_BY
                                   , A.LAST_UPDATE_DATE
                                FROM DM_PLN_PR_DETAIL            A
                                   , DM_MST_ITEM_SINGLE_V        B
                                   , GT_DMF70PR_BNP_TARGET_LIST  C
                               WHERE A.DIVISION_ID = B.DIVISION_ID(+)
                                 AND A.ITEM_ID = B.ITEM_ID(+)
                                 AND A.DIVISION_ID = C.DIVISION_ID
                                 AND A.PROJECT_CODE = C.PROJECT_CODE
                                 AND A.SCM_SITE_ID = C.SCM_SITE_ID
                                 AND A.ITEM_ID = C.ITEM_ID
                                 AND A.DOM_EXP = C.DOM_EXP
                                 AND A.FCST_TYPE = C.FCST_TYPE
                                 AND A.INCOTERMS = C.INCOTERMS
                                 AND A.PLANT_SITE_ID = C.PLANT_SITE_ID
                                 AND A.YYYYMMDD = C.BNP_YYYYMMDD
                                 AND A.UOM = C.UOM
                                 AND A.STORAGE_ID = C.STORAGE_ID
                                 AND A.STORAGE_PLANT_ID = C.STORAGE_PLANT_ID
                                 AND A.SSP_TRANSFER_FLAG = 'Y'   /* 20240430 SM TRANSFER_FLAG가 Y인건에 대해서만, 메일 발송하는 대상으로 수정 */
                               ORDER BY A.REQUEST_NO, A.ITEM_SEQ ) LOOP

                V2_REQUEST_NO      := CUR_SEND.REQUEST_NO;
                V_DIVISION_ID      := CUR_SEND.DIVISION_ID;
                V_PROJECT_CODE     := CUR_SEND.PROJECT_CODE;
                V_ITEM_SEQ         := CUR_SEND.ITEM_SEQ;
                V_ITEM_ID          := CUR_SEND.ITEM_ID;
                V_ITEM_NAME        := CUR_SEND.ITEM_NAME;
                V_UOM              := CUR_SEND.UOM;
                V_SCM_SITE_ID      := CUR_SEND.SCM_SITE_ID;
                V_CURSOR_YYYYMMDD  := CUR_SEND.YYYYMMDD;
                V_PLAN_QTY         := CUR_SEND.PLAN_QTY;
                V_CREATED_BY       := CUR_SEND.CREATED_BY;
                V_LAST_UPDATE_DATE := CUR_SEND.LAST_UPDATE_DATE;

                V_BODY_CONT := V_BODY_CONT||'<TR>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V2_REQUEST_NO||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_DIVISION_ID||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_PROJECT_CODE||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||TO_CHAR(V_ITEM_SEQ)||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_ITEM_ID||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_ITEM_NAME||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_UOM||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_SCM_SITE_ID||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||TO_CHAR(TO_DATE(V_CURSOR_YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD')||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD ALIGN="RIGHT">'||FN_GET_NUMER_TO_STRING(V_PLAN_QTY, 0)||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||V_CREATED_BY||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'<TD>'||TO_CHAR(V_LAST_UPDATE_DATE, 'YYYY-MM-DD')||'</TD>';
                V_BODY_CONT := V_BODY_CONT||'</TR>';

            END LOOP;

            V_TABLE_BODY := ' <html>
                            <head>
                                    <title>Untitled Document</title>
                                    <style>
                                        * {margin:0;padding:0;}
                                        body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
                                        table {border-collapse:collapse;width:100%;}
                                        table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
                                        table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
                                        table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
                                        table tbody td {padding:6px 8px;font-size:12px}
                                        table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
                                        .hori-table table thead td {text-align:center;padding:3px;}
                                        .hori-table table tbody td {text-align:center;padding:3px;}
                                        .vertical-table, .hori-table {margin-bottom:20px;}
                                    </style>
                                    </head>
                                    <body>'||'</br>'||
                                            '<b>'||REPLACE(V_BODY_CONTENTS, CHR(10), '<br>')||'</b>'||
                                            '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">'||
                                        '<table style=''border-top:2px solid #c8294b; width:1450px;''>
                                        <thead>'||V_HEAD_CONT||'</thead>
                                        <tbody>'||V_BODY_CONT||'</tbody>
                                        </div>
                                    </body>
                            </html>';

    /*
                EXEC SCM_ADM_MAIL_SEND
                    'kjj0070@lgespartner.com'				--//'kahonmalu@lgensol.com'
                    , @v_mail_title
                    , @TABLE_BODY
                    , 'Y'
    */

            /* 메일 발송 */
            IF SYS_CONTEXT('USERENV', 'DB_NAME') NOT IN ('OCGSCMD_P01', 'OCGSCMQ_P01', 'ESSCMD') THEN
                /* 원본 EXEC SCM_ADM_MAIL_SEND @v_to_mail, @v_mail_title, @TABLE_BODY, 'Y' */
                PKG_SEND_MAIL.P_SEND_MAIL_CLOB(V_TO_MAIL          /* 원본 주석 : 'kahonmalu@lgensol.com' */
                                             , V_MAIL_TITLE
                                             , V_TABLE_BODY
                                             , 'Y');

                /* MAIL 발송 LOG 저장 */
                SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG(
                    'MAIL'
                  , 0
                  , V_PROGRAM_NAME
                  , V_DIVISION_ID
                  , V_REQUEST_NO
                  , ''
                  , ''
                  , ''
                  , ''
                  , ''
                  , ''
                  , ''
                  , ''                                           /* p_send_pgm */
                  , V_TO_MAIL
                );
            END IF;

        END IF;

        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;
    /* ------------------------------------------------------------------------------------------ */

    /* -------------------------------------------------------------------------------------------- */

    /* -------------------------------------------------------------- */
    EXCEPTION
    /* -------------------------------------------------------------- */
        WHEN OTHERS THEN
            /* 트랜잭션 (END)
               select XACT_STATE() as xact_state_1, @@trancount
               select XACT_STATE() as xact_state_2, @@trancount, 'A21' */
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;

            V_LOG_TYPE        := 'ERROR';
            V_LOG_MESSAGE     := SUBSTR(SQLERRM, 1, 1000);
            V_LOG_DESCRIPTION := 'ERROR_LINE : '||SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480);
            D_EVENT_DATE      := SYSDATE;
            V_IN_PARA_DATA    := NULL;

            DBMS_OUTPUT.PUT_LINE('['||TO_CHAR(SQLCODE)||']'||SQLERRM);   /* 에러메시지 DISPLAY */

            PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_BATCH'
                              , V_IN_PARA_DATA, TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);


            RAISE_APPLICATION_ERROR(-20001, '['||V_PROGRAM_NAME||'] SQLCODE='||SQLCODE||' / SQLERRM='||SQLERRM
                                          ||' / BACKTRACE='||DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

    /* -------------------------------------------------------------- */
    END;
    /* -------------------------------------------------------------- */


    V_LOG_TYPE        := 'END';
    V_LOG_MESSAGE     := '########## END of procedure @@@##########';
    V_LOG_DESCRIPTION := 'input_count: '||TO_CHAR(N_INPUT_COUNT);
    D_EVENT_DATE      := SYSDATE;

    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_BATCH');

END;

PROCEDURE DMF0070_AUTO_PR_REQUEST_MAIL
/* ============================================================
 * Program ID   : DMF0070_AUTO_PR_REQUEST_MAIL
 * Description  : Procedure 작성 가이드
 * Usage        : PR Request 자동 생성 대상 추출하여 메일발송
 * Parameter    :
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2024-01-25    kjj            신규생성
 * 2024-06-05    JSSBAE         [E20240529-001017]_Auto PR Request 개선요청건
 *                              W1 주차에 Auto PR 데이터 생성 후 BNP In이 생성되지 않은 대상은
 *                              W2 주차에 대상이되는 데이터로 Auto PR 목록에 다시 생성 되어야 함
 * 2026-08-03    ZIONEX         [PJ202650304]  NextSCM Migration
 *
 * EXEC DMF0070_AUTO_PR_REQUEST_MAIL
 * ============================================================ */
AS

/*
--메인테이블 변경
DM_PLN_BNP_IN_PR_DETAIL_AUTO
=>DM_PLN_AUTO_PR_CHECK


*/

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME     VARCHAR2(150 CHAR) := 'DMF0070_AUTO_PR_REQUEST_MAIL';
    V_LOG_TYPE         VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT        NUMBER := 0;
    V_LOG_MESSAGE      VARCHAR2(1000 CHAR);
    V_LOG_DESCRIPTION  VARCHAR2(500 CHAR);
    D_EVENT_DATE       DATE;
    N_DELETE_COUNT     NUMBER := 0;
    N_INSERT_COUNT     NUMBER := 0;
    N_INPUT_COUNT      NUMBER := 0;
    N_LOGO_COUNT       NUMBER := 0;
    N_INVALID_ITEM     VARCHAR2(50 CHAR);
    N_MSG              VARCHAR2(1000 CHAR);
    V_BF_REQ_NO        VARCHAR2(30 CHAR);
    V_BF_QTY           NUMBER(10) := 0;
    V_THIS_QTY         NUMBER(10) := 0;


    /* 원본 @V_SUB_QRY NVARCHAR(MAX) = '' : Oracle 은 ''=NULL 이므로 초기값 NULL,
       원본 IF @V_SUB_QRY <> '' 은 IF V_SUB_QRY IS NOT NULL 로 대응 */
    V_SUB_QRY          CLOB;

    V_CUR_DIVISION     VARCHAR2(100 CHAR);
    V_CUR_INCOTERMS    VARCHAR2(100 CHAR);
    V_CUR_COUNTRY      VARCHAR2(100 CHAR);
    V_CUR_BNP_WEEK     VARCHAR2(100 CHAR);  /* BNP IN 출하시점 */
    V_CUR_DATA_WEEK    VARCHAR2(150 CHAR);  /* DATA 생성 시점(대상추출 메일발송은 DATA 생성시점의 1주 전) */
    V_CUR_NOT_COND     VARCHAR2(1000 CHAR); /* NOT 조건으로 지정된 건 */

    V_TABLE_BODY       CLOB;
    V_BODY_CONTENTS    CLOB;
    V_HEAD_CONT        CLOB;
    V_BODY_CONT        CLOB;
    /* , @v_to_mail  NVARCHAR(150) */
    V_MAIL_TITLE       VARCHAR2(100 CHAR);
    V_CNT              NUMBER(10);
    V_I                NUMBER(10);

    V_CUR_MODEL        VARCHAR2(100 CHAR);
    V_CUR_SITE         VARCHAR2(100 CHAR);
    V_CUR_PROJECT      VARCHAR2(8 CHAR);
    V_CUR_QTY          NUMBER(30,10);
    V_CUR_YYYYMMDD     VARCHAR2(10 CHAR);
    V_CUR_TOOWNER      VARCHAR2(150 CHAR);
    V_CUR_TOMAIL       VARCHAR2(150 CHAR);

    /* ------------------------------------------------------------
    * 본문 동일 수신자 묶음 (2026-10-06) — 같은 내용을 오너별로 개별 발송하던 것을
    * 수신인을 ';' 로 이어 한 통으로 보내기 위한 작업용 선언
    * ------------------------------------------------------------ */
    C_TO_MAIL_MAX    CONSTANT PLS_INTEGER := 4000;   /* PKG_SEND_MAIL 바디의 V_TO_MAIL VARCHAR2(4000) 와 정합 */
    C_GRP_PROBE_LEN  CONSTANT PLS_INTEGER := 1000;   /* 해시 후보용 선두 글자수. 1000자 x 최대 3바이트 < 4000 */
    TYPE T_GRP_REC IS RECORD ( BODY_CONT CLOB
                             , ADDR_LIST VARCHAR2(4000 CHAR) );
    TYPE T_GRP_TAB IS TABLE OF T_GRP_REC INDEX BY VARCHAR2(200 CHAR);
    V_GROUP            T_GRP_TAB;
    V_GRP_REC          T_GRP_REC;
    V_GRP_KEY          VARCHAR2(200 CHAR);
    V_SLOT_KEY         VARCHAR2(200 CHAR);
    V_GRP_IDX          VARCHAR2(200 CHAR);
    V_SLOT             PLS_INTEGER;
    V_GRP_PROBE        VARCHAR2(4000 CHAR);
    V_SAME_BODY        BOOLEAN;

    V_IN_PARA_DATA     VARCHAR2(4000 CHAR);

BEGIN


    /* 시작 LOG  (START) */
    V_LOG_TYPE := 'START';
    V_LOG_MESSAGE := '########## Start of procedure @@@##########';
    V_LOG_DESCRIPTION := '';
    D_EVENT_DATE := SYSDATE;
    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_BATCH');
    V_LOG_MESSAGE := NULL;   /* 변수 재사용을 위하여 초기화해야함 */


    /* -------------------------------------------------------------------------------------- */

    /* -------------------------------------------------------------------------------------- */
    BEGIN
            /* 메일발송 주기(케이스 별) */
            /*
            *1차
        (A) Incoterms= EXW => D-91(13주)
        (B) Incoterms = C* or F*, Country=KR => D-119(17주)
        (C) Incoterms = D*, Country=JP => D-119(17주)
        (D) Incoterms = D*, Country = not KR => D-175(25주)


            *2차
        (A) Incoterms= EXW => D-20 (3주 전)
        (B) Incoterms = C* or F*, Country=KR => D-48 (7주 전)
        (C) Incoterms = D*, Country=JP => D-48 (7주 전)
        (D) Incoterms = D*, Country = not KR => D-104 (15주 전)
            */

            /* ------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 메일발송 대상추출 ');
            /* ------------------------------------------------------------------------------ */
            /* 대상 추출------------------------------------------ */

            DELETE
              FROM GT_DMF70ML_TARGET_LIST;

            V_SUB_QRY := NULL;


            FOR R_GUIDE IN ( SELECT SEGMENT1
                                  , SEGMENT2
                                  , SEGMENT3
                                  , SEGMENT4
                                  , SEGMENT5
                               FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                              WHERE LOOKUP_TYPE = 'AUTO_PR_CHECK_CRITERIA'
                                AND VALID_YN = 'Y'
                              ORDER BY DISPLAY_SEQ )
            LOOP

                V_CUR_DIVISION  := R_GUIDE.SEGMENT1;
                V_CUR_INCOTERMS := R_GUIDE.SEGMENT2;
                V_CUR_COUNTRY   := R_GUIDE.SEGMENT3;
                V_CUR_BNP_WEEK  := R_GUIDE.SEGMENT4;
                V_CUR_DATA_WEEK := R_GUIDE.SEGMENT5;

                IF V_SUB_QRY IS NOT NULL THEN
                    V_SUB_QRY := V_SUB_QRY || '
                    UNION
                    ';
                END IF;

                /*                   n = @CUR_DATA_WEEK + 1 : MSSQL 은 nvarchar + int 를 자료형우선순위로 int 연산 → TO_NUMBER 사용. */
                V_SUB_QRY := V_SUB_QRY || '
                    SELECT MS.COUNTRY
                  , (
                        SELECT MP.PROJECT_OWNER FROM SCM_MST_PROJECT MP
                        WHERE MP.DIVISION_ID = MF.DIVISION_ID
                        AND MP.PROJECT_CODE = MF.PROJECT_CODE
                        AND ROWNUM = 1
                    ) PROJECT_OWNER
                  , (
                        SELECT ITM.OWNER FROM SCM_MST_SITE_ITEM ITM
                        WHERE ITM.DIVISION_ID = MF.DIVISION_ID
                        AND ITM.PROJECT_CODE = MF.PROJECT_CODE
                        AND ITM.SCM_SITE_ID = MF.SCM_SITE_ID
                        AND ITM.ITEM_ID = MF.ITEM_ID
                        AND ROWNUM = 1
                    ) OWNER
                    , MF.ITEM_ID, MF.SCM_SITE_ID, MF.PROJECT_CODE, MF.QTY, MF.YYYYMMDD
                    , MF.DIVISION_ID
                    , MF.DOM_EXP
                    , MF.FCST_TYPE
                    , MF.INCOTERMS
                    , MF.MEASURE
                    , MF.PLANT_SITE_ID
                    FROM DM_PLN_MKT_FCST MF
                       , SCM_ADM_LOOKUP_MASTER_DETAIL LUP
                       , SCM_MST_SITE MS
                    WHERE MF.DIVISION_ID = LUP.SEGMENT1
                    AND MF.ITEM_ID = LUP.SEGMENT2
                    AND MF.DIVISION_ID = MS.DIVISION_ID
                    AND MF.SCM_SITE_ID = MS.SCM_SITE_ID
                    AND LUP.VALID_YN = ''Y''
                    AND LUP.LOOKUP_TYPE = ''ESS_PRICE_EXCEPT_MODEL''
                    AND MF.MEASURE = ''MKT_FCST''
                    AND RTRIM(MF.ATTRIBUTE9) IS NULL /* 확정되지 않은 것들 (원본 ISNULL(MF.ATTRIBUTE9,'''')='''') */
                    /* [E20240529-001017]_Auto PR Request 개선요청건
                    AND NOT EXISTS --메일전송목록에 없는 것들만 발송
                    (
                        SELECT * FROM DM_PLN_AUTO_PR_CHECK ATO WITH(NOLOCK)
                        WHERE ATO.DIVISION_ID = MF.DIVISION_ID
                        AND ATO.PROJECT_CODE = MF.PROJECT_CODE
                        AND ATO.SCM_SITE_ID = MF.SCM_SITE_ID
                        AND ATO.ITEM_ID = MF.ITEM_ID
                        AND ATO.DOM_EXP = MF.DOM_EXP
                        AND ATO.FCST_TYPE = MF.FCST_TYPE
                        AND ATO.INCOTERMS = MF.INCOTERMS
                        AND ATO.PLANT_SITE_ID = MF.PLANT_SITE_ID
                        AND ATO.MKT_FCST_DATE = MF.YYYYMMDD
                        AND ATO.PLAN_QTY = MF.QTY
                    ) */
                    AND MF.QTY > 0 /* 수량이 0 이상인 것들만 */
                    AND
                    (
                        (
                            MF.YYYYMMDD >=
                            (
                                    SELECT BASIS_START_DATE FROM SCM_SYS_CALENDAR_M
                                    WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + (' || TO_CHAR(TO_NUMBER(V_CUR_DATA_WEEK) + 1) || ' * 7), ''YYYYMMDD'') /* 데이터 생성 시점의 1주 전 */
                            )
                            AND MF.YYYYMMDD <=
                            (
                                    SELECT BASIS_END_DATE FROM SCM_SYS_CALENDAR_M
                                    WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + (' || TO_CHAR(TO_NUMBER(V_CUR_DATA_WEEK) + 1) || ' * 7), ''YYYYMMDD'')
                            )
                        )
                        OR
                        (
                            MF.YYYYMMDD >=
                            (
                                    SELECT BASIS_START_DATE FROM SCM_SYS_CALENDAR_M
                                    WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + (' || TO_CHAR(TO_NUMBER(V_CUR_DATA_WEEK) + 1 - 10) || ' * 7), ''YYYYMMDD'') /* 2차발송은 1차의 10주 뒤 */
                            )
                            AND MF.YYYYMMDD <=
                            (
                                    SELECT BASIS_END_DATE FROM SCM_SYS_CALENDAR_M
                                    WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE + (' || TO_CHAR(TO_NUMBER(V_CUR_DATA_WEEK) + 1) || ' * 7), ''YYYYMMDD'') /* To는 1차발송일과 동일 */
                            )
                        )
                    )

                ';

                /* INCOTERMS */
                IF V_CUR_INCOTERMS <> '-' THEN

                    IF INSTR(V_CUR_INCOTERMS, '*') > 0 THEN

                        V_SUB_QRY := V_SUB_QRY || '
                            AND MF.INCOTERMS LIKE ''' || REPLACE(V_CUR_INCOTERMS, '*', '%') || '''
                        ';


                    ELSIF INSTR(UPPER(V_CUR_INCOTERMS), 'NOT_') > 0 THEN
                    /*
                    --Not 의 규칙
                    1)Not_로 등록
                    2)여러개일 경우는 ,로 구분
                    */
                        /* 원본 CUR_NOT_COND CURSOR : SELECT TOKEN FROM DBO.UF_FX_STRING_SPLIT(@CUR_INCOTERMS, ',') */
                        FOR R_NOT IN ( SELECT TOKEN
                                         FROM TABLE(UF_FX_STRING_SPLIT(V_CUR_INCOTERMS, ',')) )
                        LOOP

                            V_CUR_NOT_COND := R_NOT.TOKEN;

                            /* 원본 REPLACE(@V_CUR_NOT_COND,'NOT_','') : MSSQL REPLACE 는 CI 콜레이션이라 'Not_' 도 제거.
                               Oracle REPLACE 는 대소문자 구분 → REGEXP_REPLACE(...,'i') 로 CI 재현 */
                            V_SUB_QRY := V_SUB_QRY || '
                                AND MF.INCOTERMS <> ''' || REGEXP_REPLACE(V_CUR_NOT_COND, 'NOT_', '', 1, 0, 'i') || '''
                            ';

                        END LOOP;

                    ELSE

                        V_SUB_QRY := V_SUB_QRY || '
                            AND MF.INCOTERMS = ''' || V_CUR_INCOTERMS || '''
                        ';

                    END IF;
                END IF;

                /* COUNTRY */
                IF V_CUR_COUNTRY <> '-' THEN

                    IF INSTR(V_CUR_COUNTRY, '*') > 0 THEN

                        V_SUB_QRY := V_SUB_QRY || '
                            AND MS.COUNTRY LIKE ''' || REPLACE(V_CUR_COUNTRY, '*', '%') || '''
                        ';

                    ELSIF INSTR(UPPER(V_CUR_COUNTRY), 'NOT_') > 0 THEN

                    /*
                        SET @V_SUB_QRY = @V_SUB_QRY + N'
                            AND MS.COUNTRY <> ''' + REPLACE(@CUR_COUNTRY,'NOT ', '') + '''
                        '
                        */
                        /*
                        --Not 의 규칙
                        1)Not_로 등록
                        2)여러개일 경우는 ,로 구분
                        */
                        FOR R_NOT IN ( SELECT TOKEN
                                         FROM TABLE(UF_FX_STRING_SPLIT(V_CUR_COUNTRY, ',')) )
                        LOOP

                            V_CUR_NOT_COND := R_NOT.TOKEN;

                            V_SUB_QRY := V_SUB_QRY || '
                                AND MS.COUNTRY <> ''' || REGEXP_REPLACE(V_CUR_NOT_COND, 'NOT_', '', 1, 0, 'i') || '''
                            ';

                        END LOOP;

                    ELSE

                        V_SUB_QRY := V_SUB_QRY || '
                            AND MS.COUNTRY = ''' || V_CUR_COUNTRY || '''
                        ';

                    END IF;
                END IF;

            END LOOP;

            /* PRINT @V_SUB_QRY */
            /* EXEC (@V_SUB_QRY)  : 원본 주석행 — 실행코드 아님 */

            /* PRINT @V_QRY */
            /* 원본 INSERT #TMP_TARGET_LIST EXEC (@V_SUB_QRY) → EXECUTE IMMEDIATE 로 GTT 적재
               (동적 SELECT 의 컬럼 순서 = 아래 컬럼 목록 순서와 1:1) */
            EXECUTE IMMEDIATE 'INSERT INTO GT_DMF70ML_TARGET_LIST ( COUNTRY, PROJECT_OWNER, OWNER, ITEM_ID, SCM_SITE_ID, PROJECT_CODE, QTY, YYYYMMDD, DIVISION_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID ) ' || V_SUB_QRY;

            /* SELECT * FROM #TMP_TARGET_LIST */


            DELETE
              FROM GT_DMF70ML_OWNER_LIST;

            /* OWNER 정보 추출 */
            INSERT INTO GT_DMF70ML_OWNER_LIST
                 ( TO_OWNER )
            SELECT A.TO_OWNER
              FROM ( SELECT UPPER(PROJECT_OWNER) TO_OWNER
                       FROM GT_DMF70ML_TARGET_LIST
                      WHERE RTRIM(PROJECT_OWNER) IS NOT NULL
                     UNION
                     SELECT UPPER(OWNER) TO_OWNER
                       FROM GT_DMF70ML_TARGET_LIST
                      WHERE RTRIM(OWNER) IS NOT NULL ) A;

            /* ------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 메일발송');
            /* ------------------------------------------------------------------------------ */

            /* ----------------------------- */
            V_MAIL_TITLE := '[SCM.DM] BNP In & PR Request 자동생성 대상 안내';
            V_BODY_CONTENTS := '안녕하십니까, SCM.DM 시스템입니다. 다음주 <B>월요일</B> BNP In과 PR Request 자동수행 대상을 안내드립니다.</BR>
                    자동생성을 위해서는 SCM 시스템 → Demand → Demand Plan → Auto PR Check화면에서 <B>Plant Site, SLOC 정보를 이번 주</B> 안에 입력해주셔야 합니다. (공란일 시 생성 X)
                    PR 요청 취소가 필요하다면 SCM 시스템 → Demand > Demand Plan > Auto PR Check 화면에 접속하시어 ''BNP In/PR Request Auto'' 값을 <B>N</B> 으로 수정해주시기 바랍니다.
                    PR 요청 수정이 필요하다면
                1) MKT FCST 입력값을 수정 → 1주 후에 다시 메일 안내 드리며
                2) 긴급 건은 수기로 BNP In 입력 → 수기로 PR Request 진행 부탁드립니다.';

            V_BODY_CONT := '';
            V_HEAD_CONT := '<TR>
                <TH>Model 코드</TH>
                <TH>Sales Site</TH>
                <TH>Project Code</TH>
                <TH>QTY</TH>
                <TH>YYYYMMDD</TH>
                </TR>';

            /* 발송할 오너 가져오기 */
            FOR R_OWNER IN ( SELECT TO_OWNER
                                  , TO_OWNER || '@lgensol.com' AS TO_MAIL
                               FROM GT_DMF70ML_OWNER_LIST )
            LOOP

                V_CUR_TOOWNER := R_OWNER.TO_OWNER;
                V_CUR_TOMAIL  := R_OWNER.TO_MAIL;

                V_BODY_CONT := '';

                /* 오너에 맞는 대상 목록 가져오기 */
                FOR R_TARGET IN ( SELECT ITEM_ID
                                       , SCM_SITE_ID
                                       , SUBSTR(PROJECT_CODE, 1, 8) AS PROJECT_CODE
                                       , QTY
                                       , YYYYMMDD
                                    FROM GT_DMF70ML_TARGET_LIST
                                   WHERE UPPER(PROJECT_OWNER) = UPPER(V_CUR_TOOWNER)
                                      OR UPPER(OWNER) = UPPER(V_CUR_TOOWNER) )
                LOOP

                    V_CUR_MODEL    := R_TARGET.ITEM_ID;
                    V_CUR_SITE     := R_TARGET.SCM_SITE_ID;
                    V_CUR_PROJECT  := R_TARGET.PROJECT_CODE;
                    V_CUR_QTY      := R_TARGET.QTY;
                    V_CUR_YYYYMMDD := R_TARGET.YYYYMMDD;


                    V_BODY_CONT := V_BODY_CONT || '<TR>';
                    V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_MODEL || '</TD>';
                    V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_SITE || '</TD>';
                    V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_PROJECT || '</TD>';
                    V_BODY_CONT := V_BODY_CONT || '<TD ALIGN="RIGHT">' || FN_GET_NUMER_TO_STRING(V_CUR_QTY, 0) || '</TD>';
                    V_BODY_CONT := V_BODY_CONT || '<TD>' || V_CUR_YYYYMMDD || '</TD>';
                    V_BODY_CONT := V_BODY_CONT || '</TR>';

                END LOOP;

                /* ------------------------------------------------------------
                * 본문이 같은 오너를 한 묶음으로 모은다 (2026-10-06)
                * - 해시는 묶음 후보를 빨리 찾기 위한 것이고, 합칠지는 본문 전문 비교로 확정한다
                *   (해시가 충돌해 다른 본문이 한 통에 섞이면 잘못된 내용이 나가기 때문)
                * - 본문이 CLOB 이라 해시는 선두 C_GRP_PROBE_LEN 글자로 만들고
                *   확정 비교는 DBMS_LOB.COMPARE 로 본문 전문을 본다
                * - 수신인 목록이 상한을 넘으면 같은 본문으로 묶음을 하나 더 만든다(절단 방지)
                * ------------------------------------------------------------ */
                V_GRP_PROBE := NVL(DBMS_LOB.SUBSTR(V_BODY_CONT, C_GRP_PROBE_LEN, 1), ' ');
                V_GRP_KEY   := TO_CHAR(DBMS_UTILITY.GET_HASH_VALUE(V_GRP_PROBE, 0, 1073741824));
                V_SLOT      := 1;

                LOOP

                    V_SLOT_KEY := V_GRP_KEY || '|' || TO_CHAR(V_SLOT);

                    IF NOT V_GROUP.EXISTS(V_SLOT_KEY) THEN
                        V_GRP_REC.BODY_CONT := V_BODY_CONT;
                        V_GRP_REC.ADDR_LIST := V_CUR_TOMAIL;
                        V_GROUP(V_SLOT_KEY) := V_GRP_REC;
                        EXIT;
                    END IF;

                    V_SAME_BODY := ( V_GROUP(V_SLOT_KEY).BODY_CONT IS NULL AND V_BODY_CONT IS NULL );

                    IF NOT V_SAME_BODY
                       AND V_GROUP(V_SLOT_KEY).BODY_CONT IS NOT NULL
                       AND V_BODY_CONT IS NOT NULL THEN
                        V_SAME_BODY := ( DBMS_LOB.COMPARE(V_GROUP(V_SLOT_KEY).BODY_CONT, V_BODY_CONT) = 0 );
                    END IF;

                    IF V_SAME_BODY
                       AND LENGTHB(V_GROUP(V_SLOT_KEY).ADDR_LIST || ';' || V_CUR_TOMAIL) <= C_TO_MAIL_MAX THEN
                        V_GROUP(V_SLOT_KEY).ADDR_LIST := V_GROUP(V_SLOT_KEY).ADDR_LIST || ';' || V_CUR_TOMAIL;
                        EXIT;
                    END IF;

                    V_SLOT := V_SLOT + 1;

                END LOOP;

            END LOOP;

            /* 묶음마다 한 통만 발송한다 (수신인 = ';' 로 연결) */
            V_GRP_IDX := V_GROUP.FIRST;

            WHILE V_GRP_IDX IS NOT NULL LOOP

                V_BODY_CONT := V_GROUP(V_GRP_IDX).BODY_CONT;

                V_TABLE_BODY := ' <html>
                                <head>
