            /* ------------------------------------------------------------------------------ */
            DBMS_OUTPUT.PUT_LINE(TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || ' ### 신규테이블에 저장');
            /* ------------------------------------------------------------------------------ */

            MERGE INTO DM_PLN_AUTO_PR_CHECK A
            USING GT_DMF70ML_TARGET_LIST B
               ON ( A.DIVISION_ID = B.DIVISION_ID
                AND A.PROJECT_CODE = B.PROJECT_CODE
                AND A.SCM_SITE_ID = B.SCM_SITE_ID
                AND A.ITEM_ID = B.ITEM_ID
