                AND A.MKT_FCST_DATE = B.YYYYMMDD
                AND A.MAIL_INFO_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD') )
            WHEN MATCHED THEN
                UPDATE
                   SET A.PLAN_QTY = B.QTY
                     , A.CREATION_DATE = SYSDATE
                     , A.LAST_UPDATE_DATE = SYSDATE
            WHEN NOT MATCHED THEN
                INSERT
                     ( MAIL_INFO_DATE
                     , DIVISION_ID
                     , PROJECT_CODE
                     , SCM_SITE_ID
                     , ITEM_ID
                     , DOM_EXP
                     , FCST_TYPE
                     , INCOTERMS
                     , PLANT_SITE_ID
                     , MKT_FCST_DATE
                     , PLAN_QTY
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE )
                VALUES ( TO_CHAR(SYSDATE, 'YYYYMMDD')
                       , B.DIVISION_ID
                       , B.PROJECT_CODE
                       , B.SCM_SITE_ID
                       , B.ITEM_ID
                       , B.DOM_EXP
                       , B.FCST_TYPE
                       , B.INCOTERMS
                       , B.PLANT_SITE_ID
                       , B.YYYYMMDD
                       , B.QTY
                       , 'SCM_BATCH'
                       , SYSDATE
                       , 'SCM_BATCH'
                       , SYSDATE );

        /* 원본 IF XACT_STATE() > 0 and @@trancount > 0 THEN COMMIT TRAN */
        IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
            COMMIT;
        END IF;
    /* ---------------------------------------------------------------------------------- */

    /* ---------------------------------------------------------------------------------- */

    /* ------------------------------------------------------ */
    EXCEPTION

    /* ------------------------------------------------------ */
        WHEN OTHERS THEN
            /* 트랜잭션 (END) */
            /* select XACT_STATE() as xact_state_1, @@trancount */
            /* select XACT_STATE() as xact_state_2, @@trancount, 'A21' */
            /* 원본 IF @@trancount > 0 THEN ROLLBACK TRAN */
            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                ROLLBACK;
            END IF;

            V_LOG_TYPE := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

            V_LOG_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE := SYSDATE;

            /* 원본 SELECT '[' || Convert(NVARCHAR(10), ERROR_NUMBER()) || ']' || ERROR_MESSAGE() AS ERR_MSG
               (에러메시지 DISPLAY) : 스케줄 배치라 결과셋 소비자가 없음 → DBMS_OUTPUT 로 대체(H-9b) */
            DBMS_OUTPUT.PUT_LINE('[' || TO_CHAR(SQLCODE) || ']' || V_LOG_MESSAGE);


            PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME
                              , V_LOG_TYPE
                              , N_LOG_COUNT
                              , V_LOG_MESSAGE
                              , V_LOG_DESCRIPTION
                              , D_EVENT_DATE
                              , 'SCM_BATCH'
                              , P_IN_PARA_DATA  => V_IN_PARA_DATA
                              , P_SQL_ERR_CODE  => SQLCODE
                              , P_SQL_ERR_MSG   => SQLERRM
                              , P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);


            RAISE_APPLICATION_ERROR(-20001
                                  , '[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM ||
                                    ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);

    /* ------------------------------------------------------ */

    /* ------------------------------------------------------ */
    END;

    /* 종료 LOG */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure @@@##########';
    V_LOG_DESCRIPTION := 'input_count: ' || TO_CHAR(N_INPUT_COUNT);
    D_EVENT_DATE := SYSDATE;

    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, 'SCM_BATCH');

END;

SCM_MGR|PROCEDURE|DMF0073_SAVE_VERSION_S:
PROCEDURE DMF0073_SAVE_VERSION_SALESPRICE
(
    P_DIVISION_ID           IN  VARCHAR2,   /* 창 Division (콤마 복수 허용 — 조회 프로시저와 같은 규약) */
    P_VERSION_NO            IN  VARCHAR2,   /* 변경 행 CODE(순수 버전번호) '^' 연결                     */
    P_MONTHLY_ROLLING_FCST  IN  VARCHAR2,   /* 변경 값(Y/N) '^' 연결 — P_VERSION_NO 와 같은 차례        */
    P_USER_ID               IN  VARCHAR2,   /* 저장 사용자                                             */
    P_MENU_ID               IN  VARCHAR2,   /* 부른 화면 (편집 권한 판정 기준)                          */
    O_RESULT_CURSOR         OUT SYS_REFCURSOR
)
/****************************************************************************************************/
/* Program ID  : DMF0073_SAVE_VERSION_SALESPRICE                                                     */
/* Description : Version 창 — MONTHLY_ROLLING_FCST(DM_MST_VERSION.ATTRIBUTE7) 저장                    */
/*               조회 프로시저 DMF0073_GET_VERSION_SALESPRICE 와 짝이며, 그 조회를 공유하는            */
/*               DMF0020 · DMF0074 · DMF0082 가 함께 쓴다. 편집 권한 판정 기준은 P_MENU_ID 다.         */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                              */
/*--------------------------------------------------------------------------------------------------*/
/* 2024/05/13  KJJ          AS-IS DMF0073_SAVE_VERSION_SALESPRICE 신규                                */
/* 2026/09/28  ZIONEX       [PJ202650304] MSSQL -> Oracle 전환.                                       */
/*                          AS-IS 동작(ATTRIBUTE7/LAST_UPDATED_BY/LAST_UPDATE_DATE UPDATE)은 그대로.   */
/*                          서버 검증 4종은 PKG_DMF0035.P_DMF0035_SAVE_VERSION_MRF(2026-09-22 이식)와  */
/*                          같은 규칙이며, 그 판은 화면이 DMF0035 로 고정되어 다른 화면에서 권한 판정이 */
/*                          어긋나므로 화면을 인자로 받도록 했다.                                      */
/*                          AS-IS 는 DIVISION_ID 단일값 비교라 복수 Division 선택 시 0건 갱신.         */
/****************************************************************************************************/
IS
    V_CUR_YYYYWW    VARCHAR2(10 CHAR);
    N_VER_CNT       PLS_INTEGER := 0;
    N_VAL_CNT       PLS_INTEGER := 0;
    N_UPD_CNT       PLS_INTEGER := 0;
    V_INVALID       VARCHAR2(4000 CHAR);

    /* EXCEPTION 블록 변수 */
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100 CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
    D_EVENT_DATE    DATE := SYSDATE;

BEGIN

    /* 시작 로그 */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START of procedure ##########';
    V_DESCRIPTION := 'MENU_ID : ' || P_MENU_ID;
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    /* 1. 입력 건수 정합 */
    IF TRIM(P_VERSION_NO) IS NULL THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, '저장할 데이터가 없습니다.' AS MSG, CAST(NULL AS VARCHAR2(4000 CHAR)) AS EVENT FROM DUAL;
        RETURN;
    END IF;

    N_VER_CNT := REGEXP_COUNT(P_VERSION_NO || '^', '\^');
    N_VAL_CNT := REGEXP_COUNT(NVL(P_MONTHLY_ROLLING_FCST, '') || '^', '\^');

    IF N_VER_CNT <> N_VAL_CNT THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, 'Version / Monthly Rolling Forecast 건수가 일치하지 않습니다.' AS MSG
                 , N_VER_CNT || ' / ' || N_VAL_CNT AS EVENT FROM DUAL;
        RETURN;
    END IF;

    /* 2. 값 검증 — Y/N 만 (AS-IS MSG00002 필수 입력 + 선택 목록 Y/N) */
    SELECT LISTAGG(VER, ', ') WITHIN GROUP (ORDER BY N)
      INTO V_INVALID
      FROM (SELECT LEVEL AS N
                 , TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VER
                 , TRIM(REGEXP_SUBSTR(P_MONTHLY_ROLLING_FCST || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VAL
              FROM DUAL
           CONNECT BY LEVEL <= N_VER_CNT)
     WHERE NVL(VAL, '-') NOT IN ('Y', 'N');

    IF V_INVALID IS NOT NULL THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, 'Monthly Rolling Forecast 값은 Y 또는 N 이어야 합니다.' AS MSG, V_INVALID AS EVENT FROM DUAL;
        RETURN;
    END IF;

    /* 3. 당주 버전 + 사업부 편집 권한 검증 (조회 프로시저의 EDITABLE / EDIT_YN 과 같은 조건 — 연도 포함) */
    SELECT MAX(ISO_YYYYWW)
      INTO V_CUR_YYYYWW
      FROM SCM_MGR.SCM_SYS_CALENDAR_M
     WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD');

    SELECT LISTAGG(T.VER, ', ') WITHIN GROUP (ORDER BY T.N)
      INTO V_INVALID
      FROM (SELECT LEVEL AS N
                 , TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VER
              FROM DUAL
           CONNECT BY LEVEL <= N_VER_CNT) T
     WHERE NOT EXISTS (SELECT 1
                         FROM SCM_MGR.DM_MST_VERSION A
                        INNER JOIN SCM_MGR.SCM_SYS_CALENDAR_M B
                           ON B.BASIS_YYYYMMDD = A.YYYYMMDD
                        INNER JOIN TABLE(SCM_MGR.PKG_SCM_USER_MNU.PR_SCM_EDIT_YN(P_USER_ID, P_MENU_ID)) TEI
                           ON TEI.UNIT_ID = A.DIVISION_ID
                          AND TEI.EDIT_YN = 'Y'
                        WHERE A.VERSION_NO  = T.VER
                          AND A.VERSION_TYPE LIKE 'SP\_%' ESCAPE '\'   -- Sales Plan 계열 버전만 (MKT/BIZ 저장 불가 — 사용자 확정 2026-09-22)
                          AND A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(SCM_MGR.FN_STRING_SPLIT(P_DIVISION_ID, ',')))
                          AND B.ISO_YYYYWW  = V_CUR_YYYYWW);

    IF V_INVALID IS NOT NULL THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE, '당주 Sales Plan 버전이면서 편집 권한이 있는 사업부의 버전만 수정할 수 있습니다.' AS MSG, V_INVALID AS EVENT FROM DUAL;
        RETURN;
    END IF;

    /* 4. 저장 — AS-IS UPDATE 1:1 (ATTRIBUTE7 / LAST_UPDATED_BY / LAST_UPDATE_DATE) */
    UPDATE SCM_MGR.DM_MST_VERSION M_VER
       SET M_VER.ATTRIBUTE7       = (SELECT T.VAL
                                       FROM (SELECT TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VER
                                                  , TRIM(REGEXP_SUBSTR(P_MONTHLY_ROLLING_FCST || '^', '(.*?)\^', 1, LEVEL, NULL, 1)) AS VAL
                                               FROM DUAL
                                            CONNECT BY LEVEL <= N_VER_CNT) T
                                      WHERE T.VER = M_VER.VERSION_NO
                                      FETCH FIRST 1 ROWS ONLY)
         , M_VER.LAST_UPDATED_BY  = P_USER_ID
         , M_VER.LAST_UPDATE_DATE = SYSDATE
     WHERE M_VER.DIVISION_ID IN (SELECT TOKEN FROM TABLE(SCM_MGR.FN_STRING_SPLIT(P_DIVISION_ID, ',')))
       AND M_VER.VERSION_TYPE LIKE 'SP\_%' ESCAPE '\'
       AND M_VER.VERSION_NO  IN (SELECT TRIM(REGEXP_SUBSTR(P_VERSION_NO || '^', '(.*?)\^', 1, LEVEL, NULL, 1))
                                   FROM DUAL
                                CONNECT BY LEVEL <= N_VER_CNT)
       AND EXISTS (SELECT 1
                     FROM TABLE(SCM_MGR.PKG_SCM_USER_MNU.PR_SCM_EDIT_YN(P_USER_ID, P_MENU_ID)) TEI
                    WHERE TEI.UNIT_ID = M_VER.DIVISION_ID
                      AND TEI.EDIT_YN = 'Y');

    N_UPD_CNT   := SQL%ROWCOUNT;
    N_LOG_COUNT := N_UPD_CNT;

    COMMIT;

    /* 종료 로그 */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := 'UPDATED=' || N_UPD_CNT;
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE, 'success' AS MSG, TO_CHAR(N_UPD_CNT) AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;

        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := SUBSTR(JSON_OBJECT(
            'P_DIVISION_ID'          VALUE P_DIVISION_ID,
            'P_VERSION_NO'           VALUE P_VERSION_NO,
            'P_MONTHLY_ROLLING_FCST' VALUE P_MONTHLY_ROLLING_FCST,
            'P_USER_ID'              VALUE P_USER_ID,
            'P_MENU_ID'              VALUE P_MENU_ID
        ), 1, 4000);
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                $$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        OPEN O_RESULT_CURSOR FOR
            SELECT '9' AS CODE, 'fail' AS MSG, SUBSTR(V_SQL_ERRMSG, 1, 4000) AS EVENT FROM DUAL;

END DMF0073_SAVE_VERSION_SALESPRICE;

SCM_MGR|FUNCTION|FN_ASIS_SORT_KEY:
FUNCTION FN_ASIS_SORT_KEY
(
    P_TEXT              IN  VARCHAR2
)
RETURN RAW DETERMINISTIC
IS
    /* 구두점 27자 + 기호 4자 = 31자를 순서대로 CHR(1)~CHR(31) 로 옮긴다.
       뒤에 붙인 홑따옴표와 하이픈은 옮길 자리가 없어 빠진다(AS-IS 와 같다). */
    C_FROM      CONSTANT VARCHAR2(40 CHAR) := ' !"#$%&()*,./:;?@[\]^_`{|}~+<=>''-';
    C_TO        CONSTANT VARCHAR2(40 CHAR) :=
                CHR(1)  || CHR(2)  || CHR(3)  || CHR(4)  || CHR(5)  || CHR(6)  || CHR(7)  || CHR(8)
             || CHR(9)  || CHR(10) || CHR(11) || CHR(12) || CHR(13) || CHR(14) || CHR(15) || CHR(16)
             || CHR(17) || CHR(18) || CHR(19) || CHR(20) || CHR(21) || CHR(22) || CHR(23) || CHR(24)
             || CHR(25) || CHR(26) || CHR(27) || CHR(28) || CHR(29) || CHR(30) || CHR(31);
BEGIN
    IF P_TEXT IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN NLSSORT(TRANSLATE(P_TEXT, C_FROM, C_TO), 'NLS_SORT=BINARY_CI');
END FN_ASIS_SORT_KEY;

SCM_MGR|FUNCTION|FN_GET_NUMER_TO_STRING:
FUNCTION           "FN_GET_NUMER_TO_STRING" 
(
    P_INPUT      IN NUMBER
  , P_IDIGITCNT  IN PLS_INTEGER
)
RETURN VARCHAR2
/****************************************************************************
  * PROJECT       : LG CHEM SCP PRJ.
  * FUNCTION NAME : FN_GET_NUMER_TO_STRING
  * DESCRIPTION   : 메일보낼때 숫자표시용
  * INPUT         : 변환할 숫자, 소수점자리수
  * OUTPUT        : 콤마찍힌 스트링숫자
  * PROGRAM HISTORY
  *--------------------------------------------------------------
    DATE      IN CHARGE           DESCRIPTION
  *--------------------------------------------------------------
  * 2021-06-03   HWI1993 메일보낼때 숫자표시용 ( 인풋이 NUMERIC 형이어야 함. )
  * 2026-07-03   ZIONEX  [PJ202650304]  NextSCM Migration
  ****************************************************************************/
AS

    V_INPUT       NUMBER := P_INPUT;
    V_IDIGIT_CNT  PLS_INTEGER := P_IDIGITCNT;
    V_STR_INPUT   VARCHAR2(39 CHAR);
    V_RET_VALUE   VARCHAR2(50 CHAR);
    V_IDOT_INDEX  PLS_INTEGER;
    V_STR_INT     VARCHAR2(30 CHAR);
    V_STR_DEC     VARCHAR2(8 CHAR);
    V_SIGN        VARCHAR2(1 CHAR);
    V_I           PLS_INTEGER;

BEGIN

    V_SIGN := '';
    IF ( V_INPUT < 0 ) THEN
        V_SIGN  := '-';
        V_INPUT := V_INPUT * -1;
    END IF;

    V_INPUT      := NVL(V_INPUT, 0);
    V_IDIGIT_CNT := NVL(V_IDIGIT_CNT, 0);

    V_STR_INPUT  := TO_CHAR(V_INPUT, 'FM' || LPAD('0', 30, '9') || '.00000000');
    V_IDOT_INDEX := INSTR(V_STR_INPUT, '.');

    V_STR_INT := SUBSTR(V_STR_INPUT, 1, V_IDOT_INDEX - 1);                                 /* 정수부 */
    V_STR_DEC := SUBSTR(V_STR_INPUT, V_IDOT_INDEX + 1, LENGTH(V_STR_INPUT) - V_IDOT_INDEX); /* 소수부 */

    V_I := 0;
    V_RET_VALUE := SUBSTR(V_STR_INT, 1, MOD(LENGTH(V_STR_INT), 3));

    WHILE ( V_I < FLOOR(LENGTH(V_STR_INT) / 3) ) LOOP

        V_RET_VALUE := V_RET_VALUE || CASE WHEN V_RET_VALUE IS NOT NULL THEN ',' ELSE '' END
                    || SUBSTR(V_STR_INT, MOD(LENGTH(V_STR_INT), 3) + 1 + V_I * 3, 3 );

        V_I := V_I + 1;
    END LOOP;

    V_RET_VALUE := V_RET_VALUE ||
        CASE WHEN V_IDIGIT_CNT > 0
             THEN '.' || SUBSTR(REPLACE(TO_CHAR(TRUNC(V_INPUT - FLOOR(V_INPUT), V_IDIGIT_CNT), 'FM0.00000000'), '0.', ''), 1, V_IDIGIT_CNT)
             ELSE '' END;

    RETURN V_SIGN || V_RET_VALUE;

END;

