                    SELECT '-1' AS CODE
                         , 'ERR_RTN: - Save verify failed (inserted=' || NVL(v_ins_cnt, 0)
                           || ', persisted=' || NVL(v_live_cnt, 0) || ')' AS MSG
                         , 'SAVE_VERIFY' AS EVENT
                    FROM   DUAL;
                RETURN;
            END IF;
        END IF;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(N_LOG_COUNT) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
