            SET    ATTRIBUTE10 =
                   (SELECT BB.MEASURE
                    FROM   (SELECT DISTINCT A.DIVISION_ID, B.DIVISION_NAME, A.SCM_SITE_ID, A.VALID_YN, A.MEASURE, A.UPLOAD_UOM, A.UPLOAD_BUCKET_TYPE
