                    FROM   GT_SCFU_RESULTS G
                    WHERE  1 = 1
                    /* [V20260708-4] 치명 결함 수정 — GT_SCFU_RESULTS 컬럼은 V_ prefix.
                       무prefix 는 GT에 없어 외부 DM_PLN_CUSTOMER_PSI 자기참조(항상 참)로 해석
                       → 저장 1건에도 테이블 전체 삭제되던 버그. G.V_* 로 정확 상관. */
