            ,VALID_END_DATE
            ,MAPPING_ITEM_ID
            ,CREATED_BY
            ,CREATION_DATE
            ,LAST_UPDATED_BY
            ,LAST_UPDATE_DATE)
            SELECT T1.DIVISION_ID
