                BEGIN
                    FETCH CUR_CAR_RESULT
                        INTO V_DIVISION_ID
                            , V_CUSTOMER_PROJECT_CODE
                            , V_CUSTOMER_MODEL
                            , V_SCM_SITE_ID
                            , V_DOM_EXP
                            , V_FCST_TYPE
                            , V_MEASURE_GROUP
                            , V_MEASURE
                            , V_YYYYMMDD
                            , V_INCOTERMS
                            , V_PLANT_SITE_ID
                            , V_PROJECT_CODE
                            , V_ITEM_ID
                            , V_QTY
