                        -- WHEN SUMMARY_BUCKET_TYPE = 'MONTHLY' THEN TO_CHAR(ADD_MONTHS(TO_DATE(SUBSTR(TO_CHAR(MAX(SUMMARY_BUCKET_VALUE)),1,6)||'01','YYYYMMDD'), 1) - 1, 'YYYYMMDD')
