                DELETE FROM GT_DPCF_T2_DM_PLN_CUSTOMER_PSI; /* 원본 TRUNCATE→GTT는 DELETE(단일TX 원자성 보존·Oracle TRUNCATE 암묵COMMIT 회피) */
