    valid_item_id        VARCHAR2(32767);

    -- 사용자 정의 예외 (INVALID 상태 처리용)
    e_invalid_data EXCEPTION;

BEGIN

    /* [E20260824-SAVEGTTINIT] 스테이징 GTT 세션 초기화 (실측 결함 2026-08-24).
