BEGIN

	INSERT INTO GT_DMF0020_EXCH (DIVISION_ID, YYYYMMDD, CURRENCY, UNIT_CURRENCY, EXCHANGE_PRICE)
	SELECT DISTINCT A.DIVISION_ID, A.YYYYMMDD, A.CURRENCY, A.UNIT_CURRENCY, A.EXCHANGE_PRICE
	FROM DM_MST_EXCHANGE_RATE A
	JOIN GT_DMF0020_RESULTS_MST B
		ON A.DIVISION_ID	= B.v_DIVISION_ID
		AND A.YYYYMMDD		= SUBSTR(B.v_YYYYMMDD, 1, 6) || '01'
		AND A.CURRENCY		= 'KRW';

	-- LOC 동일값
		INSERT INTO GT_DMF0020_RESULTS_MST ( v_active_flag
									,v_DIVISION_ID
									,v_PROJECT_CODE
									,v_SCM_SITE_ID
									,v_PLANT_SITE_ID
									,v_ITEM_ID
									,v_YYYYMMDD
									,v_CURRENCY
									,v_MEASURE
									,v_DOM_EXP
									,v_FCST_TYPE
									,v_INCOTERMS
									,v_PRICE
									,v_CREATED_BY
									,v_CREATION_DATE
									,v_LAST_UPDATED_BY)
		SELECT v_active_flag
				,v_DIVISION_ID
				,v_PROJECT_CODE
				,v_SCM_SITE_ID
				,v_PLANT_SITE_ID
				,v_ITEM_ID
				,v_YYYYMMDD
				,v_CURRENCY
				,v_CURRENCY AS v_MEASURE
				,v_DOM_EXP
				,v_FCST_TYPE
				,v_INCOTERMS
				,v_PRICE
				,v_CREATED_BY
				,v_CREATION_DATE
				,v_LAST_UPDATED_BY
		FROM GT_DMF0020_RESULTS_MST A
		WHERE A.v_MEASURE = 'LOC'
		AND A.v_CURRENCY IN('KRW', 'USD');

		-- KRW값 구하기
		INSERT INTO GT_DMF0020_RESULTS_MST ( v_active_flag
									,v_DIVISION_ID
									,v_PROJECT_CODE
									,v_SCM_SITE_ID
									,v_PLANT_SITE_ID
									,v_ITEM_ID
									,v_YYYYMMDD
									,v_CURRENCY
									,v_MEASURE
									,v_DOM_EXP
									,v_FCST_TYPE
									,v_INCOTERMS
									,v_PRICE
									,v_CREATED_BY
									,v_CREATION_DATE
									,v_LAST_UPDATED_BY)
		SELECT v_active_flag
				,v_DIVISION_ID
				,v_PROJECT_CODE
				,v_SCM_SITE_ID
				,v_PLANT_SITE_ID
				,v_ITEM_ID
				,v_YYYYMMDD
				,v_CURRENCY
				,'KRW' AS v_MEASURE
				,v_DOM_EXP
				,v_FCST_TYPE
				,v_INCOTERMS
				--[E20260930-DMF0020FXZERO] 원문: ,ROUND(A.v_PRICE * B.EXCHANGE_PRICE, 3)
				,ROUND(A.v_PRICE * NVL(B.EXCHANGE_PRICE, 0), 3)   -- 환율 없으면 KRW 0
				,v_CREATED_BY
				,v_CREATION_DATE
				,v_LAST_UPDATED_BY
		FROM GT_DMF0020_RESULTS_MST A
		--[E20260930-DMF0020FXZERO] 원문: JOIN GT_DMF0020_EXCH B
		LEFT JOIN GT_DMF0020_EXCH B   -- 환율 없는 달도 KRW 행 생성
		ON B.UNIT_CURRENCY = A.v_CURRENCY
		AND B.YYYYMMDD = SUBSTR(A.v_YYYYMMDD, 1, 6) || '01'
		WHERE A.v_MEASURE = 'LOC'
		AND A.v_CURRENCY <> 'KRW';

		-- USD값 구하기
		INSERT INTO GT_DMF0020_RESULTS_MST ( v_active_flag
									,v_DIVISION_ID
									,v_PROJECT_CODE
									,v_SCM_SITE_ID
									,v_PLANT_SITE_ID
									,v_ITEM_ID
									,v_YYYYMMDD
									,v_CURRENCY
									,v_MEASURE
									,v_DOM_EXP
									,v_FCST_TYPE
									,v_INCOTERMS
									,v_PRICE
									,v_CREATED_BY
									,v_CREATION_DATE
									,v_LAST_UPDATED_BY)
		SELECT  v_active_flag
				,v_DIVISION_ID
				,v_PROJECT_CODE
				,v_SCM_SITE_ID
				,v_PLANT_SITE_ID
				,v_ITEM_ID
				,v_YYYYMMDD
				,v_CURRENCY
				,'USD' AS v_MEASURE
				,v_DOM_EXP
				,v_FCST_TYPE
				,v_INCOTERMS
				--[E20260930-DMF0020FXZERO] 원문: ,ROUND(A.v_PRICE / B.EXCHANGE_PRICE, 3)
				,CASE WHEN NVL(B.EXCHANGE_PRICE, 0) = 0 THEN 0 ELSE ROUND(A.v_PRICE / B.EXCHANGE_PRICE, 3) END   -- USD 환율 없으면 0
				,v_CREATED_BY
				,v_CREATION_DATE
				,v_LAST_UPDATED_BY
		FROM GT_DMF0020_RESULTS_MST A
		--[E20260930-DMF0020FXZERO] 원문: JOIN GT_DMF0020_EXCH B
		LEFT JOIN GT_DMF0020_EXCH B   -- 환율 없는 달도 USD 행 생성
		ON B.UNIT_CURRENCY = 'USD'
		AND B.YYYYMMDD = SUBSTR(A.v_YYYYMMDD, 1, 6) || '01'
		WHERE A.v_MEASURE = 'KRW'
		AND A.v_CURRENCY <> 'USD';
END;

	--###############################################   #results_MST 테이블에 split후 insert (END)
	       -- PROJECT_CODE 잘못들어왔을때 강제 에러발생시킴 start -----------------------------------------------
		   DECLARE
		       v_chk_cnt PLS_INTEGER;
		   BEGIN
		   IF v_DIVISION_ID <> '40' THEN

			   SELECT count(1) INTO v_chk_cnt
			     FROM GT_DMF0020_RESULTS_MST R
			    WHERE ( SELECT count(1) FROM scm_mst_project WHERE project_code = R.v_PROJECT_CODE ) = 0;

			   IF v_chk_cnt > 0 THEN
				   v_log_type := 'INVALID';
				   v_result_message := '['|| v_PROJECT_CODE ||']'|| ' Invalid Project Code !';
				   RAISE e_invalid_data;
			   END IF;


			   SELECT count(1) INTO v_chk_cnt
			     FROM GT_DMF0020_RESULTS_MST R
			    WHERE ( SELECT count(1) FROM SCM_MST_ITEM_SN WHERE ITEM_ID = R.v_ITEM_ID ) = 0;

			   IF v_chk_cnt > 0 THEN
				   v_log_type := 'INVALID';
				   v_result_message := '['|| v_ITEM_ID ||']'|| ' Invalid Item ID !';
				   RAISE e_invalid_data;
			   END IF;

				-- 20180814 KHSONG Invalid Site Item validation 추가
				valid_item_id := NULL;

		----------------------------------------------------------------------------------------------------------◎◎◎◎
			SELECT count(1) INTO v_chk_cnt
			  FROM GT_DMF0020_RESULTS_MST
			 WHERE v_division_id IN ('81','40');  -- 자동차,소형인경우

			IF v_chk_cnt > 0 THEN

					BEGIN
						SELECT A.v_item_id INTO valid_item_id
							FROM GT_DMF0020_RESULTS_MST A
							WHERE 1=1
							AND NOT EXISTS (SELECT  ITEM.division_id
												FROM scm_mst_site_item ITEM
													,DM_MST_ITEM_SINGLE_V SN
												where 1=1
 													and ITEM.division_id   = A.v_division_id
													and ITEM.PROJECT_CODE  = A.v_project_code
													and ITEM.scm_site_id   = A.v_scm_site_id
													and ITEM.ITEM_ID       = A.v_ITEM_ID
													and ITEM.division_id   = SN.division_id
													and ITEM.ITEM_ID       = SN.ITEM_ID
													and SN.ACTIVE_FLAG	   = 'Y'
													and ITEM.VALID_YN	   = 'Y'
													and ITEM.division_id IN ('81','40')
											  )
								AND A.v_division_id IN ('81','40')
								AND ROWNUM = 1;
					EXCEPTION
