              --  AND D.SCM_SITE_ID  = COALESCE(D.MAX_SCM_SITE_ID, '-') -- COALESCE 사용
              LEFT OUTER JOIN (SELECT EC.DIVISION_ID ,EC.SCM_SITE_ID ,EC.END_CUSTOMER
                                     ,MAX(EC.SCM_SITE_ID) AS MAX_SCM_SITE_ID
                               FROM   SCM_MGR.GT_DM35_EDI_END_CUST EC
