           , INCOTERMS, DOM_EXP, FCST_TYPE, MEASURE, MEASURE_GROUP, YYYYMMDD, QTY, PLAN_RESULT, GUBUN, CREATE_DATE
           , LAST_UPDATED_BY, SENDER_CODE, SENDER_NAME
