             , MAX(X.LAST_UPDATE_DATE), MAX(X.LAST_UPDATED_BY)
        FROM (
            SELECT A.VERSION_NO, A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE
                 --[E20241126-000426]_CUST_FCST 추가 START
