            WHERE A.DIVISION_ID = P_DIVISION_ID
            AND   A.QTY <> 0
            --[E20260820-VERPUSH] 동일 취지 — 아래 JOIN GT_DM35_VERSION C ON A.VERSION_NO = C.VERSION_NO 와 같은 집합
            AND   A.VERSION_NO IN (SELECT VERSION_NO FROM SCM_MGR.GT_DM35_VERSION)
            GROUP BY A.VERSION_NO, A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE
