             , A.MEASURE
             , CASE WHEN A.DIVISION_ID = '40' AND B.MEASURE_GROUP IS NULL THEN 'MKT_FCST_RP'
                    WHEN A.DIVISION_ID = '40' THEN B.MEASURE_GROUP
                    ELSE '' END AS MEASURE_GROUP
             , A.YYYYMMDD
             , A.QTY
             , 'P', 3
             --[E20260820-RAWSCALAR] 행별 상관 스칼라 서브쿼리 10개 → 선계산 LEFT JOIN 3본 치환 (hook #129 ① 최우선)
             --  근거(사내 플랜 g0w0gvnn7rkb2 실측): Id 2~20 이 전부 TABLE ACCESS FULL + filter only
             --    (access predicate 없음). 상관키가 8~9컬럼이라 스칼라 서브쿼리 캐시가 사실상 무효 →
             --    외부행마다 GT_DM35_T_LAST_SETUP_C 7회 + GT_DM35_EDI_SENDER 3회 전면스캔.
             --  치환 대상 뷰는 FROM 절 하단 LEFT JOIN 참조: LS_K(상관키별) / LS_M(상관키+MEASURE) / ES_S(SCM_SITE_ID).
             --  값 동등성: 세 뷰 모두 **조인키로 GROUP BY** 되어 키당 최대 1행 → 행 증식 0.
             --            NULL 키는 원본 상관 등호(= NULL)와 동일하게 미매칭 → NULL 반환.
             --[E20241126-000426]_CUST_FCST 추가 START
             --, (CASE WHEN A.MEASURE IN ('CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN
             , (CASE WHEN A.MEASURE IN ('CUST_FCST', 'CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN
             --[E20241126-000426]_CUST_FCST 추가 END
                     LS_K.CREATE_DATE_S1
                      --[E20241126-000426]_CUST_FCST 추가 START
                WHEN A.MEASURE IN ('CUST_FCST', 'CUSTOMER FCST') THEN
                     LS_K.CREATE_DATE_S2
                WHEN A.MEASURE IN ('RTF', 'RTF_SYS_RP', 'MKT_FCST') THEN
                     LS_K.CREATE_DATE_S3
                ELSE LS_M.CREATE_DATE
               END)
             , (CASE WHEN A.MEASURE IN ('CUST_FCST', 'Customer FCST') THEN
                     (CASE WHEN A.LAST_UPDATED_BY LIKE '%robot' THEN A.LAST_UPDATED_BY || '_RPA'
                           --[E20250325-000681]_CUST_FCST Measure LAST_UPDATE 생성 로직 변경
                           -- ELSE A.LAST_UPDATED_BY || '_EXCEL' END)
                           ELSE A.LAST_UPDATED_BY END)
                     --[E20241126-000426]_CUST_FCST 추가 START
                     --WHEN A.MEASURE IN ('CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN
                     WHEN A.MEASURE IN ('CUST_FCST', 'CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN
                     --[E20241126-000426]_CUST_FCST 추가 END
                     (CASE WHEN NVL(A.ATTRIBUTE5, '@#@#@#') = '@#@#@#' THEN
                                ES_S.SENDER_NAME || '_EDI'
                          ELSE A.ATTRIBUTE5 || '_' || A.LAST_UPDATED_BY END)
                WHEN A.MEASURE IN ('RTF', 'RTF_SYS_RP', 'MKT_FCST') THEN
                     LS_K.LAST_UPDATED_BY_S3
                ELSE LS_M.LAST_UPDATED_BY
               END)
             --[E20241126-000426]_CUST_FCST 추가 START
             --, (CASE WHEN A.MEASURE IN ('CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN
             , (CASE WHEN A.MEASURE IN ('CUST_FCST', 'CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN
             --[E20241126-000426]_CUST_FCST 추가 END
                     (CASE WHEN NVL(A.ATTRIBUTE4, '@#@#@#') = '@#@#@#' THEN
                                ES_S.SENDER_CODE
                          ELSE A.ATTRIBUTE4 END)
                ELSE NULL END)
             --[E20241126-000426]_CUST_FCST 추가 START
             --, (CASE WHEN A.MEASURE IN ('CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN
             , (CASE WHEN A.MEASURE IN ('CUST_FCST', 'CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN
             --[E20241126-000426]_CUST_FCST 추가 END
                     (CASE WHEN NVL(A.ATTRIBUTE5, '@#@#@#') = '@#@#@#' THEN
                                ES_S.SENDER_NAME
                          ELSE A.ATTRIBUTE5 END)
                ELSE NULL END)
             --[E20231121-000493] 82번사업부_mktFcstWaterfall 화면 내 AS From Site 추가 요청
             , CASE WHEN A.DIVISION_ID IN ('81', '82') THEN A.ATTRIBUTE10 ELSE NULL END AS AS_FROM_SITE
             --[E20250805-000706]_CELL_PROD_SITE_ID는 하단에서 다 처리함으로 A.CELL_PROD_SITE_ID로 쓰는게 맞다. 버그 수정 START
             --, '-' AS CELL_PROD_SITE_ID -- [PJ2025-50017] CELL_PROD_SITE_ID 추가
             , A.CELL_PROD_SITE_ID -- [PJ2025-50017] CELL_PROD_SITE_ID 추가
             --[E20250805-000706]_CELL_PROD_SITE_ID는 하단에서 다 처리함으로 A.CELL_PROD_SITE_ID로 쓰는게 맞다. 버그 수정 END
        FROM (
            SELECT F.DIVISION_ID, F.PROJECT_CODE, F.SCM_SITE_ID, F.PLANT_SITE_ID, F.ITEM_ID, F.DOM_EXP, F.FCST_TYPE, F.INCOTERMS, F.MEASURE, F.YYYYMMDD, F.QTY, F.ATTRIBUTE10, '-' AS CELL_PROD_SITE_ID -- [PJ2025-50017] CELL_PROD_SITE_ID 추가
                 , F.LAST_UPDATED_BY, F.LAST_UPDATE_DATE, F.ATTRIBUTE4, F.ATTRIBUTE5, F.ATTRIBUTE9, F.VERSION_NO, F.CUTOFF_TYPE, F.CUTOFF_YYYYMMDD
            FROM SCM_MGR.DM_PLN_MKT_FCST_C F WHERE (CASE WHEN P_DIVISION_ID = '40' THEN 1 ELSE 2 END) = 2
                --[E20260820-VERPUSH2] 버전 술어를 UNION ALL 분기 안으로 push — 아래 JOIN GT_DM35_VERSION 이
                --  이미 강제하는 조건의 중복 술어이므로 결과 불변. 원장 선두 인덱스(DIVISION_ID, VERSION_NO)
                --  를 access predicate 로 쓰게 해 전면스캔을 없앤다 (hook #129 ②/④ · 1차 VERPUSH 패치와 동일 처방).
                AND F.VERSION_NO IN (SELECT VERSION_NO FROM SCM_MGR.GT_DM35_VERSION)
            UNION ALL
            SELECT F.DIVISION_ID, F.PROJECT_CODE, F.SCM_SITE_ID, F.PLANT_SITE_ID, F.ITEM_ID, F.DOM_EXP, F.FCST_TYPE, F.INCOTERMS, F.MEASURE, F.YYYYMMDD, F.QTY, F.ATTRIBUTE10, F.CELL_PROD_SITE_ID -- [PJ2025-50017] CELL_PROD_SITE_ID 추가
                 , F.LAST_UPDATED_BY, F.LAST_UPDATE_DATE, F.ATTRIBUTE4, F.ATTRIBUTE5, F.ATTRIBUTE9, F.VERSION_NO, F.CUTOFF_TYPE, F.CUTOFF_YYYYMMDD
            FROM SCM_MGR.DM_PLN_CFM_MKT_DEMAND_PLAN_C F WHERE (CASE WHEN P_DIVISION_ID = '40' THEN 1 ELSE 2 END) = 1
                --[E20260820-VERPUSH2] 버전 술어를 UNION ALL 분기 안으로 push — 아래 JOIN GT_DM35_VERSION 이
                --  이미 강제하는 조건의 중복 술어이므로 결과 불변. 원장 선두 인덱스(DIVISION_ID, VERSION_NO)
                --  를 access predicate 로 쓰게 해 전면스캔을 없앤다 (hook #129 ②/④ · 1차 VERPUSH 패치와 동일 처방).
                AND F.VERSION_NO IN (SELECT VERSION_NO FROM SCM_MGR.GT_DM35_VERSION)
        ) A
        JOIN SCM_MGR.GT_DM35_SEL_MEASURE B ON A.MEASURE = B.MEASURE
        JOIN SCM_MGR.SCM_MST_SITE C ON A.DIVISION_ID = C.DIVISION_ID AND A.SCM_SITE_ID = C.SCM_SITE_ID AND C.VALID_YN = 'Y'
        JOIN SCM_MGR.GT_DM35_VERSION E
          ON A.VERSION_NO = E.VERSION_NO
         AND (E.VERSION_NO LIKE '%MF%' OR E.VERSION_NO LIKE '%SF%') --[PJ2025-50188] Version 팝업에서 SF를 선택해서 조회하기 위해서 %SF% 추가
        --[E20260820-RAWSCALAR] 상관 스칼라 대체 선계산 3본. 각 뷰가 조인키로 GROUP BY 되어 키당 1행 = 행 증식 없음.
        LEFT JOIN (SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, VERSION_NO
                        , MAX(CASE WHEN MEASURE IN ('CUST_FCST', 'CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN CREATE_DATE END) AS CREATE_DATE_S1
                        , MAX(CASE WHEN MEASURE IN ('CUST_FCST', 'CUSTOMER FCST') THEN CREATE_DATE END) AS CREATE_DATE_S2
                        , MAX(CASE WHEN MEASURE IN ('RTF', 'RTF_SYS_RP', 'MKT_FCST') THEN CREATE_DATE END) AS CREATE_DATE_S3
                        --  원본: MAX(LAST_UPDATED_BY) WHERE CREATE_DATE = (SELECT MAX(CREATE_DATE) … 동일키·동일 MEASURE 집합)
                        --  → 정렬키를 RTF 계열만 남긴 CREATE_DATE 로 두고 KEEP (DENSE_RANK LAST … NULLS FIRST).
                        --    · RTF 계열이 없으면 정렬키 전부 NULL → 집계 CASE 도 NULL → 원본과 동일하게 NULL
                        --    · RTF 계열은 있으나 CREATE_DATE 가 전부 NULL 이면 원본 등호(= NULL)가 미성립 → NULL.
                        --      집계 CASE 의 CREATE_DATE IS NOT NULL 조건이 같은 NULL 을 만든다
                        --    · 그 외에는 NULLS FIRST 로 최대 CREATE_DATE 그룹이 마지막 → 원본 등호 대상과 동일 집합
                        , MAX(CASE WHEN MEASURE IN ('RTF', 'RTF_SYS_RP', 'MKT_FCST') AND CREATE_DATE IS NOT NULL THEN LAST_UPDATED_BY END)
                              KEEP (DENSE_RANK LAST ORDER BY CASE WHEN MEASURE IN ('RTF', 'RTF_SYS_RP', 'MKT_FCST') THEN CREATE_DATE END NULLS FIRST) AS LAST_UPDATED_BY_S3
                     FROM SCM_MGR.GT_DM35_T_LAST_SETUP_C
                    GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, VERSION_NO) LS_K
               ON  LS_K.DIVISION_ID = A.DIVISION_ID
               AND LS_K.PROJECT_CODE = A.PROJECT_CODE
               AND LS_K.SCM_SITE_ID = A.SCM_SITE_ID
               AND LS_K.ITEM_ID = A.ITEM_ID
               AND LS_K.DOM_EXP = A.DOM_EXP
               AND LS_K.FCST_TYPE = A.FCST_TYPE
               AND LS_K.INCOTERMS = A.INCOTERMS
               AND LS_K.VERSION_NO = A.VERSION_NO
        LEFT JOIN (SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, VERSION_NO, MEASURE
                        --  원본 ELSE 분기는 비집계 스칼라(키+MEASURE 유일 전제, 중복이면 원본은 ORA-01427).
                        --  MAX() 로 감싸 행 증식을 원천 차단 — 유일할 때 값은 원본과 동일.
                        , MAX(CREATE_DATE) AS CREATE_DATE, MAX(LAST_UPDATED_BY) AS LAST_UPDATED_BY
                     FROM SCM_MGR.GT_DM35_T_LAST_SETUP_C
                    GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, VERSION_NO, MEASURE) LS_M
               ON  LS_M.DIVISION_ID = A.DIVISION_ID
               AND LS_M.PROJECT_CODE = A.PROJECT_CODE
               AND LS_M.SCM_SITE_ID = A.SCM_SITE_ID
               AND LS_M.ITEM_ID = A.ITEM_ID
               AND LS_M.DOM_EXP = A.DOM_EXP
               AND LS_M.FCST_TYPE = A.FCST_TYPE
               AND LS_M.INCOTERMS = A.INCOTERMS
               AND LS_M.VERSION_NO = A.VERSION_NO
               AND LS_M.MEASURE = A.MEASURE
        LEFT JOIN (SELECT SCM_SITE_ID, MAX(SENDER_CODE) AS SENDER_CODE, MAX(SENDER_NAME) AS SENDER_NAME
                     FROM SCM_MGR.GT_DM35_EDI_SENDER GROUP BY SCM_SITE_ID) ES_S
               ON  ES_S.SCM_SITE_ID = A.SCM_SITE_ID
        WHERE A.YYYYMMDD >= P_FROM_YYYYMMDD AND A.YYYYMMDD <= P_TO_YYYYMMDD
        AND   A.YYYYMMDD >= E.NOW_YYYYMMDD
        AND   A.DIVISION_ID = P_DIVISION_ID
        AND   A.MEASURE NOT IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
        AND   A.QTY <> 0;


        N_LOG_COUNT   := SQL%ROWCOUNT;
        V_LOG_TYPE    := 'INFO';
        V_LOG_MESSAGE := 'E12--GT_DM35_RAW_DATA';
        D_EVENT_DATE  := SYSDATE;
        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

        --[E20241126-000426]_ORG 데이터는 보여주지 않기로 했으므로 주석처리한다. START
