                 , (CASE WHEN A.MEASURE IN ('CUST_FCST_EDI', 'CUST_FCST', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder'
