            -- [hook#150 2026-09-06 AJS] AS-IS: WHERE  SU.USER_ID = (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(A.OWNER,',')) P WHERE ROWNUM = 1)) AS DEPT_ID
