          )
    SELECT B.SCM_SITE_ID, B.DIVISION_ID, B.PROJECT_CODE, B.ITEM_ID, B.DEPT_ID
         , K.SOLDTO_CODE, B.VMI_YN, B.END_CUSTOMER, B.SOLDTO_CUSTOMER
