    IF V_I_COUNT = 0
    THEN
        SELECT LISTAGG(' ' || COLUMN_NAME || ',', '') WITHIN GROUP (ORDER BY SORT_ORDER_NO)
             , LISTAGG(' ' || COLUMN_NAME || ' ' || DATA_SORT_METHOD_CODE || ',', '') WITHIN GROUP (ORDER BY SORT_ORDER_NO)
        INTO   V_COL_LIST, V_ORDER_LIST
        FROM (
