    V_COL_LIST   := V_COL_LIST || ',NOTATION';

    --[E20260909-MEASURECOL] MEASURE 컬럼 보장 — T_WF_DATA 는 컬럼목록(V_COL_LIST)을 사전과 조인해
    --  SELECT 를 만드는데, 아래 집계부는 F.MEASURE 를 **무조건** 참조한다(BALANCE/VMI_Inv/AS_Inv/
    --  SS_LVL/SS_GAP 주말값 처리 + LOC 평균 분기). 그런데 'C' 개인화가 있는 사용자는 위 ELSE 분기의
    --  NOT IN ('MEASURE','VERSION_NO') 때문에 MEASURE 가 목록에서 빠지고, 바로 아래 REPLACE 도
    --  치환 대상이 없어 무동작 → T_WF_DATA 에 MEASURE 부재 → ORA-00904 "F"."MEASURE".
    --  개인화가 없는 사용자는 IF 분기(SHEET_COLUMNS DEFAULT_FLAG='Y')로 MEASURE 가 들어와 무증상이라
    --  [E20260909-SHEETUNIFY] 로 titleset 시트명이 실등록명으로 바뀌면서 비로소 드러났다(A/B 실증).
    --  MEASURE 는 표시축이자 집계 grain 이므로 목록 말미에 보장 삽입한다(정렬은 REPLACE 규약이 담당).
    IF INSTR(',' || REPLACE(REPLACE(V_COL_LIST, ' ', ''), CHR(10), '') || ',', ',MEASURE,') = 0 THEN
        V_COL_LIST := V_COL_LIST || ',MEASURE';
        --[E20260917-MEASUREORDER] 정렬축도 함께 보강 (사용자 신고 2026-09-17 — MEASURE POPUP 순서 미반영).
        --  아래 [E20260916-VERCOL] VERSION_NO 가드와 **동형**이다. 종전에는 V_COL_LIST 에만 넣어
        --  L3082 `REPLACE(V_ORDER_LIST,'MEASURE','SORT_ORDER_NO')` 가 치환 대상을 못 찾고 무동작 →
        --  ORDER BY 에 SORT_ORDER_NO 가 빠져 메저 순서가 비결정이었다('C' 개인화 사용자 한정 증상).
        --  위치(말미)는 개인화 없는 경로와 동일하다 — SHEET_COLUMNS MEASURE SORT_ORDER_NO=999 = 최후미.
        V_ORDER_LIST := CASE WHEN V_ORDER_LIST IS NULL OR LENGTH(TRIM(V_ORDER_LIST)) = 0
                             THEN 'MEASURE ASC' ELSE V_ORDER_LIST || ',MEASURE ASC' END;
    END IF;

    --[E20260916-VERCOL] ② VERSION_NO 보장 — MEASURECOL(2026-09-09) 동형 가드.
    --  사용자가 Column Setting 에서 VERSION 을 끈 경우에도 목록에 없으면 보강한다.
    --  FE 는 VERSION_NO 를 FORCED_AXIS 로 선언해(waterfall.columns.ts) '컬럼 설정으로도 끌 수 없는'
    --  행 축으로 취급하므로 SP 도 같은 계약을 지킨다. 정렬축(V_ORDER_LIST)도 함께 보강해야
    --  AS-IS 규약(VERSION_SORT DESC)이 살아난다 — 바로 아래 REPLACE 가 확장한다.
    --  위치는 ①(개인화 자리)과 동일하게 목록 말미로 맞춘다.
    IF INSTR(',' || REPLACE(REPLACE(V_COL_LIST, ' ', ''), CHR(10), '') || ',', ',VERSION_NO,') = 0 THEN
        V_COL_LIST   := V_COL_LIST || ',VERSION_NO';
        V_ORDER_LIST := CASE WHEN V_ORDER_LIST IS NULL OR LENGTH(TRIM(V_ORDER_LIST)) = 0
                             THEN 'VERSION_NO ASC' ELSE V_ORDER_LIST || ',VERSION_NO ASC' END;
    END IF;

    V_COL_LIST   := REPLACE(V_COL_LIST,   'VERSION_NO', 'VERSION_SORT,VERSION_NO');
    V_COL_LIST   := REPLACE(V_COL_LIST,   'MEASURE',    'MEASURE_GROUP,MEASURE,SORT_ORDER_NO');
    V_ORDER_LIST := REPLACE(V_ORDER_LIST, 'VERSION_NO', 'VERSION_SORT DESC,VERSION_NO');
    V_ORDER_LIST := REPLACE(V_ORDER_LIST, 'MEASURE',    'SORT_ORDER_NO');

