            ) VALUES (
                                     v_active_flag
                                    ,v_division_id
                                    ,v_YYYYMMDD
                                    ,v_CURRENCY
                                    ,v_UNIT_CURRENCY
                                    ,v_EXCHANGE_PRICE
                                    ,v_CREATED_BY
                                    ,v_LAST_UPDATED_BY
            );
    ELSE
            -- [20260805 SPLIT-FIX] 도달 불가 잔존 분기(모든 토큰이 '^' 종결) — 만약 도달 시 무한루프 방어
            v_DIVISION_ID := p_DIVISION_ID;
            v_recv_division_id := NULL;

            INSERT INTO GT_SDBE_RESULTS (
                                     active_flag
