                END IF;
END LOOP;

    --###############################################   GT_SDBE_RESULTS 테이블에 split후 insert (END)
--===================================================================================== DELETE FROM start
BEGIN
           --  select * from GT_SDBE_RESULTS
           DELETE
           FROM DM_BP_EXCHANGE_RATE
           WHERE exists(
                    SELECT DIVISION_ID
                      FROM GT_SDBE_RESULTS
                     where active_flag      = 'D'
