                       AND DM_BP_EXCHANGE_RATE.UNIT_CURRENCY      =   UNIT_CURRENCY
                  );
END;
--===================================================================================== DELETE FROM end
--===================================================================================== update, INSERT INTO start

                    MERGE INTO DM_BP_EXCHANGE_RATE A
                    USING (
                            SELECT
                                     division_id
                                    , YYYYMMDD
                                    , CURRENCY
                                    , UNIT_CURRENCY
