        /* 원본 : V_IN_PARA_DATA VARCHAR2(4000); */
        V_IN_PARA_DATA          VARCHAR2(32767);
        /* 2026.08.26 AJS 아이템 마스터 임시 테이블 생성 여부 판단용 */
        V_CNT_DIV81             INTEGER := 0;
        -- 선언부에 추가
        V_RC1_SUB SYS_REFCURSOR;
        V_RC2_SUB SYS_REFCURSOR;
        V_RESULT_CURSOR_SUB SYS_REFCURSOR;
