        --    v_CELL_PER_MODULE VARCHAR2(4000 CHAR);
        --    v_MODULE_PER_PACK VARCHAR2(4000 CHAR);
        -- 20190830 변수 추가 (END)
        -- -----------------------------------------------------------------------------------------------
