                V_ITEM_USE  := SUBSTR(VP_ITEM_USE, 1, V_INDEX_ITEM_USE - 1);
                VP_ITEM_USE := SUBSTR(VP_ITEM_USE, V_INDEX_ITEM_USE + 1);

