                VP_CELL_PROD_SITE := SUBSTR(VP_CELL_PROD_SITE, V_INDEX_CELL_PROD_SITE + 1);
                -- -----------------------------------------------------------------------------------------------
                --[E20240731-000845]_[공급 SCM PI팀] Business Plan 저장 관련 소스 수정 요청 (START)
                -- 화면에서 코드를 넘기는 것으로 변경했으므로, 더이상 필요없는 작업이므로 주석처리해서 막음
                /*
