                V_LAST_UPDATED_BY  := SUBSTR(VP_LAST_UPDATED_BY, 1, V_INDEX_LAST_UPDATED_BY - 1);
                VP_LAST_UPDATED_BY := SUBSTR(VP_LAST_UPDATED_BY, V_INDEX_LAST_UPDATED_BY + 1);

