                          , CELL_PROD_SITE
                           -- 20190830 추가 (END)
                           -- -----------------------------------------------------------------------------------------------
                          , CREATED_BY
                          , LAST_UPDATED_BY
                    FROM   GT_SDPB2_BP_FCST_4 TMP
