    OPEN O_RC1 FOR
    SELECT
        T1.DIVISION_ID
        , CURRENCY
        , UNIT_CURRENCY
        , CURRENCY || '/' || UNIT_CURRENCY AS CURRENCY_UNITCURRENCY
        , NVL(T2.EDIT_YN,'N') AS EDIT_YN
    FROM DM_PLN_SALES_REPORT_EXCHANGE_C T1
        --[E20260820-EXAUTH] 권한 뷰 INNER JOIN 은 편집권한을 조회 필터로 만들어 AS-IS 에 없던 행 탈락을 낳는다
