        T1.DIVISION_ID
        , CURRENCY
        , UNIT_CURRENCY
        , CURRENCY || '/' || UNIT_CURRENCY AS CURRENCY_UNITCURRENCY
        , NVL(T2.EDIT_YN,'N') AS EDIT_YN
    FROM DM_PLN_SALES_REPORT_EXCHANGE_C T1
