                    SELECT TO_NUMBER(QTY) INTO V_ADJQTY FROM SCM_MGR.GT_0044_RESULTS_MST_C WHERE SEQ_RANK = V_I AND MEASURE = 'SalesAmt_LOC' AND ROWNUM = 1;

