                                AND B.END_CUST_REPORT = A.END_CUST_REPORT AND B.CUST_REPORT = A.CUST_REPORT AND B.PRODUCT_GROUP = A.PRODUCT_GROUP
                                AND B.PROJECT_CODE = A.PROJECT_CODE AND B.SCM_SITE_ID = A.SCM_SITE_ID AND B.ITEM_ID = A.ITEM_ID
                                AND A.YYYYMMDD LIKE SUBSTR(B.YYYYMMDD,1,6)||'%' AND B.CURRENCY = A.CURRENCY AND B.COMPANY_ID = A.COMPANY_ID AND B.CELL_PROD_SITE = A.CELL_PROD_SITE AND B.FCST_TYPE = A.FCST_TYPE AND B.INCOTERMS = A.INCOTERMS AND B.PLANT_SITE_ID = A.PLANT_SITE_ID /*[E20260911-CELLPRODKEY]*/
                                AND B.MEASURE = A.MEASURE AND B.SEQ_RANK = V_I);
