                        SELECT '1', NVL(A.DIVISION_ID, '-'), NVL(A.VERSION_NO, '-'), A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD, NVL(A.DEPARTMENT_ID, '-'), NVL(A.DEPARTMENT_NAME, '-'), NVL(A.DEPT_ID, '-'), NVL(A.DEPT_NAME, '-'), NVL(A.END_CUST_REPORT, '-')
