							, NVL(A.PROJECT_CODE, '-'), NVL(A.FCST_TYPE, '-'), NVL(A.PLANT_SITE_ID, '-'), NVL(A.ITEM_ID, '-'), NVL(A.SCM_SITE_ID, '-')
