        --SRESULT: 소형수주 수주기간내 전체 SUM / SPLAN: 소형수주 수주기간내 전체 PLAN
        --계획구간: DM_PLN_BP_FCST_C / 실적구간: DM_PLN_SALES_PLAN_RESULT
        INSERT INTO SCM_MGR.GT_DM68_ORD_BRESULT_BPLAN
        (
