                            SELECT 'PLAN' AS GUBUN, B.DIVISION_ID, B.PROJECT_CODE, PJT_IFO.PROJECT_INFO, B.SCM_SITE_ID, B.ITEM_ID, '' AS ORG_MEASURE, B.YYYYMM
                                 , 0 AS SRESULT
