    END IF;

    OPEN O_RC1 FOR
        SELECT L.DIVISION_ID
             , D.DIVISION_NAME
             , L.SCM_SITE_ID
             , L.LOCATION_CODE
             , L.LOCATION_DESCRIPTION
             , L.STORAGE_ID
