             , SCM_MGR.SCM_MST_DIVISION  D
        WHERE  L.DIVISION_ID     = D.DIVISION_ID
        AND    L.LOCATION_CODE   = L.LOCATION_CODE
        AND    L.STORAGE_ID      IS NOT NULL
        -- CASE WHEN ALL → OR IN 분해
        AND    (
