    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_VENDOR_CODE' VALUE P_VENDOR_CODE,
            'P_VENDOR_NAME' VALUE P_VENDOR_NAME,
            'P_PAKER'       VALUE P_PAKER
        );
        V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); END;
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );

END P_SCM0002_GET_VENDOR_POPUP;

/* ============================================================
   1. SCM0002_GET_VERSIONBYWATERFALLPOPUP
   ============================================================ */
PROCEDURE P_SCM0002_GET_VERSIONBYWATERFALLPOPUP
(
    P_START_YYYYMMDD  IN VARCHAR2,
    P_END_YYYYMMDD    IN VARCHAR2,
    P_CREATED_BY      IN VARCHAR2,
    P_DIVISION_ID     IN VARCHAR2,
    P_VERSION_TYPE    IN VARCHAR2,
    P_VERSION_NO      IN VARCHAR2,
    O_RC1             OUT SYS_REFCURSOR,
    O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
AS
/************************************************************************************************
 Program ID  : DM0035_GET_SPREAD_TITLE
 Description : Procedure 작성 가이드
 Usage       : Procedure 작성 시 참조하세요!
 Parameter   :

-------------------------------------------------------------------------------------------------
 Date        In Charge    Description
-------------------------------------------------------------------------------------------------
 2018/03/12  SeungJae.Hwnag       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 20200714     P.C.I       [PJ20200138] Created_by 'WITHOUT_SP_W' 는 제외(화요일에 Sales Paln Cutoff 제외하고 생성된 SP Version)
 20200722     P.C.I       [PJ20200138] Created_by 'WITHOUT_SP_W' 는 제외 원복
 2021/07/03   HWI1993   하반기과제 속도개선 - 데이터 이동보관 처리
 2021/12/13     kdw2819   [과제 ]EDI Waterfall 조회 조건 추가
 2022/02/24   kdw2819   [과제][PJ20216891R] LGES Digital SCM 3 Level 가속화를 위한 개선 - BMW EDI WATERFALL
 2022/06/07     kdw2819   business plan waterfall
 2022/06/22     kdw2819   [C20220620-000557] GSCM DM 영역내, Version에 주차표기
 2022/09/30     rosia27   [C20220929-000333] Plan이 없는 휴무 주차에는 PLAN명 뒤에 (NO PLAN)을 기입
 2023/05/03   kdmcc14 [EDI과제]
 2025/02/20   dsiol     [PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선          -- 1. MF_SP 추가
 2025/04/23   dsiol     [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : SCM_FCST - MEASURE 추가 -- 1. MF_SP를 MF_SP_SF으로 변경 / 2. MF_SF 추가
 2026.03.31   kimcd     [PJ20264226] NextSCM Pilot 설계 및 개발.
******************************************************************************************************/
    V_PROGRAM_NAME    VARCHAR2(200  CHAR);
    V_VERSION_TYPE    VARCHAR2(100  CHAR);

    V_PROC_INPUT      VARCHAR2(4000 CHAR);
    V_BACKTRACE       VARCHAR2(4000 CHAR);
    V_SQL_CODE        VARCHAR2(100  CHAR);
    V_SQL_ERRMSG      VARCHAR2(1000 CHAR);
    V_LOG_TYPE        VARCHAR2(100  CHAR);
    V_LOG_MESSAGE     VARCHAR2(4000 CHAR);
    V_DESCRIPTION     VARCHAR2(4000 CHAR);
    N_LOG_COUNT       PLS_INTEGER        := 0;
    D_EVENT_DATE      DATE               := SYSDATE;

BEGIN
    -- 프로그램명 설정 (패키지 바디 이관 시 패키지명.프로시저명 자동 기록)
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    -- [과제 ]EDI Waterfall 조회 조건 추가 - EDI VERSION 조회시 CURRENT 제외
    IF INSTR(P_VERSION_TYPE, 'EC') != 0 THEN
        V_DESCRIPTION := 'EC IN CASE';

        OPEN O_RC1 FOR
            SELECT VERSION_NO AS CODE
                 , VERSION_NO || '(' || B.WEEK_NAME || ')' AS VERSION_NO
                 , VERSION_DESCRIPTION
                 , VERSION_TYPE
                 , 'N'  AS EDI_APPLY
                 , VER_CRE_SEQ
                 , YYYYMMDD
                 , MAX(CREATED_BY)      AS CREATED_BY
                 , MAX(CREATION_DATE)   AS CREATION_DATE
            FROM   SCM_MGR.DM_MST_VERSION     A
            INNER JOIN SCM_MGR.SCM_SYS_CALENDAR_M B ON A.YYYYMMDD = B.BASIS_YYYYMMDD
            WHERE  (YYYYMMDD >= P_START_YYYYMMDD AND YYYYMMDD <= P_END_YYYYMMDD)
            AND    DIVISION_ID IN (
                       SELECT TRIM(REGEXP_SUBSTR(P_DIVISION_ID, '[^,]+', 1, LEVEL))
                       FROM   DUAL
                       CONNECT BY REGEXP_SUBSTR(P_DIVISION_ID, '[^,]+', 1, LEVEL) IS NOT NULL
                   )
            AND    VERSION_TYPE IN (
                       SELECT TRIM(REGEXP_SUBSTR(P_VERSION_TYPE, '[^,]+', 1, LEVEL))
                       FROM   DUAL
                       CONNECT BY REGEXP_SUBSTR(P_VERSION_TYPE, '[^,]+', 1, LEVEL) IS NOT NULL
                   )
            AND    EXISTS (
                       SELECT 1
                       FROM   (
                                  SELECT TRIM(REGEXP_SUBSTR(P_VERSION_NO, '[^,]+', 1, LEVEL)) AS TOKEN
                                  FROM   DUAL
                                  CONNECT BY REGEXP_SUBSTR(P_VERSION_NO, '[^,]+', 1, LEVEL) IS NOT NULL
                              ) P
                       WHERE  VERSION_NO LIKE P.TOKEN || '%'
                   )
            AND    ( NVL(ATTRIBUTE1, '') <> 'MOVE' OR ATTRIBUTE1 IS NULL )
            --AND CREATED_BY <> 'WITHOUT_SP_W' -- [PJ20200138] Created_by 'WITHOUT_SP_W' 는 제외
            GROUP BY VERSION_NO, VERSION_DESCRIPTION, VERSION_TYPE, VER_CRE_SEQ, YYYYMMDD, B.WEEK_NAME
            ORDER BY CODE DESC, VERSION_NO DESC;

    ELSIF INSTR(P_VERSION_TYPE, 'BP') != 0 THEN
        V_DESCRIPTION := 'BP IN CASE';

        OPEN O_RC1 FOR
            SELECT 'BP_Z_CURRENT' AS CODE
                 , 'Current'      AS VERSION_NO
                 , 'Current'      AS VERSION_DESCRIPTION
                 , ''             AS VERSION_TYPE
                 , ''             AS EDI_APPLY
                 , CASE WHEN 1 = 2 THEN 1 ELSE NULL END AS VER_CRE_SEQ
                 , ''             AS YYYYMMDD
                 , ''             AS CREATED_BY
                 , SYSDATE        AS CREATION_DATE
            FROM   DUAL
            UNION ALL
            SELECT VERSION_NO AS CODE
                 , VERSION_NO || '(' || B.WEEK_NAME || ')' AS VERSION_NO
                 , VERSION_DESCRIPTION
                 , VERSION_TYPE
                 , 'N'         AS EDI_APPLY
                 , VER_CRE_SEQ
                 , YYYYMMDD
                 , CREATED_BY
                 , CREATION_DATE
            FROM   SCM_MGR.DM_MST_VERSION     A
            INNER JOIN SCM_MGR.SCM_SYS_CALENDAR_M B ON A.YYYYMMDD = B.BASIS_YYYYMMDD
            WHERE  (YYYYMMDD >= P_START_YYYYMMDD AND YYYYMMDD <= P_END_YYYYMMDD)
            AND    DIVISION_ID = P_DIVISION_ID
            AND    VERSION_TYPE IN (
                       SELECT TRIM(REGEXP_SUBSTR(P_VERSION_TYPE, '[^,]+', 1, LEVEL))
                       FROM   DUAL
                       CONNECT BY REGEXP_SUBSTR(P_VERSION_TYPE, '[^,]+', 1, LEVEL) IS NOT NULL
                   )
            AND    ( P_VERSION_NO IS NULL OR VERSION_DESCRIPTION LIKE P_VERSION_NO || '%' )  --[E20260806-WF] 설명 NULL 행 탈락 정정(검색어 없으면 전 행)
            AND    ( NVL(ATTRIBUTE1, '') <> 'MOVE' OR ATTRIBUTE1 IS NULL )
            ORDER BY CODE DESC, VERSION_NO DESC;

    ELSIF INSTR(P_VERSION_TYPE, 'MF_SP_SF') != 0 THEN  --[PJ2025-50188] MF_SP를 MF_SP_SF으로 변경
                                                         -- 작성기준 DMF0082_FcstNPrice_Mgmt.cs 에서 호출
        V_DESCRIPTION := 'MF_SP_SF IN CASE';

        V_VERSION_TYPE := '';
        --EXEC SCM0002_GET_VERSIONBYWATERFALLPOPUP '20250101','20250531','test','40','MF_SP_SF_D,MF_SP_SF_W,MF_SP_SF_M',''
        IF INSTR(P_VERSION_TYPE, 'MF_SP_SF_D') != 0 THEN
            V_VERSION_TYPE := 'SP_D,MF_D,SF_D,';
        END IF;
        IF INSTR(P_VERSION_TYPE, 'MF_SP_SF_W') != 0 THEN
            V_VERSION_TYPE := V_VERSION_TYPE || 'SP_W,MF_W,SF_W,';
        END IF;
        IF INSTR(P_VERSION_TYPE, 'MF_SP_SF_M') != 0 THEN
            V_VERSION_TYPE := V_VERSION_TYPE || 'SP_M,MF_M,SF_M,';
        END IF;

        -- LEFT(@V_VERSION_TYPE, LEN(@V_VERSION_TYPE)-1) → 마지막 쉼표 제거
        V_VERSION_TYPE := SUBSTR(V_VERSION_TYPE, 1, LENGTH(V_VERSION_TYPE) - 1);

        OPEN O_RC1 FOR
            SELECT * FROM (
                SELECT 'CURRENT' AS CODE
                     , 'Current' AS VERSION_NO
                     , 'Current' AS VERSION_DESCRIPTION
                     , ''        AS VERSION_TYPE
                     , ''        AS EDI_APPLY
                     , CASE WHEN 1 = 2 THEN 1 ELSE NULL END AS VER_CRE_SEQ
                     , ''        AS YYYYMMDD
                     , ''        AS CREATED_BY
                     , SYSDATE   AS CREATION_DATE
                FROM   DUAL
                UNION ALL
                SELECT VERSION_NO AS CODE
                     , CASE WHEN C.DM_RTF_YN = 'N'
                                 THEN VERSION_NO || '(' || B.WEEK_NAME || ') (NO PLAN)'
                                 ELSE VERSION_NO || '(' || B.WEEK_NAME || ')'
                            END AS VERSION_NO
                     , VERSION_DESCRIPTION
                     , VERSION_TYPE
                     , CASE WHEN VERSION_TYPE = 'ME_S' THEN 'Y' ELSE 'N' END AS EDI_APPLY
                     , VER_CRE_SEQ
                     , YYYYMMDD
                     , MAX(CREATED_BY)      AS CREATED_BY
                     , MAX(CREATION_DATE)   AS CREATION_DATE
                FROM   SCM_MGR.DM_MST_VERSION       A
                INNER JOIN SCM_MGR.SCM_SYS_CALENDAR_M B ON A.YYYYMMDD = B.BASIS_YYYYMMDD
                LEFT  JOIN SCM_MGR.SCP_PLN_INTERFACE_YN C
                       ON  A.DIVISION_ID       = C.DIVISION_ID
                       AND B.BASIS_START_DATE  = C.PLAN_START_YYYYMMDD
                WHERE  (YYYYMMDD >= P_START_YYYYMMDD AND YYYYMMDD <= P_END_YYYYMMDD)
                AND    A.DIVISION_ID IN (
                           SELECT TRIM(REGEXP_SUBSTR(P_DIVISION_ID, '[^,]+', 1, LEVEL))
                           FROM   DUAL
                           CONNECT BY REGEXP_SUBSTR(P_DIVISION_ID, '[^,]+', 1, LEVEL) IS NOT NULL
                       )
                AND    VERSION_TYPE IN (
                           SELECT TRIM(REGEXP_SUBSTR(V_VERSION_TYPE, '[^,]+', 1, LEVEL))
                           FROM   DUAL
                           CONNECT BY REGEXP_SUBSTR(V_VERSION_TYPE, '[^,]+', 1, LEVEL) IS NOT NULL
                       )
                AND    EXISTS (
                           SELECT 1
                           FROM   (
                                      SELECT TRIM(REGEXP_SUBSTR(P_VERSION_NO, '[^,]+', 1, LEVEL)) AS TOKEN
                                      FROM   DUAL
                                      CONNECT BY REGEXP_SUBSTR(P_VERSION_NO, '[^,]+', 1, LEVEL) IS NOT NULL
                                  ) P
                           WHERE  VERSION_NO LIKE P.TOKEN || '%'
                       )
                AND    ( NVL(ATTRIBUTE1, '') <> 'MOVE' OR ATTRIBUTE1 IS NULL )
                --AND CREATED_BY <> 'WITHOUT_SP_W' -- [PJ20200138] Created_by 'WITHOUT_SP_W' 는 제외
                GROUP BY VERSION_NO, VERSION_DESCRIPTION, VERSION_TYPE, VER_CRE_SEQ, YYYYMMDD, B.WEEK_NAME, C.DM_RTF_YN
            ) A
            --팝업에 표시되는 기준 CURRENT가 제일 위, 그 다음은 코드에 상관없이 최근 생성 시간순으로 정렬 (필요시 아래 참고해서 변경바람)
            ORDER BY CASE WHEN CODE = 'CURRENT'          THEN 1  --팝업에 표시되는 순서1
                          --WHEN INSTR(CODE,'SP') <> 0   THEN 2  --팝업에 표시되는 순서2
                          --WHEN INSTR(CODE,'MF') <> 0   THEN 3  --팝업에 표시되는 순서3
                          --WHEN INSTR(CODE,'SF') <> 0   THEN 4  --팝업에 표시되는 순서4
                          ELSE 5
                          --END, VERSION_NO DESC
                     END, CREATION_DATE DESC;

    ELSIF INSTR(P_VERSION_TYPE, 'MF_SF') != 0 THEN  --[PJ2025-50188] 2. MF_SF 추가
                                                      -- 작성기준 DMF0035_MktFcstWaterfall.cs 에서 호출
        V_DESCRIPTION := 'MF_SF IN CASE';

        V_VERSION_TYPE := '';
        --EXEC SCM0002_GET_VERSIONBYWATERFALLPOPUP '20250101','20250531','test','40','MF_SF_D,MF_SF_W,MF_SF_M',''
        IF INSTR(P_VERSION_TYPE, 'MF_SF_D') != 0 THEN
            V_VERSION_TYPE := 'MF_D,SF_D,';
        END IF;
        IF INSTR(P_VERSION_TYPE, 'MF_SF_W') != 0 THEN
            V_VERSION_TYPE := V_VERSION_TYPE || 'MF_W,SF_W,';
        END IF;
        IF INSTR(P_VERSION_TYPE, 'MF_SF_M') != 0 THEN
            V_VERSION_TYPE := V_VERSION_TYPE || 'MF_M,SF_M,';
        END IF;

        V_VERSION_TYPE := SUBSTR(V_VERSION_TYPE, 1, LENGTH(V_VERSION_TYPE) - 1);

        OPEN O_RC1 FOR
            SELECT * FROM (
                SELECT 'CURRENT' AS CODE
                     , 'Current' AS VERSION_NO
                     , 'Current' AS VERSION_DESCRIPTION
                     , ''        AS VERSION_TYPE
                     , ''        AS EDI_APPLY
                     , CASE WHEN 1 = 2 THEN 1 ELSE NULL END AS VER_CRE_SEQ
                     , ''        AS YYYYMMDD
                     , ''        AS CREATED_BY
                     , SYSDATE   AS CREATION_DATE
                FROM   DUAL
                UNION ALL
                SELECT VERSION_NO AS CODE
                     , CASE WHEN C.DM_RTF_YN = 'N'
                                 THEN VERSION_NO || '(' || B.WEEK_NAME || ') (NO PLAN)'
                                 ELSE VERSION_NO || '(' || B.WEEK_NAME || ')'
                            END AS VERSION_NO
                     , VERSION_DESCRIPTION
                     , VERSION_TYPE
                     , CASE WHEN VERSION_TYPE = 'ME_S' THEN 'Y' ELSE 'N' END AS EDI_APPLY
                     , VER_CRE_SEQ
                     , YYYYMMDD
                     , MAX(CREATED_BY)      AS CREATED_BY
                     , MAX(CREATION_DATE)   AS CREATION_DATE
                FROM   SCM_MGR.DM_MST_VERSION       A
                INNER JOIN SCM_MGR.SCM_SYS_CALENDAR_M B ON A.YYYYMMDD = B.BASIS_YYYYMMDD
                LEFT  JOIN SCM_MGR.SCP_PLN_INTERFACE_YN C
                       ON  A.DIVISION_ID       = C.DIVISION_ID
                       AND B.BASIS_START_DATE  = C.PLAN_START_YYYYMMDD
                WHERE  (YYYYMMDD >= P_START_YYYYMMDD AND YYYYMMDD <= P_END_YYYYMMDD)
                AND    A.DIVISION_ID IN (
                           SELECT TRIM(REGEXP_SUBSTR(P_DIVISION_ID, '[^,]+', 1, LEVEL))
                           FROM   DUAL
                           CONNECT BY REGEXP_SUBSTR(P_DIVISION_ID, '[^,]+', 1, LEVEL) IS NOT NULL
                       )
                AND    VERSION_TYPE IN (
                           SELECT TRIM(REGEXP_SUBSTR(V_VERSION_TYPE, '[^,]+', 1, LEVEL))
                           FROM   DUAL
                           CONNECT BY REGEXP_SUBSTR(V_VERSION_TYPE, '[^,]+', 1, LEVEL) IS NOT NULL
                       )
                AND    EXISTS (
                           SELECT 1
                           FROM   (
                                      SELECT TRIM(REGEXP_SUBSTR(P_VERSION_NO, '[^,]+', 1, LEVEL)) AS TOKEN
                                      FROM   DUAL
                                      CONNECT BY REGEXP_SUBSTR(P_VERSION_NO, '[^,]+', 1, LEVEL) IS NOT NULL
                                  ) P
                           WHERE  VERSION_NO LIKE P.TOKEN || '%'
                       )
                AND    ( NVL(ATTRIBUTE1, '') <> 'MOVE' OR ATTRIBUTE1 IS NULL )
                --AND CREATED_BY <> 'WITHOUT_SP_W' -- [PJ20200138] Created_by 'WITHOUT_SP_W' 는 제외
                GROUP BY VERSION_NO, VERSION_DESCRIPTION, VERSION_TYPE, VER_CRE_SEQ, YYYYMMDD, B.WEEK_NAME, C.DM_RTF_YN
            ) A
            --팝업에 표시되는 기준 CURRENT가 제일 위, 그 다음은 코드에 상관없이 최근 생성 시간순으로 정렬 (필요시 아래 참고해서 변경바람)
            ORDER BY CASE WHEN CODE = 'CURRENT'          THEN 1     --팝업에 표시되는 순서1
                          --WHEN INSTR(CODE,'SP') <> 0   THEN 2     --팝업에 표시되는 순서2
                          --WHEN INSTR(CODE,'MF') <> 0   THEN 3     --팝업에 표시되는 순서3
                          --WHEN INSTR(CODE,'SF') <> 0   THEN 4     --팝업에 표시되는 순서4
                          ELSE 5
                          --END, VERSION_NO DESC
                     END, CREATION_DATE DESC;

    ELSE
        V_DESCRIPTION := 'ELSE CASE';

        OPEN O_RC1 FOR
            SELECT 'SP_Z_CURRENT' AS CODE
                 , 'Current'      AS VERSION_NO
                 , 'Current'      AS VERSION_DESCRIPTION
                 , ''             AS VERSION_TYPE
                 , ''             AS EDI_APPLY
                 , CASE WHEN 1 = 2 THEN 1 ELSE NULL END AS VER_CRE_SEQ
                 , ''             AS YYYYMMDD
                 , ''             AS CREATED_BY
                 , SYSDATE        AS CREATION_DATE
            FROM   DUAL
            UNION ALL
            SELECT VERSION_NO AS CODE
                 , CASE WHEN C.DM_RTF_YN = 'N'
                             THEN VERSION_NO || '(' || B.WEEK_NAME || ') (NO PLAN)'
                             ELSE VERSION_NO || '(' || B.WEEK_NAME || ')'
                        END AS VERSION_NO
                 , VERSION_DESCRIPTION
                 , VERSION_TYPE
                 , CASE WHEN VERSION_TYPE = 'ME_S' THEN 'Y' ELSE 'N' END AS EDI_APPLY
                 , VER_CRE_SEQ
                 , YYYYMMDD
                 , MAX(CREATED_BY)      AS CREATED_BY
                 , MAX(CREATION_DATE)   AS CREATION_DATE
            FROM   SCM_MGR.DM_MST_VERSION       A
            INNER JOIN SCM_MGR.SCM_SYS_CALENDAR_M B ON A.YYYYMMDD = B.BASIS_YYYYMMDD
            LEFT  JOIN SCM_MGR.SCP_PLN_INTERFACE_YN C
                   ON  A.DIVISION_ID       = C.DIVISION_ID
                   AND B.BASIS_START_DATE  = C.PLAN_START_YYYYMMDD
            WHERE  (YYYYMMDD >= P_START_YYYYMMDD AND YYYYMMDD <= P_END_YYYYMMDD)
            AND    A.DIVISION_ID IN (
                       SELECT TRIM(REGEXP_SUBSTR(P_DIVISION_ID, '[^,]+', 1, LEVEL))
                       FROM   DUAL
                       CONNECT BY REGEXP_SUBSTR(P_DIVISION_ID, '[^,]+', 1, LEVEL) IS NOT NULL
                   )
            AND    VERSION_TYPE IN (
                       SELECT TRIM(REGEXP_SUBSTR(P_VERSION_TYPE, '[^,]+', 1, LEVEL))
                       FROM   DUAL
                       CONNECT BY REGEXP_SUBSTR(P_VERSION_TYPE, '[^,]+', 1, LEVEL) IS NOT NULL
                   )
            AND    EXISTS (
                       SELECT 1
                       FROM   (
                                  SELECT TRIM(REGEXP_SUBSTR(P_VERSION_NO, '[^,]+', 1, LEVEL)) AS TOKEN
                                  FROM   DUAL
                                  CONNECT BY REGEXP_SUBSTR(P_VERSION_NO, '[^,]+', 1, LEVEL) IS NOT NULL
                              ) P
                       WHERE  VERSION_NO LIKE P.TOKEN || '%'
                   )
            AND    ( NVL(ATTRIBUTE1, '') <> 'MOVE' OR ATTRIBUTE1 IS NULL )
            --AND CREATED_BY <> 'WITHOUT_SP_W' -- [PJ20200138] Created_by 'WITHOUT_SP_W' 는 제외
            GROUP BY VERSION_NO, VERSION_DESCRIPTION, VERSION_TYPE, VER_CRE_SEQ, YYYYMMDD, B.WEEK_NAME, C.DM_RTF_YN
            ORDER BY CODE DESC, VERSION_NO DESC;

    END IF;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_START_YYYYMMDD' VALUE P_START_YYYYMMDD,
            'P_END_YYYYMMDD'   VALUE P_END_YYYYMMDD,
            'P_CREATED_BY'     VALUE P_CREATED_BY,
            'P_DIVISION_ID'    VALUE P_DIVISION_ID,
            'P_VERSION_TYPE'   VALUE P_VERSION_TYPE,
            'P_VERSION_NO'     VALUE P_VERSION_NO
        );
        V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); END;
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );

END P_SCM0002_GET_VERSIONBYWATERFALLPOPUP;


/* ============================================================
   2. SCM0002_SET_DEFAULT_TITLESET_POPUP
   ============================================================ */
PROCEDURE P_SCM0002_SET_DEFAULT_TITLESET_POPUP
(
    P_PROGRAM_ID    IN VARCHAR2,
    P_SHEET_NAME    IN VARCHAR2,
    P_COLUMN_TYPE   IN VARCHAR2,
    P_USER_ID       IN VARCHAR2,
    O_RESULT_CURSOR OUT SYS_REFCURSOR
)
AS
/*
 * Program ID   : SCM0002_SET_DEFAULT_TITLESET_POPUP
 * Description  : Column Setting, Measure Setting
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2017.11.21   정병훈         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018.06.19   윤혜원      유저컬럼 조회 조건 수정
 * 2026.03.31   kimcd        [PJ20264226] NextSCM Pilot 설계 및 개발.
 *
 */
    V_PROGRAM_NAME  VARCHAR2(200 CHAR);

    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100  CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100  CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER        := 0;
    D_EVENT_DATE    DATE               := SYSDATE;

BEGIN
    -- 프로그램명 설정 (패키지 바디 이관 시 패키지명.프로시저명 자동 기록)
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    IF P_COLUMN_TYPE = 'C' THEN
        -- Column
        INSERT INTO SCM_MGR.SCM_MST_TITLESET_USER
              ( USER_ID    , PROGRAM_ID   , SHEET_NAME                   , USER_INQUIRY_COLUMN_TYPE_CODE
              , COLUMN_NAME, SORT_ORDER_NO, DATA_SORT_METHOD_CODE
              , CREATED_BY , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
        SELECT P_USER_ID   , B.PROGRAM_ID , B.SHEET_NAME                 , P_COLUMN_TYPE
             , B.COLUMN_NAME
             , RANK() OVER (ORDER BY B.SORT_ORDER_NO)
             , SCM_MGR.FN_SCM_SYS_NVL(B.DATA_SORT_METHOD_CODE, 'ASC')
             , P_USER_ID, SYSDATE, P_USER_ID, SYSDATE
        FROM   SCM_MGR.SCM_MST_SHEET_COLUMNS B
        WHERE  B.PROGRAM_ID    = P_PROGRAM_ID
        AND    B.SHEET_NAME    = NVL(P_SHEET_NAME, B.SHEET_NAME)
        AND    B.VALID_YN      = 'Y'
        --AND    b.user_selectable_flag = 'Y'
        AND    B.DEFAULT_FLAG  = 'Y'
        AND    NVL(B.ATTRIBUTE6, 'Y') <> 'N'
        AND    NOT EXISTS (
                   SELECT 1 FROM SCM_MGR.SCM_MST_TITLESET_USER U
                   WHERE  U.USER_ID                      = P_USER_ID
                   AND    U.PROGRAM_ID                   = B.PROGRAM_ID
                   AND    U.SHEET_NAME                   = B.SHEET_NAME
                   AND    U.USER_INQUIRY_COLUMN_TYPE_CODE = P_COLUMN_TYPE
               );
    ELSE
        -- Measure
        INSERT INTO SCM_MGR.SCM_MST_TITLESET_USER
              ( USER_ID    , PROGRAM_ID   , SHEET_NAME , USER_INQUIRY_COLUMN_TYPE_CODE
              , COLUMN_NAME, SORT_ORDER_NO, DATA_SORT_METHOD_CODE
              , CREATED_BY , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
        SELECT P_USER_ID   , B.PROGRAM_ID , B.SHEET_NAME, P_COLUMN_TYPE
             , B.COLUMN_NAME, B.SORT_ORDER_NO, NULL
             , P_USER_ID, SYSDATE, P_USER_ID, SYSDATE
        FROM   SCM_MGR.SCM_MST_SHEET_MEASURE B
        WHERE  B.PROGRAM_ID   = P_PROGRAM_ID
        AND    B.SHEET_NAME   = NVL(P_SHEET_NAME, B.SHEET_NAME)
        AND    B.DEFAULT_FLAG = 'Y'
        AND    NOT EXISTS (
                   SELECT 1 FROM SCM_MGR.SCM_MST_TITLESET_USER U
                   WHERE  U.USER_ID                      = P_USER_ID
                   AND    U.PROGRAM_ID                   = B.PROGRAM_ID
                   AND    U.SHEET_NAME                   = B.SHEET_NAME
                   AND    U.USER_INQUIRY_COLUMN_TYPE_CODE = P_COLUMN_TYPE
               );
    END IF;

    N_LOG_COUNT := SQL%ROWCOUNT;
    COMMIT;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(N_LOG_COUNT) AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_PROGRAM_ID'   VALUE P_PROGRAM_ID,
            'P_SHEET_NAME'   VALUE P_SHEET_NAME,
            'P_COLUMN_TYPE'  VALUE P_COLUMN_TYPE,
            'P_USER_ID'      VALUE P_USER_ID
        );
        V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); END;
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );

END P_SCM0002_SET_DEFAULT_TITLESET_POPUP;


/* ============================================================
   3. SCM0002_SET_TITLESET_POPUP
   ============================================================ */
PROCEDURE P_SCM0002_SET_TITLESET_POPUP
(
    P_PROGRAM_ID        IN VARCHAR2,
    P_SHEET_NAME        IN VARCHAR2,
    P_COLUMN_TYPE       IN VARCHAR2,
    P_ACTIVE_FLAG       IN VARCHAR2,
    P_COLUMN_NAME       IN VARCHAR2,
    P_SORT_ORDER_NO     IN VARCHAR2,
    P_SUB_TOTAL_FLAG    IN VARCHAR2,
    P_SORT_METHOD_CODE  IN VARCHAR2,
    P_USER_ID           IN VARCHAR2,
        P_COLUMN_WIDTH     IN VARCHAR2 DEFAULT NULL,
        P_CELL_COLOR       IN VARCHAR2 DEFAULT NULL,
        P_TEXT_COLOR       IN VARCHAR2 DEFAULT NULL,
    O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
AS
/*
 * Program ID   : SCM0002_SET_TITLESET_POPUP
 * Description  : Column Setting, Measure Setting
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2017.11.21   정병훈         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2024.11.06   jahn1502       UI 컬럼 0처리로 인해 'SCP0104','SCP0105','SCP0106','SCP0107','SCP0108' 화면 별도 설정
 * 2026.03.31   kimcd         [PJ20264226] NextSCM Pilot 설계 및 개발.
 */
    V_PROGRAM_NAME      VARCHAR2(200  CHAR);

    RECV_ACTIVE_FLAG    VARCHAR2(400 CHAR);
    V_PROGRAM_ID        VARCHAR2(400 CHAR);
    V_SHEET_NAME        VARCHAR2(400 CHAR);
    V_COLUMN_TYPE       VARCHAR2(400 CHAR);
    V_ACTIVE_FLAG       VARCHAR2(400 CHAR);
    V_COLUMN_NAME       VARCHAR2(400 CHAR);
    V_SORT_ORDER_NO     VARCHAR2(400 CHAR);
    V_SUB_TOTAL_FLAG    VARCHAR2(400 CHAR);
    V_SORT_METHOD_CODE  VARCHAR2(400 CHAR);
    V_USER_ID           VARCHAR2(400 CHAR);
    V_COLUMN_WIDTH     VARCHAR2(400 CHAR);
    V_CELL_COLOR       VARCHAR2(400 CHAR);
    V_TEXT_COLOR       VARCHAR2(400 CHAR);

    V_DELIMITER         VARCHAR2(10   CHAR) := '^';
    V_MAX_LOOP_CNT      PLS_INTEGER        := 0;
    V_MST_LOOP_CNT      PLS_INTEGER        := 0;

    -- LOG 용 변수 설정
    V_LOG_TYPE          VARCHAR2(300  CHAR);  -- START/END/ERROR/...
    N_LOG_COUNT         PLS_INTEGER        := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(1000 CHAR);
    D_EVENT_DATE        DATE;

    V_PROC_INPUT        VARCHAR2(4000 CHAR);
    V_BACKTRACE         VARCHAR2(4000 CHAR);
    V_SQL_CODE          VARCHAR2(100  CHAR);
    V_SQL_ERRMSG        VARCHAR2(1000 CHAR);

BEGIN
    -- 프로그램명 설정 (패키지 바디 이관 시 패키지명.프로시저명 자동 기록)
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    RECV_ACTIVE_FLAG := P_ACTIVE_FLAG;

    -- 시작 LOG
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    -- 프로시저 LOOP 길이를 판단
    V_MAX_LOOP_CNT := SCM_MGR.SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);
    V_DESCRIPTION := 'BEFORE DELETE';

    DELETE FROM SCM_MGR.SCM_MST_TITLESET_USER
    WHERE  USER_ID                       = P_USER_ID
    AND    PROGRAM_ID                    = P_PROGRAM_ID
    AND    SHEET_NAME                    = P_SHEET_NAME
    AND    USER_INQUIRY_COLUMN_TYPE_CODE = P_COLUMN_TYPE;

    V_DESCRIPTION := 'BEFORE WHILE';

    WHILE LENGTH(RECV_ACTIVE_FLAG) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
    LOOP
        V_DESCRIPTION := 'IN WHILE : ' || TO_CHAR(V_MST_LOOP_CNT);
        -- @mst_loop_cnt 1증가
        V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

        -- 각 컬럼들에 대한 스플릿처리로직 스타트
        V_ACTIVE_FLAG      := SCM_MGR.SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,      V_DELIMITER, V_MST_LOOP_CNT);
        V_COLUMN_NAME      := SCM_MGR.SCM_ARR_SPL_VAL(P_COLUMN_NAME,      V_DELIMITER, V_MST_LOOP_CNT);
        V_SORT_ORDER_NO    := SCM_MGR.SCM_ARR_SPL_VAL(P_SORT_ORDER_NO,    V_DELIMITER, V_MST_LOOP_CNT);
        V_SUB_TOTAL_FLAG   := SCM_MGR.SCM_ARR_SPL_VAL(P_SUB_TOTAL_FLAG,   V_DELIMITER, V_MST_LOOP_CNT);
        V_SORT_METHOD_CODE := SCM_MGR.SCM_ARR_SPL_VAL(P_SORT_METHOD_CODE, V_DELIMITER, V_MST_LOOP_CNT);
        V_COLUMN_WIDTH     := SCM_MGR.SCM_ARR_SPL_VAL(P_COLUMN_WIDTH,     V_DELIMITER, V_MST_LOOP_CNT);
        V_CELL_COLOR       := SCM_MGR.SCM_ARR_SPL_VAL(P_CELL_COLOR,       V_DELIMITER, V_MST_LOOP_CNT);
        V_TEXT_COLOR       := SCM_MGR.SCM_ARR_SPL_VAL(P_TEXT_COLOR,       V_DELIMITER, V_MST_LOOP_CNT);

        IF V_MST_LOOP_CNT > 0 THEN  -- 여러개

            IF (P_COLUMN_TYPE = 'C' AND P_PROGRAM_ID NOT IN ('SCP0104','SCP0105','SCP0106','SCP0107','SCP0108')) THEN  --Column
                V_DESCRIPTION := 'IN WHILE NOT IN SCP0104 ETC';

                INSERT INTO SCM_MGR.SCM_MST_TITLESET_USER
                ( USER_ID    , PROGRAM_ID  , SHEET_NAME    , USER_INQUIRY_COLUMN_TYPE_CODE
                , COLUMN_NAME, SORT_ORDER_NO, SUB_TOTAL_FLAG, DATA_SORT_METHOD_CODE
                , CREATED_BY , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                ,   COLUMN_WIDTH
                ,   CELL_COLOR
                ,   TEXT_COLOR
               )
                SELECT P_USER_ID
                     , C.PROGRAM_ID
                     , C.SHEET_NAME
                     , P_COLUMN_TYPE
                     , C.COLUMN_NAME
                     --, p_sort_order_no(i) + c.sort_order_no - TRUNC(c.sort_order_no)
                     , CASE WHEN V_SORT_ORDER_NO IS NULL OR TO_NUMBER(V_SORT_ORDER_NO) = 0
                                 THEN C.SORT_ORDER_NO
                                 ELSE TO_NUMBER(V_SORT_ORDER_NO) + C.SORT_ORDER_NO - TRUNC(C.SORT_ORDER_NO)
                            END
                     , V_SUB_TOTAL_FLAG
                     , V_SORT_METHOD_CODE
                     , P_USER_ID
                     , SYSDATE
                     , P_USER_ID
                     , SYSDATE
                     , CASE WHEN V_COLUMN_WIDTH IS NULL OR V_COLUMN_WIDTH = '' THEN C.COLUMN_WIDTH ELSE TO_NUMBER(V_COLUMN_WIDTH) END
                     , V_CELL_COLOR
                     , V_TEXT_COLOR
                FROM   SCM_MGR.SCM_MST_SHEET_COLUMNS C
                WHERE  C.PROGRAM_ID     = P_PROGRAM_ID
                AND    C.SHEET_NAME     = P_SHEET_NAME
                AND    C.SORT_ORDER_NO  = (SELECT SORT_ORDER_NO
                                           FROM   SCM_MGR.SCM_MST_SHEET_COLUMNS
                                           WHERE  PROGRAM_ID  = P_PROGRAM_ID
                                           AND    SHEET_NAME  = P_SHEET_NAME
                                           AND    COLUMN_NAME = V_COLUMN_NAME)
                AND    NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_MST_TITLESET_USER
                                   WHERE  PROGRAM_ID  = C.PROGRAM_ID
                                   AND    SHEET_NAME  = C.SHEET_NAME
                                   AND    COLUMN_NAME = C.COLUMN_NAME
                                   AND    USER_ID     = P_USER_ID);

--------------------------------------------------------------------------------------------------------------
            ELSIF (P_COLUMN_TYPE = 'C' AND P_PROGRAM_ID IN ('SCP0104','SCP0105','SCP0106','SCP0107','SCP0108')) THEN  --Column
                V_DESCRIPTION := 'IN WHILE IN SCP0104 ETC';

                INSERT INTO SCM_MGR.SCM_MST_TITLESET_USER
                ( USER_ID    , PROGRAM_ID  , SHEET_NAME    , USER_INQUIRY_COLUMN_TYPE_CODE
                , COLUMN_NAME, SORT_ORDER_NO, SUB_TOTAL_FLAG, DATA_SORT_METHOD_CODE
                , CREATED_BY , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE3
                ,   COLUMN_WIDTH
                ,   CELL_COLOR
                ,   TEXT_COLOR
               )
                SELECT P_USER_ID
                     , C.PROGRAM_ID
                     , C.SHEET_NAME
                     , P_COLUMN_TYPE
                     , C.COLUMN_NAME
                     --, p_sort_order_no(i) + c.sort_order_no - TRUNC(c.sort_order_no)
                     , C.SORT_ORDER_NO
                     , V_SUB_TOTAL_FLAG
                     , V_SORT_METHOD_CODE
                     , P_USER_ID
                     , SYSDATE
                     , P_USER_ID
                     , SYSDATE
                     , NULL
                     , CASE WHEN V_COLUMN_WIDTH IS NULL OR V_COLUMN_WIDTH = '' THEN C.COLUMN_WIDTH ELSE TO_NUMBER(V_COLUMN_WIDTH) END
                     , V_CELL_COLOR
                     , V_TEXT_COLOR
                FROM   SCM_MGR.SCM_MST_SHEET_COLUMNS C
                WHERE  C.PROGRAM_ID     = P_PROGRAM_ID
                AND    C.SHEET_NAME     = P_SHEET_NAME
                AND    C.COLUMN_WIDTH  <> 0
                AND    C.SORT_ORDER_NO  = (SELECT SORT_ORDER_NO
                                           FROM   SCM_MGR.SCM_MST_SHEET_COLUMNS
                                           WHERE  PROGRAM_ID  = P_PROGRAM_ID
                                           AND    SHEET_NAME  = P_SHEET_NAME
                                           AND    COLUMN_NAME = V_COLUMN_NAME)
                AND    NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_MST_TITLESET_USER
                                   WHERE  PROGRAM_ID  = C.PROGRAM_ID
                                   AND    SHEET_NAME  = C.SHEET_NAME
                                   AND    COLUMN_NAME = C.COLUMN_NAME
                                   AND    USER_ID     = P_USER_ID);

                IF V_MST_LOOP_CNT = 0 THEN  --한번만 처리
                    IF P_PROGRAM_ID = 'SCP0104' THEN  --예외 DUMMY_YN 필수 컬럼이지만 0으로 설정되어 있음.
                        INSERT INTO SCM_MGR.SCM_MST_TITLESET_USER
                        ( USER_ID    , PROGRAM_ID  , SHEET_NAME    , USER_INQUIRY_COLUMN_TYPE_CODE
                        , COLUMN_NAME, SORT_ORDER_NO, SUB_TOTAL_FLAG, DATA_SORT_METHOD_CODE
                        , CREATED_BY , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE3
                        ,   COLUMN_WIDTH
                        ,   CELL_COLOR
                        ,   TEXT_COLOR
                       )
                        SELECT P_USER_ID
                             , C.PROGRAM_ID
                             , C.SHEET_NAME
                             , P_COLUMN_TYPE
                             , C.COLUMN_NAME
                             , C.SORT_ORDER_NO
                             , V_SUB_TOTAL_FLAG
                             , V_SORT_METHOD_CODE
                             , P_USER_ID
                             , SYSDATE
                             , P_USER_ID
                             , SYSDATE
                             , NULL
                             , CASE WHEN V_COLUMN_WIDTH IS NULL OR V_COLUMN_WIDTH = '' THEN C.COLUMN_WIDTH ELSE TO_NUMBER(V_COLUMN_WIDTH) END
                             , V_CELL_COLOR
                             , V_TEXT_COLOR
                        FROM   SCM_MGR.SCM_MST_SHEET_COLUMNS C
                        WHERE  C.PROGRAM_ID   = 'SCP0104'
                        AND    C.SHEET_NAME   = P_SHEET_NAME
                        AND    C.COLUMN_NAME  = 'DUMMY_YN';

                    ELSIF P_PROGRAM_ID = 'SCP0105' THEN
                        INSERT INTO SCM_MGR.SCM_MST_TITLESET_USER
                        ( USER_ID    , PROGRAM_ID  , SHEET_NAME    , USER_INQUIRY_COLUMN_TYPE_CODE
                        , COLUMN_NAME, SORT_ORDER_NO, SUB_TOTAL_FLAG, DATA_SORT_METHOD_CODE
                        , CREATED_BY , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE3
                        ,   COLUMN_WIDTH
                        ,   CELL_COLOR
                        ,   TEXT_COLOR
                       )
                        SELECT P_USER_ID
                             , C.PROGRAM_ID
                             , C.SHEET_NAME
                             , P_COLUMN_TYPE
                             , C.COLUMN_NAME
                             , C.SORT_ORDER_NO
                             , V_SUB_TOTAL_FLAG
                             , V_SORT_METHOD_CODE
                             , P_USER_ID
                             , SYSDATE
                             , P_USER_ID
                             , SYSDATE
                             , NULL
                             , CASE WHEN V_COLUMN_WIDTH IS NULL OR V_COLUMN_WIDTH = '' THEN C.COLUMN_WIDTH ELSE TO_NUMBER(V_COLUMN_WIDTH) END
                             , V_CELL_COLOR
                             , V_TEXT_COLOR
                        FROM   SCM_MGR.SCM_MST_SHEET_COLUMNS C
                        WHERE  C.PROGRAM_ID   = 'SCP0105'
                        AND    C.SHEET_NAME   = P_SHEET_NAME
                        AND    C.COLUMN_NAME  = 'IDX';
                    END IF;
                END IF;

                IF V_ACTIVE_FLAG = 'U' THEN
                    V_DESCRIPTION := 'IN WHILE V_ACTIVE_FLAG = U';

                    UPDATE SCM_MGR.SCM_MST_TITLESET_USER SET ATTRIBUTE3 = 'N'
                    WHERE  1 = 1
                    AND    PROGRAM_ID  = P_PROGRAM_ID
                    AND    SHEET_NAME  = P_SHEET_NAME
                    AND    COLUMN_NAME = V_COLUMN_NAME
                    AND    USER_ID     = P_USER_ID;
                END IF;

--------------------------------------------------------------------------------------------------------
            ELSIF V_COLUMN_NAME IS NOT NULL OR V_COLUMN_NAME != '' THEN  -- Measure
                V_DESCRIPTION := 'IN WHILE V_COLUMN_NAME : Measure ';

                INSERT INTO SCM_MGR.SCM_MST_TITLESET_USER
                ( USER_ID    , PROGRAM_ID   , SHEET_NAME    , USER_INQUIRY_COLUMN_TYPE_CODE
                , COLUMN_NAME, SORT_ORDER_NO, SUB_TOTAL_FLAG, DATA_SORT_METHOD_CODE
                , CREATED_BY , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                ,   COLUMN_WIDTH
                ,   CELL_COLOR
                ,   TEXT_COLOR
               )
                VALUES
                ( P_USER_ID       , P_PROGRAM_ID   , P_SHEET_NAME    , P_COLUMN_TYPE
                , V_COLUMN_NAME, TO_NUMBER(V_SORT_ORDER_NO), V_SUB_TOTAL_FLAG, V_SORT_METHOD_CODE
                , P_USER_ID , SYSDATE, P_USER_ID, SYSDATE
                ,   CASE WHEN V_COLUMN_WIDTH IS NULL OR V_COLUMN_WIDTH = '' THEN NULL ELSE TO_NUMBER(V_COLUMN_WIDTH) END
                ,   V_CELL_COLOR
                ,   V_TEXT_COLOR
               );

                /*
                INSERT INTO scm_mst_titleset_user
                ( user_id    , program_id   , sheet_name    , user_inquiry_column_type_code
                , column_name, sort_order_no, sub_total_flag, data_sort_method_code
                , created_by , creation_date, last_updated_by, last_update_date )
                SELECT
                , m.column_name, @v_sort_order_no, @v_sub_total_flag, @v_sort_method_code
                , @p_user_id , sysdatetime(), @p_user_id, sysdatetime()
                FROM   scm_mst_sheet_measure m
                WHERE  m.program_id = @p_program_id
                AND    m.sheet_name = @p_sheet_name
                AND    m.column_name = @p_column_name
                ;*/

            END IF;

        ELSE  -- V_MST_LOOP_CNT = 0 분기 (단건)

            V_ACTIVE_FLAG      := P_ACTIVE_FLAG;
            V_COLUMN_NAME      := P_COLUMN_NAME;
            V_SORT_ORDER_NO    := P_SORT_ORDER_NO;
            V_SUB_TOTAL_FLAG   := P_SUB_TOTAL_FLAG;
            V_SORT_METHOD_CODE := P_SORT_METHOD_CODE;

            IF P_COLUMN_TYPE = 'C' THEN  --Column

                INSERT INTO SCM_MGR.SCM_MST_TITLESET_USER
                ( USER_ID    , PROGRAM_ID  , SHEET_NAME    , USER_INQUIRY_COLUMN_TYPE_CODE
                , COLUMN_NAME, SORT_ORDER_NO, SUB_TOTAL_FLAG, DATA_SORT_METHOD_CODE
                , CREATED_BY , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                ,   COLUMN_WIDTH
                ,   CELL_COLOR
                ,   TEXT_COLOR
               )
                SELECT P_USER_ID
                     , C.PROGRAM_ID
                     , C.SHEET_NAME
                     , P_COLUMN_TYPE
                     , C.COLUMN_NAME
                     --, p_sort_order_no(i) + c.sort_order_no - TRUNC(c.sort_order_no)
                     , CASE WHEN V_SORT_ORDER_NO IS NULL OR TO_NUMBER(V_SORT_ORDER_NO) = 0
                                 THEN C.SORT_ORDER_NO
                                 ELSE TO_NUMBER(V_SORT_ORDER_NO) + C.SORT_ORDER_NO - TRUNC(C.SORT_ORDER_NO)
                            END
                     , V_SUB_TOTAL_FLAG
                     , V_SORT_METHOD_CODE
                     , P_USER_ID
                     , SYSDATE
                     , P_USER_ID
                     , SYSDATE
                     , CASE WHEN V_COLUMN_WIDTH IS NULL OR V_COLUMN_WIDTH = '' THEN C.COLUMN_WIDTH ELSE TO_NUMBER(V_COLUMN_WIDTH) END
                     , V_CELL_COLOR
                     , V_TEXT_COLOR
                FROM   SCM_MGR.SCM_MST_SHEET_COLUMNS C
                WHERE  C.PROGRAM_ID    = P_PROGRAM_ID
                AND    C.SHEET_NAME    = P_SHEET_NAME
                AND    TRUNC(C.SORT_ORDER_NO) = (SELECT TRUNC(SORT_ORDER_NO)
                                                  FROM   SCM_MGR.SCM_MST_SHEET_COLUMNS
                                                  WHERE  PROGRAM_ID  = P_PROGRAM_ID
                                                  AND    SHEET_NAME  = P_SHEET_NAME
                                                  AND    COLUMN_NAME = V_COLUMN_NAME)
                AND    NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_MST_TITLESET_USER
                                   WHERE  PROGRAM_ID  = C.PROGRAM_ID
                                   AND    SHEET_NAME  = C.SHEET_NAME
                                   AND    COLUMN_NAME = C.COLUMN_NAME
                                   AND    USER_ID     = P_USER_ID);

            ELSIF V_COLUMN_NAME IS NOT NULL OR V_COLUMN_NAME != '' THEN  -- Measure

                INSERT INTO SCM_MGR.SCM_MST_TITLESET_USER
                ( USER_ID    , PROGRAM_ID   , SHEET_NAME    , USER_INQUIRY_COLUMN_TYPE_CODE
                , COLUMN_NAME, SORT_ORDER_NO, SUB_TOTAL_FLAG, DATA_SORT_METHOD_CODE
                , CREATED_BY , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                ,   COLUMN_WIDTH
                ,   CELL_COLOR
                ,   TEXT_COLOR
               )
                VALUES
                ( P_USER_ID       , P_PROGRAM_ID   , P_SHEET_NAME    , P_COLUMN_TYPE
                , V_COLUMN_NAME, TO_NUMBER(V_SORT_ORDER_NO), V_SUB_TOTAL_FLAG, V_SORT_METHOD_CODE
                , P_USER_ID , SYSDATE, P_USER_ID, SYSDATE
                ,   CASE WHEN V_COLUMN_WIDTH IS NULL OR V_COLUMN_WIDTH = '' THEN NULL ELSE TO_NUMBER(V_COLUMN_WIDTH) END
                ,   V_CELL_COLOR
                ,   V_TEXT_COLOR
               );

            END IF;

        END IF;

    END LOOP;

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    N_LOG_COUNT := V_MAX_LOOP_CNT;
    COMMIT;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(N_LOG_COUNT) AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_PROGRAM_ID'       VALUE P_PROGRAM_ID,
            'P_SHEET_NAME'       VALUE P_SHEET_NAME,
            'P_COLUMN_TYPE'      VALUE P_COLUMN_TYPE,
            'P_ACTIVE_FLAG'      VALUE P_ACTIVE_FLAG,
            'P_COLUMN_NAME'      VALUE P_COLUMN_NAME,
            'P_SORT_ORDER_NO'    VALUE P_SORT_ORDER_NO,
            'P_SUB_TOTAL_FLAG'   VALUE P_SUB_TOTAL_FLAG,
            'P_SORT_METHOD_CODE' VALUE P_SORT_METHOD_CODE,
            'P_USER_ID'          VALUE P_USER_ID
        );
        V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); END;
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );

END P_SCM0002_SET_TITLESET_POPUP;


    -- 아1 SCP0104 CAPA Item 팝업 (AS-IS SCM0002_GET_CAPA_ITEM_POPUP / FN_SCM0002_GET_CAPA_ITEM_POPUP 이관)
    PROCEDURE P_SCM0002_GET_CAPA_ITEM_POPUP
    (
        P_DIVISION_ID   IN  VARCHAR2,
        P_ITEM_ID       IN  VARCHAR2,
        O_RC1           OUT SYS_REFCURSOR,
        O_RESULT_CURSOR OUT SYS_REFCURSOR
    )
    AS
    BEGIN
        OPEN O_RC1 FOR
            SELECT   A.DIVISION_ID
                   , A.OPERATION_GROUP
                   , A.OPERATION_ID
                   , A.ITEM_ID
                   , MAX(A.ITEM_NAME) AS ITEM_NAME
                   , MAX(A.NICK_NAME) AS NICK_NAME
            FROM   (
                       SELECT   A.DIVISION_ID
                              , A.OPERATION_GROUP
                              , A.FLOW_ID          AS OPERATION_ID
                              , A.ITEM_ID
                              , B.ITEM_NAME
                              , CASE WHEN B.NICK_NAME IS NULL THEN A.NICK_NAME ELSE B.NICK_NAME END AS NICK_NAME
                       FROM   SCM_MGR.SCP_MST_FINAL_ITEM A
                       JOIN   SCM_MGR.SCM_MST_ITEM_SN    B
                              ON  A.DIVISION_ID = B.DIVISION_ID
                              AND A.ITEM_ID     = B.ITEM_ID
                   ) A
            WHERE  1 = 1
            AND    ( P_DIVISION_ID IS NULL
                     OR P_DIVISION_ID IN ('', 'ALL')
                     OR A.DIVISION_ID IN ( SELECT REGEXP_SUBSTR(P_DIVISION_ID, '[^,]+', 1, LEVEL)
                                           FROM   DUAL
                                           CONNECT BY LEVEL <= REGEXP_COUNT(P_DIVISION_ID, '[^,]+') ) )
            AND    ( CASE
                         WHEN P_ITEM_ID LIKE '%,%' THEN
                             CASE WHEN A.ITEM_ID IN ( SELECT REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)
                                                      FROM   DUAL
                                                      CONNECT BY LEVEL <= REGEXP_COUNT(P_ITEM_ID, '[^,]+') )
                                  THEN 1 ELSE 0 END
                         WHEN ( A.ITEM_ID   LIKE '%' || P_ITEM_ID || '%'
                                OR A.NICK_NAME LIKE '%' || P_ITEM_ID || '%' ) THEN 1
                         ELSE 0
                     END = 1 )
            GROUP BY A.DIVISION_ID
                   , A.OPERATION_GROUP
                   , A.OPERATION_ID
                   , A.ITEM_ID;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;
    END P_SCM0002_GET_CAPA_ITEM_POPUP;

/* ============================================================
   27. P_SCM0002_GET_PROJECT_ROUTE_LIST_FORSAVE_POPUP
   ============================================================ */
PROCEDURE P_SCM0002_GET_PROJECT_ROUTE_LIST_FORSAVE_POPUP
(
    P_DIVISION_ID    IN  VARCHAR2                      /* chaan */
  , P_MODEL_ID       IN  VARCHAR2
  , P_ITEM_ID        IN  VARCHAR2
  , P_TIMEZONE       IN  VARCHAR2
  , O_RC1            OUT SYS_REFCURSOR                 /* 입력목록 */
  , O_RC2            OUT SYS_REFCURSOR                 /* 전체 route */
  , O_RC3            OUT SYS_REFCURSOR                 /* 소형 VALIDATION용 ERP ITEM */
  , O_RESULT_CURSOR  OUT SYS_REFCURSOR
)
IS
/*
 * Program ID   : SCM0002_GET_PROJECT_ROUTE_LIST_FORSAVE_POPUP
 * Description  : project route 입력목록 조회
 * Program History
 *===================================================================================================
 *   Date       In Charge       Description
 *===================================================================================================
 * 2018/07/25   YHW             Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018/08/09   YHW             조회조건 model_id, item_id추가
 * 2018/08/20   YHW             소형 VALIDATION용 ERP ITEM 조회
 * 2018/09/19   hwyoon          Item Type = R 도 보이도록 수정
 * 2018/11/08   hwyoon          vmi에 따라 MKT measure 조절
 * 2021/10/05   khj79           [PJ20209643] LGES Digital SCM Level.3 달성을 위한 개선 (Phase.3) - W/S AS UI 변경
 * 2022/04/29   chaan           81_UC, EE_UC 추가로 DIVSION 크기 확장
 * 2022/11/07   jahn1501        PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 - MKT FCST 조건 변경
 * 2026.09.17   AJS             PKG_SCM0002 편입 (MSSQL 원문 기준 전환, 동적 SQL 을 사업부 81 / 그 외 정적 SQL 두 갈래로 분리)
 *                              - debug_mode 인자 제외(출력 전용)
 *                              - ISNULL(attribute10,'')='' : 이관 공백(' ') 값 포함 판정(TRIM)
 *                              - item_type 비교 : 이관 공백(' ') 값은 AS-IS NULL 과 같게 판정(TRIM)
 *                              - 모델 BOM 조인 인덱스 힌트 (전체 읽기 47초 → 2.5초, DBA 협의 대상)
 */
    V_PROGRAM_NAME     VARCHAR2(200 CHAR) := 'PKG_SCM0002.P_SCM0002_GET_PROJECT_ROUTE_LIST_FORSAVE_POPUP';
    V_FROM_YYYYMMDD    VARCHAR2(8 CHAR);
    V_TO_YYYYMMDD      VARCHAR2(8 CHAR);
    V_TZ_DATE          DATE;
    V_TODAY            VARCHAR2(8 CHAR);
    V_MODEL_ID         VARCHAR2(200 CHAR);
    V_ITEM_ID          VARCHAR2(200 CHAR);

    V_LOG_TYPE         VARCHAR2(30 CHAR);
    N_LOG_COUNT        PLS_INTEGER        := 0;
    V_LOG_MESSAGE      VARCHAR2(1000 CHAR);
    V_DESCRIPTION      VARCHAR2(500 CHAR);
    V_PROC_INPUT       VARCHAR2(4000 CHAR);
    V_BACKTRACE        VARCHAR2(4000 CHAR);
    V_SQL_CODE         VARCHAR2(100 CHAR);
    V_SQL_ERRMSG       VARCHAR2(1000 CHAR);
BEGIN
    V_DESCRIPTION := 'INIT';
    V_TODAY       := TO_CHAR(SYSDATE, 'YYYYMMDD');
    V_TZ_DATE     := FN_MULTY_TIME(P_TIMEZONE);
    /* MSSQL CI 정렬 : 조회조건은 대소문자 무시 (대상 칸 소문자 0건) */
    V_MODEL_ID    := UPPER(P_MODEL_ID);
    V_ITEM_ID     := UPPER(P_ITEM_ID);

    /* 임시테이블만들기 - Main 조회 테이블 */
    DELETE FROM GT_SPRL_PIVOT01;

    /* 시작일 설정(현재 월의 1일) ex.20180801 */
    SELECT SUBSTR(NVL(IA.MIN_YYYYMMDD, V_TODAY), 1, 6) || '01'
      INTO V_FROM_YYYYMMDD
      FROM (SELECT MIN(A.BASIS_YYYYMMDD) AS MIN_YYYYMMDD
              FROM SCM_SYS_CALENDAR_M A
             WHERE A.ISO_WEEK IN (SELECT B.ISO_WEEK
                                    FROM SCM_SYS_CALENDAR_M B
                                   WHERE B.BASIS_YYYYMMDD = TO_CHAR(V_TZ_DATE, 'YYYYMMDD'))
               AND A.BASIS_YYYYMM = TO_CHAR(V_TZ_DATE, 'YYYYMM')
           ) IA;

    /* 종료일 설정(12개월) ex.20190731 */
    V_TO_YYYYMMDD := TO_CHAR(ADD_MONTHS(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD'), 12) - 1, 'YYYYMMDD');

    /* from_yyyymmdd는 현재일자의 월요일로 강제설정 */
    /* ex.20180806 */
    BEGIN
        SELECT TO_CHAR(TO_DATE(IA.BASIS_YYYYMMDD, 'YYYYMMDD') - (IA.DAYOFWEEK_NO - 1), 'YYYYMMDD') AS BASIS_START_DATE
          INTO V_FROM_YYYYMMDD
          FROM (SELECT CASE WHEN A.DAYOFWEEK_NO - 1 = 0 THEN 7 ELSE A.DAYOFWEEK_NO - 1 END AS DAYOFWEEK_NO
                     , A.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M A
                 WHERE A.BASIS_YYYYMMDD = V_TODAY
               ) IA;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_FROM_YYYYMMDD := NULL;
    END;

    /* 1. 입력목록 조회 */
    /* 판매계획은 키 중복을 먼저 제거한 뒤 BOM 과 조인 (결과 동일, 조인 행 수만 줄임) */
    V_DESCRIPTION := 'INSERT GT_SPRL_PIVOT01';
    IF P_DIVISION_ID = '81' THEN
        INSERT INTO GT_SPRL_PIVOT01
             ( DIVISION_ID
             , SCM_SITE_ID
             , SCM_SITE_NAME
             , PROJECT_CODE
             , MODEL_ID
             , NICK_NAME
             , ITEM_ID
             , ITEM_NAME
             , OPERATION_GROUP_ID
             , OPERATION_GROUP
             , PLANT_SITE_ID
             , VALID_YN
             , PRIORITY
             , FROM_YYYYMMDD
             , TO_YYYYMMDD
             , ORG_FROM_YYYYMMDD
             , ORG_TO_YYYYMMDD
             )
        SELECT IC.DIVISION_ID
             , IC.SCM_SITE_ID
             , FN_GET_SCM_SITE_DESCRIPTION(IC.DIVISION_ID, IC.SCM_SITE_ID) AS SCM_SITE_NAME
             , IC.PROJECT_CODE
             , IC.MODEL_ID
             , FN_GET_ITEM_NICKNAME(IC.DIVISION_ID, IC.MODEL_ID) AS NICK_NAME
             , IC.ITEM_ID
             , FN_GET_ITEM_NICKNAME(IC.DIVISION_ID, IC.ITEM_ID) AS ITEM_NAME
             , IC.OPERATION_GROUP AS OPERATION_GROUP_ID
             , IC.OPERATION_GROUP_ID AS OPERATION_GROUP
             , '' AS PLANT_SITE_ID
             , 'Y' AS VALID_YN
             , 1 AS PRIORITY
             , '' AS FROM_YYYYMMDD
             , '' AS TO_YYYYMMDD
             , '' AS ORG_FROM_YYYYMMDD
             , '' AS ORG_TO_YYYYMMDD
          FROM (SELECT DISTINCT
                       XB.DIVISION_ID
                     , XB.SCM_SITE_ID
                     , XB.PROJECT_CODE
                     , XB.MODEL_ID
                     , XB.ITEM_ID
                     , XB.OPERATION_GROUP
                     , XB.OPERATION_GROUP_ID
                  FROM (SELECT DISTINCT
                               B.DIVISION_ID
                             , B.PROJECT_CODE
                             , B.SCM_SITE_ID
                             , B.ITEM_ID
                          FROM DM_PLN_MKT_FCST B
                             , (SELECT D.DIVISION_ID
                                     , D.SCM_SITE_ID
                                     , D.OPERATION_GROUP
                                     , D.VMI_YN
                                  FROM SCM_MST_SITE D
                                 WHERE (D.VMI_YN = 'Y' OR (D.SITE_TYPE = 'SALES' AND D.OPERATION_GROUP = 'W'))
                               ) XD
                         WHERE B.DIVISION_ID   = XD.DIVISION_ID(+)
                           AND B.SCM_SITE_ID   = XD.SCM_SITE_ID(+)
                           AND B.MEASURE       = CASE WHEN XD.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                                      WHEN XD.VMI_YN = 'Y' THEN 'VMI_In_Req'
                                                      WHEN TRIM(B.ATTRIBUTE10) IS NULL THEN 'MKT_FCST'
                                                 END
                           AND EXISTS (SELECT 1
                                         FROM SCM_MST_ITEM_SN C
                                        WHERE C.DIVISION_ID = B.DIVISION_ID
                                          AND C.ITEM_ID     = B.ITEM_ID
                                          AND C.SCP_OPERATION_GROUP_ID <> 'E')
                           AND B.MEASURE      IN ('AS_In_Req', 'VMI_In_Req', 'MKT_FCST')
                           AND B.QTY           > 0
                           AND B.DIVISION_ID   = P_DIVISION_ID
                           AND B.YYYYMMDD     >= V_FROM_YYYYMMDD
                           AND B.YYYYMMDD     <= V_TO_YYYYMMDD
                       ) XA
                     , (SELECT /*+ LEADING(XE) USE_NL(F) INDEX_SS(F IX01_SCM_MST_MODEL_BOM) */
                               DISTINCT
                               (CASE WHEN XE.OPERATION_GROUP = 'E' THEN G.ITEM_ID
                                     ELSE F.MODEL_ID
                                END) AS MODEL_ID
                             , (CASE
                                     /* 전극 제외 20180517 */
                                     /* WHEN d.operation_group_id = 'E' THEN 'Electrode' */
                                     WHEN H.OPERATION_GROUP_ID = 'A' THEN 'Cell'
                                     WHEN H.OPERATION_GROUP_ID = 'P' THEN 'Pack'
                                END) AS OPERATION_GROUP_ID
                             , F.CHILD_ITEM_ID AS ITEM_ID
                             , F.DIVISION_ID
                             , XE.SCM_SITE_ID
                             , XE.PROJECT_CODE
                             , H.OPERATION_GROUP_ID AS OPERATION_GROUP
                          FROM (SELECT IA.DIVISION_ID
                                     , IA.ITEM_ID
                                     , IA.SCM_SITE_ID
                                     , IA.PROJECT_CODE
                                     , FN_GET_ITEM_OPERATION_GROUP(IA.DIVISION_ID, IA.ITEM_ID) AS OPERATION_GROUP
                                  FROM (SELECT DISTINCT
                                               E.DIVISION_ID
                                             , E.ITEM_ID
                                             , E.SCM_SITE_ID
                                             , E.PROJECT_CODE
                                          FROM DM_PLN_MKT_FCST E
                                             , (SELECT I.DIVISION_ID
                                                     , I.SCM_SITE_ID
                                                     , I.OPERATION_GROUP
                                                     , I.VMI_YN
                                                  FROM SCM_MST_SITE I
                                                 WHERE (I.VMI_YN = 'Y' OR (I.SITE_TYPE = 'SALES' AND I.OPERATION_GROUP = 'W'))
                                               ) XF
                                         WHERE E.DIVISION_ID = XF.DIVISION_ID(+)
                                           AND E.SCM_SITE_ID = XF.SCM_SITE_ID(+)
                                           AND E.MEASURE     = CASE WHEN XF.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                                                    WHEN XF.VMI_YN = 'Y' THEN 'VMI_In_Req'
                                                                    WHEN TRIM(E.ATTRIBUTE10) IS NULL THEN 'MKT_FCST'
                                                               END
                                           AND E.QTY         > 0
                                           AND E.DIVISION_ID = P_DIVISION_ID
                                           AND E.YYYYMMDD   >= V_FROM_YYYYMMDD
                                           AND E.YYYYMMDD   <= V_TO_YYYYMMDD
                                       ) IA
                               ) XE
                             , SCM_MST_BOM_SN_V F        /* 2021.03.30 대체 BOM 모델링 */
                             , SCM_MST_ITEM_SN G
                             , SCM_MST_FINAL_ITEM_V H
                         WHERE XE.DIVISION_ID  = F.DIVISION_ID
                           AND XE.ITEM_ID      = F.MODEL_ID
                           AND F.COMPANY_ID    = G.COMPANY_ID
                           AND F.DIVISION_ID   = G.DIVISION_ID
                           AND F.SITE_ID       = G.SITE_ID
                           AND F.CHILD_ITEM_ID = G.ITEM_ID
                           AND F.DIVISION_ID   = H.DIVISION_ID
                           AND F.CHILD_ITEM_ID = H.ITEM_ID
                           /* 팩모델 하위의 CELL중에서 일부가 자동차전지에만 BOM에서 모ITEM으로 존재하지만,PROJECT ROUTE화면에서 ESS에 생산지를 등록하도록 표기되는 오류수정 */
                           AND EXISTS (SELECT 1
                                         FROM SCM_MST_BOM_ENG_SN K
                                        WHERE K.PARENT_ITEM_ID = F.CHILD_ITEM_ID
                                          /* BOM을 제거모델 조회안되도록 수정 */
                                          AND K.KEY_DATE       = (SELECT MAX(L.KEY_DATE)
                                                                    FROM SCM_MST_BOM_ENG_SN L
                                                                   WHERE L.PARENT_ITEM_ID = F.CHILD_ITEM_ID
                                                                     AND L.DIVISION_ID    = P_DIVISION_ID)
                                          AND K.DIVISION_ID    = P_DIVISION_ID
                                          AND K.EFF_END_DATE  >= SYSDATE)
                           /* primary_plant 가 없는 것만 (ISNULL(primary_plant,'')='') */
                           AND NOT EXISTS (SELECT 1
                                             FROM SCM_MST_SITE_ITEM_PRIORITY J
                                            WHERE J.DIVISION_ID   = F.DIVISION_ID
                                              AND J.ITEM_ID       = F.CHILD_ITEM_ID
                                              AND J.PROJECT_CODE  = XE.PROJECT_CODE
                                              AND J.SALES_SITE_ID = XE.SCM_SITE_ID      /* 20180326 sales site 추가부분 */
                                              AND J.VALID_YN      = 'Y'
                                              AND J.PRIORITY      = 1
                                              AND J.TO_YYYYMMDD  >= V_TODAY)
                           /* 실적(등록된 카운트)수량은 분기되기 이전 날짜 전체를 사용해야 카운트가 맞음 */
                           /* Alternate Part 제외로직 추가 */
                           AND TRIM(G.ITEM_TYPE) <> 'R'
                           AND F.ALT_PRIORITY  = 'Y'
                           AND H.OPERATION_GROUP_ID <> 'E'
                       ) XB
                     , SCM_MST_SITE_ITEM A
                     , (SELECT M.DIVISION_ID
                             , M.ITEM_ID
                             , M.ITEM_TYPE
                             , ROW_NUMBER() OVER (PARTITION BY M.DIVISION_ID, M.ITEM_ID
                                                      ORDER BY CASE M.ITEM_TYPE WHEN 'P' THEN 999 WHEN 'H' THEN 888 WHEN 'R' THEN 777 WHEN 'Q' THEN 666 ELSE 0 END DESC) AS NUMS
                          FROM SCM_MST_ITEM_SN M
                         WHERE M.DIVISION_ID = P_DIVISION_ID
                       ) XC
                 WHERE XA.DIVISION_ID  = XB.DIVISION_ID
                   AND XA.SCM_SITE_ID  = XB.SCM_SITE_ID
                   AND XA.PROJECT_CODE = XB.PROJECT_CODE
                   AND XA.ITEM_ID      = XB.MODEL_ID
                   AND XA.DIVISION_ID  = A.DIVISION_ID
                   AND XA.ITEM_ID      = A.ITEM_ID
                   AND XA.SCM_SITE_ID  = A.SCM_SITE_ID
                   AND XA.PROJECT_CODE = A.PROJECT_CODE
                   AND XA.DIVISION_ID  = XC.DIVISION_ID
                   AND XA.ITEM_ID      = XC.ITEM_ID
                   AND XC.NUMS         = 1
                   AND TRIM(XC.ITEM_TYPE) NOT IN ('Q', 'R')
                   AND (TRIM(V_MODEL_ID) IS NULL OR XB.MODEL_ID LIKE '%' || V_MODEL_ID || '%')
                   AND (TRIM(V_ITEM_ID)  IS NULL OR XB.ITEM_ID  LIKE '%' || V_ITEM_ID  || '%')
               ) IC;
    ELSE
        INSERT INTO GT_SPRL_PIVOT01
             ( DIVISION_ID
             , SCM_SITE_ID
             , SCM_SITE_NAME
             , PROJECT_CODE
             , MODEL_ID
             , NICK_NAME
             , ITEM_ID
             , ITEM_NAME
             , OPERATION_GROUP_ID
             , OPERATION_GROUP
             , PLANT_SITE_ID
             , VALID_YN
             , PRIORITY
             , FROM_YYYYMMDD
             , TO_YYYYMMDD
             , ORG_FROM_YYYYMMDD
             , ORG_TO_YYYYMMDD
             )
        SELECT IC.DIVISION_ID
             , IC.SCM_SITE_ID
             , '-' AS SCM_SITE_NAME
             , IC.PROJECT_CODE
             , IC.MODEL_ID
             , FN_GET_ITEM_NICKNAME(IC.DIVISION_ID, IC.MODEL_ID) AS NICK_NAME
             , IC.ITEM_ID
             , FN_GET_ITEM_NICKNAME(IC.DIVISION_ID, IC.ITEM_ID) AS ITEM_NAME
             , IC.OPERATION_GROUP AS OPERATION_GROUP_ID
             , IC.OPERATION_GROUP_ID AS OPERATION_GROUP
             , '' AS PLANT_SITE_ID
             , 'Y' AS VALID_YN
             , 1 AS PRIORITY
             , '' AS FROM_YYYYMMDD
             , '' AS TO_YYYYMMDD
             , '' AS ORG_FROM_YYYYMMDD
             , '' AS ORG_TO_YYYYMMDD
          FROM (SELECT DISTINCT
                       XB.DIVISION_ID
                     , XB.SCM_SITE_ID
                     , XB.PROJECT_CODE
                     , XB.MODEL_ID
                     , XB.ITEM_ID
                     , XB.OPERATION_GROUP
                     , XB.OPERATION_GROUP_ID
                  FROM (SELECT DISTINCT
                               B.DIVISION_ID
                             , '-' AS PROJECT_CODE
                             , '-' AS SCM_SITE_ID
                             , B.ITEM_ID
                          FROM DM_PLN_MKT_FCST B
                             , (SELECT D.DIVISION_ID
                                     , D.SCM_SITE_ID
                                     , D.OPERATION_GROUP
                                     , D.VMI_YN
                                  FROM SCM_MST_SITE D
                                 WHERE (D.VMI_YN = 'Y' OR (D.SITE_TYPE = 'SALES' AND D.OPERATION_GROUP = 'W'))
                               ) XD
                         WHERE B.DIVISION_ID   = XD.DIVISION_ID(+)
                           AND B.SCM_SITE_ID   = XD.SCM_SITE_ID(+)
                           AND B.MEASURE       = CASE WHEN XD.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                                      WHEN XD.VMI_YN = 'Y' THEN 'VMI_In_Req'
                                                      WHEN TRIM(B.ATTRIBUTE10) IS NULL THEN 'MKT_FCST'
                                                 END
                           AND EXISTS (SELECT 1
                                         FROM SCM_MST_ITEM_SN C
                                        WHERE C.DIVISION_ID = B.DIVISION_ID
                                          AND C.ITEM_ID     = B.ITEM_ID
                                          AND C.SCP_OPERATION_GROUP_ID <> 'E')
                           AND B.MEASURE      IN ('AS_In_Req', 'VMI_In_Req', 'MKT_FCST')
                           AND B.QTY           > 0
                           AND B.DIVISION_ID   = P_DIVISION_ID
                           AND B.YYYYMMDD     >= V_FROM_YYYYMMDD
                           AND B.YYYYMMDD     <= V_TO_YYYYMMDD
                       ) XA
                     , (SELECT /*+ LEADING(XE) USE_NL(F) INDEX_SS(F IX01_SCM_MST_MODEL_BOM) */
                               DISTINCT
                               (CASE WHEN XE.OPERATION_GROUP = 'E' THEN G.ITEM_ID
                                     ELSE F.MODEL_ID
                                END) AS MODEL_ID
                             , (CASE
                                     /* 전극 제외 20180517 */
                                     /* WHEN d.operation_group_id = 'E' THEN 'Electrode' */
                                     WHEN H.OPERATION_GROUP_ID = 'A' THEN 'Cell'
                                     WHEN H.OPERATION_GROUP_ID = 'P' THEN 'Pack'
                                END) AS OPERATION_GROUP_ID
                             , F.CHILD_ITEM_ID AS ITEM_ID
                             , F.DIVISION_ID
                             , '-' AS SCM_SITE_ID
                             , '-' AS PROJECT_CODE
                             , H.OPERATION_GROUP_ID AS OPERATION_GROUP
                          FROM (SELECT IA.DIVISION_ID
                                     , IA.ITEM_ID
                                     , FN_GET_ITEM_OPERATION_GROUP(IA.DIVISION_ID, IA.ITEM_ID) AS OPERATION_GROUP
                                  FROM (SELECT DISTINCT
                                               E.DIVISION_ID
                                             , E.ITEM_ID
                                          FROM DM_PLN_MKT_FCST E
                                             , (SELECT I.DIVISION_ID
                                                     , I.SCM_SITE_ID
                                                     , I.OPERATION_GROUP
                                                     , I.VMI_YN
                                                  FROM SCM_MST_SITE I
                                                 WHERE (I.VMI_YN = 'Y' OR (I.SITE_TYPE = 'SALES' AND I.OPERATION_GROUP = 'W'))
                                               ) XF
                                         WHERE E.DIVISION_ID = XF.DIVISION_ID(+)
                                           AND E.SCM_SITE_ID = XF.SCM_SITE_ID(+)
                                           AND E.MEASURE     = CASE WHEN XF.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                                                    WHEN XF.VMI_YN = 'Y' THEN 'VMI_In_Req'
                                                                    WHEN TRIM(E.ATTRIBUTE10) IS NULL THEN 'MKT_FCST'
                                                               END
                                           AND E.QTY         > 0
                                           AND E.DIVISION_ID = P_DIVISION_ID
                                           AND E.YYYYMMDD   >= V_FROM_YYYYMMDD
                                           AND E.YYYYMMDD   <= V_TO_YYYYMMDD
                                       ) IA
                               ) XE
                             , SCM_MST_BOM_SN_V F        /* 2021.03.30 대체 BOM 모델링 */
                             , SCM_MST_ITEM_SN G
                             , SCM_MST_FINAL_ITEM_V H
                         WHERE XE.DIVISION_ID  = F.DIVISION_ID
                           AND XE.ITEM_ID      = F.MODEL_ID
                           AND F.COMPANY_ID    = G.COMPANY_ID
                           AND F.DIVISION_ID   = G.DIVISION_ID
                           AND F.SITE_ID       = G.SITE_ID
                           AND F.CHILD_ITEM_ID = G.ITEM_ID
                           AND F.DIVISION_ID   = H.DIVISION_ID
                           AND F.CHILD_ITEM_ID = H.ITEM_ID
                           /* 팩모델 하위의 CELL중에서 일부가 자동차전지에만 BOM에서 모ITEM으로 존재하지만,PROJECT ROUTE화면에서 ESS에 생산지를 등록하도록 표기되는 오류수정 */
                           AND EXISTS (SELECT 1
                                         FROM SCM_MST_BOM_ENG_SN K
                                        WHERE K.PARENT_ITEM_ID = F.CHILD_ITEM_ID
                                          /* BOM을 제거모델 조회안되도록 수정 */
                                          AND K.KEY_DATE       = (SELECT MAX(L.KEY_DATE)
                                                                    FROM SCM_MST_BOM_ENG_SN L
                                                                   WHERE L.PARENT_ITEM_ID = F.CHILD_ITEM_ID
                                                                     AND L.DIVISION_ID    = P_DIVISION_ID)
                                          AND K.DIVISION_ID    = P_DIVISION_ID
                                          AND K.EFF_END_DATE  >= SYSDATE)
                           /* primary_plant 가 없는 것만 (ISNULL(primary_plant,'')='') */
                           AND NOT EXISTS (SELECT 1
                                             FROM SCM_MST_SITE_ITEM_PRIORITY J
                                            WHERE J.DIVISION_ID   = F.DIVISION_ID
                                              AND J.ITEM_ID       = F.CHILD_ITEM_ID
                                              AND J.VALID_YN      = 'Y'
                                              AND J.PRIORITY      = 1
                                              AND J.TO_YYYYMMDD  >= V_TODAY)
                           /* 실적(등록된 카운트)수량은 분기되기 이전 날짜 전체를 사용해야 카운트가 맞음 */
                           /* Alternate Part 제외로직 추가 */
                           AND TRIM(G.ITEM_TYPE) <> 'R'
                           AND F.ALT_PRIORITY  = 'Y'
                           AND H.OPERATION_GROUP_ID <> 'E'
                       ) XB
                     , (SELECT M.DIVISION_ID
                             , M.ITEM_ID
                             , M.ITEM_TYPE
                             , ROW_NUMBER() OVER (PARTITION BY M.DIVISION_ID, M.ITEM_ID
                                                      ORDER BY CASE M.ITEM_TYPE WHEN 'P' THEN 999 WHEN 'H' THEN 888 WHEN 'R' THEN 777 WHEN 'Q' THEN 666 ELSE 0 END DESC) AS NUMS
                          FROM SCM_MST_ITEM_SN M
                         WHERE M.DIVISION_ID = P_DIVISION_ID
                       ) XC
                 WHERE XA.DIVISION_ID  = XB.DIVISION_ID
                   AND XA.SCM_SITE_ID  = XB.SCM_SITE_ID
                   AND XA.PROJECT_CODE = XB.PROJECT_CODE
                   AND XA.ITEM_ID      = XB.MODEL_ID
                   AND XA.DIVISION_ID  = XC.DIVISION_ID
                   AND XA.ITEM_ID      = XC.ITEM_ID
                   AND XC.NUMS         = 1
                   AND TRIM(XC.ITEM_TYPE) NOT IN ('Q', 'R')
                   AND (TRIM(V_MODEL_ID) IS NULL OR XB.MODEL_ID LIKE '%' || V_MODEL_ID || '%')
                   AND (TRIM(V_ITEM_ID)  IS NULL OR XB.ITEM_ID  LIKE '%' || V_ITEM_ID  || '%')
               ) IC;
    END IF;

    V_DESCRIPTION := 'OPEN O_RC1';
    OPEN O_RC1 FOR
        SELECT DIVISION_ID
             , SCM_SITE_ID
             , SCM_SITE_NAME
             , PROJECT_CODE
             , MODEL_ID
             , NICK_NAME
             , ITEM_ID
             , ITEM_NAME
             , OPERATION_GROUP_ID
             , OPERATION_GROUP
             , PLANT_SITE_ID
             , VALID_YN
             , PRIORITY
             , FROM_YYYYMMDD
             , TO_YYYYMMDD
             , ORG_FROM_YYYYMMDD
             , ORG_TO_YYYYMMDD
          FROM GT_SPRL_PIVOT01
         /* MSSQL 정렬 규칙 재현 : 대소문자·하이픈 무시, 밑줄은 글자·숫자 앞 */
         ORDER BY UPPER(TRANSLATE(DIVISION_ID, '_-', '/')) NULLS FIRST
                , DIVISION_ID NULLS FIRST
                , UPPER(TRANSLATE(SCM_SITE_NAME, '_-', '/')) NULLS FIRST
                , SCM_SITE_NAME NULLS FIRST
                , UPPER(TRANSLATE(PROJECT_CODE, '_-', '/')) NULLS FIRST
                , PROJECT_CODE NULLS FIRST
                , UPPER(TRANSLATE(MODEL_ID, '_-', '/')) NULLS FIRST
                , MODEL_ID NULLS FIRST
                , UPPER(TRANSLATE(ITEM_ID, '_-', '/')) NULLS FIRST
                , ITEM_ID NULLS FIRST;

    /* 2. 전체조회 */
    V_DESCRIPTION := 'OPEN O_RC2';
    OPEN O_RC2 FOR
        SELECT TO_CHAR(A.PRIORITY_SEQ) AS PRIORITY_SEQ
             , A.DIVISION_ID
             , NVL(A.PROJECT_CODE, '-') AS PROJECT_CODE
             , A.ITEM_ID
             , NVL(A.SALES_SITE_ID, '-') AS SCM_SITE_ID
             , A.PLANT_SITE_ID
             , A.PRIORITY
             , A.VALID_YN
             , A.VALID_YN AS ORG_VALID_YN
             , TO_CHAR(FN_CHAR_TO_DATE(A.FROM_YYYYMMDD), 'YYYY-MM-DD') AS FROM_YYYYMMDD
             , TO_CHAR(FN_CHAR_TO_DATE(A.TO_YYYYMMDD), 'YYYY-MM-DD') AS TO_YYYYMMDD
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
             , B.OPERATION_GROUP
             , A.FROM_YYYYMMDD AS ORG_FROM_YYYYMMDD
             , A.TO_YYYYMMDD AS ORG_TO_YYYYMMDD
             , A.FROM_YYYYMMDD || A.TO_YYYYMMDD AS MERGE_DATE
             , '' AS IS_PASS_N1
             , '' AS IS_PASS_N2
             , '' AS IS_PASS_N3
             , '' AS IS_PASS_N4
             , '' AS IS_PASS_N5
             , '' AS IS_PASS_N6
             , '' AS IS_PASS_N7
             , '-' AS ACTION_FLAG_DIV
             , 0 AS ROW_COLOR_INDEX
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE B
         WHERE A.DIVISION_ID     = B.DIVISION_ID
           AND A.PLANT_SITE_ID   = B.SCM_SITE_ID
           AND B.OPERATION_GROUP <> 'E'
           AND B.SITE_TYPE       = 'PLANT'
           AND A.VALID_YN        = 'Y'
           AND A.DIVISION_ID     = P_DIVISION_ID      /* '40' */
         /* MSSQL 정렬 규칙 재현 : 대소문자·하이픈 무시, 밑줄은 글자·숫자 앞 */
         ORDER BY A.DIVISION_ID
                , UPPER(TRANSLATE(A.ITEM_ID, '_-', '/'))
                , A.ITEM_ID
                , A.FROM_YYYYMMDD
                , A.PRIORITY
                , A.VALID_YN DESC
                , A.TO_YYYYMMDD;

    /* 3. 소형 VALIDATION용 ERP ITEM 조회 */
    V_DESCRIPTION := 'OPEN O_RC3';
    OPEN O_RC3 FOR
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.ITEM_ID
             , A.SITE_ID
          FROM SCM_MST_ITEM_SN A
             , GT_SPRL_PIVOT01 B
         WHERE A.ITEM_ID     LIKE SUBSTR(B.ITEM_ID, 1, LENGTH(RTRIM(B.ITEM_ID)) - 1) || '%'
           AND B.ITEM_ID     IS NOT NULL
           AND A.DIVISION_ID = '40'
           AND A.ACTIVE_FLAG = 'Y';

    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE
             , 'SUCCESS' AS MSG
             , CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT
          FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        V_PROC_INPUT  := SUBSTR(JSON_OBJECT( 'P_DIVISION_ID' VALUE P_DIVISION_ID
                                           , 'P_MODEL_ID'    VALUE P_MODEL_ID
                                           , 'P_ITEM_ID'     VALUE P_ITEM_ID
                                           , 'P_TIMEZONE'    VALUE P_TIMEZONE
                                           RETURNING VARCHAR2(4000)), 1, 4000);
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, SYSDATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
END P_SCM0002_GET_PROJECT_ROUTE_LIST_FORSAVE_POPUP;



/* ============================================================
   28. P_SCM0002_GET_BODITEM_FOR_SUPPLY_POPUP
   ============================================================ */
PROCEDURE P_SCM0002_GET_BODITEM_FOR_SUPPLY_POPUP
(
    P_DIVISION_ID               IN  VARCHAR2           /* chaan */
  , P_PLAN_START_YYYYMMDD       IN  VARCHAR2
  , P_PLAN_TYPE                 IN  VARCHAR2
  , P_SEQ                       IN  VARCHAR2
  , P_OPERATION_GROUP           IN  VARCHAR2
  , P_ORIGIN_FROM_DIVISION_ID   IN  VARCHAR2           /* chaan */
  , P_ORIGIN_TO_DIVISION_ID     IN  VARCHAR2           /* chaan */
  , P_ITEM_ID                   IN  VARCHAR2
  , P_PRGRAM_ID                 IN  VARCHAR2
  , O_RC1                       OUT SYS_REFCURSOR
  , O_RESULT_CURSOR             OUT SYS_REFCURSOR
)
IS
/*
 * Program ID   : SCM0002_GET_BODITEM_FOR_SUPPLY_POPUP
 * Description  : BOD ITEM 조회
 * Program History
 *===================================================================================================
 *   Date       In Charge       Description
 *===================================================================================================
 * 2019/07/08   hwyoon          Initial Release [PS02199094B] [CSR ID:4043582] GSCM - Shipment Plan FG / SEMI "New" 버튼 생성 요청 건
 * 2021/07/07   khj79           PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD 2단계 개발 : FROM,TO 추가 , scp_mst_bod_v=> scp_mst_bod_n_v
 * 2022/04/29   chaan           81_UC, EE_UC 추가로 DIVSION 크기 확장
 * 2026/04/17   YMH             E20260417-001788 Shipment Plan FG 에 New line 추가 시 BOD Validation 기능 제거
 * 2026/06/29   YMH             E20260511-000181 BOD ITEM-Excluded Item Tab 조회저장 로직 수정요청
 * 2026.09.17   AJS             PKG_SCM0002 편입 (MSSQL 원문 기준 전환)
 *                              - #TblDynamic_SCM0002_ShpimentPlan : 한 번만 참조하므로 인라인 뷰(FG / SEMI UNION ALL)
 *                              - 출하계획 원장 조회에 파티션 키(PLAN_START_YYYYMMDD_DATE) 조건 추가
 *                              - FG 원장 인덱스 건너뛰기 힌트 (인덱스 범위 조회 303초 → 0.0초, DBA 협의 대상)
 */
    V_PROGRAM_NAME     VARCHAR2(200 CHAR) := 'PKG_SCM0002.P_SCM0002_GET_BODITEM_FOR_SUPPLY_POPUP';
    V_PRGRAM_ID        VARCHAR2(4000 CHAR);
    V_TO_SITE_TYPE     VARCHAR2(4000 CHAR);
    V_PLAN_START_DATE  DATE;
    V_DIVISION_ID      VARCHAR2(4000 CHAR);
    V_PLAN_TYPE        VARCHAR2(4000 CHAR);
    V_SEQ              NUMBER;
    V_OPERATION_GROUP  VARCHAR2(4000 CHAR);
    V_FROM_DIVISION_ID VARCHAR2(4000 CHAR);
    V_TO_DIVISION_ID   VARCHAR2(4000 CHAR);
    V_ITEM_ID          VARCHAR2(4000 CHAR);

    V_LOG_TYPE         VARCHAR2(30 CHAR);
    N_LOG_COUNT        PLS_INTEGER        := 0;
    V_LOG_MESSAGE      VARCHAR2(1000 CHAR);
    V_DESCRIPTION      VARCHAR2(500 CHAR);
    V_PROC_INPUT       VARCHAR2(4000 CHAR);
    V_BACKTRACE        VARCHAR2(4000 CHAR);
    V_SQL_CODE         VARCHAR2(100 CHAR);
    V_SQL_ERRMSG       VARCHAR2(1000 CHAR);
BEGIN
    V_DESCRIPTION := 'INIT';
    /* MSSQL CI 정렬 : 프로그램ID 비교는 대소문자·후행 공백 무시 */
    V_PRGRAM_ID   := UPPER(RTRIM(P_PRGRAM_ID));
    /* MSSQL CI 정렬 : 조회조건은 대소문자 무시 (대상 칸 소문자 0건) */
    V_DIVISION_ID      := UPPER(P_DIVISION_ID);
    V_PLAN_TYPE        := UPPER(P_PLAN_TYPE);
    V_OPERATION_GROUP  := UPPER(P_OPERATION_GROUP);
    V_FROM_DIVISION_ID := UPPER(P_ORIGIN_FROM_DIVISION_ID);
    V_TO_DIVISION_ID   := UPPER(P_ORIGIN_TO_DIVISION_ID);
    V_ITEM_ID          := UPPER(P_ITEM_ID);

    IF V_PRGRAM_ID = 'FG' THEN
        V_TO_SITE_TYPE := 'SALES';
    ELSIF V_PRGRAM_ID = 'ALL' THEN          /* E20260511-000181  BOD ITEM-Excluded Item Tab 조회저장 로직 수정요청 */
        V_TO_SITE_TYPE := 'ALL';             /* E20260511-000181  BOD ITEM-Excluded Item Tab 조회저장 로직 수정요청 */
    ELSE
        V_TO_SITE_TYPE := 'PLANT';
    END IF;

    V_DESCRIPTION     := 'PLAN_START_DATE';
    V_PLAN_START_DATE := TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD');
    V_SEQ             := TO_NUMBER(P_SEQ);

    V_DESCRIPTION := 'OPEN O_RC1';
    OPEN O_RC1 FOR
        /* E20260417-001788 Shipment Plan FG 에 New line 추가 시 BOD Validation 기능 제거 로직 추가. FG UI 에서 베리데이션 해제. */
        SELECT CASE WHEN V_PRGRAM_ID = 'FG' THEN 'N'
                    WHEN XB.BOD_ID IS NULL THEN 'N'
                    ELSE 'Y'
               END AS CHK
             , CASE WHEN V_PRGRAM_ID = 'FG' THEN 'N'
                    WHEN XB.BOD_ID IS NULL THEN 'N'
                    ELSE 'Y'
               END AS "LOCK"
             , XA.DIVISION_ID
             , XA.FROM_SITE
             , XA.FROM_DIVISION_ID
             , XA.FROM_SITE_TYPE
             , XA.FROM_SITE_NAME
             , XA.TO_SITE
             , XA.TO_DIVISION_ID
             , XA.TO_SITE_TYPE
             , XA.TO_SITE_NAME
             , XA.ITEM_ID
             , XA.PRIORITY
             , XA.BOD_ID
             , XA.INCOTERMS
             , XA.TRANSPORT_MODE
             , XA.LEAD_TIME
             , XA.BOD_ITEM_VALID
             , XA.ROUTE_ID
             , XA.DAYS_MON
             , XA.DAYS_TUE
             , XA.DAYS_WED
             , XA.DAYS_THU
             , XA.DAYS_FRI
             , XA.DAYS_SAT
             , XA.DAYS_SUN
             , XA.FROM_YYYYMMDD
             , XA.TO_YYYYMMDD
          FROM (SELECT DISTINCT
                       A.DIVISION_ID
                     , B.FROM_SITE
                     , C.DIVISION_ID AS FROM_DIVISION_ID
                     , C.SITE_TYPE AS FROM_SITE_TYPE
                     , C.SITE_DESCRIPTION AS FROM_SITE_NAME
                     , B.TO_SITE
                     , D.DIVISION_ID AS TO_DIVISION_ID
                     , D.SITE_TYPE AS TO_SITE_TYPE
                     , D.SITE_DESCRIPTION AS TO_SITE_NAME
                     , A.ITEM_ID
                     , A.PRIORITY
                     , A.BOD_ID
                     , B.INCOTERMS
                     , E.TRANSPORT_MODE
                       /* BOD 2단계 개발 */
                       /* ,(SELECT v.lt_total FROM scp_mst_bod_v v WHERE v.division_id = b.division_id  and v.bod_id = b.bod_id ) AS lead_time */
                     , (SELECT SA.LT_TOTAL
                          FROM SCP_MST_BOD_N_V SA
                         WHERE SA.DIVISION_ID = B.DIVISION_ID
                           AND SA.BOD_ID      = B.BOD_ID) AS LEAD_TIME
                     , A.VALID_YN AS BOD_ITEM_VALID
                     , E.ROUTE_ID
                     , E.DAYS_MON
                     , E.DAYS_TUE
                     , E.DAYS_WED
                     , E.DAYS_THU
                     , E.DAYS_FRI
                     , E.DAYS_SAT
                     , E.DAYS_SUN
                     , TO_DATE(B.ATTRIBUTE2, 'YYYYMMDD') AS FROM_YYYYMMDD    /* BOD 2단계 개발 */
                     , TO_DATE(B.ATTRIBUTE3, 'YYYYMMDD') AS TO_YYYYMMDD      /* BOD 2단계 개발 */
                  FROM SCP_MST_BOD_ITEM A
                     , SCP_MST_BOD B
                     , SCM_MST_SITE C
                     , SCM_MST_SITE D
                     , SCP_MST_DISTRIBUTION_ROUTE E
                 WHERE A.BOD_ID          = B.BOD_ID
                   AND B.FROM_SITE       = C.SCM_SITE_ID
                   AND B.TO_SITE         = D.SCM_SITE_ID
                   AND B.ROUTE_ID        = E.ROUTE_ID
                   AND C.SITE_TYPE       = 'PLANT'
                   /* E20260511-000181  BOD ITEM-Excluded Item Tab 조회저장 로직 수정요청으로 신규로직 */
                   AND (V_TO_SITE_TYPE = 'ALL' OR (V_TO_SITE_TYPE <> 'ALL' AND D.SITE_TYPE = V_TO_SITE_TYPE))
                   AND C.OPERATION_GROUP = V_OPERATION_GROUP
                   AND A.DIVISION_ID     = V_FROM_DIVISION_ID
                   AND A.ITEM_ID         = V_ITEM_ID
               ) XA
             , (SELECT /*+ INDEX_SS(F IDX01_SCP_ANL_SHIPMENT_PLAN_FG) */
                       DISTINCT
                       F.DIVISION_ID
                     , F.ORIGIN_FROM_DIVISION_ID
                     , F.FROM_SITE
                     , F.ORIGIN_TO_DIVISION_ID
                     , F.TO_SITE
                     , F.ITEM_ID
                     , F.BOD_ID
                  FROM SCP_ANL_SHIPMENT_PLAN_FG F
                 WHERE F.MEASURE             = 'SHIP_PLAN_AMEND'
                   AND V_PRGRAM_ID          IN ('FG', 'ALL')
                   AND F.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE
                   AND F.DIVISION_ID         = V_DIVISION_ID
                   AND F.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                   AND F.PLAN_TYPE           = V_PLAN_TYPE
                   AND F.SEQ                 = V_SEQ
                   AND F.BIZ_TYPE            = V_OPERATION_GROUP
                   AND F.ITEM_ID             = V_ITEM_ID
                   AND F.YYYYMMDD            = P_PLAN_START_YYYYMMDD
                 UNION ALL
                SELECT DISTINCT
                       G.DIVISION_ID
                     , G.ORIGIN_FROM_DIVISION_ID
                     , G.FROM_SITE
                     , G.ORIGIN_TO_DIVISION_ID
                     , G.TO_SITE
                     , G.ITEM_ID
                     , G.BOD_ID
                  FROM SCP_ANL_SHIPMENT_PLAN_SEMI G
                 WHERE G.MEASURE             = 'SHIP_PLAN_AMEND'
                   AND (V_PRGRAM_ID IS NULL OR V_PRGRAM_ID <> 'FG')
                   AND G.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE
                   AND G.DIVISION_ID         = V_DIVISION_ID
                   AND G.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                   AND G.PLAN_TYPE           = V_PLAN_TYPE
                   AND G.SEQ                 = V_SEQ
                   AND G.OPERATION_GROUP     = V_OPERATION_GROUP
                   AND G.ITEM_ID             = V_ITEM_ID
                   AND G.YYYYMMDD            = P_PLAN_START_YYYYMMDD
               ) XB
         WHERE XA.FROM_DIVISION_ID = XB.ORIGIN_FROM_DIVISION_ID(+)
           AND XA.FROM_SITE        = XB.FROM_SITE(+)
           AND XA.TO_DIVISION_ID   = XB.ORIGIN_TO_DIVISION_ID(+)
           AND XA.TO_SITE          = XB.TO_SITE(+)
           AND XA.BOD_ID           = XB.BOD_ID(+)
           AND XA.TO_DIVISION_ID   = V_TO_DIVISION_ID
         /* MSSQL 정렬 규칙 재현 : 대소문자·하이픈 무시, 밑줄은 글자·숫자 앞, NULL 은 오름차순 맨 앞 */
         ORDER BY UPPER(XA.BOD_ITEM_VALID) DESC NULLS LAST
                , UPPER(TRANSLATE(XA.DIVISION_ID, '_-', '/')) NULLS FIRST
                , XA.DIVISION_ID NULLS FIRST
                , UPPER(TRANSLATE(XA.FROM_SITE, '_-', '/')) NULLS FIRST
                , XA.FROM_SITE NULLS FIRST
                , UPPER(TRANSLATE(XA.TO_SITE, '_-', '/')) NULLS FIRST
                , XA.TO_SITE NULLS FIRST
                , XA.PRIORITY NULLS FIRST
                , UPPER(TRANSLATE(XA.INCOTERMS, '_-', '/')) NULLS FIRST
                , XA.INCOTERMS NULLS FIRST
                , UPPER(TRANSLATE(XA.TRANSPORT_MODE, '_-', '/')) NULLS FIRST
                , XA.TRANSPORT_MODE NULLS FIRST;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE
             , 'SUCCESS' AS MSG
             , CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT
          FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        V_PROC_INPUT  := SUBSTR(JSON_OBJECT( 'P_DIVISION_ID'             VALUE P_DIVISION_ID
                                           , 'P_PLAN_START_YYYYMMDD'     VALUE P_PLAN_START_YYYYMMDD
                                           , 'P_PLAN_TYPE'               VALUE P_PLAN_TYPE
                                           , 'P_SEQ'                     VALUE P_SEQ
                                           , 'P_OPERATION_GROUP'         VALUE P_OPERATION_GROUP
                                           , 'P_ORIGIN_FROM_DIVISION_ID' VALUE P_ORIGIN_FROM_DIVISION_ID
                                           , 'P_ORIGIN_TO_DIVISION_ID'   VALUE P_ORIGIN_TO_DIVISION_ID
                                           , 'P_ITEM_ID'                 VALUE P_ITEM_ID
                                           , 'P_PRGRAM_ID'               VALUE P_PRGRAM_ID
                                           RETURNING VARCHAR2(4000)), 1, 4000);
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, SYSDATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
END P_SCM0002_GET_BODITEM_FOR_SUPPLY_POPUP;



/* ============================================================
   29. P_SCM0002_SAVE_SHIPMENT_PLAN_NEW
   ============================================================ */
PROCEDURE P_SCM0002_SAVE_SHIPMENT_PLAN_NEW
(
    P_DIVISION_ID               IN  VARCHAR2
  , P_PLAN_START_YYYYMMDD       IN  VARCHAR2
  , P_PLAN_TYPE                 IN  VARCHAR2
  , P_SEQ                       IN  VARCHAR2
  , P_OPERATION_GROUP           IN  VARCHAR2
  , P_PROJECT_CODE              IN  VARCHAR2
  , P_ITEM_ID                   IN  VARCHAR2
  , P_TO_SITE                   IN  VARCHAR2
  , P_INCOTERMS                 IN  VARCHAR2
  , P_FROM_SITE                 IN  VARCHAR2
  , P_BOD_ID                    IN  VARCHAR2
  , P_ORIGIN_FROM_DIVISION_ID   IN  VARCHAR2
  , P_ORIGIN_TO_DIVISION_ID     IN  VARCHAR2
  , P_ELECTRODE_TYPE            IN  VARCHAR2
  , P_PRGRAM_ID                 IN  VARCHAR2
  , P_USER_ID                   IN  VARCHAR2
  , O_RC1                       OUT SYS_REFCURSOR
  , O_RESULT_CURSOR             OUT SYS_REFCURSOR
)
IS
/*
 * Program ID   : SCM0002_SAVE_SHIPMENT_PLAN_NEW
 * Description  : Shipment Plan FG/SEMI New 입력
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019/07/11  YHW              [CSR ID:4043582] GSCM - Shipment Plan FG / SEMI "New" 버튼 생성 요청 건
 * 2021/07/26   khj79           [PJ20209643] LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - 중장기 프로젝트(기간82주로 연장)
 * 2025/11/11   hrkim           [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선
 *                              : ESS 가상 사이트 계획을 매핑된 JV 사이트 계획으로 동기화 저장 (ESS 가상 -> JV Real 단방향 저장)
 *                                - TO Site 정보는 그대로 가져간다. (BOD_ID는 매핑이 안되면 '-')
 *                              - 2025.12.16 동기화 대상 데이터 from/to 사이트와 무관하게 origin from/to division_id 컬럼 division_id와 같은 값으로 저장(81_ST) : 김춘동 책임님
 *                              - 2025.12.23 동기화 데이터 생성시 BOD_ID 매핑이 안되는 경우 ESS 가상 사이트 BOD_ID 유지
 * 2026.09.17   AJS             PKG_SCM0002 편입 (MSSQL 원문 기준 전환)
 *                              - #TblDynamic_SCM0002_ShpimentPlanNew → GT_SSPN_SHPNEW
 *                              - #TblDynamic_SCM0002_ShpimentPlan · #DIVISION_LAST_PLAN_INFO · #BOD_ITEM : 한 번만 참조하므로 인라인 뷰
 *                              - #JV_ESS_SCM_SITE_MAP : TABLE(FN_GET_JV_REAL_ESS_VIRTUAL_SITE_MAP())
 *                              - 빈 토큰은 이관 규칙대로 NOT NULL 칸 '-' · NULL 허용 칸 NULL, 없는 토큰은 AS-IS 와 같이 필수값 오류
 *                              - 저장 시작 SAVEPOINT : 오류 시 이번 호출 저장분 전체 되돌림
 *                              - 출하계획 원장 조회에 파티션 키(PLAN_START_YYYYMMDD_DATE) 조건 추가
 *                              - 기존 입력건 확인은 행마다 원장 인덱스로 (DBA 협의 대상 힌트)
 */
    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'PKG_SCM0002.P_SCM0002_SAVE_SHIPMENT_PLAN_NEW';
    V_DELIMITER             VARCHAR2(1 CHAR)   := '^';
    V_MAX_LOOP_CNT          PLS_INTEGER        := 0;
    V_MST_LOOP_CNT          PLS_INTEGER        := 0;

    /* 중장기 개발 : 52주 => 82주 변경 */
    V_DAILY_PLAN_PERIOD     PLS_INTEGER        := 0;
    V_PLAN_END_YYYYMMDD     VARCHAR2(8 CHAR);
    V_PLAN_START_DATE       DATE;
    V_SEQ                   NUMBER;
    V_PRGRAM_ID             VARCHAR2(4000 CHAR);
    V_CAL_CNT               PLS_INTEGER        := 0;
    V_NULL_CNT              PLS_INTEGER        := 0;

    V_PROJECT_CODE          VARCHAR2(50 CHAR);
    V_ITEM_ID               VARCHAR2(50 CHAR);
    V_TO_SITE               VARCHAR2(30 CHAR);
    V_INCOTERMS             VARCHAR2(10 CHAR);
    V_FROM_SITE             VARCHAR2(30 CHAR);
    V_BOD_ID                VARCHAR2(150 CHAR);
    V_ORIGIN_FROM_DIVISION_ID VARCHAR2(30 CHAR);
    V_ORIGIN_TO_DIVISION_ID VARCHAR2(30 CHAR);
    V_ELECTRODE_TYPE        VARCHAR2(30 CHAR);
    V_MISSING_YN            VARCHAR2(1 CHAR);

    /* LOG 용 변수 설정 */
    V_LOG_TYPE              VARCHAR2(30 CHAR);
    N_LOG_COUNT             PLS_INTEGER        := 0;
    V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
    V_DESCRIPTION           VARCHAR2(500 CHAR);
    D_EVENT_DATE            DATE;
    V_PROC_INPUT            VARCHAR2(4000 CHAR);
    V_BACKTRACE             VARCHAR2(4000 CHAR);
    V_SQL_CODE              VARCHAR2(100 CHAR);
    V_SQL_ERRMSG            VARCHAR2(1000 CHAR);

    /* AS-IS SCM_ARR_SPL_VAL 동작 : 값이 비어 있는 토큰은 '', 없는 토큰은 NULL */
    /* TO-BE 는 '' 를 담을 수 없으므로 빈 토큰은 P_EMPTY(이관 채움값) 로 돌려준다 */
    FUNCTION F_TOKEN
    (
        P_TEXT   IN VARCHAR2
      , P_IDX    IN PLS_INTEGER
      , P_EMPTY  IN VARCHAR2
    )
    RETURN VARCHAR2
    IS
        V_TEXT   VARCHAR2(32767 CHAR);
        V_CNT    PLS_INTEGER;
        V_WORD   VARCHAR2(32767 CHAR);
    BEGIN
        IF P_TEXT IS NULL OR P_IDX < 1 THEN
            RETURN NULL;
        END IF;
        V_TEXT := TRIM(P_TEXT);
        V_CNT  := NVL(REGEXP_COUNT(V_TEXT, '\^'), 0) + 1;
        IF P_IDX > V_CNT THEN
            RETURN NULL;
        END IF;
        V_WORD := TRIM(REGEXP_SUBSTR(V_TEXT || V_DELIMITER, '([^^]*)\^', 1, P_IDX, NULL, 1));
        RETURN NVL(V_WORD, P_EMPTY);
    END F_TOKEN;

    /* 토큰 존재 여부 (빈 토큰도 존재) */
    FUNCTION F_HAS_TOKEN
    (
        P_TEXT   IN VARCHAR2
      , P_IDX    IN PLS_INTEGER
    )
    RETURN BOOLEAN
    IS
    BEGIN
        IF P_TEXT IS NULL OR P_IDX < 1 THEN
            RETURN FALSE;
        END IF;
        RETURN P_IDX <= NVL(REGEXP_COUNT(TRIM(P_TEXT), '\^'), 0) + 1;
    END F_HAS_TOKEN;

BEGIN
    SAVEPOINT SP_SCM0002_SAVE_SHIPMENT_PLAN_NEW;

    /********************************************************************************
    * 임시테이블만들기
    ********************************************************************************/
    /* 신규입력(다건) */
    DELETE FROM GT_SSPN_SHPNEW;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* MSSQL CI 정렬 : 프로그램ID 비교는 대소문자·후행 공백 무시 */
    V_PRGRAM_ID := UPPER(RTRIM(P_PRGRAM_ID));

    /* 중장기 개발 : 52주 => 82주 변경 */
    V_DESCRIPTION := 'DAILY_PLAN_PERIOD';
    BEGIN
        SELECT NVL(DAILY_PLAN_PERIOD, 52)
          INTO V_DAILY_PLAN_PERIOD
          FROM SCM_MST_DIVISION
         WHERE DIVISION_ID = P_DIVISION_ID;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_DAILY_PLAN_PERIOD := 0;
    END;

    V_PLAN_START_DATE   := TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD');
    /* SET @p_plan_end_yyyymmdd = CONVERT(CHAR(8),DATEADD( YEAR, 1, CONVERT(DATETIME, @p_plan_start_yyyymmdd,112)), 112) */
    V_PLAN_END_YYYYMMDD := TO_CHAR(V_PLAN_START_DATE + (V_DAILY_PLAN_PERIOD * 7) - 1, 'YYYYMMDD');
    /* 중장기 개발 : 52주 => 82주 변경 끝 */
    V_SEQ               := TO_NUMBER(P_SEQ);

    /* 프로시저 LOOP 길이를 판단 */
    V_MAX_LOOP_CNT := TO_NUMBER(SCM_ARR_SPL_CNT(P_ITEM_ID, V_DELIMITER));

    /*** 1. 신규건 MEASURE별 입력데이터 정리   *****/
    V_DESCRIPTION := 'INSERT GT_SSPN_SHPNEW';
    WHILE LENGTH(RTRIM(P_DIVISION_ID)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
    LOOP
        /* @mst_loop_cnt 1증가 */
        V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

        /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
        V_PROJECT_CODE            := SUBSTR(F_TOKEN(P_PROJECT_CODE,            V_MST_LOOP_CNT, '-'),  1, 50);
        V_ITEM_ID                 := SUBSTR(F_TOKEN(P_ITEM_ID,                 V_MST_LOOP_CNT, '-'),  1, 50);
        V_TO_SITE                 := SUBSTR(F_TOKEN(P_TO_SITE,                 V_MST_LOOP_CNT, NULL), 1, 30);
        V_INCOTERMS               := SUBSTR(F_TOKEN(P_INCOTERMS,               V_MST_LOOP_CNT, '-'),  1, 10);
        V_FROM_SITE               := SUBSTR(F_TOKEN(P_FROM_SITE,               V_MST_LOOP_CNT, '-'),  1, 30);
        V_BOD_ID                  := SUBSTR(F_TOKEN(P_BOD_ID,                  V_MST_LOOP_CNT, '-'),  1, 150);
        V_ORIGIN_FROM_DIVISION_ID := SUBSTR(F_TOKEN(P_ORIGIN_FROM_DIVISION_ID, V_MST_LOOP_CNT, NULL), 1, 30);
        V_ORIGIN_TO_DIVISION_ID   := SUBSTR(F_TOKEN(P_ORIGIN_TO_DIVISION_ID,   V_MST_LOOP_CNT, NULL), 1, 30);
        V_ELECTRODE_TYPE          := SUBSTR(F_TOKEN(P_ELECTRODE_TYPE,          V_MST_LOOP_CNT, NULL), 1, 30);

        /* 필수 칸(원장·이력 NOT NULL)에 넣을 토큰이 없으면 AS-IS 는 입력 단계에서 오류 */
        IF NOT F_HAS_TOKEN(P_ITEM_ID,   V_MST_LOOP_CNT)
        OR NOT F_HAS_TOKEN(P_FROM_SITE, V_MST_LOOP_CNT)
        OR NOT F_HAS_TOKEN(P_BOD_ID,    V_MST_LOOP_CNT)
        OR NOT F_HAS_TOKEN(P_TO_SITE,   V_MST_LOOP_CNT)
        OR (V_PRGRAM_ID = 'FG' AND (NOT F_HAS_TOKEN(P_PROJECT_CODE, V_MST_LOOP_CNT) OR NOT F_HAS_TOKEN(P_INCOTERMS, V_MST_LOOP_CNT))) THEN
            V_MISSING_YN := 'Y';
        ELSE
            V_MISSING_YN := 'N';
        END IF;

        INSERT INTO GT_SSPN_SHPNEW
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , PROJECT_CODE
             , ITEM_ID
             , TO_SITE
             , INCOTERMS
             , FROM_SITE
             , BOD_ID
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , MEASURE
             , MISSING_YN
             )
        SELECT P_DIVISION_ID
             , P_PLAN_START_YYYYMMDD
             , P_PLAN_TYPE
             , P_SEQ
             , P_OPERATION_GROUP
             , V_PROJECT_CODE
             , V_ITEM_ID
             , V_TO_SITE
             , V_INCOTERMS
             , V_FROM_SITE
             , V_BOD_ID
             , V_ORIGIN_FROM_DIVISION_ID
             , V_ORIGIN_TO_DIVISION_ID
             , V_ELECTRODE_TYPE
             , XA.MEASURE
             , V_MISSING_YN
          FROM (SELECT 'SHIP_REQ' AS MEASURE
                  FROM DUAL
                 UNION
                SELECT 'SHIP_PLAN' AS MEASURE
                  FROM DUAL
                 UNION
                SELECT 'SHIP_PLAN_AMEND' AS MEASURE
                  FROM DUAL
               ) XA;
    END LOOP;

    /* ------------------------------------------------------------------------------------------------------------------------------------------------------- */
    /* ### Start : [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : ESS 가상 사이트에 매핑된 JV 사이트 계획 추가 */
    /* SEMI인 경우만 추가 */
    /* ------------------------------------------------------------------------------------------------------------------------------------------------------- */
    V_DESCRIPTION := 'INSERT GT_SSPN_SHPNEW JV';
    IF V_PRGRAM_ID <> 'FG' THEN     /* FG 제외 */
        INSERT INTO GT_SSPN_SHPNEW
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , PROJECT_CODE
             , ITEM_ID
             , TO_SITE
             , INCOTERMS
             , FROM_SITE
             , BOD_ID
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , MEASURE
             , MISSING_YN
             )
        SELECT B.RP_DIVISION_ID AS DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , XA.PLAN_TYPE AS PLAN_TYPE
             , TO_CHAR(XA.PLAN_SEQ) AS SEQ
             , A.OPERATION_GROUP
             , A.PROJECT_CODE
             , A.ITEM_ID
             , A.TO_SITE
             , A.INCOTERMS
             , B.RP_SCM_SITE_ID AS FROM_SITE
             , NVL(NVL(XB.BOD_ID, A.BOD_ID), '-') AS BOD_ID      /* 2025.12.23 bod_id 매핑이 안되는 경우 ESS가상 사이트 기준 BOD_ID 유지 */
             , B.RP_DIVISION_ID AS ORIGIN_FROM_DIVISION_ID
             , B.RP_DIVISION_ID AS ORIGIN_TO_DIVISION_ID          /* 2025.12.16 division_id와 같은 값으로 */
             , A.ELECTRODE_TYPE
             , A.MEASURE
             , A.MISSING_YN
          FROM GT_SSPN_SHPNEW A
             , TABLE(FN_GET_JV_REAL_ESS_VIRTUAL_SITE_MAP()) B
               /* DIVISION 주차별 최종 수행 Plan 버전 정보 */
               /* ESS 가상 라인 매핑 JV division의 동기화 대상 버전 정보 확인을 위한 데이터 */
             , (SELECT IA.DIVISION_ID
                     , IA.PLAN_START_YYYYMMDD
                     , IA.PLAN_TYPE
                     , IA.PLAN_SEQ
                  FROM (SELECT D.DIVISION_ID
                             , C.PLAN_NAME AS PLAN_START_YYYYMMDD
                             , D.PLAN_TYPE
                             , D.PLAN_SEQ
                             , ROW_NUMBER() OVER (PARTITION BY D.DIVISION_ID
                                                             , C.PLAN_NAME
                                                      ORDER BY CASE WHEN D.PLAN_TYPE = 'PR' THEN 4
                                                                    WHEN D.PLAN_TYPE = 'MA' THEN 3
                                                                    WHEN D.PLAN_TYPE = 'SE' THEN 2
                                                                    WHEN D.PLAN_TYPE = 'FN' THEN 1
                                                                    ELSE 0
                                                               END
                                                             , D.PLAN_SEQ DESC NULLS LAST
                                                             , D.INPUT_START_DATE DESC NULLS LAST) AS RN
                          FROM SCM_MST_PLAN C
                             , SCM_MST_PLAN_DETAIL D
                             , SCM_MST_DIVISION E
                         WHERE C.DIVISION_ID  = D.DIVISION_ID
                           AND C.PLAN_ID      = D.PLAN_ID
                           AND C.DIVISION_ID  = E.DIVISION_ID
                           AND D.PLAN_STATUS  = '1'
                           AND E.ATTRIBUTE3  <> 'EE'
                           AND C.PLAN_CYCLE   = 'WEEKLY'
                           AND C.PLAN_NAME   >= TO_CHAR(SYSDATE - 20, 'YYYYMMDD')
                       ) IA
                 WHERE IA.RN         = 1
                   AND IA.PLAN_TYPE <> 'FN'      /* Final plan 대상에서 제외 */
               ) XA
               /* BOD 및 BOD ITEM 정보 */
             , (SELECT IB.DIVISION_ID
                     , IB.FROM_SITE
                     , IB.TO_SITE
                     , IB.INCOTERMS
                     , IB.ITEM_ID
                     , IB.BOD_ID
                  FROM (SELECT F.DIVISION_ID
                             , F.FROM_SITE
                             , F.TO_SITE
                             , F.INCOTERMS
                             , G.ITEM_ID
                             , F.BOD_ID
                             , ROW_NUMBER() OVER (PARTITION BY F.DIVISION_ID
                                                             , F.FROM_SITE
                                                             , F.TO_SITE
                                                             , F.INCOTERMS
                                                             , G.ITEM_ID
                                                      ORDER BY F.PRIORITY NULLS FIRST
                                                             , G.PRIORITY NULLS FIRST
                                                             , F.ATTRIBUTE3 DESC NULLS LAST
                                                             , G.TO_YYYYMMDD DESC NULLS LAST
                                                             , F.LAST_UPDATE_DATE DESC NULLS LAST
                                                             , F.BOD_ID DESC) AS RN   /* 이관 시 수정일시 밀리초 절삭 → 동률은 BOD_ID 로 고정 */
                          FROM SCP_MST_BOD F
                             , SCP_MST_BOD_ITEM G
                         WHERE F.BOD_ID       = G.BOD_ID
                           AND EXISTS (SELECT 1
                                         FROM TABLE(FN_GET_JV_REAL_ESS_VIRTUAL_SITE_MAP()) XC
                                        WHERE XC.RP_DIVISION_ID = F.DIVISION_ID
                                          AND XC.RP_SCM_SITE_ID = F.FROM_SITE)
                           AND F.VALID_YN     = 'Y'
                           AND G.VALID_YN     = 'Y'
                           AND F.ATTRIBUTE3   > TO_CHAR(SYSDATE - 7, 'YYYYMMDD')
                           AND G.TO_YYYYMMDD >= TO_CHAR(SYSDATE - 7, 'YYYYMMDD')
                       ) IB
                 WHERE IB.RN = 1
               ) XB
         WHERE A.DIVISION_ID         = B.VP_DIVISION_ID
           AND A.FROM_SITE           = B.VP_SCM_SITE_ID
           AND B.RP_DIVISION_ID      = XA.DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = XA.PLAN_START_YYYYMMDD
           AND B.RP_DIVISION_ID      = XB.DIVISION_ID(+)
           AND B.RP_SCM_SITE_ID      = XB.FROM_SITE(+)
           AND A.TO_SITE             = XB.TO_SITE(+)
           AND A.INCOTERMS           = XB.INCOTERMS(+)
           AND A.ITEM_ID             = XB.ITEM_ID(+);
    END IF;
    /* ### End : [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : ESS 가상 사이트에 매핑된 JV 사이트 계획 추가 */

    /*** 2. 기존 Plan에 입력되있는 MEASURE 선별 삭제 *****/
    V_DESCRIPTION := 'DELETE GT_SSPN_SHPNEW';
    IF V_PRGRAM_ID = 'FG' THEN
        DELETE
          FROM GT_SSPN_SHPNEW A
         WHERE EXISTS (SELECT /*+ NO_UNNEST INDEX(B IDX01_SCP_ANL_SHIPMENT_PLAN_FG) */
                              1
                         FROM SCP_ANL_SHIPMENT_PLAN_FG B
                        WHERE B.PROJECT_CODE        = UPPER(A.PROJECT_CODE)
                          AND B.ITEM_ID             = UPPER(A.ITEM_ID)
                          AND B.TO_SITE             = UPPER(NVL(A.TO_SITE, '-'))
                          AND B.INCOTERMS           = UPPER(A.INCOTERMS)
                          AND B.FROM_SITE           = UPPER(A.FROM_SITE)
                          AND B.BOD_ID              = UPPER(A.BOD_ID)
                          AND B.MEASURE             = A.MEASURE
                          AND B.MEASURE            IN ('SHIP_REQ', 'SHIP_PLAN', 'SHIP_PLAN_AMEND')
                          AND B.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE
                          AND B.DIVISION_ID         = UPPER(P_DIVISION_ID)
                          AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                          AND B.PLAN_TYPE           = UPPER(P_PLAN_TYPE)
                          AND B.SEQ                 = V_SEQ
                          AND B.BIZ_TYPE            = UPPER(P_OPERATION_GROUP)
                          AND B.YYYYMMDD            = P_PLAN_START_YYYYMMDD);
    ELSE
        /* ### Start : [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : 기 등록된 데이터 처리 대상에서 삭제 */
        DELETE
          FROM GT_SSPN_SHPNEW A
         WHERE EXISTS (SELECT /*+ NO_UNNEST INDEX(B PK_SCP_ANL_SHIPMENT_PLAN_SEMI) */
                              1
                         FROM SCP_ANL_SHIPMENT_PLAN_SEMI B    /* DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, OPERATION_GROUP, ITEM_ID, FROM_SITE, BOD_ID, MEASURE, YYYYMMDD */
                        WHERE B.DIVISION_ID         = UPPER(A.DIVISION_ID)
                          AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
                          AND B.PLAN_TYPE           = UPPER(A.PLAN_TYPE)
                          AND B.SEQ                 = TO_NUMBER(A.SEQ)
                          AND B.OPERATION_GROUP     = UPPER(A.OPERATION_GROUP)
                          AND B.ITEM_ID             = UPPER(A.ITEM_ID)
                          AND B.FROM_SITE           = UPPER(A.FROM_SITE)
                          AND B.BOD_ID              = UPPER(A.BOD_ID)
                          AND B.MEASURE             = A.MEASURE
                          AND B.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE);
        /* ### End : [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : 기 등록된 데이터 처리 대상에서 삭제 */
    END IF;

    /*** 3. Shipment Plan FG/SEMI 입력 *****/
    D_EVENT_DATE := SYSDATE;

    /* AS-IS 필수 칸 NULL 입력 오류 재현 (TO-BE 원장은 NULL 을 '-' 로 채우므로 여기서 막는다) */
    V_DESCRIPTION := 'CHECK NOT NULL';
    SELECT COUNT(*)
      INTO V_CAL_CNT
      FROM SCM_SYS_CALENDAR_M
     WHERE BASIS_YYYYMMDD >= P_PLAN_START_YYYYMMDD
       AND BASIS_YYYYMMDD <  V_PLAN_END_YYYYMMDD;

    IF V_CAL_CNT > 0 THEN
        SELECT COUNT(*)
          INTO V_NULL_CNT
          FROM GT_SSPN_SHPNEW
         WHERE MISSING_YN          = 'Y'
            OR DIVISION_ID         IS NULL
            OR PLAN_START_YYYYMMDD IS NULL
            OR PLAN_TYPE           IS NULL
            OR SEQ                 IS NULL
            OR OPERATION_GROUP     IS NULL;

        IF V_NULL_CNT > 0 THEN
            RAISE_APPLICATION_ERROR(-20002, 'Cannot insert the value NULL into a NOT NULL column (' || V_NULL_CNT || ' rows)');
        END IF;
    END IF;

    IF V_PRGRAM_ID = 'FG' THEN
        /* 본 테이블 입력 */
        V_DESCRIPTION := 'INSERT SCP_ANL_SHIPMENT_PLAN_FG';
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FG
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , BIZ_TYPE
             , PROJECT_CODE
             , ITEM_ID
             , TO_SITE
             , INCOTERMS
             , FROM_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , TO_NUMBER(A.SEQ) AS SEQ
             , A.OPERATION_GROUP AS BIZ_TYPE
             , A.PROJECT_CODE
             , A.ITEM_ID
             , NVL(A.TO_SITE, '-') AS TO_SITE
             , A.INCOTERMS
             , A.FROM_SITE
             , A.BOD_ID
             , A.MEASURE
             , B.BASIS_YYYYMMDD AS YYYYMMDD
             , 0 AS QTY
             , A.ORIGIN_FROM_DIVISION_ID
             , A.ORIGIN_TO_DIVISION_ID
             , A.ELECTRODE_TYPE
             , P_USER_ID
             , D_EVENT_DATE
             , P_USER_ID
             , D_EVENT_DATE
          FROM GT_SSPN_SHPNEW A
             , SCM_SYS_CALENDAR_M B
         WHERE B.BASIS_YYYYMMDD >= P_PLAN_START_YYYYMMDD
           AND B.BASIS_YYYYMMDD <  V_PLAN_END_YYYYMMDD;

        /* History 입력 */
        V_DESCRIPTION := 'INSERT SCP_ANL_SHIPMENT_PLAN_FG_H';
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FG_H
             ( HISTORY_SEQ
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , BIZ_TYPE
             , PROJECT_CODE
             , ITEM_ID
             , TO_SITE
             , INCOTERMS
             , FROM_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_SHIPMENT_PLAN_FG_H.NEXTVAL
             , A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , TO_NUMBER(A.SEQ) AS SEQ
             , A.OPERATION_GROUP AS BIZ_TYPE
             , A.PROJECT_CODE
             , A.ITEM_ID
             , NVL(A.TO_SITE, '-') AS TO_SITE
             , A.INCOTERMS
             , A.FROM_SITE
             , A.BOD_ID
             , A.MEASURE
             , B.BASIS_YYYYMMDD AS YYYYMMDD
             , 0 AS QTY
             , A.ORIGIN_FROM_DIVISION_ID
             , A.ORIGIN_TO_DIVISION_ID
             , A.ELECTRODE_TYPE
             , P_USER_ID
             , D_EVENT_DATE
             , P_USER_ID
             , D_EVENT_DATE
             , D_EVENT_DATE
          FROM GT_SSPN_SHPNEW A
             , SCM_SYS_CALENDAR_M B
         WHERE B.BASIS_YYYYMMDD >= P_PLAN_START_YYYYMMDD
           AND B.BASIS_YYYYMMDD <  V_PLAN_END_YYYYMMDD;
    ELSE
        /* 본 테이블 입력 */
        V_DESCRIPTION := 'INSERT SCP_ANL_SHIPMENT_PLAN_SEMI';
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_SEMI
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , ITEM_ID
             , FROM_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , TO_SITE
             , QTY
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , TO_NUMBER(A.SEQ) AS SEQ
             , A.OPERATION_GROUP
             , A.ITEM_ID
             , A.FROM_SITE
             , A.BOD_ID
             , A.MEASURE
             , B.BASIS_YYYYMMDD AS YYYYMMDD
             , A.TO_SITE
             , 0 AS QTY
             , A.ORIGIN_FROM_DIVISION_ID
             , A.ORIGIN_TO_DIVISION_ID
             , A.ELECTRODE_TYPE
             , P_USER_ID
             , D_EVENT_DATE
             , P_USER_ID
             , D_EVENT_DATE
          FROM GT_SSPN_SHPNEW A
             , SCM_SYS_CALENDAR_M B
         WHERE B.BASIS_YYYYMMDD >= P_PLAN_START_YYYYMMDD
           AND B.BASIS_YYYYMMDD <  V_PLAN_END_YYYYMMDD;

        /* History 입력 */
        V_DESCRIPTION := 'INSERT SCP_ANL_SHIPMENT_PLAN_SEMI_H';
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_SEMI_H
             ( HISTORY_SEQ
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , ITEM_ID
             , FROM_SITE
             , TO_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_SHIPMENT_PLAN_SEMI_H.NEXTVAL
             , A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , TO_NUMBER(A.SEQ) AS SEQ
             , A.OPERATION_GROUP
             , A.ITEM_ID
             , A.FROM_SITE
             , NVL(A.TO_SITE, '-') AS TO_SITE
             , A.BOD_ID
             , A.MEASURE
             , B.BASIS_YYYYMMDD AS YYYYMMDD
             , 0 AS QTY
             , A.ORIGIN_FROM_DIVISION_ID
             , A.ORIGIN_TO_DIVISION_ID
             , A.ELECTRODE_TYPE
             , P_USER_ID
             , D_EVENT_DATE
             , P_USER_ID
             , D_EVENT_DATE
             , D_EVENT_DATE
          FROM GT_SSPN_SHPNEW A
             , SCM_SYS_CALENDAR_M B
         WHERE B.BASIS_YYYYMMDD >= P_PLAN_START_YYYYMMDD
           AND B.BASIS_YYYYMMDD <  V_PLAN_END_YYYYMMDD;
    END IF;

    /* 임시테이블 정리 */
    DELETE FROM GT_SSPN_SHPNEW;

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;

    OPEN O_RC1 FOR
        SELECT 'S' AS RESULT_CODE
             , '' AS MSG
          FROM DUAL;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE
             , 'SUCCESS' AS MSG
             , CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT
          FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_SQL_CODE   := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG := SQLERRM;
        V_BACKTRACE  := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        /* 되돌리기는 결과 커서 OPEN 앞에서 */
        BEGIN
            ROLLBACK TO SAVEPOINT SP_SCM0002_SAVE_SHIPMENT_PLAN_NEW;
        EXCEPTION
            WHEN OTHERS THEN
                ROLLBACK;
        END;
        DELETE FROM GT_SSPN_SHPNEW;

        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        D_EVENT_DATE  := SYSDATE;
        V_PROC_INPUT  := SUBSTR(JSON_OBJECT( 'P_DIVISION_ID'         VALUE P_DIVISION_ID
                                           , 'P_PLAN_START_YYYYMMDD' VALUE P_PLAN_START_YYYYMMDD
                                           , 'P_PLAN_TYPE'           VALUE P_PLAN_TYPE
                                           , 'P_SEQ'                 VALUE P_SEQ
                                           , 'P_OPERATION_GROUP'     VALUE P_OPERATION_GROUP
                                           , 'P_ITEM_ID'             VALUE SUBSTR(P_ITEM_ID, 1, 1000)
                                           , 'P_FROM_SITE'           VALUE SUBSTR(P_FROM_SITE, 1, 500)
                                           , 'P_PRGRAM_ID'           VALUE P_PRGRAM_ID
                                           , 'P_USER_ID'             VALUE P_USER_ID
                                           RETURNING VARCHAR2(4000)), 1, 4000);
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);

        /* error코드, errror 메시지 반환 */
        OPEN O_RC1 FOR
            SELECT 'F' AS RESULT_CODE
                 , '[' || V_SQL_CODE || ']' || V_SQL_ERRMSG AS ERR_MESSAGE
              FROM DUAL;

        OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE
                 , '[' || V_SQL_CODE || ']' || V_SQL_ERRMSG AS MSG
                 , V_DESCRIPTION AS EVENT
              FROM DUAL;
END P_SCM0002_SAVE_SHIPMENT_PLAN_NEW;


END PKG_SCM0002;

