                    /* 2025/10/24 kimcd [PJ2025F254] JV 동기화 설정 끝 */

                END IF;
            END LOOP;

        END IF;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', NULL, SYSDATE);

        COMMIT;

        /* 결과코드, 결과 카운트 반환 */
        O_RESULT_CODE := 'S';
        O_RESULT_CNT  := V_LOOP_CNT;
        O_RESULT_MSG  := NULL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG   := SUBSTR(SQLERRM, 1, 4000);
            V_ERR_CODE  := TO_CHAR(SQLCODE);
            V_BACKTRACE := SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 4000);

            ROLLBACK;  /* 입력 데이타 롤백 처리 */

            INSERT INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , SQL_ERR_CODE
                 , SQL_ERR_MSG
                 , SQL_BACKTRACE
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY )
            VALUES
                 ( V_PROGRAM_NAME
                 , 'ERROR'
                 , NULL
                 , V_ERR_MSG
                 , NULL
                 , V_ERR_CODE
                 , V_ERR_MSG
                 , V_BACKTRACE
                 , SYSDATE
                 , SYSDATE
                 , V_PROGRAM_NAME
                 , SYSDATE
                 , V_PROGRAM_NAME );

            COMMIT;

            /* error코드, errror 메시지 반환 */
            O_RESULT_CODE := 'F';
            O_RESULT_CNT  := NULL;
            O_RESULT_MSG  := '[' || V_ERR_CODE || ']' || V_ERR_MSG;

    END P_SCP0006_SAVE_PROJECT_ROUTE_PLANT;

