     *===================================================================================================
     * 2018/01/22   byunghunjung   Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
     * 2018/02/13   PJS   성능개선  PIVOT제거, CASE SUM방식으로 변경
     * 2018/04/17   PJS   임시테이블 삭제 OBJECT_ID형식으로 변경
     * 2018/05/28   byunghunjung 실적 테이블 값 조회시 scp_operation_group 조회조건 추가
     * 2018/05/29   PJS 주Sum 집계방식 변경
     * 2018/07/11   byunghunjung EE 사업부 실적 추가
     * 2018/07/18   YHW				전극용 조회항목 추가
     * 2021.10.25   khj79			[PJ20209643] LGES Digital SCM Level.3 달성을 위한 개선 (Phase.3) - 이력 테이블 분리(SCP_ANL_PRODUCTION_PLAN / HIST_SCP_ANL_PRODUCTION_PLAN)
     * 2022.05.13   LSC             PJ20216891 Digital SCM 3 Level 가속화를 위한 개선 : GM JV 추가
     * 2023/01/02   LWY             PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 - 조회기준 변경(main / hist) - 당주,전주(main) / 당주,전주 이전(hist)
     * 2023/04/10   LWY				PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 이행 - DIVISION_ID 공통화 작업(div_commonization)
     * 2023.07.26   vadabi3		   PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 이행 - Model, Material 개선
     * 2026.09.17                  [MSSQL -> Oracle 전환] 시트 이름 · 사용자 ID 대소문자 무시 비교(AS-IS 정렬규칙 CI 대응)
     *==================================================================================================*/
    PROCEDURE P_SCP0011_GET_PROD_PLAN_LINE
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_OPERATION_GROUP       IN  VARCHAR2,
        P_SCM_SITE_ID           IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_PROGRAM_ID            IN  VARCHAR2 DEFAULT 'SCP0011',
        P_SHEET_NAME            IN  VARCHAR2 DEFAULT 'LINE',
        P_USER_ID               IN  VARCHAR2,
        P_ELECTRODE_TYPE        IN  VARCHAR2 DEFAULT NULL,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        O_RC1                   OUT SYS_REFCURSOR,
        O_RESULT_CODE           OUT VARCHAR2,
        O_RESULT_MSG            OUT VARCHAR2
    )
    IS
        V_DIVISION_ID           VARCHAR2(50 CHAR)  := UPPER(P_DIVISION_ID);
        V_OPERATION_GROUP       VARCHAR2(50 CHAR)  := UPPER(P_OPERATION_GROUP);
        V_SCM_SITE_ID           VARCHAR2(150 CHAR) := UPPER(P_SCM_SITE_ID);
        V_ITEM_ID               VARCHAR2(300 CHAR) := UPPER(P_ITEM_ID);
        V_PLAN_TYPE             VARCHAR2(50 CHAR)  := UPPER(P_PLAN_TYPE);
        V_PROGRAM_ID            VARCHAR2(300 CHAR) := UPPER(P_PROGRAM_ID);
        V_SHEET_NAME            VARCHAR2(150 CHAR) := UPPER(P_SHEET_NAME);
        V_USER_ID               VARCHAR2(150 CHAR) := UPPER(P_USER_ID);
        V_SEQ                   NUMBER;
        V_PLAN_START_DATE       DATE;

        V_CNT_USR_MEASURE       NUMBER := 0;
        V_MIN_YYYYMMDD          VARCHAR2(8 CHAR);
        V_FROM_YYYYMMDD         VARCHAR2(8 CHAR);
        V_TO_YYYYMMDD           VARCHAR2(8 CHAR);
        V_FROM_RESULT           VARCHAR2(8 CHAR);
        V_TO_RESULT             VARCHAR2(8 CHAR);
        V_FROM_RESULT_DATE      DATE;
        V_TO_RESULT_DATE        DATE;
        V_FROM_CMP              VARCHAR2(8 CHAR);   /* 빈 문자 비교값 */
        V_TO_CMP                VARCHAR2(8 CHAR);

        V_SITE_TAB              T_STR_TAB;
        V_SITE_ALL              VARCHAR2(1 CHAR);
        V_ITEM_TAB              T_STR_TAB;
        V_ITEM_ALL              VARCHAR2(1 CHAR);
        V_ELEC_TAB              T_STR_TAB;
        V_ELEC_ALL              VARCHAR2(1 CHAR);

        V_QRY_SUM               CLOB;
        V_SQL                   CLOB;
    BEGIN

        O_RESULT_CODE := 'S';
        O_RESULT_MSG  := NULL;

        V_SEQ             := TO_NUMBER(P_SEQ);
        SELECT TO_DATE(P_PLAN_START_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD')
          INTO V_PLAN_START_DATE
          FROM DUAL;

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE PROGRAM_ID         = V_PROGRAM_ID
           AND UPPER(SHEET_NAME)  = V_SHEET_NAME
           AND UPPER(USER_ID)     = V_USER_ID;

        P_SET_PERIOD(P_PLAN_START_YYYYMMDD, P_FROM_YYYYMMDD, P_TO_YYYYMMDD
                   , V_FROM_YYYYMMDD, V_TO_YYYYMMDD, V_FROM_RESULT, V_TO_RESULT);

        V_FROM_RESULT_DATE := F_STR_DATE(V_FROM_RESULT);
        V_TO_RESULT_DATE   := F_STR_DATE(V_TO_RESULT);
        V_FROM_CMP         := F_CMP(V_FROM_YYYYMMDD);
        V_TO_CMP           := F_CMP(V_TO_YYYYMMDD);

        IF P_DEBUG_MODE = 'T' THEN
            DBMS_OUTPUT.PUT_LINE('----------------------------------');
            DBMS_OUTPUT.PUT_LINE('v_from_yyyymmdd =' || V_FROM_YYYYMMDD);
            DBMS_OUTPUT.PUT_LINE('v_to_yyyymmdd =' || V_TO_YYYYMMDD);
            DBMS_OUTPUT.PUT_LINE('v_from_result =' || V_FROM_RESULT);
            DBMS_OUTPUT.PUT_LINE('v_to_result =' || V_TO_RESULT);
            DBMS_OUTPUT.PUT_LINE('----------------------------------');
            DBMS_OUTPUT.PUT_LINE('');
        END IF;

        /* 생산실적 조회 조건은 쉼표 목록, 계획 조회 조건은 단일 값이다 (AS-IS 원문 그대로) */
        P_SPLIT_LIST(P_SCM_SITE_ID   , 'Y', V_SITE_TAB, V_SITE_ALL);
        P_SPLIT_LIST(P_ITEM_ID       , 'Y', V_ITEM_TAB, V_ITEM_ALL);
        P_SPLIT_LIST(P_ELECTRODE_TYPE, 'Y', V_ELEC_TAB, V_ELEC_ALL);

        -- 2023.01.02
        V_MIN_YYYYMMDD := F_PREV_MONDAY;     -- previous monday

        /********************************************************************************
        * 임시테이블 초기화
        ********************************************************************************/
        DELETE FROM GT_0011_LINE;

        /********************************************************************************
        * 데이타조회, 임시테이블에 저장
        ********************************************************************************/
        -- 2021.10.25 : 이력 테이블 분리
        IF F_CMP(P_PLAN_START_YYYYMMDD) >= V_MIN_YYYYMMDD THEN

            INSERT INTO GT_0011_LINE
                 (
                   DIVISION_ID
                  ,OPERATION_GROUP
                  ,SCM_SITE_ID
                  ,LINE_ID
                  ,ITEM_ID
                  ,MEASURE
                  ,MEASURE_NAME
                  ,USER_SORT_ORDER_NO
                  ,OPERATION_ID
                  ,PLAN_TYPE
                  ,PLAN_SEQ
                  ,FROM_YYYYMMDD
                  ,PLAN_START_YYYYMMDD
                  ,YYYYMMDD
                  ,YYYYMM
                  ,ISO_WEEK
                  ,QTY
                  ,ORIGIN_DIVISION_ID
                  ,ELECTRODE_TYPE
                 )
            SELECT IA.DIVISION_ID
                 , IA.OPERATION_GROUP
                 , IA.SCM_SITE_ID
                 , IA.LINE_ID
                 , IA.ITEM_ID
                 , IA.MEASURE
                 , IA.MEASURE_NAME
                 , IA.USER_SORT_ORDER_NO
                 , IA.OPERATION_ID
                 , P_PLAN_TYPE                                      AS PLAN_TYPE
                 , P_SEQ                                            AS PLAN_SEQ
                 , P_FROM_YYYYMMDD                                  AS FROM_YYYYMMDD
                 , P_PLAN_START_YYYYMMDD                            AS PLAN_START_YYYYMMDD
                 , 'D_' || IA.YYYYMMDD                              AS YYYYMMDD
                 , C.BASIS_YYYYMM                                   AS YYYYMM
                 , SUBSTR(C.BASIS_YYYYMM, -4) || C.ISO_WEEK         AS ISO_WEEK
                 , IB.QTY
                 , IA.ORIGIN_DIVISION_ID
                 , IA.ELECTRODE_TYPE
              FROM (SELECT XC.DIVISION_ID
                         , XC.PLAN_START_YYYYMMDD
                         , XC.PLAN_TYPE
                         , XC.SEQ
                         , XC.OPERATION_GROUP
                         , XC.SCM_SITE_ID
                         , XC.ITEM_ID
                         , XC.LINE_ID
                         , XC.OPERATION_ID
                         , XA.COLUMN_NAME                           AS MEASURE
                         , XA.COLUMN_LABEL_NAME                     AS MEASURE_NAME
                         , NVL(XB.SORT_ORDER_NO, XA.SORT_ORDER_NO)  AS USER_SORT_ORDER_NO
                         , XC.YYYYMMDD
                         , XC.ORIGIN_DIVISION_ID
                         , XC.ELECTRODE_TYPE
                      FROM SCM_MST_SHEET_MEASURE    XA
                         , SCM_MST_TITLESET_USER    XB
                         , (SELECT SA.DIVISION_ID
                                 , SA.PLAN_START_YYYYMMDD
                                 , SA.PLAN_TYPE
                                 , SA.SEQ
                                 , SA.OPERATION_GROUP
                                 , SA.SCM_SITE_ID
                                 , SA.ITEM_ID
                                 , SA.OPERATION_ID
                                 , SA.LINE_ID
                                 , SA.MEASURE
                                 , SA.YYYYMMDD
                                 , NVL(SA.ORIGIN_DIVISION_ID, '-')  AS ORIGIN_DIVISION_ID
                                 , NVL(SA.ELECTRODE_TYPE, '-')      AS ELECTRODE_TYPE
                              FROM SCP_ANL_PRODUCTION_PLAN SA
                             WHERE SA.YYYYMMDD                >= P_FROM_YYYYMMDD
                               AND SA.YYYYMMDD                <= P_TO_YYYYMMDD
                               AND SA.DIVISION_ID              = V_DIVISION_ID
                               AND SA.OPERATION_GROUP          = V_OPERATION_GROUP
                               AND SA.SCM_SITE_ID              = V_SCM_SITE_ID
                               AND SA.ITEM_ID                  = V_ITEM_ID
                               AND SA.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
                               AND SA.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE     /* 파티션 프루닝 */
                               AND SA.PLAN_TYPE                = V_PLAN_TYPE
                               AND SA.SEQ                      = V_SEQ
                               AND (V_ELEC_ALL = 'Y' OR NVL(SA.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                             GROUP BY SA.DIVISION_ID
                                    , SA.PLAN_START_YYYYMMDD
                                    , SA.PLAN_TYPE
                                    , SA.SEQ
                                    , SA.OPERATION_GROUP
                                    , SA.SCM_SITE_ID
                                    , SA.ITEM_ID
                                    , SA.LINE_ID
                                    , SA.OPERATION_ID
                                    , SA.MEASURE
                                    , SA.YYYYMMDD
                                    , SA.ORIGIN_DIVISION_ID
                                    , SA.ELECTRODE_TYPE
                             UNION ALL
                            -- 생산실적
                            -- Plan 테이블에는 실적 보고자 하는 YYYYMMDD가 없으므로 생성을 위해 추가
                            SELECT V_DIVISION_ID                    AS DIVISION_ID     -- div_commonization
                                 , P_PLAN_START_YYYYMMDD            AS PLAN_START_YYYYMMDD
                                 , P_PLAN_TYPE                      AS PLAN_TYPE
                                 , V_SEQ                            AS SEQ
                                 , SB.SCP_OPERATION_GROUP           AS OPERATION_GROUP
                                 , SB.SCM_SITE_ID
                                 , SB.ITEM_ID
                                 , SB.OPERATION_ID
                                 , SB.LINE_ID
                                 , 'PROD_PLAN_ENGINE'               AS MEASURE
                                 , TO_CHAR(SB.PLAN_DATE, 'YYYYMMDD') AS YYYYMMDD
                                 , SB.DIVISION_ID                   AS ORIGIN_DIVISION_ID
                                 , NVL(SB.ELECTRODE_TYPE, '-')      AS ELECTRODE_TYPE
                              FROM SCM_DNM_PRODUCT_RESULT_V SB
                             WHERE SB.DIVISION_ID IN (SELECT SC.DIVISION_ID      --div_commonization
                                                        FROM SCM_MST_DIVISION SC
                                                       WHERE SC.ATTRIBUTE4 IN (SELECT SD.ATTRIBUTE4
                                                                                 FROM SCM_MST_DIVISION SD
                                                                                WHERE SD.DIVISION_ID = V_DIVISION_ID
                                                                                  AND SD.ATTRIBUTE3  = 'EE')
                                                         AND SC.ATTRIBUTE3 <> 'EE'
                                                       UNION ALL
                                                      SELECT V_DIVISION_ID
                                                        FROM DUAL)
                               AND SB.PLAN_DATE           >= V_FROM_RESULT_DATE
                               AND SB.PLAN_DATE           <  V_TO_RESULT_DATE      -- equal 표시 주의할것
                               AND SB.SCP_OPERATION_GROUP  = V_OPERATION_GROUP
                               AND (V_SITE_ALL = 'Y' OR SB.SCM_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_SITE_TAB)))
                               AND (V_ITEM_ALL = 'Y' OR SB.ITEM_ID     IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))
                               AND (V_ELEC_ALL = 'Y' OR NVL(SB.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                             GROUP BY SB.DIVISION_ID
                                    , SB.SCP_OPERATION_GROUP
                                    , SB.SCM_SITE_ID
                                    , SB.ITEM_ID
                                    , SB.LINE_ID
                                    , SB.OPERATION_ID
                                    , SB.PLAN_DATE
                                    , SB.ELECTRODE_TYPE) XC
                     WHERE XA.PROGRAM_ID          = XB.PROGRAM_ID(+)
                       AND UPPER(XA.SHEET_NAME)   = UPPER(XB.SHEET_NAME(+))
                       AND UPPER(XA.COLUMN_NAME)  = UPPER(XB.COLUMN_NAME(+))
                       AND UPPER(XB.USER_ID(+))   = V_USER_ID
                       AND (   V_CNT_USR_MEASURE = 0
                            OR EXISTS (SELECT 1
                                         FROM SCM_MST_TITLESET_USER SE
                                        WHERE SE.PROGRAM_ID         = V_PROGRAM_ID
                                          AND UPPER(SE.SHEET_NAME)  = V_SHEET_NAME
                                          AND UPPER(SE.USER_ID)     = V_USER_ID
                                          AND UPPER(SE.COLUMN_NAME) = UPPER(XA.COLUMN_NAME)))
                       AND XA.PROGRAM_ID          = V_PROGRAM_ID
                       AND UPPER(XA.SHEET_NAME)   = V_SHEET_NAME
                       AND XA.VALID_YN            = 'Y'
                     GROUP BY XC.DIVISION_ID
                            , XC.PLAN_START_YYYYMMDD
                            , XC.PLAN_TYPE
                            , XC.SEQ
                            , XC.OPERATION_GROUP
                            , XC.SCM_SITE_ID
                            , XC.ITEM_ID
                            , XC.LINE_ID
                            , XC.OPERATION_ID
                            , XA.COLUMN_NAME
                            , XA.COLUMN_LABEL_NAME
                            , XC.YYYYMMDD
                            , NVL(XB.SORT_ORDER_NO, XA.SORT_ORDER_NO)
                            , XC.ORIGIN_DIVISION_ID
                            , XC.ELECTRODE_TYPE) IA
                 , (  -- 계획
                    SELECT XD.DIVISION_ID
                         , XD.OPERATION_GROUP
                         , XD.SCM_SITE_ID
                         , XD.ITEM_ID
                         , XD.OPERATION_ID
                         , XD.LINE_ID
                         , XD.MEASURE
                         , XD.YYYYMMDD
                         , XD.QTY
                         , NVL(XD.ORIGIN_DIVISION_ID, '-')          AS ORIGIN_DIVISION_ID
                         , NVL(XD.ELECTRODE_TYPE, '-')              AS ELECTRODE_TYPE
                      FROM SCP_ANL_PRODUCTION_PLAN XD
                     WHERE XD.YYYYMMDD                >= V_FROM_CMP
                       AND XD.YYYYMMDD                <= V_TO_CMP
                       AND XD.DIVISION_ID              = V_DIVISION_ID
                       AND XD.OPERATION_GROUP          = V_OPERATION_GROUP
                       AND XD.SCM_SITE_ID              = V_SCM_SITE_ID
                       AND XD.ITEM_ID                  = V_ITEM_ID
                       AND XD.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
                       AND XD.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE     /* 파티션 프루닝 */
                       AND XD.PLAN_TYPE                = V_PLAN_TYPE
                       AND XD.SEQ                      = V_SEQ
                       AND (V_ELEC_ALL = 'Y' OR NVL(XD.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                     UNION ALL
                    -- 생산실적
                    SELECT V_DIVISION_ID                            AS DIVISION_ID     --div_commonization
                         , XE.SCP_OPERATION_GROUP                   AS OPERATION_GROUP
                         , XE.SCM_SITE_ID
                         , XE.ITEM_ID
                         , XE.OPERATION_ID
                         , XE.LINE_ID
                         , 'PROD_PLAN_ENGINE'                       AS MEASURE
                         , TO_CHAR(XE.PLAN_DATE, 'YYYYMMDD')        AS YYYYMMDD
                         , XE.ACTUAL_GOOD_QTY                       AS QTY
                         , XE.DIVISION_ID                           AS ORIGIN_DIVISION_ID
                         , NVL(XE.ELECTRODE_TYPE, '-')              AS ELECTRODE_TYPE
                      FROM SCM_DNM_PRODUCT_RESULT_V XE
                     WHERE XE.DIVISION_ID IN (SELECT SF.DIVISION_ID      --div_commonization
                                                FROM SCM_MST_DIVISION SF
                                               WHERE SF.ATTRIBUTE4 IN (SELECT SG.ATTRIBUTE4
                                                                         FROM SCM_MST_DIVISION SG
                                                                        WHERE SG.DIVISION_ID = V_DIVISION_ID
                                                                          AND SG.ATTRIBUTE3  = 'EE')
                                                 AND SF.ATTRIBUTE3 <> 'EE'
                                               UNION ALL
                                              SELECT V_DIVISION_ID
                                                FROM DUAL)
                       AND XE.PLAN_DATE           >= V_FROM_RESULT_DATE
                       AND XE.PLAN_DATE           <  V_TO_RESULT_DATE      -- equal 표시 주의할것
                       AND XE.SCP_OPERATION_GROUP  = V_OPERATION_GROUP
                       AND XE.SCM_SITE_ID          = V_SCM_SITE_ID
                       AND XE.ITEM_ID              = V_ITEM_ID
                       AND (V_ELEC_ALL = 'Y' OR NVL(XE.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))) IB
                 , SCM_SYS_CALENDAR_M C
             WHERE IA.DIVISION_ID        = IB.DIVISION_ID(+)
               AND IA.OPERATION_GROUP    = IB.OPERATION_GROUP(+)
               AND IA.SCM_SITE_ID        = IB.SCM_SITE_ID(+)
               AND IA.ITEM_ID            = IB.ITEM_ID(+)
               AND IA.OPERATION_ID       = IB.OPERATION_ID(+)
               AND IA.LINE_ID            = IB.LINE_ID(+)
               AND IA.MEASURE            = IB.MEASURE(+)
               AND IA.YYYYMMDD           = IB.YYYYMMDD(+)
               AND IA.ORIGIN_DIVISION_ID = IB.ORIGIN_DIVISION_ID(+)
               AND IA.ELECTRODE_TYPE     = IB.ELECTRODE_TYPE(+)
               AND IA.YYYYMMDD           = C.BASIS_YYYYMMDD
                -- 조회조건 추가부분 (Model Tab에서만 사용하는 REQUIREMENT , FORMATION_YIELD Measure는 *로 입력되어 Line조회시 제외함)
               AND IA.LINE_ID           IS NOT NULL
               AND IA.LINE_ID           <> '*';

        ELSIF F_CMP(P_PLAN_START_YYYYMMDD) < V_MIN_YYYYMMDD THEN

            INSERT INTO GT_0011_LINE
                 (
                   DIVISION_ID
                  ,OPERATION_GROUP
                  ,SCM_SITE_ID
                  ,LINE_ID
                  ,ITEM_ID
                  ,MEASURE
                  ,MEASURE_NAME
                  ,USER_SORT_ORDER_NO
                  ,OPERATION_ID
                  ,PLAN_TYPE
                  ,PLAN_SEQ
                  ,FROM_YYYYMMDD
                  ,PLAN_START_YYYYMMDD
                  ,YYYYMMDD
                  ,YYYYMM
                  ,ISO_WEEK
                  ,QTY
                  ,ORIGIN_DIVISION_ID
                  ,ELECTRODE_TYPE
                 )
            SELECT IA.DIVISION_ID
                 , IA.OPERATION_GROUP
                 , IA.SCM_SITE_ID
                 , IA.LINE_ID
                 , IA.ITEM_ID
                 , IA.MEASURE
                 , IA.MEASURE_NAME
                 , IA.USER_SORT_ORDER_NO
                 , IA.OPERATION_ID
                 , P_PLAN_TYPE                                      AS PLAN_TYPE
                 , P_SEQ                                            AS PLAN_SEQ
                 , P_FROM_YYYYMMDD                                  AS FROM_YYYYMMDD
                 , P_PLAN_START_YYYYMMDD                            AS PLAN_START_YYYYMMDD
                 , 'D_' || IA.YYYYMMDD                              AS YYYYMMDD
                 , C.BASIS_YYYYMM                                   AS YYYYMM
                 , SUBSTR(C.BASIS_YYYYMM, -4) || C.ISO_WEEK         AS ISO_WEEK
                 , IB.QTY
                 , IA.ORIGIN_DIVISION_ID
                 , IA.ELECTRODE_TYPE
              FROM (SELECT XC.DIVISION_ID
                         , XC.PLAN_START_YYYYMMDD
                         , XC.PLAN_TYPE
                         , XC.SEQ
                         , XC.OPERATION_GROUP
                         , XC.SCM_SITE_ID
                         , XC.ITEM_ID
                         , XC.LINE_ID
                         , XC.OPERATION_ID
                         , XA.COLUMN_NAME                           AS MEASURE
                         , XA.COLUMN_LABEL_NAME                     AS MEASURE_NAME
                         , NVL(XB.SORT_ORDER_NO, XA.SORT_ORDER_NO)  AS USER_SORT_ORDER_NO
                         , XC.YYYYMMDD
                         , XC.ORIGIN_DIVISION_ID
                         , XC.ELECTRODE_TYPE
                      FROM SCM_MST_SHEET_MEASURE    XA
                         , SCM_MST_TITLESET_USER    XB
                         , (SELECT SA.DIVISION_ID
                                 , SA.PLAN_START_YYYYMMDD
                                 , SA.PLAN_TYPE
                                 , SA.SEQ
                                 , SA.OPERATION_GROUP
                                 , SA.SCM_SITE_ID
                                 , SA.ITEM_ID
                                 , SA.OPERATION_ID
                                 , SA.LINE_ID
                                 , SA.MEASURE
                                 , SA.YYYYMMDD
                                 , NVL(SA.ORIGIN_DIVISION_ID, '-')  AS ORIGIN_DIVISION_ID
                                 , NVL(SA.ELECTRODE_TYPE, '-')      AS ELECTRODE_TYPE
                              FROM HIST_SCP_ANL_PRODUCTION_PLAN SA
                             WHERE SA.YYYYMMDD                >= P_FROM_YYYYMMDD
                               AND SA.YYYYMMDD                <= P_TO_YYYYMMDD
                               AND SA.DIVISION_ID              = V_DIVISION_ID
                               AND SA.OPERATION_GROUP          = V_OPERATION_GROUP
                               AND SA.SCM_SITE_ID              = V_SCM_SITE_ID
                               AND SA.ITEM_ID                  = V_ITEM_ID
                               AND SA.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
                               AND SA.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE     /* 파티션 프루닝 */
                               AND SA.PLAN_TYPE                = V_PLAN_TYPE
                               AND SA.SEQ                      = V_SEQ
                               AND (V_ELEC_ALL = 'Y' OR NVL(SA.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                             GROUP BY SA.DIVISION_ID
                                    , SA.PLAN_START_YYYYMMDD
                                    , SA.PLAN_TYPE
                                    , SA.SEQ
                                    , SA.OPERATION_GROUP
                                    , SA.SCM_SITE_ID
                                    , SA.ITEM_ID
                                    , SA.LINE_ID
                                    , SA.OPERATION_ID
                                    , SA.MEASURE
                                    , SA.YYYYMMDD
                                    , SA.ORIGIN_DIVISION_ID
                                    , SA.ELECTRODE_TYPE
                             UNION ALL
                            -- 생산실적
                            -- Plan 테이블에는 실적 보고자 하는 YYYYMMDD가 없으므로 생성을 위해 추가
                            SELECT V_DIVISION_ID                    AS DIVISION_ID     --div_commonization
                                 , P_PLAN_START_YYYYMMDD            AS PLAN_START_YYYYMMDD
                                 , P_PLAN_TYPE                      AS PLAN_TYPE
                                 , V_SEQ                            AS SEQ
                                 , SB.SCP_OPERATION_GROUP           AS OPERATION_GROUP
                                 , SB.SCM_SITE_ID
                                 , SB.ITEM_ID
                                 , SB.OPERATION_ID
                                 , SB.LINE_ID
                                 , 'PROD_PLAN_ENGINE'               AS MEASURE
                                 , TO_CHAR(SB.PLAN_DATE, 'YYYYMMDD') AS YYYYMMDD
                                 , SB.DIVISION_ID                   AS ORIGIN_DIVISION_ID
                                 , NVL(SB.ELECTRODE_TYPE, '-')      AS ELECTRODE_TYPE
                              FROM SCM_DNM_PRODUCT_RESULT_V SB
                             WHERE SB.DIVISION_ID IN (SELECT SC.DIVISION_ID      --div_commonization
                                                        FROM SCM_MST_DIVISION SC
                                                       WHERE SC.ATTRIBUTE4 IN (SELECT SD.ATTRIBUTE4
                                                                                 FROM SCM_MST_DIVISION SD
                                                                                WHERE SD.DIVISION_ID = V_DIVISION_ID
                                                                                  AND SD.ATTRIBUTE3  = 'EE')
                                                         AND SC.ATTRIBUTE3 <> 'EE'
                                                       UNION ALL
                                                      SELECT V_DIVISION_ID
                                                        FROM DUAL)
                               AND SB.PLAN_DATE           >= V_FROM_RESULT_DATE
                               AND SB.PLAN_DATE           <  V_TO_RESULT_DATE      -- equal 표시 주의할것
                               AND SB.SCP_OPERATION_GROUP  = V_OPERATION_GROUP
                               AND (V_SITE_ALL = 'Y' OR SB.SCM_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_SITE_TAB)))
                               AND (V_ITEM_ALL = 'Y' OR SB.ITEM_ID     IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))
                               AND (V_ELEC_ALL = 'Y' OR NVL(SB.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                             GROUP BY SB.DIVISION_ID
                                    , SB.SCP_OPERATION_GROUP
                                    , SB.SCM_SITE_ID
                                    , SB.ITEM_ID
                                    , SB.LINE_ID
                                    , SB.OPERATION_ID
                                    , SB.PLAN_DATE
                                    , SB.ELECTRODE_TYPE) XC
                     WHERE XA.PROGRAM_ID          = XB.PROGRAM_ID(+)
                       AND UPPER(XA.SHEET_NAME)   = UPPER(XB.SHEET_NAME(+))
                       AND UPPER(XA.COLUMN_NAME)  = UPPER(XB.COLUMN_NAME(+))
                       AND UPPER(XB.USER_ID(+))   = V_USER_ID
                       AND (   V_CNT_USR_MEASURE = 0
                            OR EXISTS (SELECT 1
                                         FROM SCM_MST_TITLESET_USER SE
                                        WHERE SE.PROGRAM_ID         = V_PROGRAM_ID
                                          AND UPPER(SE.SHEET_NAME)  = V_SHEET_NAME
                                          AND UPPER(SE.USER_ID)     = V_USER_ID
                                          AND UPPER(SE.COLUMN_NAME) = UPPER(XA.COLUMN_NAME)))
                       AND XA.PROGRAM_ID          = V_PROGRAM_ID
                       AND UPPER(XA.SHEET_NAME)   = V_SHEET_NAME
                       AND XA.VALID_YN            = 'Y'
                     GROUP BY XC.DIVISION_ID
                            , XC.PLAN_START_YYYYMMDD
                            , XC.PLAN_TYPE
                            , XC.SEQ
                            , XC.OPERATION_GROUP
                            , XC.SCM_SITE_ID
                            , XC.ITEM_ID
                            , XC.LINE_ID
                            , XC.OPERATION_ID
                            , XA.COLUMN_NAME
                            , XA.COLUMN_LABEL_NAME
                            , XC.YYYYMMDD
                            , NVL(XB.SORT_ORDER_NO, XA.SORT_ORDER_NO)
                            , XC.ORIGIN_DIVISION_ID
                            , XC.ELECTRODE_TYPE) IA
                 , (  -- 계획
                    SELECT XD.DIVISION_ID
                         , XD.OPERATION_GROUP
                         , XD.SCM_SITE_ID
                         , XD.ITEM_ID
                         , XD.OPERATION_ID
                         , XD.LINE_ID
                         , XD.MEASURE
                         , XD.YYYYMMDD
                         , XD.QTY
                         , NVL(XD.ORIGIN_DIVISION_ID, '-')          AS ORIGIN_DIVISION_ID
                         , NVL(XD.ELECTRODE_TYPE, '-')              AS ELECTRODE_TYPE
                      FROM HIST_SCP_ANL_PRODUCTION_PLAN XD
                     WHERE XD.YYYYMMDD                >= V_FROM_CMP
                       AND XD.YYYYMMDD                <= V_TO_CMP
                       AND XD.DIVISION_ID              = V_DIVISION_ID
                       AND XD.OPERATION_GROUP          = V_OPERATION_GROUP
                       AND XD.SCM_SITE_ID              = V_SCM_SITE_ID
                       AND XD.ITEM_ID                  = V_ITEM_ID
                       AND XD.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
                       AND XD.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE     /* 파티션 프루닝 */
                       AND XD.PLAN_TYPE                = V_PLAN_TYPE
                       AND XD.SEQ                      = V_SEQ
                       AND (V_ELEC_ALL = 'Y' OR NVL(XD.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))
                     UNION ALL
                    -- 생산실적
                    SELECT V_DIVISION_ID                            AS DIVISION_ID     --div_commonization
                         , XE.SCP_OPERATION_GROUP                   AS OPERATION_GROUP
                         , XE.SCM_SITE_ID
                         , XE.ITEM_ID
                         , XE.OPERATION_ID
                         , XE.LINE_ID
                         , 'PROD_PLAN_ENGINE'                       AS MEASURE
                         , TO_CHAR(XE.PLAN_DATE, 'YYYYMMDD')        AS YYYYMMDD
                         , XE.ACTUAL_GOOD_QTY                       AS QTY
                         , XE.DIVISION_ID                           AS ORIGIN_DIVISION_ID
                         , NVL(XE.ELECTRODE_TYPE, '-')              AS ELECTRODE_TYPE
                      FROM SCM_DNM_PRODUCT_RESULT_V XE
                     WHERE XE.DIVISION_ID IN (SELECT SF.DIVISION_ID      --div_commonization
                                                FROM SCM_MST_DIVISION SF
                                               WHERE SF.ATTRIBUTE4 IN (SELECT SG.ATTRIBUTE4
                                                                         FROM SCM_MST_DIVISION SG
                                                                        WHERE SG.DIVISION_ID = V_DIVISION_ID
                                                                          AND SG.ATTRIBUTE3  = 'EE')
                                                 AND SF.ATTRIBUTE3 <> 'EE'
                                               UNION ALL
                                              SELECT V_DIVISION_ID
                                                FROM DUAL)
                       AND XE.PLAN_DATE           >= V_FROM_RESULT_DATE
                       AND XE.PLAN_DATE           <  V_TO_RESULT_DATE      -- equal 표시 주의할것
                       AND XE.SCP_OPERATION_GROUP  = V_OPERATION_GROUP
                       AND XE.SCM_SITE_ID          = V_SCM_SITE_ID
                       AND XE.ITEM_ID              = V_ITEM_ID
                       AND (V_ELEC_ALL = 'Y' OR NVL(XE.ELECTRODE_TYPE, '-') IN (SELECT COLUMN_VALUE FROM TABLE(V_ELEC_TAB)))) IB
                 , SCM_SYS_CALENDAR_M C
             WHERE IA.DIVISION_ID        = IB.DIVISION_ID(+)
               AND IA.OPERATION_GROUP    = IB.OPERATION_GROUP(+)
               AND IA.SCM_SITE_ID        = IB.SCM_SITE_ID(+)
               AND IA.ITEM_ID            = IB.ITEM_ID(+)
               AND IA.OPERATION_ID       = IB.OPERATION_ID(+)
               AND IA.LINE_ID            = IB.LINE_ID(+)
               AND IA.MEASURE            = IB.MEASURE(+)
               AND IA.YYYYMMDD           = IB.YYYYMMDD(+)
               AND IA.ORIGIN_DIVISION_ID = IB.ORIGIN_DIVISION_ID(+)
               AND IA.ELECTRODE_TYPE     = IB.ELECTRODE_TYPE(+)
               AND IA.YYYYMMDD           = C.BASIS_YYYYMMDD
                -- 조회조건 추가부분 (Model Tab에서만 사용하는 REQUIREMENT , FORMATION_YIELD Measure는 *로 입력되어 Line조회시 제외함)
               AND IA.LINE_ID           IS NOT NULL
               AND IA.LINE_ID           <> '*';

        END IF;

        /********************************************************************************
        * PIVOIT처리
        ********************************************************************************/
        -- PIVOIT 대상 날짜문자열 생성
        V_QRY_SUM := NULL;

        FOR R IN (SELECT IA.COL_NAME
                    FROM (SELECT 'W_' || XA.BASIS_YYYYMM || XA.ISO_WEEK             AS COL_NAME
                               , XA.BASIS_START_DATE || '21'                        AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M XA
                           WHERE XA.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           GROUP BY XA.BASIS_YYYYMM
                                  , XA.ISO_WEEK
                                  , XA.BASIS_START_DATE
                           UNION ALL
                          SELECT 'M_' || XB.BASIS_YYYYMM                            AS COL_NAME
                               , MIN(XB.BASIS_START_DATE) || '01'                   AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M XB
                           WHERE XB.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           GROUP BY XB.BASIS_YYYYMM
                                  , XB.MONTH_NAME
                           UNION ALL
                          SELECT 'D_' || XC.BASIS_YYYYMMDD                          AS COL_NAME
                               , XC.BASIS_YYYYMMDD || '31'                          AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M XC
                           WHERE XC.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           GROUP BY XC.BASIS_YYYYMMDD) IA
                   ORDER BY IA.SORT_ORDER_NO)
        LOOP
            IF SUBSTR(R.COL_NAME, 1, 2) = 'M_' THEN
                V_QRY_SUM := V_QRY_SUM
                          || '     , SUM(CASE WHEN YYYYMM = ''' || SUBSTR(R.COL_NAME, -6) || ''' THEN QTY END) AS ' || R.COL_NAME || CHR(10);
            ELSIF SUBSTR(R.COL_NAME, 1, 2) = 'W_' THEN
                V_QRY_SUM := V_QRY_SUM
                          || '     , SUM(CASE WHEN ISO_WEEK = ''' || SUBSTR(R.COL_NAME, -6) || ''' THEN QTY END) AS ' || R.COL_NAME || CHR(10);
            ELSE
                V_QRY_SUM := V_QRY_SUM
                          || '     , SUM(CASE WHEN YYYYMMDD = ''' || R.COL_NAME || ''' THEN QTY END) AS ' || R.COL_NAME || CHR(10);
            END IF;
        END LOOP;

        V_SQL := 'SELECT DIVISION_ID' || CHR(10)
              || '     , FN_GET_DIVISION_NAME(DIVISION_ID) AS DIVISION_NAME' || CHR(10)
              || '     , OPERATION_GROUP' || CHR(10)
              || '     , FN_GET_LOOKUP_CODE_DESC(''OPERATION_GROUP'', OPERATION_GROUP) AS OPERATION_GROUP_NAME' || CHR(10)
              || '     , SCM_SITE_ID' || CHR(10)
              || '     , FN_GET_SCM_SITE_DESCRIPTION(DIVISION_ID, SCM_SITE_ID) AS SCM_SITE_DESCRIPTION' || CHR(10)
              || '     , LINE_ID' || CHR(10)
              || '     , FN_GET_ITEM_PROD_OP(DIVISION_ID, OPERATION_GROUP, ITEM_ID) AS MODEL_ID' || CHR(10)
              || '     , ITEM_ID' || CHR(10)
              || '     , NVL(FN_GET_ITEM_NICKNAME(DIVISION_ID, ITEM_ID), ''-'') AS NICK_NAME' || CHR(10)
              || '     , MEASURE' || CHR(10)
              || '     , MEASURE_NAME' || CHR(10)
              || '     , OPERATION_ID' || CHR(10)
              || '     , PLAN_TYPE' || CHR(10)
              || '     , PLAN_SEQ' || CHR(10)
              || '     , PLAN_START_YYYYMMDD' || CHR(10)
              || '     , FROM_YYYYMMDD' || CHR(10)
              || '     , USER_SORT_ORDER_NO' || CHR(10)
              || '     , ORIGIN_DIVISION_ID' || CHR(10)
              || '     , ELECTRODE_TYPE' || CHR(10)
              || V_QRY_SUM
              || '  FROM GT_0011_LINE' || CHR(10)
              || ' GROUP BY DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, LINE_ID, ITEM_ID, MEASURE, MEASURE_NAME, OPERATION_ID, PLAN_TYPE, PLAN_SEQ, PLAN_START_YYYYMMDD, FROM_YYYYMMDD, USER_SORT_ORDER_NO' || CHR(10)
              || '        , ORIGIN_DIVISION_ID, ELECTRODE_TYPE' || CHR(10)
              || ' ORDER BY DIVISION_ID NULLS FIRST, OPERATION_GROUP NULLS FIRST, SCM_SITE_ID NULLS FIRST, LINE_ID NULLS FIRST, ITEM_ID NULLS FIRST, USER_SORT_ORDER_NO NULLS FIRST';   /* AS-IS 오름차순은 NULL 이 앞 */

        -----------------------------------------------------------
        -- DEBUG QRY 출력
        -----------------------------------------------------------
        IF P_DEBUG_MODE = 'T' THEN
            P_PUT_CLOB(V_SQL);
        END IF;

        OPEN O_RC1 FOR V_SQL;

    EXCEPTION
        WHEN OTHERS THEN
            O_RESULT_CODE := 'F';
            O_RESULT_MSG  := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

            P_LOG_ERROR('SCP0011_GET_PRODUCTION_PLAN_LINE'
                      , 'P_DIVISION_ID=' || P_DIVISION_ID
                     || ', P_OPERATION_GROUP=' || P_OPERATION_GROUP
                     || ', P_SCM_SITE_ID=' || P_SCM_SITE_ID
                     || ', P_ITEM_ID=' || P_ITEM_ID
                     || ', P_FROM_YYYYMMDD=' || P_FROM_YYYYMMDD
                     || ', P_TO_YYYYMMDD=' || P_TO_YYYYMMDD
                     || ', P_PLAN_START_YYYYMMDD=' || P_PLAN_START_YYYYMMDD
                     || ', P_PLAN_TYPE=' || P_PLAN_TYPE
                     || ', P_SEQ=' || P_SEQ
                     || ', P_USER_ID=' || P_USER_ID
                     || ', P_ELECTRODE_TYPE=' || P_ELECTRODE_TYPE
                      , SQLCODE
                      , SQLERRM
                      , DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

    END P_SCP0011_GET_PROD_PLAN_LINE;


    /*==================================================================================================
     * Program ID   : SCP0011_GET_PLAN_EDIT_INFO
     * Description  : PLAN 별 편집가능 여부 정보 조회
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2018/04/02   PJS    			Initial Release  전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
     * 2018/05/21   PJS             PR 수정모드 조건 변경
     * 2018/06/01   PJS             PLAN 시작일 가져오는 조건 변경
     * 2018/06/07   PJS             MA일 경우 FP운용기간-7일 처리
     * 2018/06/20   PJS             edit_start_date 계산 로직수정(offset -7반영)
     * 2018/07/18	YHW				전극데이터 편집가능여부 조건 수정(ORIGIN DIVISION 사용)
     * 2020/10/28   khj79           [C20201019-000175] , 자동차(81) 사업부의 경우 Final Plan 제외하고 전 구간 생산계획 수정 가능
     * 2021/10/13   khj79			[PJ20209643] LGES Digital SCM Level.3 달성을 위한 개선 (Phase.3) - 82(ESS) 'MA' 플랜 전 구간 수정 가능
     * 2023/05/03   LWY			    PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 이행 - 81 / SE : PROD_FROZEN 구간 EDIT 불가 적용.
     * 2026.09.17                   [MSSQL -> Oracle 전환] 사이트 비교 대소문자 무시(AS-IS 정렬규칙 CI 대응)
     *==================================================================================================*/
    PROCEDURE P_SCP0011_GET_PLAN_EDIT_INFO
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_SCM_SITE_ID           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_ORIGIN_DIVISION_ID    IN  VARCHAR2 DEFAULT NULL,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        O_RC1                   OUT SYS_REFCURSOR,
        O_RESULT_CODE           OUT VARCHAR2,
        O_RESULT_MSG            OUT VARCHAR2
    )
    IS
        V_DIVISION_ID           VARCHAR2(50 CHAR) := UPPER(P_DIVISION_ID);
        V_PLAN_TYPE             VARCHAR2(50 CHAR) := UPPER(P_PLAN_TYPE);
        V_ORIGIN_DIVISION_ID    VARCHAR2(60 CHAR) := UPPER(P_ORIGIN_DIVISION_ID);
        V_SEQ                   NUMBER;
        V_BUCKET_M10            VARCHAR2(8 CHAR);       /* 10주전 */
    BEGIN

        O_RESULT_CODE := 'S';
        O_RESULT_MSG  := NULL;

        V_SEQ        := TO_NUMBER(P_SEQ);
        V_BUCKET_M10 := FN_GET_BUCKET_YYYYMMDD(-10);

        OPEN O_RC1 FOR
        SELECT IA.DIVISION_ID
             , IA.PLAN_VERSION_ID
             , IA.PLAN_NAME                                         AS PLAN_START_YYYYMMDD
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IC.OSP_YN
             , IC.FP_PLAN_PERIOD
             , CASE
                   WHEN IA.PLAN_TYPE = 'PR' THEN 0
                   WHEN IA.PLAN_TYPE = 'MA' THEN IC.OFFSET - 7
                   ELSE IC.OFFSET
               END                                                  AS OFFSET
                -- 자동차(81) 사업부의 경우 Final Plan 제외하고 전 구간 생산계획 수정 가능
                -- 2021.10.13 : ESS(82) 사업부의 경우 'MA' 플랜 전 구간 생산계획 수정 가능
             , TO_CHAR(TO_DATE(IA.PLAN_NAME, 'YYYYMMDD')
                       + CASE
                             WHEN IA.PLAN_TYPE = 'PR' THEN 0
                              -- LWY begin (2023/05/03)
                              --WHEN A.DIVISION_ID = '81' THEN 0
                             WHEN IA.DIVISION_ID = '81'  AND IA.PLAN_TYPE != 'SE' THEN 0
                             WHEN IA.DIVISION_ID = '81'  AND IA.PLAN_TYPE  = 'SE' THEN IC.PROD_FROZEN
                              -- LWY end	 (2023/05/03)
                              -- 2021.10.13 : ESS(82) 사업부의 경우 'MA' 플랜 전 구간 생산계획 수정 가능
                              --WHEN plan_type ='MA' THEN c.offset -7
                             WHEN IA.DIVISION_ID = '82'  AND IA.PLAN_TYPE  = 'MA' THEN 0
                             WHEN IA.DIVISION_ID != '82' AND IA.PLAN_TYPE  = 'MA' THEN IC.OFFSET - 7
                             ELSE IC.OFFSET
                         END, 'YYYYMMDD')                           AS EDIT_START_DATE
             , CASE IA.PLAN_TYPE
                   WHEN 'PR' THEN 0
                   WHEN 'MA' THEN 1
                   WHEN 'SE' THEN 3
                   WHEN 'FI' THEN 4
                   ELSE 9
               END                                                  AS PLAN_TYPE_ORDER
             , IA.CONFIRM_YN
             , CASE
                   WHEN IA.PLAN_NAME < IB.BASIS_START_DATE
                   THEN 'N'
                   ELSE 'Y'
               END                                                  AS DATE_CHK
             , 'Y'                                                  AS IS_EDITABLE
          FROM (SELECT XA.DIVISION_ID
                     , XB.PLAN_NAME || '-' || XA.PLAN_TYPE || '-' || FN_ZERO_LPAD(TO_CHAR(XA.PLAN_SEQ), 2)  AS PLAN_VERSION_ID
                     , XB.PLAN_NAME
                     , XA.PLAN_SEQ
                     , XA.PLAN_TYPE
                     , CASE
                           WHEN RTRIM(XA.CONFIRM_FLAG) IS NULL
                           THEN 'N'
                           ELSE XA.CONFIRM_FLAG
                       END                                          AS CONFIRM_YN
                  FROM SCM_MST_PLAN_DETAIL  XA
                     , SCM_MST_PLAN         XB
                     , SCM_MST_MODELING     XC
                 WHERE XC.MODELING_ID = XA.MODELING_ID
                   AND XC.DIVISION_ID = XA.DIVISION_ID
                   AND XB.DIVISION_ID = XA.DIVISION_ID
                   AND XB.PLAN_CYCLE  = XC.PLAN_CYCLE
                   AND XB.PLAN_ID     = XA.PLAN_ID
                   AND XC.PLAN_CYCLE  = 'WEEKLY'
                   AND XB.PLAN_NAME  >= V_BUCKET_M10       --10주전
                   AND XA.DIVISION_ID = V_DIVISION_ID
                   AND XA.PLAN_TYPE   = V_PLAN_TYPE
                   AND XA.PLAN_SEQ    = V_SEQ
                   AND XB.PLAN_NAME   = P_PLAN_START_YYYYMMDD) IA
             , (SELECT TO_CHAR(TO_DATE(XD.BASIS_YYYYMMDD, 'YYYYMMDD') - (XD.DAYOFWEEK_NO - 1), 'YYYYMMDD') AS BASIS_START_DATE
                  FROM (SELECT CASE
                                   WHEN SA.DAYOFWEEK_NO - 1 = 0
                                   THEN 7
                                   ELSE SA.DAYOFWEEK_NO - 1
                               END                                  AS DAYOFWEEK_NO
                             , SA.BASIS_YYYYMMDD
                          FROM SCM_SYS_CALENDAR_M SA
                         WHERE SA.BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD')) XD) IB
             , (SELECT XE.OSP_YN
                     , XE.FP_PLAN_PERIOD
                     , CASE
                           WHEN XE.OSP_YN = 'Y'
                           THEN 0
                           ELSE XE.FP_PLAN_PERIOD
                       END                                          AS OFFSET
                     , XE.PROD_FROZEN -- LWY
                  FROM SCM_MST_SITE XE
                 WHERE XE.DIVISION_ID        = V_ORIGIN_DIVISION_ID
                   AND UPPER(XE.SCM_SITE_ID) = UPPER(P_SCM_SITE_ID)) IC;

    EXCEPTION
        WHEN OTHERS THEN
            O_RESULT_CODE := 'F';
            O_RESULT_MSG  := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

            P_LOG_ERROR('SCP0011_GET_PLAN_EDIT_INFO'
                      , 'P_DIVISION_ID=' || P_DIVISION_ID
                     || ', P_SCM_SITE_ID=' || P_SCM_SITE_ID
                     || ', P_PLAN_START_YYYYMMDD=' || P_PLAN_START_YYYYMMDD
                     || ', P_PLAN_TYPE=' || P_PLAN_TYPE
                     || ', P_SEQ=' || P_SEQ
                     || ', P_ORIGIN_DIVISION_ID=' || P_ORIGIN_DIVISION_ID
                      , SQLCODE
                      , SQLERRM
                      , DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

    END P_SCP0011_GET_PLAN_EDIT_INFO;


    /*==================================================================================================
     * Program ID   : PR_SCP_ANL_PRODUCTION_PLAN_I_AMEND
     * Description  :
     * OutTable     :
     * Execute      : EXEC PR_SCP_ANL_PRODUCTION_PLAN_I_AMEND N'81',N'20180108',N'MA',N'2',N'LTW'
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2018.06.07   LTW         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
     * 2018.06.11	HWY			EOH 계산 관련 RETURN값 수정
     * 2026.09.18               [MSSQL -> Oracle 전환] 화면 Target-Plan(Amend) 재계산 (SCP0011 만 호출)
     *                          조인 갱신은 재계산 값을 임시 테이블에 담은 뒤 상관 갱신으로 전환
     *==================================================================================================*/
    PROCEDURE P_SCP_ANL_PROD_PLAN_I_AMEND
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,   -- plan_name
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_OPERATION_GROUP       IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2 DEFAULT 'scp_batch',
        O_RC1                   OUT SYS_REFCURSOR,
        O_RESULT_CODE           OUT VARCHAR2,
        O_RESULT_MSG            OUT VARCHAR2
    )
    IS
        V_DIVISION_ID           VARCHAR2(30 CHAR)   := UPPER(P_DIVISION_ID);
        V_PLAN_TYPE             VARCHAR2(30 CHAR)   := UPPER(P_PLAN_TYPE);
        V_OPERATION_GROUP       VARCHAR2(10 CHAR)   := UPPER(P_OPERATION_GROUP);
        V_SEQ                   NUMBER;
        V_PLAN_START_DATE       DATE;

        -- LOG 용 변수 설정
        V_BATCH_USER            VARCHAR2(150 CHAR)  := P_USER_ID;
        V_PROGRAM_NAME          VARCHAR2(150 CHAR)  := 'PR_SCP_ANL_PRODUCTION_PLAN_I_AMEND';
        V_LOG_TYPE              VARCHAR2(30 CHAR);  -- START/END/ERROR/...
        N_LOG_COUNT             NUMBER              := 0;
        V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
        V_DESCRIPTION           VARCHAR2(500 CHAR);
        V_TABLE_ID              VARCHAR2(150 CHAR)  := 'SCP_ANL_PRODUCTION_PLAN';
        D_EVENT_DATE            DATE;
    BEGIN

        O_RESULT_CODE := 'S';
        O_RESULT_MSG  := NULL;

        -- 시작 LOG
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := V_PROGRAM_NAME || ':' || ' SCP_ANL_PRODUCTION_PLAN UPDATE LOGIC';
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                           , P_LOG_TYPE     => V_LOG_TYPE
                           , P_LOG_COUNT    => N_LOG_COUNT
                           , P_LOG_MESSAGE  => V_LOG_MESSAGE
                           , P_DESCRIPTION  => V_DESCRIPTION
                           , P_EVENT_DATE   => D_EVENT_DATE
                           , P_USER_ID      => V_BATCH_USER);

        BEGIN

            /* AS-IS 는 문자 차수를 숫자 칸과 비교해 형 변환 오류가 나면 CATCH 로 간다 */
            V_SEQ := TO_NUMBER(P_SEQ);

            /* 파티션 프루닝용 - 형식이 틀리면 NULL 이고, 이때는 계획 일자 조건이 이미 0 건이다 */
            SELECT TO_DATE(P_PLAN_START_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD')
              INTO V_PLAN_START_DATE
              FROM DUAL;

            -----------------------------------------------------------
            --1. 생산계획(ONHAND_EOH) 데이터 AMEND
            -----------------------------------------------------------
            DELETE FROM GT_0011_AMEND;

            /* 사이트 · 품목별 누적(생산계획 AMEND - 요구량) — 같은 일자 행은 같은 누적값(RANGE 기본 범위) */
            INSERT INTO GT_0011_AMEND
                 (
                   SCM_SITE_ID
                  ,ITEM_ID
                  ,YYYYMMDD
                  ,QTY
                 )
            SELECT DISTINCT
                   IA.SCM_SITE_ID
                 , IA.ITEM_ID
                 , IA.YYYYMMDD
                 , IA.P_SUM - IA.S_SUM                              AS QTY
              FROM (SELECT A.SCM_SITE_ID
                         , A.ITEM_ID
                         , A.YYYYMMDD
                         , SUM(CASE
                                   WHEN A.MEASURE = 'REQUIREMENT'
                                   THEN NVL(A.QTY, 0)
                                   ELSE 0
                               END) OVER (PARTITION BY A.SCM_SITE_ID
                                                     , A.ITEM_ID
                                              ORDER BY A.SCM_SITE_ID
                                                     , A.ITEM_ID
                                                     , A.YYYYMMDD)  AS S_SUM
                         , SUM(CASE
                                   WHEN A.MEASURE = 'PROD_PLAN_AMEND'
                                   THEN NVL(A.QTY, 0)
                                   ELSE 0
                               END) OVER (PARTITION BY A.SCM_SITE_ID
                                                     , A.ITEM_ID
                                              ORDER BY A.SCM_SITE_ID
                                                     , A.ITEM_ID
                                                     , A.YYYYMMDD)  AS P_SUM
                      FROM SCP_ANL_PRODUCTION_PLAN A
                     WHERE A.MEASURE                 IN ('PROD_PLAN_AMEND', 'REQUIREMENT')
                       AND A.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
                       AND A.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE        /* 파티션 프루닝 */
                       AND A.PLAN_TYPE                = V_PLAN_TYPE
                       AND A.SEQ                      = V_SEQ
                       AND A.DIVISION_ID              = V_DIVISION_ID
                       AND A.OPERATION_GROUP          = V_OPERATION_GROUP) IA;

            UPDATE SCP_ANL_PRODUCTION_PLAN A
               SET A.QTY              = (SELECT SA.QTY
                                           FROM GT_0011_AMEND SA
                                          WHERE SA.SCM_SITE_ID = A.SCM_SITE_ID
                                            AND SA.ITEM_ID     = A.ITEM_ID
                                            AND SA.YYYYMMDD    = A.YYYYMMDD)
                 , A.LAST_UPDATED_BY  = P_USER_ID
                 , A.LAST_UPDATE_DATE = SYSDATE
             WHERE EXISTS (SELECT 1
                             FROM GT_0011_AMEND SB
                            WHERE SB.SCM_SITE_ID = A.SCM_SITE_ID
                              AND SB.ITEM_ID     = A.ITEM_ID
                              AND SB.YYYYMMDD    = A.YYYYMMDD)
               AND A.MEASURE                  = 'ONHAND_EOH'
               AND A.PLAN_START_YYYYMMDD      = P_PLAN_START_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD_DATE = V_PLAN_START_DATE            /* 파티션 프루닝 */
               AND A.PLAN_TYPE                = V_PLAN_TYPE
               AND A.SEQ                      = V_SEQ
               AND A.DIVISION_ID              = V_DIVISION_ID
               AND A.OPERATION_GROUP          = V_OPERATION_GROUP;

            -- TXN LOG
            V_LOG_TYPE    := 'TXN';
            N_LOG_COUNT   := 1;     /* AS-IS 는 변수 대입 직후의 @@ROWCOUNT(=1)를 기록한다 */
            V_LOG_MESSAGE := 'UPDATE ' || V_TABLE_ID;
            V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYY-MM-DD HH24:MI:SS') || '.000';
            D_EVENT_DATE  := SYSDATE;
            PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                               , P_LOG_TYPE     => V_LOG_TYPE
                               , P_LOG_COUNT    => N_LOG_COUNT
                               , P_LOG_MESSAGE  => V_LOG_MESSAGE
                               , P_DESCRIPTION  => V_DESCRIPTION
                               , P_EVENT_DATE   => D_EVENT_DATE
                               , P_USER_ID      => V_BATCH_USER);

            /* AS-IS 는 명시 트랜잭션 없이 문장 단위로 확정된다 */
            COMMIT;

            -- 결과코드 반환
            OPEN O_RC1 FOR
            SELECT 'S'                                              AS RESULT_CODE
              FROM DUAL;

        EXCEPTION
            WHEN OTHERS THEN
                ROLLBACK;

                O_RESULT_CODE := 'F';
                O_RESULT_MSG  := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

                -- ERROR LOG
                V_LOG_TYPE    := 'ERROR';
                V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
                V_DESCRIPTION := 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 480);
                D_EVENT_DATE  := SYSDATE;
                PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                                   , P_LOG_TYPE     => V_LOG_TYPE
                                   , P_LOG_COUNT    => N_LOG_COUNT
                                   , P_LOG_MESSAGE  => V_LOG_MESSAGE
                                   , P_DESCRIPTION  => V_DESCRIPTION
                                   , P_EVENT_DATE   => D_EVENT_DATE
                                   , P_USER_ID      => V_BATCH_USER);

                -- 결과코드 반환
                OPEN O_RC1 FOR
                SELECT 'F'                                          AS RESULT_CODE
                  FROM DUAL;
        END;

        -- 종료 LOG
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := SYSDATE;
        PR_SCP_SYS_LOG_BATCH(P_PROGRAM_NAME => V_PROGRAM_NAME
                           , P_LOG_TYPE     => V_LOG_TYPE
                           , P_LOG_COUNT    => N_LOG_COUNT
                           , P_LOG_MESSAGE  => V_LOG_MESSAGE
                           , P_DESCRIPTION  => V_DESCRIPTION
                           , P_EVENT_DATE   => D_EVENT_DATE
                           , P_USER_ID      => V_BATCH_USER);

    END P_SCP_ANL_PROD_PLAN_I_AMEND;

END PKG_SCP0011;

SCM_MGR|PACKAGE BODY|PKG_SCP0017:
PACKAGE BODY PKG_SCP0017
IS
/*
 * Program ID   : PKG_SCP0017
 * Description  : SCP0017 Waterfall Production Plan
 * Program History
 *===================================================================================================
 * Date         In Charge       Description
 *===================================================================================================
 * 2026.09.26   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */

    /*******************************************************************************
     * FN_ORDER_EXPR
     *   AS-IS 정렬 순서를 내는 ORDER BY 식을 만든다.
     *   문자 칸은 공용 함수 FN_ASIS_SORT_KEY 를 쓴다
     *   (AS-IS 순서를 글자 95 자 전수로 재어 만든 것 · 하이픈·홑따옴표는 빠지고
     *    구두점·기호는 숫자·문자보다 앞 · 대소문자를 가리지 않음).
     *   ★NULLS FIRST 를 반드시 붙인다 — 값이 하이픈뿐이면 정렬 열쇠가 NULL 이 되고
     *     Oracle 기본은 NULL 을 맨 뒤에 두지만 AS-IS 는 맨 앞이다.
     *   숫자 칸은 바꾸지 않는다.
     *******************************************************************************/
    FUNCTION FN_ORDER_EXPR
    (
        P_COLS  IN VARCHAR2
    )
    RETURN VARCHAR2
    IS

        C_NUMBER_COLS   CONSTANT VARCHAR2(200) := ',CELL_CF,QTY,';

        V_RESULT        VARCHAR2(4000);
        V_TOKEN         VARCHAR2(200);
        V_COL           VARCHAR2(200);
        V_DESC_YN       VARCHAR2(1);
        V_EXPR          VARCHAR2(600);
        V_IDX           PLS_INTEGER := 1;

    BEGIN

        LOOP

            V_TOKEN := TRIM(REGEXP_SUBSTR(P_COLS, '[^,]+', 1, V_IDX));

            EXIT WHEN V_TOKEN IS NULL;

            IF UPPER(V_TOKEN) LIKE '% DESC' THEN
                V_COL     := TRIM(SUBSTR(V_TOKEN, 1, LENGTH(V_TOKEN) - 5));
                V_DESC_YN := 'Y';
            ELSE
                V_COL     := V_TOKEN;
                V_DESC_YN := 'N';
            END IF;

            IF INSTR(C_NUMBER_COLS, ',' || UPPER(V_COL) || ',') > 0 THEN
                /* 숫자 칸 */
                IF V_DESC_YN = 'Y' THEN
                    V_EXPR := V_COL || ' DESC NULLS LAST';
                ELSE
                    V_EXPR := V_COL || ' NULLS FIRST';
                END IF;
            ELSE
                /* 문자 칸 : AS-IS 정렬 순서를 내는 공용 함수 */
                V_EXPR := 'FN_ASIS_SORT_KEY(' || V_COL || ')';

                IF V_DESC_YN = 'Y' THEN
                    V_EXPR := V_EXPR || ' DESC NULLS LAST';
                ELSE
                    V_EXPR := V_EXPR || ' NULLS FIRST';
                END IF;
            END IF;

            IF V_RESULT IS NULL THEN
                V_RESULT := V_EXPR;
            ELSE
                V_RESULT := V_RESULT || CHR(10) || '        , ' || V_EXPR;
            END IF;

            V_IDX := V_IDX + 1;

        END LOOP;

        RETURN V_RESULT;

    END FN_ORDER_EXPR;

    /*******************************************************************************
     * P_SCP0017_GET_SHEET_CALENDAR_3SPAN
     *   화면 머리글 달력. AS-IS 에 SCP0017 전용 프로시저가 없고
     *   화면 등록이 이 패키지를 가리키므로 공용
     *   PKG_COM0000.P_SCP0009_GET_SHEET_CALENDAR_3SPAN 과 같은 내용으로 둔다.
     *
     * 전환 기준 (AS-IS 동작 재현)
     *   1. 인자는 AS-IS NVARCHAR(8) 이므로 앞 8 자만 사용
     *   2. AS-IS 비교 콜레이션은 하이픈·아포스트로피를 견주지 않고 기호·공백류를 숫자보다 앞에 둔다
     *   3. 시작일이 빈값이면 AS-IS 는 '' 비교로 전체 기간 조회
     *   4. DAY_CODE 빈 문자('')는 Oracle 에서 NULL
     *******************************************************************************/
    PROCEDURE P_SCP0017_GET_SHEET_CALENDAR_3SPAN
    (
        P_START_YYYYMMDD        IN  VARCHAR2
      , P_END_YYYYMMDD          IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS

        V_START_KEY     VARCHAR2(40);
        V_END_KEY       VARCHAR2(40);

        /* AS-IS 문자열 비교 기준으로 인자 변환 */
        FUNCTION F_COMPARE_KEY(P_VALUE IN VARCHAR2) RETURN VARCHAR2
        IS
            V_VALUE     VARCHAR2(40);
        BEGIN
            /* NVARCHAR(8) 절삭 */
            V_VALUE := SUBSTR(P_VALUE, 1, 8);
            /* 비교에서 견주지 않는 문자 제거 : 아포스트로피 · 하이픈 · 소프트 하이픈 · EN DASH */
            V_VALUE := TRANSLATE(V_VALUE
                               , CHR(1) || '''-' || UNISTR('\00AD\2013')
                               , CHR(1));
            /* 전각·위첨자 숫자는 숫자로, 숫자보다 앞에 정렬되는 기호·공백류는 공백으로 */
            V_VALUE := TRANSLATE(V_VALUE
                               , UNISTR('\FF10\FF11\FF12\FF13\FF14\FF15\FF16\FF17\FF18\FF19\00B9\00B2\00B3')
                                 || ':;<=>?@[\]^_`{|}~'
                                 || UNISTR('\3000\00A0')
                               , '0123456789123'
                                 || RPAD(' ', 19));
            RETURN V_VALUE;
        END F_COMPARE_KEY;

    BEGIN

        /* 시작일 빈값 = AS-IS '' 비교(전체) */
        V_START_KEY := NVL(F_COMPARE_KEY(P_START_YYYYMMDD), ' ');
        /* 종료일 빈값 = NULL 비교(0건), AS-IS '' 비교와 같은 결과 */
        V_END_KEY   := F_COMPARE_KEY(P_END_YYYYMMDD);

        OPEN O_RC1 FOR
            SELECT 'D_' || BASIS_YYYYMMDD           AS COLUMN_NAME
                 , CALENDAR_DAY                     AS COLUMN_LABEL_NAME
                 , WEEK_NAME                        AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                       AS LARGE_CLASS_LABEL_NAME
                 , DAYOFWEEK                        AS DAY_CODE
                 , BASIS_YYYYMMDD || '31'           AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= V_START_KEY
               AND BASIS_YYYYMMDD <= V_END_KEY
             UNION ALL
            SELECT 'W_' || BASIS_YYYYMM || ISO_WEEK AS COLUMN_NAME
                 , WEEK_NAME                        AS COLUMN_LABEL_NAME
                 , WEEK_NAME                        AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                       AS LARGE_CLASS_LABEL_NAME
                 , NULL                             AS DAY_CODE
                 , BASIS_START_DATE || '21'         AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= V_START_KEY
               AND BASIS_YYYYMMDD <= V_END_KEY
             GROUP BY BASIS_YYYYMM
                    , ISO_WEEK
                    , WEEK_NAME
                    , MONTH_NAME
                    , BASIS_START_DATE
             UNION ALL
            SELECT 'M_' || BASIS_YYYYMM             AS COLUMN_NAME
                 , MONTH_NAME                       AS COLUMN_LABEL_NAME
                 , MONTH_NAME                       AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                       AS LARGE_CLASS_LABEL_NAME
                 , NULL                             AS DAY_CODE
                 , MIN(BASIS_START_DATE) || '01'    AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= V_START_KEY
               AND BASIS_YYYYMMDD <= V_END_KEY
             GROUP BY BASIS_YYYYMM
                    , MONTH_NAME
             ORDER BY SORT_ORDER_NO;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, '0' AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[PKG_SCP0017.P_SCP0017_GET_SHEET_CALENDAR_3SPAN] ' || SQLERRM);

    END P_SCP0017_GET_SHEET_CALENDAR_3SPAN;


    /*******************************************************************************
     * P_SCP0017_GET_PRODUCTION_PLAN_MODEL_WATERFALL
     *   AS-IS SCP0017_GET_PRODUCTION_PLAN_MODEL_WATERFALL
     *
     * 전환 기준
     *   1. AS-IS 임시 자료는 전역 임시 테이블(GT_0017_*)로 옮기고 시작할 때 비운다.
     *   2. AS-IS 가 문자열로 조립하던 조회문은 조건 분기가 있는 정적 SQL 로 바꾼다.
     *      조회 기간에 따라 칸 개수가 달라지는 마지막 피벗만 동적으로 둔다.
     *   3. AS-IS 가 만들기만 하고 쓰지 않는 임시 자료(NICKITEM)는 만들지 않는다.
     *   4. 원본 MSSQL 주석은 형태 그대로 둔다.
     *******************************************************************************/
    PROCEDURE P_SCP0017_GET_PRODUCTION_PLAN_MODEL_WATERFALL
    (
        P_DIVISION_ID           IN  VARCHAR2
      , P_OPERATION_GROUP       IN  VARCHAR2
      , P_SCM_SITE_ID           IN  VARCHAR2
      , P_MODEL_ID              IN  VARCHAR2
      , P_ITEM_ID               IN  VARCHAR2
      , P_FROM_YYYYMMDD         IN  VARCHAR2
      , P_TO_YYYYMMDD           IN  VARCHAR2
      , P_VERSION_NO            IN  VARCHAR2
      , P_PROGRAM_ID            IN  VARCHAR2
      , P_SHEET_NAME            IN  VARCHAR2
      , P_USER_ID               IN  VARCHAR2
      , P_ELECTRODE_TYPE        IN  VARCHAR2
      , P_NICK_NAME             IN  VARCHAR2
      , P_GAP                   IN  VARCHAR2
      , P_LINE_ID               IN  VARCHAR2
      , DEBUG_MODE              IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS

        V_PLAN_START_YYYYMMDD   VARCHAR2(4000);
        V_TO_PERIOD             VARCHAR2(20);
        V_CNT_USER_MEASURE      PLS_INTEGER := 0;
        V_CNT_USR_COLUMN        PLS_INTEGER := 0;
        V_CNT_USR_COLUMN_FINAL  PLS_INTEGER := 0;

        V_FROM_YYYYMMDD         VARCHAR2(8);
        V_TO_YYYYMMDD           VARCHAR2(8);
        V_FROM_RESULT           VARCHAR2(8);
        V_TO_RESULT             VARCHAR2(8);

        V_CURR_CNT              PLS_INTEGER := 0;
        V_CURR_PLAN_START       VARCHAR2(100);

        V_DIV_ATTRIBUTE3        VARCHAR2(100);
        V_CURR_YYYYMM           VARCHAR2(6);

        /* 화면 칸 목록 */
        V_USER_COLS             VARCHAR2(4000);     /* AS-IS @v_final_user_cols   : MEASURE 가 두 번 들어갈 수 있다 */
        V_USER_COLS_UNIQ        VARCHAR2(4000);     /* 같은 목록에서 중복 이름을 뺀 것 (적재용) */
        V_USER_COLS_ORDER       VARCHAR2(4000);     /* AS-IS @v_final_user_cols_order */
        V_GAP_USER_COLS         VARCHAR2(4000);     /* AS-IS @v_gap_user_cols : 'A.' 를 붙인 것 */
        V_GAP_USER_KEYS         VARCHAR2(4000);     /* AS-IS @v_gap_user_keys : 키 연결식 */

        /* 피벗 칸 */
        V_PIVOT_COLS            CLOB;               /* 결과 칸 이름 목록 ('     , A.D_20260601' 꼴) */
        V_ACC_SEL_COLS          CLOB;               /* 누계 조회에서 고른 값 목록 */
        V_SUM_COLS              CLOB;
        V_ACC_DAY_COLS          CLOB;
        V_ACC_WEEK_COLS         CLOB;
        V_ACC_MONTH_COLS        CLOB;
        V_SQL                   CLOB;

        V_ERR_MSG               VARCHAR2(4000);

    BEGIN

        DBMS_LOB.CREATETEMPORARY(V_PIVOT_COLS,     TRUE);
        DBMS_LOB.CREATETEMPORARY(V_ACC_SEL_COLS,   TRUE);
        DBMS_LOB.CREATETEMPORARY(V_SUM_COLS,       TRUE);
        DBMS_LOB.CREATETEMPORARY(V_ACC_DAY_COLS,   TRUE);
        DBMS_LOB.CREATETEMPORARY(V_ACC_WEEK_COLS,  TRUE);
        DBMS_LOB.CREATETEMPORARY(V_ACC_MONTH_COLS, TRUE);
        DBMS_LOB.CREATETEMPORARY(V_SQL,            TRUE);

        /* 임시 자료 비우기 */
        DELETE FROM GT_0017_COLUMN_ALL;
        DELETE FROM GT_0017_COLUMN;
        DELETE FROM GT_0017_UOM;
        DELETE FROM GT_0017_CELL_TYPE_GROUP;
        DELETE FROM GT_0017_PRE;
        DELETE FROM GT_0017_FINAL_ITEM;
        DELETE FROM GT_0017_STD;
        DELETE FROM GT_0017_STD_PLAN;
        DELETE FROM GT_0017_STD_RESULT;
        DELETE FROM GT_0017_STD_RESULT_TEMP;
        DELETE FROM GT_0017_STD_TEMP;
        DELETE FROM GT_0017_RAW;
        DELETE FROM GT_0017_RAW_ALL_UOM;
        DELETE FROM GT_0017_FINAL_RAW;
        DELETE FROM GT_0017_GAP_DAY;
        DELETE FROM GT_0017_GAP_WEEK;
        DELETE FROM GT_0017_GAP_MONTH;

        V_PLAN_START_YYYYMMDD := REPLACE(P_VERSION_NO, 'PP_W_', '');
        V_TO_PERIOD           := P_TO_YYYYMMDD;
        V_CURR_YYYYMM         := TO_CHAR(SYSDATE, 'YYYYMM');

        SELECT COUNT(*)
          INTO V_CNT_USER_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE 1 = 1
           AND PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID    = P_USER_ID;
           /* AND USER_INQUIRY_COLUMN_TYPE_CODE = 'M' */

        /* 사업부 계열 (E20260907-000019 신규로직에서 쓴다) */
        BEGIN
            SELECT ATTRIBUTE3
              INTO V_DIV_ATTRIBUTE3
              FROM SCM_MST_DIVISION
             WHERE DIVISION_ID = P_DIVISION_ID;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_DIV_ATTRIBUTE3 := NULL;
        END;

        /*==========================================================================
         * 화면 칸 목록
         *========================================================================*/
        INSERT INTO GT_0017_COLUMN_ALL
        (
            COLUMN_NAME
          , USER_SORT_ORDER_NO
        )
        SELECT COLUMN_NAME
             , USER_SORT_ORDER_NO
          FROM ( SELECT A.COLUMN_NAME
                      , ROW_NUMBER() OVER (ORDER BY NVL(B.SORT_ORDER_NO, A.SORT_ORDER_NO))  AS USER_SORT_ORDER_NO
                   FROM SCM_MST_SHEET_COLUMNS   A
                      , SCM_MST_TITLESET_USER   B
                  WHERE B.PROGRAM_ID(+)                    = A.PROGRAM_ID
                    AND B.SHEET_NAME(+)                    = A.SHEET_NAME
                    AND B.COLUMN_NAME(+)                   = A.COLUMN_NAME
                    AND B.USER_ID(+)                       = P_USER_ID
                    AND B.USER_INQUIRY_COLUMN_TYPE_CODE(+) = 'C'
                    AND A.PROGRAM_ID                       = P_PROGRAM_ID
                    AND A.SHEET_NAME                       = P_SHEET_NAME
                    AND A.VALID_YN                         = 'Y'
                    AND A.VISIBLE_FLAG                     = 'Y'
               )  IA;

        SELECT COUNT(1)
          INTO V_CNT_USR_COLUMN
          FROM GT_0017_COLUMN_ALL;

        INSERT INTO GT_0017_COLUMN
        (
            COLUMN_NAME
          , USER_SORT_ORDER_NO
        )
        SELECT A.COLUMN_NAME
             , A.USER_SORT_ORDER_NO
          FROM GT_0017_COLUMN_ALL  A
         WHERE 1 = 1
           AND ( V_CNT_USR_COLUMN = 0
                 OR EXISTS (SELECT 1
                              FROM SCM_MST_TITLESET_USER
                             WHERE 1 = 1
                               AND PROGRAM_ID                      = P_PROGRAM_ID
                               AND SHEET_NAME                      = P_SHEET_NAME
                               AND COLUMN_NAME                     = A.COLUMN_NAME
                               AND USER_ID                         = P_USER_ID
                               AND USER_INQUIRY_COLUMN_TYPE_CODE   = 'C')
               );

        SELECT COUNT(*)
          INTO V_CNT_USR_COLUMN_FINAL
          FROM GT_0017_COLUMN;

        /* 사용자ID 오류로 인해서 컬럼 못 가져오는 경우 있음(원인불명) */
        IF V_CNT_USR_COLUMN_FINAL = 0 THEN

            INSERT INTO GT_0017_COLUMN
            (
                COLUMN_NAME
              , USER_SORT_ORDER_NO
            )
            SELECT COLUMN_NAME
                 , USER_SORT_ORDER_NO
              FROM GT_0017_COLUMN_ALL;

        END IF;

        /*==========================================================================
         * UOM 은 DIV = 'EE' & @p_operation_group = 'E' 일때만 표시
         *========================================================================*/
        IF P_DIVISION_ID = 'EE' AND P_OPERATION_GROUP = 'E' THEN

            INSERT INTO GT_0017_UOM (UOM) SELECT 'M'  AS UOM FROM DUAL;
            INSERT INTO GT_0017_UOM (UOM) SELECT 'EA' AS UOM FROM DUAL;

        ELSE

            INSERT INTO GT_0017_UOM (UOM) SELECT 'EA' AS UOM FROM DUAL;

        END IF;

        /*==========================================================================
         * 셀 종류 묶음
         *========================================================================*/
        INSERT INTO GT_0017_CELL_TYPE_GROUP
        (
            CELL_TYPE_CODE
          , FLOW_TYPE
          , CELL_TYPE_GROUP_CODE
          , CELL_TYPE_GROUP_NAME
          , DISPLAY_SEQ
        )
        SELECT A.CODE                   AS CELL_TYPE_CODE
             , SUBSTR(A.NAME, 1, 1)     AS FLOW_TYPE
             , A.GROUP_CODE             AS CELL_TYPE_GROUP_CODE
             , G.NAME                   AS CELL_TYPE_GROUP_NAME
             , A.DISPLAY_SEQ
          FROM ( SELECT B.SEGMENT1  AS CODE
                      , B.SEGMENT2  AS NAME
                      , B.SEGMENT3  AS GROUP_CODE
                      , B.DISPLAY_SEQ
                   FROM SCM_ADM_LOOKUP_MASTER          A
                      , SCM_ADM_LOOKUP_MASTER_DETAIL   B
                  WHERE A.LOOKUP_TYPE = B.LOOKUP_TYPE
                    AND B.VALID_YN    = 'Y'
                    AND A.LOOKUP_TYPE = 'CELL_TYPE_ITEM_CODE'
                    AND A.VALID_YN    = 'Y'
               )  A
             , ( SELECT B.SEGMENT1  AS CODE
                      , B.SEGMENT2  AS NAME
                   FROM SCM_ADM_LOOKUP_MASTER          A
                      , SCM_ADM_LOOKUP_MASTER_DETAIL   B
                  WHERE A.LOOKUP_TYPE = B.LOOKUP_TYPE
                    AND B.VALID_YN    = 'Y'
                    AND A.LOOKUP_TYPE = 'CELL_TYPE_ITEM_GROUP'
                    AND A.VALID_YN    = 'Y'
               )  G
         WHERE A.GROUP_CODE = G.CODE;

        /*==========================================================================
         * 대상 품목
         *   [PJ20257329] Cell 완성 공정 하드 코딩 변경
         *   AS-IS 는 완성 공정 목록을 테이블 변수에 담아 외부조인했다.
         *   목록이 중복 없는 한 칸짜리라 EXISTS 로 옮겨도 결과가 같다.
         *========================================================================*/
        INSERT INTO GT_0017_PRE
        (
            DIVISION_ID
          , OPERATION_ID
          , ITEM_ID
          , CELL_TYPE_CODE
          , LEVEL_EXCEPT
          , CELL_NICKNAME
          , BASIC_NICKNAME_CELL40
          , NICKNAME_40
          , GROUP_CODE4
          , GROUP_CODE5
          , GROUP_CODE6
          , GROUP_CODE7
          , FLOW_TYPE
        )
        SELECT A.DIVISION_ID
             , A.FLOW_ID                        AS OPERATION_ID
             , A.ITEM_ID
             , SUBSTR(A.ITEM_ID, 3, 1)          AS CELL_TYPE_CODE
             , SUBSTR(A.ITEM_ID, 1, 2)          AS LEVEL_EXCEPT /* 예외적용 */
             , CASE
                 WHEN SUBSTR(A.DIVISION_ID, 1, 2) = '81'  THEN A.GROUP_CODE1
                 WHEN A.DIVISION_ID = '82'                THEN A.LEVEL2_CODE
                 ELSE ''
               END                              AS CELL_NICKNAME
             , CASE
                 WHEN SUBSTR(A.ITEM_ID, 1, 2) = 'EC' THEN 'ESS'
                 WHEN SUBSTR(A.ITEM_ID, 1, 2) = 'AM' THEN 'M50L'
                 ELSE
                   CASE
                     WHEN A.OPERATION_GROUP = 'P'
                     THEN (SELECT SA.NICK_NAME
                             FROM ( SELECT B.NICK_NAME
                                      FROM SCP_MST_FINAL_ITEM B
                                     WHERE B.DIVISION_ID = A.DIVISION_ID
                                       AND B.ITEM_ID     = (SELECT XA.DOE
                                                              FROM ( SELECT C.DOE
                                                                       FROM SCM_MST_ITEM_SN C
                                                                      WHERE C.DIVISION_ID = A.DIVISION_ID
                                                                        AND C.ITEM_ID     = A.ATTRIBUTE1
                                                                        AND C.DOE IS NOT NULL
                                                                   )  XA
                                                             WHERE ROWNUM = 1)
                                  )  SA
                            WHERE ROWNUM = 1)
                     ELSE (SELECT SA.NICK_NAME
                             FROM ( SELECT B.NICK_NAME
                                      FROM SCP_MST_FINAL_ITEM B
                                     WHERE B.DIVISION_ID = A.DIVISION_ID
                                       AND B.ITEM_ID     = (SELECT XA.DOE
                                                              FROM ( SELECT C.DOE
                                                                       FROM SCM_MST_ITEM_SN C
                                                                      WHERE C.DIVISION_ID = A.DIVISION_ID
                                                                        AND C.ITEM_ID     = A.ITEM_ID
                                                                        AND C.DOE IS NOT NULL
                                                                   )  XA
                                                             WHERE ROWNUM = 1)
                                  )  SA
                            WHERE ROWNUM = 1)
                   END
               END                              AS BASIC_NICKNAME_CELL40
             , A.NICK_NAME                      AS NICKNAME_40
             , A.GROUP_CODE4
             , A.GROUP_CODE5
             , A.GROUP_CODE6
             , A.GROUP_CODE7
             , CASE
                 /* [PJ20257329] 변경전 WHEN A.FLOW_ID IN ('A3000', 'A9000') THEN 'C' */
                 WHEN EXISTS (SELECT 1                      /* [PJ20257329] Cell 완성 공정 하드 코딩 변경 */
                                FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK
                               WHERE LK.LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
                                 AND LK.SEGMENT3    = 'A'   /* 공정그룹(Cell) */
                                 AND LK.ATTRIBUTE1  = 'Y'   /* Final Operation */
                                 AND LK.SEGMENT1    = A.FLOW_ID)
                 THEN 'C'
                 ELSE 'E'
               END                              AS FLOW_TYPE
          FROM SCP_MST_FINAL_ITEM A
         WHERE 1 = 1
           AND (SUBSTR(A.ATTRIBUTE8, 1, 2) <> 'CA' OR A.ATTRIBUTE8 IS NULL)   /* 활성화코드 분리 */
           AND A.DIVISION_ID = P_DIVISION_ID
           AND ( TRIM(P_OPERATION_GROUP) IS NULL
                 OR A.OPERATION_GROUP IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_OPERATION_GROUP, ','))) )
           AND ( TRIM(P_MODEL_ID) IS NULL
                 OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))) );

        INSERT INTO GT_0017_FINAL_ITEM
        (
            DIVISION_ID
          , OPERATION_ID
          , ITEM_ID
          , CELL_TYPE_CODE
          , LEVEL_EXCEPT
          , CELL_NICKNAME
          , BASIC_NICKNAME_CELL40
          , NICKNAME_40
          , GROUP_CODE4
          , GROUP_CODE5
          , GROUP_CODE6
          , GROUP_CODE7
          , FLOW_TYPE
          , CELL_TYPE_GROUP_NAME
        )
        SELECT P.DIVISION_ID
             , P.OPERATION_ID
             , P.ITEM_ID
             , P.CELL_TYPE_CODE
             , P.LEVEL_EXCEPT
             , P.CELL_NICKNAME
             , P.BASIC_NICKNAME_CELL40
             , P.NICKNAME_40
             , P.GROUP_CODE4
             , P.GROUP_CODE5
             , P.GROUP_CODE6
             , P.GROUP_CODE7
             , P.FLOW_TYPE
             , CASE
                 WHEN P.LEVEL_EXCEPT = 'EC' THEN 'Pouch'
                 WHEN P.LEVEL_EXCEPT = 'AM' THEN 'Cylindrical'
                 WHEN SUBSTR(P.ITEM_ID, 3, 1) = 'M' AND P.OPERATION_ID = 'P9500' THEN 'Pouch'
                 ELSE G.CELL_TYPE_GROUP_NAME
               END                              AS CELL_TYPE_GROUP_NAME
          FROM GT_0017_PRE               P
             , GT_0017_CELL_TYPE_GROUP   G
         WHERE P.FLOW_TYPE      = G.FLOW_TYPE(+)
           AND P.CELL_TYPE_CODE = G.CELL_TYPE_CODE(+);


        /*==========================================================================
         * 기준일(버전)별 되풀이
         *   AS-IS 는 커서로 @p_plan_start_yyyymmdd 를 쉼표로 나눠 돌린다.
         *   AS-IS String_Split 의 순번(nr)은 1 부터이므로 ROWNUM 으로 옮긴다.
         *========================================================================*/
        FOR CUR_SCP0017 IN ( SELECT ROWNUM        AS NR
                                  , COLUMN_VALUE  AS TOKEN
                               FROM TABLE(STRING_SPLIT(V_PLAN_START_YYYYMMDD, ','))
                           )
        LOOP

            V_CURR_CNT        := CUR_SCP0017.NR;
            V_CURR_PLAN_START := CUR_SCP0017.TOKEN;

            BEGIN
                SELECT C.BASIS_START_DATE
                  INTO V_FROM_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M C
                 WHERE 1 = 1
                   AND C.BASIS_YYYYMMDD = V_CURR_PLAN_START;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_FROM_YYYYMMDD := NULL;
            END;

            BEGIN
                SELECT C.BASIS_START_DATE
                  INTO V_FROM_RESULT
                  FROM SCM_SYS_CALENDAR_M C
                 WHERE 1 = 1
                   AND C.BASIS_YYYYMMDD = P_FROM_YYYYMMDD;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_FROM_RESULT := NULL;
            END;

            BEGIN
                SELECT C.BASIS_START_DATE
                  INTO V_TO_RESULT
                  FROM SCM_SYS_CALENDAR_M C
                 WHERE 1 = 1
                   AND C.BASIS_YYYYMMDD = P_TO_YYYYMMDD;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_TO_RESULT := NULL;
            END;

            IF V_FROM_YYYYMMDD > V_FROM_RESULT THEN
                /* 실적 보여줌 */
                V_TO_YYYYMMDD   := P_TO_YYYYMMDD;
                V_TO_RESULT     := V_FROM_YYYYMMDD;
            ELSIF V_FROM_YYYYMMDD <= V_FROM_RESULT THEN
                /* 실적 없음 */
                V_TO_YYYYMMDD   := P_TO_YYYYMMDD;
                V_FROM_RESULT   := TO_CHAR(ADD_MONTHS(TO_DATE(V_CURR_PLAN_START, 'YYYYMMDD'),  6), 'YYYYMMDD');
                V_TO_RESULT     := TO_CHAR(ADD_MONTHS(TO_DATE(V_CURR_PLAN_START, 'YYYYMMDD'), -6), 'YYYYMMDD');
            ELSIF V_FROM_YYYYMMDD > V_TO_RESULT THEN
                V_FROM_YYYYMMDD := TO_CHAR(ADD_MONTHS(TO_DATE(V_CURR_PLAN_START, 'YYYYMMDD'), -6), 'YYYYMMDD');
                V_TO_YYYYMMDD   := TO_CHAR(ADD_MONTHS(TO_DATE(V_CURR_PLAN_START, 'YYYYMMDD'), -6), 'YYYYMMDD');
                V_FROM_RESULT   := P_FROM_YYYYMMDD;
                V_TO_RESULT     := P_TO_YYYYMMDD;
            ELSIF V_FROM_YYYYMMDD = V_TO_RESULT THEN
                V_TO_YYYYMMDD   := V_FROM_YYYYMMDD;
                V_FROM_RESULT   := P_FROM_YYYYMMDD;
                V_TO_RESULT     := P_TO_YYYYMMDD;
            END IF;

            /*======================================================================
             * 기준정보 RESULT C : 회차마다 비운다
             *====================================================================*/
            DELETE FROM GT_0017_STD;
            DELETE FROM GT_0017_STD_PLAN;
            DELETE FROM GT_0017_STD_RESULT;
            DELETE FROM GT_0017_STD_RESULT_TEMP;
            DELETE FROM GT_0017_STD_TEMP;

            /* 계획 */
            INSERT INTO GT_0017_STD_PLAN
            (
                DIVISION_ID
              , OPERATION_GROUP
              , SCM_SITE_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
            )
            SELECT A.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.SCM_SITE_ID
                 , A.ITEM_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.MEASURE
                 , A.YYYYMMDD
                 , A.QTY
                 , CASE WHEN TRIM(A.ORIGIN_DIVISION_ID) IS NULL THEN A.DIVISION_ID
                        ELSE A.ORIGIN_DIVISION_ID END               AS ORIGIN_DIVISION_ID
                 , CASE WHEN TRIM(A.ELECTRODE_TYPE) IS NULL THEN '-'
                        ELSE A.ELECTRODE_TYPE END                   AS ELECTRODE_TYPE
              FROM SCP_ANL_PRODUCTION_PLAN_C A
             WHERE 1 = 1
               AND A.YYYYMMDD            >= P_FROM_YYYYMMDD
               AND A.YYYYMMDD            <= P_TO_YYYYMMDD
               AND A.DIVISION_ID          = P_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD  = V_CURR_PLAN_START
               /* 2026.09.26 성능 : 버전을 함께 걸어 기본키(사업부 · 버전 · …) 선두를 쓰게 한다.
                *   버전을 빼면 기본키 건너뛰기 조회가 되어 결과가 742 행인데 100 만 블록을 뒤진다.
                *   원장에서 버전은 언제나 'PP_W_' + 기준일 이다(실측 2026-09-26 · 사업부 82 어긋남 0 행).
                *   화면이 이 값을 받아 라인 조회에 그대로 넘기고 라인 조회가 버전으로 조회하므로
                *   짝이 어긋나면 라인 조회가 애초에 0 행이 된다. */
               AND A.VERSION_NO           = 'PP_W_' || V_CURR_PLAN_START
               AND A.OPERATION_GROUP      = P_OPERATION_GROUP
               AND A.QTY                 <> 0
               AND ( TRIM(P_SCM_SITE_ID) IS NULL
                     OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
               AND ( ( TRIM(P_ITEM_ID) IS NULL AND TRIM(P_NICK_NAME) IS NULL )
                     OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_GET_ITEM_LIKE_CONDITION(P_ITEM_ID, P_NICK_NAME))) )
               AND ( TRIM(P_ELECTRODE_TYPE) IS NULL
                     OR A.ELECTRODE_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_ELECTRODE_TYPE, ','))) )
               AND ( TRIM(P_LINE_ID) IS NULL
                     OR A.LINE_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_LINE_ID, ','))) );

            /* 실적 */
            INSERT INTO GT_0017_STD_RESULT_TEMP
            (
                DIVISION_ID
              , OPERATION_GROUP
              , SCM_SITE_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
            )
            SELECT CASE
                     /* E20260907-000019 기존 로직 주석처리 */
                     /* WHEN @p_division_id = 'EE' OR @p_division_id = 'EE_UC' OR @p_division_id = 'EE_HM' THEN @p_division_id */
                     /* E20260907-000019 신규로직 */
                     WHEN V_DIV_ATTRIBUTE3 = 'EE' THEN P_DIVISION_ID
                     ELSE A.DIVISION_ID
                   END                                              AS DIVISION_ID
                 , A.SCP_OPERATION_GROUP                            AS OPERATION_GROUP
                 , A.SCM_SITE_ID
                 , A.ITEM_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , 'PROD_PLAN_ENGINE'                               AS MEASURE
                 , TO_CHAR(A.PLAN_DATE, 'YYYYMMDD')                 AS YYYYMMDD
                 , A.ACTUAL_GOOD_QTY                                AS QTY
                 , A.DIVISION_ID                                    AS ORIGIN_DIVISION_ID
                 , CASE WHEN TRIM(A.ELECTRODE_TYPE) IS NULL THEN '-'
                        ELSE A.ELECTRODE_TYPE END                   AS ELECTRODE_TYPE
              FROM SCM_DNM_PRODUCT_RESULT_V A
             WHERE 1 = 1
               /* AND ( @p_division_id IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) OR A.division_id = @p_division_id ) --div_commonization */
               AND ( A.DIVISION_ID = P_DIVISION_ID
                     OR A.DIVISION_ID IN (SELECT DIVISION_ID
                                            FROM SCM_MST_DIVISION
                                           WHERE ATTRIBUTE4 IN (SELECT ATTRIBUTE4
                                                                  FROM SCM_MST_DIVISION
                                                                 WHERE DIVISION_ID = P_DIVISION_ID)
                                             AND ATTRIBUTE3 <> 'EE') )    /* div_commonization */
               AND A.COMPANY_ID IN (SELECT DISTINCT COMPANY_ID
                                      FROM SCM_MST_SITE
                                     WHERE 1 = 1
                                       AND ( P_DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_GET_DIVISION_DIV('EE')))
                                             OR DIVISION_ID = P_DIVISION_ID )   /* div_commonization */
                                       AND SITE_TYPE = 'PLANT'
                                       AND VALID_YN  = 'Y')
               AND A.PLAN_DATE >= TO_DATE(V_FROM_RESULT, 'YYYYMMDD')
               AND A.PLAN_DATE <  TO_DATE(V_TO_RESULT,   'YYYYMMDD');

            INSERT INTO GT_0017_STD_RESULT
            (
                DIVISION_ID
              , OPERATION_GROUP
              , SCM_SITE_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
            )
            SELECT A.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.SCM_SITE_ID
                 , A.ITEM_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.MEASURE
                 , A.YYYYMMDD
                 , A.QTY
                 , A.ORIGIN_DIVISION_ID
                 , A.ELECTRODE_TYPE
              FROM GT_0017_STD_RESULT_TEMP A
             WHERE 1 = 1
               AND A.OPERATION_GROUP = P_OPERATION_GROUP
               AND ( SUBSTR(A.OPERATION_ID, 1, 5) IN    /* LOOKUP_TYPE 'SCP_PLAN_OPERATION' 에 정의된 공정만 조회 */
                                                     (SELECT SEGMENT1  AS OPERATION_ID
                                                        FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                                       WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
                                                         AND SEGMENT1   <> 'F6000'
                                                         AND VALID_YN    = 'Y')
                     OR A.OPERATION_ID IN             /* 외주PACKER의 업체코드 */
                                                     (SELECT S.PLANT_ID  AS OPERATION_ID
                                                        FROM SCM_MST_SITE S
                                                       WHERE 1 = 1
                                                         AND ( ( P_DIVISION_ID = 'EE'
                                                                 AND S.DIVISION_ID IN ('40', '81', '82') )
                                                               OR ( P_DIVISION_ID = 'EE_UC'
                                                                    AND S.DIVISION_ID = '81_UC' )
                                                               OR ( P_DIVISION_ID NOT IN ('EE', 'EE_UC')
                                                                    AND S.DIVISION_ID = P_DIVISION_ID ) )
                                                         AND S.SITE_TYPE = 'PLANT'
                                                         AND S.OSP_YN    = 'Y'
                                                         AND S.VALID_YN  = 'Y') )
               AND ( TRIM(P_SCM_SITE_ID) IS NULL
                     OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
               AND ( ( TRIM(P_ITEM_ID) IS NULL AND TRIM(P_NICK_NAME) IS NULL )
                     OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_GET_ITEM_LIKE_CONDITION(P_ITEM_ID, P_NICK_NAME))) )
               AND ( TRIM(P_ELECTRODE_TYPE) IS NULL
                     OR A.ELECTRODE_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_ELECTRODE_TYPE, ','))) )
               AND ( TRIM(P_LINE_ID) IS NULL
                     OR A.LINE_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_LINE_ID, ','))) );

            INSERT INTO GT_0017_STD
            (
                DIVISION_ID
              , OPERATION_GROUP
              , SCM_SITE_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
            )
            SELECT DIVISION_ID
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , ITEM_ID
                 , OPERATION_ID
                 , LINE_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
              FROM GT_0017_STD_PLAN
             UNION ALL
            SELECT DIVISION_ID
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , ITEM_ID
                 , OPERATION_ID
                 , LINE_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
              FROM GT_0017_STD_RESULT;

            /*======================================================================
             * (PROD PLAN AMEND) 추가
             *====================================================================*/
            INSERT INTO GT_0017_STD_TEMP
            (
                DIVISION_ID
              , OPERATION_GROUP
              , SCM_SITE_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
            )
            SELECT DIVISION_ID
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , ITEM_ID
                 , OPERATION_ID
                 , LINE_ID
                 , 'PROD_PLAN_AMEND'  AS MEASURE
                 , YYYYMMDD
                 , QTY
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
              FROM GT_0017_STD
             WHERE 1 = 1
               AND MEASURE = 'PROD_PLAN_ENGINE';

            DELETE FROM GT_0017_STD
             WHERE 1 = 1
               AND MEASURE = 'PROD_PLAN_AMEND';

            INSERT INTO GT_0017_STD
            (
                DIVISION_ID
              , OPERATION_GROUP
              , SCM_SITE_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
            )
            SELECT DIVISION_ID
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , ITEM_ID
                 , OPERATION_ID
                 , LINE_ID
                 , 'PROD_PLAN_AMEND'  AS MEASURE
                 , YYYYMMDD
                 , QTY
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
              FROM GT_0017_STD_TEMP
             WHERE 1 = 1
               AND MEASURE = 'PROD_PLAN_AMEND';

            /*======================================================================
             * 데이타조회, 임시테이블에 저장
             *   AS-IS 는 FN_GET_ITEM_PROD_OP 를 조인조건과 조회목록에서 두 번 부른다.
             *   같은 값이므로 인라인 뷰에서 한 번만 불러 쓴다.
             *====================================================================*/
            INSERT INTO GT_0017_RAW
            (
                KEY_IDX
              , DIVISION_ID
              , DIVISION_NAME
              , OPERATION_GROUP
              , OPERATION_GROUP_NAME
              , SCM_SITE_ID
              , SCM_SITE_DESCRIPTION
              , LINE_ID
              , CELL_NICKNAME
              , PRODUCT_LEVEL1
              , PRODUCT_LEVEL2
              , PRODUCT_LEVEL3
              , MODEL_ID
              , ITEM_ID
              , NICK_NAME
              , MEASURE
              , MEASURE_NAME
              , USER_SORT_ORDER_NO
              , UOM
              , CELL_CF
              , PLAN_START_YYYYMMDD
              , FROM_YYYYMMDD
              , TO_YYYYMMDD
              , YYYYMMDD
              , YYYYMM
              , ISO_WEEK
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
              , WEEK_YN
              , MONTH_YN
              , VERSION_NO
              , VERSION_IDX
            )
            SELECT    A.DIVISION_ID
                   || ';' || A.DIVISION_NAME
                   || ';' || A.OPERATION_GROUP
                   || ';' || A.OPERATION_GROUP_NAME
                   || ';' || A.SCM_SITE_ID
                   || ';' || A.SCM_SITE_DESCRIPTION
                   || ';' || A.LINE_ID
                   || ';' || A.CELL_NICKNAME
                   || ';' || A.PRODUCT_LEVEL1
                   || ';' || A.PRODUCT_LEVEL2
                   || ';' || A.PRODUCT_LEVEL3
                   || ';' || A.MODEL_ID
                   || ';' || A.ITEM_ID
                   || ';' || A.NICK_NAME
                   || ';' || A.UOM
                   || ';' || A.CELL_CF
                   || ';' || A.PLAN_START_YYYYMMDD
                   || ';' || A.FROM_YYYYMMDD
                   || ';' || A.TO_YYYYMMDD
                   || ';' || A.YYYYMMDD
                   || ';' || A.YYYYMM
                   || ';' || A.ISO_WEEK
                   || ';' || A.ORIGIN_DIVISION_ID
                   || ';' || A.ELECTRODE_TYPE
                   || ';' || A.WEEK_YN
                   || ';' || A.MONTH_YN
                   || ';' || A.VERSION_NO
                   || ';' || A.VERSION_IDX                                          AS KEY_IDX
                 , A.DIVISION_ID
                 , A.DIVISION_NAME
                 , A.OPERATION_GROUP
                 , A.OPERATION_GROUP_NAME
                 , A.SCM_SITE_ID
                 , A.SCM_SITE_DESCRIPTION
                 , A.LINE_ID
                 , A.CELL_NICKNAME
                 , A.PRODUCT_LEVEL1
                 , A.PRODUCT_LEVEL2
                 , A.PRODUCT_LEVEL3
                 , A.MODEL_ID
                 , A.ITEM_ID
                 , A.NICK_NAME
                 , A.MEASURE
                 , A.MEASURE_NAME
                 , A.USER_SORT_ORDER_NO
                 , A.UOM
                 , A.CELL_CF
                 , A.PLAN_START_YYYYMMDD
                 , A.FROM_YYYYMMDD
                 , A.TO_YYYYMMDD
                 , A.YYYYMMDD
                 , A.YYYYMM
                 , A.ISO_WEEK
                 , A.QTY
                 , A.ORIGIN_DIVISION_ID
                 , A.ELECTRODE_TYPE
                 , A.WEEK_YN
                 , A.MONTH_YN
                 , A.VERSION_NO
                 , A.VERSION_IDX
              FROM ( SELECT A.DIVISION_ID
                          , FN_GET_DIVISION_NAME(A.DIVISION_ID)                     AS DIVISION_NAME
                          , A.OPERATION_GROUP
                          , ( SELECT SA.SEGMENT2
                                FROM ( SELECT C.SEGMENT2
                                         FROM SCM_ADM_LOOKUP_MASTER_DETAIL C
                                        WHERE C.LOOKUP_TYPE = 'OPERATION_GROUP'
                                          AND NVL(TRIM(C.SEGMENT1), '@') = NVL(TRIM(A.OPERATION_GROUP), '@')
                                     )  SA
                               WHERE ROWNUM = 1 )                                   AS OPERATION_GROUP_NAME
                          , A.SCM_SITE_ID
                          , ( SELECT SA.SITE_DESCRIPTION
                                FROM ( SELECT X.SITE_DESCRIPTION
                                         FROM SCM_MST_SITE X
                                        WHERE X.SCM_SITE_ID = A.SCM_SITE_ID
                                     )  SA
                               WHERE ROWNUM = 1 )                                   AS SCM_SITE_DESCRIPTION
                          , A.LINE_ID
                          , F.CELL_NICKNAME
                          , CASE
                              WHEN SUBSTR(A.DIVISION_ID, 1, 2) = '81' OR A.DIVISION_ID = '82'  THEN F.GROUP_CODE6
                              ELSE                                                                  F.CELL_TYPE_GROUP_NAME
                            END                                                     AS PRODUCT_LEVEL1
                          , CASE
                              WHEN SUBSTR(A.DIVISION_ID, 1, 2) = '81' OR A.DIVISION_ID = '82'  THEN F.GROUP_CODE7
                              ELSE                                                                  F.BASIC_NICKNAME_CELL40
                            END                                                     AS PRODUCT_LEVEL2
                          , CASE
                              WHEN SUBSTR(A.DIVISION_ID, 1, 2) = '81'                          THEN F.GROUP_CODE5
                              WHEN A.DIVISION_ID = '82'                                        THEN F.GROUP_CODE4
                              ELSE                                                                  F.NICKNAME_40
                            END                                                     AS PRODUCT_LEVEL3
                          , A.MODEL_ID
                          , A.ITEM_ID
                          , ( SELECT SA.NICK_NAME
                                FROM ( SELECT CASE
                                                WHEN X.NICK_NAME IS NULL OR X.NICK_NAME = ' ' THEN '-'
                                                ELSE                                               X.NICK_NAME
                                              END  AS NICK_NAME
                                         FROM SCM_MST_ITEM_SN X
                                        WHERE X.ITEM_ID = A.ITEM_ID
                                     )  SA
                               WHERE ROWNUM = 1 )                                   AS NICK_NAME
                          , A.MEASURE
                          , A.MEASURE_NAME
                          , A.USER_SORT_ORDER_NO
                          , 'EA'                                                    AS UOM
                          , 0                                                       AS CELL_CF
                          , V_CURR_PLAN_START                                       AS PLAN_START_YYYYMMDD
                          , P_FROM_YYYYMMDD                                         AS FROM_YYYYMMDD
                          , P_TO_YYYYMMDD                                           AS TO_YYYYMMDD
                          , 'D_' || A.YYYYMMDD                                      AS YYYYMMDD
                          , O.BASIS_YYYYMM                                          AS YYYYMM
                          , SUBSTR(O.BASIS_YYYYMM, -4) || O.ISO_WEEK                AS ISO_WEEK
                          , NVL(N.QTY, 0)                                           AS QTY
                          , A.ORIGIN_DIVISION_ID
                          , A.ELECTRODE_TYPE
                          , 'N'                                                     AS WEEK_YN
                          , 'N'                                                     AS MONTH_YN
                          , 'PP_W_' || V_CURR_PLAN_START                            AS VERSION_NO
                          , TO_CHAR(V_CURR_CNT)                                     AS VERSION_IDX
                       FROM ( SELECT XA.DIVISION_ID
                                   , XA.OPERATION_GROUP
                                   , XA.SCM_SITE_ID
                                   , XA.ITEM_ID
                                   , XA.LINE_ID
                                   , XA.OPERATION_ID
                                   , XA.MEASURE
                                   , XA.MEASURE_NAME
                                   , XA.USER_SORT_ORDER_NO
                                   , XA.YYYYMMDD
                                   , XA.ORIGIN_DIVISION_ID
                                   , XA.ELECTRODE_TYPE
                                   , FN_GET_ITEM_PROD_OP(XA.DIVISION_ID, XA.OPERATION_GROUP, XA.ITEM_ID)  AS MODEL_ID
                                FROM ( SELECT C.DIVISION_ID
                                            , C.OPERATION_GROUP
                                            , C.SCM_SITE_ID
                                            , C.ITEM_ID
                                            , C.LINE_ID
                                            , C.OPERATION_ID
                                            , A.COLUMN_NAME                         AS MEASURE
                                            , A.COLUMN_LABEL_NAME                   AS MEASURE_NAME
                                            , NVL(B.SORT_ORDER_NO, A.SORT_ORDER_NO) AS USER_SORT_ORDER_NO
                                            , C.YYYYMMDD
                                            , C.ORIGIN_DIVISION_ID
                                            , C.ELECTRODE_TYPE
                                         FROM SCM_MST_SHEET_MEASURE    A
                                            , SCM_MST_TITLESET_USER    B
                                            , GT_0017_STD              C
                                        WHERE B.PROGRAM_ID(+)  = A.PROGRAM_ID
                                          AND B.SHEET_NAME(+)  = A.SHEET_NAME
                                          AND B.COLUMN_NAME(+) = A.COLUMN_NAME
                                          AND B.USER_ID(+)     = P_USER_ID
                                          AND A.PROGRAM_ID     = P_PROGRAM_ID
                                          AND A.SHEET_NAME     = P_SHEET_NAME
                                          AND A.VALID_YN       = 'Y'
                                          AND ( P_OPERATION_GROUP = 'A' OR NVL(TRIM(A.ATTRIBUTE1), '@') <> 'A' )
                                          AND ( V_CNT_USER_MEASURE = 0
                                                OR EXISTS (SELECT 1
                                                             FROM SCM_MST_TITLESET_USER
                                                            WHERE PROGRAM_ID  = P_PROGRAM_ID
                                                              AND SHEET_NAME  = P_SHEET_NAME
                                                              AND USER_ID     = P_USER_ID
                                                              AND COLUMN_NAME = A.COLUMN_NAME) )
                                        GROUP BY C.DIVISION_ID
                                               , C.OPERATION_GROUP
                                               , C.SCM_SITE_ID
                                               , C.ITEM_ID
                                               , C.LINE_ID
                                               , C.OPERATION_ID
                                               , A.COLUMN_NAME
                                               , A.COLUMN_LABEL_NAME
                                               , C.YYYYMMDD
                                               , C.ORIGIN_DIVISION_ID
                                               , C.ELECTRODE_TYPE
                                               , NVL(B.SORT_ORDER_NO, A.SORT_ORDER_NO)
                                     )  XA
                            )  A
                          , GT_0017_FINAL_ITEM   F
                          , GT_0017_STD          N
                          , SCM_SYS_CALENDAR_M   O
                      WHERE A.DIVISION_ID          = F.DIVISION_ID(+)
                        AND A.MODEL_ID             = F.ITEM_ID(+)
                        AND A.DIVISION_ID          = N.DIVISION_ID(+)
                        AND A.OPERATION_GROUP      = N.OPERATION_GROUP(+)
                        AND A.SCM_SITE_ID          = N.SCM_SITE_ID(+)
                        AND A.ITEM_ID              = N.ITEM_ID(+)
                        AND A.OPERATION_ID         = N.OPERATION_ID(+)
                        AND A.LINE_ID              = N.LINE_ID(+)
                        AND A.MEASURE              = N.MEASURE(+)
                        AND A.YYYYMMDD             = N.YYYYMMDD(+)
                        AND A.ORIGIN_DIVISION_ID   = N.ORIGIN_DIVISION_ID(+)
                        AND A.ELECTRODE_TYPE       = N.ELECTRODE_TYPE(+)
                        AND A.YYYYMMDD             = O.BASIS_YYYYMMDD
                        AND A.LINE_ID IS NOT NULL
                        AND A.LINE_ID <> '*'
                   )  A
             WHERE 1 = 1;

            /* FILTER BEGIN */
            IF P_DIVISION_ID = 'EE' THEN

                DELETE FROM GT_0017_RAW
                 WHERE ORIGIN_DIVISION_ID NOT IN ('40', '81', '82');

            ELSIF P_DIVISION_ID = 'EE_UC' THEN

                DELETE FROM GT_0017_RAW
                 WHERE ORIGIN_DIVISION_ID <> '81_UC';

            ELSE

                DELETE FROM GT_0017_RAW
                 WHERE DIVISION_ID <> P_DIVISION_ID;

            END IF;

            IF TRIM(P_SCM_SITE_ID) IS NOT NULL THEN

                DELETE FROM GT_0017_RAW
                 WHERE SCM_SITE_ID NOT IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ',')));

            END IF;

            IF TRIM(P_MODEL_ID) IS NOT NULL THEN

                DELETE FROM GT_0017_RAW
                 WHERE MODEL_ID NOT IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_MODEL_ID, ',')));

            END IF;

            IF TRIM(P_ITEM_ID) IS NOT NULL OR TRIM(P_NICK_NAME) IS NOT NULL THEN

                DELETE FROM GT_0017_RAW
                 WHERE ITEM_ID NOT IN (SELECT COLUMN_VALUE FROM TABLE(FN_GET_ITEM_LIKE_CONDITION(P_ITEM_ID, P_NICK_NAME)));

            END IF;

            IF TRIM(P_ELECTRODE_TYPE) IS NOT NULL THEN

                DELETE FROM GT_0017_RAW
                 WHERE ELECTRODE_TYPE NOT IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_ELECTRODE_TYPE, ',')));

            END IF;

            IF TRIM(P_LINE_ID) IS NOT NULL THEN

                DELETE FROM GT_0017_RAW
                 WHERE LINE_ID NOT IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_LINE_ID, ',')));

            END IF;
            /* FILTER END */

            /*======================================================================
             * MEASURE = ONHAND_EOH의 경우
             *====================================================================*/
            UPDATE GT_0017_RAW A
               SET A.WEEK_YN = 'Y'
             WHERE 1 = 1
               AND A.MEASURE     = 'ONHAND_EOH'
               AND A.VERSION_IDX = TO_CHAR(V_CURR_CNT)
               AND EXISTS (SELECT 1
                             FROM ( SELECT MAX(BASIS_YYYYMMDD)  AS YYYYMMDD
                                      FROM SCM_SYS_CALENDAR_M
                                     WHERE BASIS_YYYYMMDD >= V_FROM_YYYYMMDD
                                       AND BASIS_YYYYMMDD <= V_TO_PERIOD    /* 마지막 구간 오류 발생으로 1개월 더함 */
                                     GROUP BY ISO_WEEK
                                            , PARTIAL_WEEK_NAME
                                  )  XA
                            WHERE XA.YYYYMMDD = SUBSTR(A.YYYYMMDD, -8));

            UPDATE GT_0017_RAW A
               SET A.MONTH_YN = 'Y'
             WHERE 1 = 1
               AND A.MEASURE     = 'ONHAND_EOH'
               AND A.VERSION_IDX = TO_CHAR(V_CURR_CNT)
               AND EXISTS (SELECT 1
                             FROM ( SELECT MAX(BASIS_YYYYMMDD)  AS YYYYMMDD
                                      FROM SCM_SYS_CALENDAR_M
                                     WHERE BASIS_YYYYMMDD >= V_FROM_YYYYMMDD
                                       AND BASIS_YYYYMMDD <= V_TO_PERIOD    /* 마지막 구간 오류 발생으로 1개월 더함 */
                                     GROUP BY BASIS_YYYYMM
                                  )  XA
                            WHERE XA.YYYYMMDD = SUBSTR(A.YYYYMMDD, -8));

            /* MEASURE => PROD_PLAN_ENGINE(B) 기준으로 PROD_PLAN_AMEND(A) 값 맞춤 20220914 by 신재욱책임님
             *
             * ★AS-IS 결함 : 갱신 대상은 MEASURE = 'PROD_PLAN_AMEND' 인 행인데
             *   짝을 찾는 조건에 A.MEASURE = B.MEASURE 가 있고 B 는 MEASURE = 'PROD_PLAN_ENGINE' 이므로
             *   두 값이 같아질 수 없어 AS-IS 에서도 갱신 건수가 언제나 0 이다.
             *   결과가 달라지지 않도록 조건을 그대로 두고 옮긴다. */
            UPDATE GT_0017_RAW A
               SET A.QTY = ( SELECT SUM(B.QTY)
                               FROM GT_0017_RAW B
                              WHERE B.KEY_IDX             = A.KEY_IDX
                                AND B.DIVISION_ID         = A.DIVISION_ID
                                AND B.OPERATION_GROUP     = A.OPERATION_GROUP
                                AND B.SCM_SITE_ID         = A.SCM_SITE_ID
                                AND B.LINE_ID             = A.LINE_ID
                                AND B.CELL_NICKNAME       = A.CELL_NICKNAME
                                AND B.PRODUCT_LEVEL1      = A.PRODUCT_LEVEL1
                                AND B.PRODUCT_LEVEL2      = A.PRODUCT_LEVEL2
                                AND B.PRODUCT_LEVEL3      = A.PRODUCT_LEVEL3
                                AND B.MODEL_ID            = A.MODEL_ID
                                AND B.ITEM_ID             = A.ITEM_ID
                                AND B.MEASURE             = A.MEASURE   /* chaan */
                                AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
                                AND B.FROM_YYYYMMDD       = A.FROM_YYYYMMDD
                                AND B.TO_YYYYMMDD         = A.TO_YYYYMMDD
                                AND B.YYYYMMDD            = A.YYYYMMDD
                                AND B.MEASURE             = 'PROD_PLAN_ENGINE'
                                AND B.YYYYMM             <= V_CURR_YYYYMM )   /* 당월까지 수량 일치시킴 */
             WHERE A.MEASURE = 'PROD_PLAN_AMEND'
               AND EXISTS (SELECT 1
                             FROM GT_0017_RAW B
                            WHERE B.KEY_IDX             = A.KEY_IDX
                              AND B.DIVISION_ID         = A.DIVISION_ID
                              AND B.OPERATION_GROUP     = A.OPERATION_GROUP
                              AND B.SCM_SITE_ID         = A.SCM_SITE_ID
                              AND B.LINE_ID             = A.LINE_ID
                              AND B.CELL_NICKNAME       = A.CELL_NICKNAME
                              AND B.PRODUCT_LEVEL1      = A.PRODUCT_LEVEL1
                              AND B.PRODUCT_LEVEL2      = A.PRODUCT_LEVEL2
                              AND B.PRODUCT_LEVEL3      = A.PRODUCT_LEVEL3
                              AND B.MODEL_ID            = A.MODEL_ID
                              AND B.ITEM_ID             = A.ITEM_ID
                              AND B.MEASURE             = A.MEASURE   /* chaan */
                              AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
                              AND B.FROM_YYYYMMDD       = A.FROM_YYYYMMDD
                              AND B.TO_YYYYMMDD         = A.TO_YYYYMMDD
                              AND B.YYYYMMDD            = A.YYYYMMDD
                              AND B.MEASURE             = 'PROD_PLAN_ENGINE'
                              AND B.YYYYMM             <= V_CURR_YYYYMM);

        END LOOP;


        /*==========================================================================
         * GAP
         *   AS-IS 는 Prod Plan(Amend) 의 1 회차(#..._RAW_PLAN_1)와 2 회차(#..._RAW_PLAN_2)를
         *   따로 담아 서로 외부조인한다. 두 벌을 그대로 인라인 뷰로 옮긴다.
         *
         *   ★측정값 이름 : AS-IS 는 첫 번째를 'GAP', 두 번째를 'Gap' 으로 넣는다.
         *     MSSQL 은 묶을 때 대소문자를 가리지 않아 두 행이 한 묶음이 되고
         *     묶음의 이름은 행마다 'GAP' 또는 'Gap' 으로 섞여 나온다(정해져 있지 않다).
         *     Oracle 은 갈리므로 그대로 두면 Gap 행이 두 줄로 나뉜다.
         *     그래서 두 곳 모두 'Gap' 으로 넣어 AS-IS 와 같은 행 구성을 만든다.
         *     실측(2026-09-26) : 'Gap' 으로 맞추면 사업부 82 Pack 425 행 · Cell 260 행으로
         *     AS-IS 와 같고, 나누면 Cell 이 306 행으로 늘어난다.
         *========================================================================*/
        IF P_GAP = 'Y' THEN

            INSERT INTO GT_0017_RAW
            (
                KEY_IDX
              , DIVISION_ID
              , DIVISION_NAME
              , OPERATION_GROUP
              , OPERATION_GROUP_NAME
              , SCM_SITE_ID
              , SCM_SITE_DESCRIPTION
              , LINE_ID
              , CELL_NICKNAME
              , PRODUCT_LEVEL1
              , PRODUCT_LEVEL2
              , PRODUCT_LEVEL3
              , MODEL_ID
              , ITEM_ID
              , NICK_NAME
              , MEASURE
              , MEASURE_NAME
              , USER_SORT_ORDER_NO
              , UOM
              , CELL_CF
              , PLAN_START_YYYYMMDD
              , FROM_YYYYMMDD
              , TO_YYYYMMDD
              , YYYYMMDD
              , YYYYMM
              , ISO_WEEK
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
              , WEEK_YN
              , MONTH_YN
              , VERSION_NO
              , VERSION_IDX
            )
            SELECT A.KEY_IDX
                 , A.DIVISION_ID
                 , A.DIVISION_NAME
                 , A.OPERATION_GROUP
                 , A.OPERATION_GROUP_NAME
                 , A.SCM_SITE_ID
                 , ( SELECT SA.SITE_DESCRIPTION
                       FROM ( SELECT X.SITE_DESCRIPTION
                                FROM SCM_MST_SITE X
                               WHERE X.SCM_SITE_ID = A.SCM_SITE_ID
                            )  SA
                      WHERE ROWNUM = 1 )                             AS SCM_SITE_DESCRIPTION
                 , A.LINE_ID
                 , A.CELL_NICKNAME
                 , A.PRODUCT_LEVEL1
                 , A.PRODUCT_LEVEL2
                 , A.PRODUCT_LEVEL3
                 , A.MODEL_ID
                 , A.ITEM_ID
                 , A.NICK_NAME
                 , 'GAP'                                             AS MEASURE
                 , 'Gap'                                             AS MEASURE_NAME
                 , A.USER_SORT_ORDER_NO
                 , A.UOM
                 , A.CELL_CF
                 , '99991231'                                        AS PLAN_START_YYYYMMDD
                 , NULL                                              AS FROM_YYYYMMDD
                 , NULL                                              AS TO_YYYYMMDD
                 , A.YYYYMMDD
                 , A.YYYYMM
                 , A.ISO_WEEK
                 , (NVL(A.QTY, 0.0) - NVL(B.QTY, 0.0))               AS QTY
                 , A.ORIGIN_DIVISION_ID
                 , A.ELECTRODE_TYPE
                 , A.WEEK_YN
                 , A.MONTH_YN
                 , '-'                                               AS VERSION_NO
                 , '3'                                               AS VERSION_IDX
              FROM ( SELECT *
                       FROM GT_0017_RAW
                      WHERE 1 = 1
                        AND MEASURE_NAME = 'Prod Plan(Amend)'
                        AND VERSION_IDX  = '2'
                   )  A
                 , ( SELECT *
                       FROM GT_0017_RAW
                      WHERE 1 = 1
                        AND MEASURE_NAME = 'Prod Plan(Amend)'
                        AND VERSION_IDX  = '1'
                   )  B
             WHERE A.KEY_IDX            = B.KEY_IDX(+)
               AND A.DIVISION_ID        = B.DIVISION_ID(+)
               AND A.OPERATION_GROUP    = B.OPERATION_GROUP(+)
               AND A.MEASURE            = B.MEASURE(+)
               AND A.MEASURE_NAME       = B.MEASURE_NAME(+)
               AND A.FROM_YYYYMMDD      = B.FROM_YYYYMMDD(+)
               AND A.TO_YYYYMMDD        = B.TO_YYYYMMDD(+)
               AND A.SCM_SITE_ID        = B.SCM_SITE_ID(+)
               AND A.LINE_ID            = B.LINE_ID(+)
               AND A.CELL_NICKNAME      = B.CELL_NICKNAME(+)
               AND A.PRODUCT_LEVEL1     = B.PRODUCT_LEVEL1(+)
               AND A.PRODUCT_LEVEL2     = B.PRODUCT_LEVEL2(+)
               AND A.PRODUCT_LEVEL3     = B.PRODUCT_LEVEL3(+)
               AND A.MODEL_ID           = B.MODEL_ID(+)
               AND A.ITEM_ID            = B.ITEM_ID(+)
               AND A.YYYYMMDD           = B.YYYYMMDD(+)
               AND A.ISO_WEEK           = B.ISO_WEEK(+)
               AND A.USER_SORT_ORDER_NO = B.USER_SORT_ORDER_NO(+);

            INSERT INTO GT_0017_RAW
            (
                KEY_IDX
              , DIVISION_ID
              , DIVISION_NAME
              , OPERATION_GROUP
              , OPERATION_GROUP_NAME
              , SCM_SITE_ID
              , SCM_SITE_DESCRIPTION
              , LINE_ID
              , CELL_NICKNAME
              , PRODUCT_LEVEL1
              , PRODUCT_LEVEL2
              , PRODUCT_LEVEL3
              , MODEL_ID
              , ITEM_ID
              , NICK_NAME
              , MEASURE
              , MEASURE_NAME
              , USER_SORT_ORDER_NO
              , UOM
              , CELL_CF
              , PLAN_START_YYYYMMDD
              , FROM_YYYYMMDD
              , TO_YYYYMMDD
              , YYYYMMDD
              , YYYYMM
              , ISO_WEEK
              , QTY
              , ORIGIN_DIVISION_ID
              , ELECTRODE_TYPE
              , WEEK_YN
              , MONTH_YN
              , VERSION_NO
              , VERSION_IDX
            )
            SELECT A.KEY_IDX
                 , A.DIVISION_ID
                 , A.DIVISION_NAME
                 , A.OPERATION_GROUP
                 , A.OPERATION_GROUP_NAME
                 , A.SCM_SITE_ID
                 , ( SELECT SA.SITE_DESCRIPTION
                       FROM ( SELECT X.SITE_DESCRIPTION
                                FROM SCM_MST_SITE X
                               WHERE X.SCM_SITE_ID = A.SCM_SITE_ID
                            )  SA
                      WHERE ROWNUM = 1 )                             AS SCM_SITE_DESCRIPTION
                 , A.LINE_ID
                 , A.CELL_NICKNAME
                 , A.PRODUCT_LEVEL1
                 , A.PRODUCT_LEVEL2
                 , A.PRODUCT_LEVEL3
                 , A.MODEL_ID
                 , A.ITEM_ID
                 , A.NICK_NAME
                 , 'GAP'                                             AS MEASURE
                 , 'Gap'                                             AS MEASURE_NAME
                 , A.USER_SORT_ORDER_NO
                 , A.UOM
                 , A.CELL_CF
                 , '99991231'                                        AS PLAN_START_YYYYMMDD
                 , NULL                                              AS FROM_YYYYMMDD
                 , NULL                                              AS TO_YYYYMMDD
                 , A.YYYYMMDD
                 , A.YYYYMM
                 , A.ISO_WEEK
                 , (NVL(B.QTY, 0.0) - NVL(A.QTY, 0.0))               AS QTY
                 , A.ORIGIN_DIVISION_ID
                 , A.ELECTRODE_TYPE
                 , A.WEEK_YN
                 , A.MONTH_YN
                 , '-'                                               AS VERSION_NO
                 , '3'                                               AS VERSION_IDX
              FROM ( SELECT *
                       FROM GT_0017_RAW
                      WHERE 1 = 1
                        AND MEASURE_NAME = 'Prod Plan(Amend)'
                        AND VERSION_IDX  = '1'
                   )  A
                 , ( SELECT *
                       FROM GT_0017_RAW
                      WHERE 1 = 1
                        AND MEASURE_NAME = 'Prod Plan(Amend)'
                        AND VERSION_IDX  = '2'
                   )  B
             WHERE A.KEY_IDX            = B.KEY_IDX(+)
               AND A.DIVISION_ID        = B.DIVISION_ID(+)
               AND A.OPERATION_GROUP    = B.OPERATION_GROUP(+)
               AND A.MEASURE            = B.MEASURE(+)
               AND A.MEASURE_NAME       = B.MEASURE_NAME(+)
               AND A.FROM_YYYYMMDD      = B.FROM_YYYYMMDD(+)
               AND A.TO_YYYYMMDD        = B.TO_YYYYMMDD(+)
               AND A.SCM_SITE_ID        = B.SCM_SITE_ID(+)
               AND A.LINE_ID            = B.LINE_ID(+)
               AND A.CELL_NICKNAME      = B.CELL_NICKNAME(+)
               AND A.PRODUCT_LEVEL1     = B.PRODUCT_LEVEL1(+)
               AND A.PRODUCT_LEVEL2     = B.PRODUCT_LEVEL2(+)
               AND A.PRODUCT_LEVEL3     = B.PRODUCT_LEVEL3(+)
               AND A.MODEL_ID           = B.MODEL_ID(+)
               AND A.ITEM_ID            = B.ITEM_ID(+)
               AND A.YYYYMMDD           = B.YYYYMMDD(+)
               AND A.ISO_WEEK           = B.ISO_WEEK(+)
               AND A.USER_SORT_ORDER_NO = B.USER_SORT_ORDER_NO(+);

        END IF;

        /*==========================================================================
         * 단위 환산
         *   AS-IS 는 #..._RAW_ALL (RAW x UOM) 을 만든 뒤 환산해 #..._RAW_ALL_UOM 에 담는다.
         *   #..._RAW_ALL 은 한 번만 읽히므로 한 문장으로 합친다.
         *========================================================================*/
        INSERT INTO GT_0017_RAW_ALL_UOM
        (
            KEY_IDX
          , DIVISION_ID
          , DIVISION_NAME
          , OPERATION_GROUP
          , OPERATION_GROUP_NAME
          , SCM_SITE_ID
          , SCM_SITE_DESCRIPTION
          , LINE_ID
          , CELL_NICKNAME
          , PRODUCT_LEVEL1
          , PRODUCT_LEVEL2
          , PRODUCT_LEVEL3
          , MODEL_ID
          , ITEM_ID
          , NICK_NAME
          , MEASURE
          , MEASURE_NAME
          , USER_SORT_ORDER_NO
          , UOM
          , CELL_CF
          , PLAN_START_YYYYMMDD
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , YYYYMMDD
          , YYYYMM
          , ISO_WEEK
          , QTY
          , ORIGIN_DIVISION_ID
          , ELECTRODE_TYPE
          , WEEK_YN
          , MONTH_YN
          , VERSION_NO
          , VERSION_IDX
        )
        SELECT A.KEY_IDX
             , A.DIVISION_ID
             , A.DIVISION_NAME
             , A.OPERATION_GROUP
             , A.OPERATION_GROUP_NAME
             , A.SCM_SITE_ID
             , A.SCM_SITE_DESCRIPTION
             , A.LINE_ID
             , A.CELL_NICKNAME
             , A.PRODUCT_LEVEL1
             , A.PRODUCT_LEVEL2
             , A.PRODUCT_LEVEL3
             , A.MODEL_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , A.MEASURE
             , A.MEASURE_NAME
             , A.USER_SORT_ORDER_NO
             , U.UOM
             , T.CELL_CF
             , A.PLAN_START_YYYYMMDD
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.YYYYMMDD
             , A.YYYYMM
             , A.ISO_WEEK
             , CASE
                 WHEN T.CELL_CF IS NOT NULL THEN A.QTY
                 WHEN TT.UOM = 'M'          THEN A.QTY * TT.CELL_CF
                 ELSE A.QTY / CASE WHEN NVL(TE.CELL_CF, 0) = 0 THEN 1.0 ELSE TE.CELL_CF END
               END                                                      AS QTY
             , A.ORIGIN_DIVISION_ID
             , A.ELECTRODE_TYPE
             , A.WEEK_YN
             , A.MONTH_YN
             , A.VERSION_NO
             , A.VERSION_IDX
          FROM GT_0017_RAW    A
             , GT_0017_UOM    U        /* UOM 갯수만큼 행 복제를 위해 풀조인함 */
             , ( SELECT ITEM_ID
                      , UNIT                                AS UOM
                      , CAST(CELL_CF AS NUMBER(23,10))      AS CELL_CF
                   FROM SCP_MST_ITEM_CELL_CF
                  WHERE 1 = 1
               )  T
             , ( SELECT ITEM_ID
                      , UNIT                                AS UOM
                      , CAST(CELL_CF AS NUMBER(23,10))      AS CELL_CF
                   FROM SCP_MST_ITEM_CELL_CF
                  WHERE 1 = 1
               )  TT
             , ( SELECT XA.DIVISION_ID
                      , XA.ITEM_ID
                      , XA.VALUE  AS CELL_CF
                   FROM ( SELECT C.DIVISION_ID
                               , C.ITEM_ID
                               , C.VALUE
                               , ROW_NUMBER() OVER (PARTITION BY C.DIVISION_ID
                                                               , C.ITEM_ID
                                                       ORDER BY C.VALUE DESC)  AS RN
                            FROM SCM_MST_ITEM_CONV_CALC_SN C
                           WHERE 1 = 1
                             AND C.CATEGORY     = 'Pancake (cell/m)'   /* 고정 */
                             AND C.VERSION_TYPE = 'MASS'               /* 고정 */
                             AND C.MAX_VER_FLAG = 'Y'                  /* 고정 */
                        )  XA
                  WHERE 1 = 1
                    AND XA.RN = 1
               )  TE
         WHERE A.ITEM_ID            = T.ITEM_ID(+)
           AND U.UOM                = T.UOM(+)      /* CELL_CF 가 NULL 이 아닌 경우로 원래 UNIT 판별 */
           AND A.ITEM_ID            = TT.ITEM_ID(+) /* ITEM_ID와 UOM 로 조인하는 경우 CELL_CF 가 NULL 일 수 있으므로 CELL_CF 를 다시 검색하기위한 조인 */
           AND A.ORIGIN_DIVISION_ID = TE.DIVISION_ID(+)  /* EA->M 변환시 환산로직 */
           AND A.ITEM_ID            = TE.ITEM_ID(+);

        /*==========================================================================
         * pivot 전 사용자 지정 컬럼별로 합산 - 컬럼 변수셋팅
         *========================================================================*/
        FOR R IN ( SELECT COLUMN_NAME
                     FROM GT_0017_COLUMN
                    ORDER BY USER_SORT_ORDER_NO
                 )
        LOOP
            V_USER_COLS := V_USER_COLS || ', ' || R.COLUMN_NAME;
        END LOOP;

        V_USER_COLS       := SUBSTR(V_USER_COLS, 3) || ', MEASURE';   /* UI에서 MEASURE 필수 컬럼 */
        V_USER_COLS       := REPLACE(V_USER_COLS, 'VERSION_NO', 'USER_SORT_ORDER_NO, VERSION_IDX, VERSION_NO');

        /* ★같은 칸 이름이 두 번 들어가면 묶을 수도 담을 수도 없으므로 중복을 뺀다.
         *   AS-IS 는 MEASURE 를 보이지 않는 칸으로 두어 목록에 한 번만 들어가므로
         *   중복을 뺀 목록이 곧 AS-IS 목록이다.
         *   (기준 데이터베이스는 이관 과정에서 MEASURE 가 보이는 칸으로 바뀌어 있어 두 번 들어간다.
         *    칸 설정을 AS-IS 와 같게 되돌리는 조치문을 따로 낸다.) */
        DECLARE
            V_TOKEN     VARCHAR2(200);
            V_IDX       PLS_INTEGER := 1;
        BEGIN
            LOOP
                V_TOKEN := TRIM(REGEXP_SUBSTR(V_USER_COLS, '[^,]+', 1, V_IDX));
                EXIT WHEN V_TOKEN IS NULL;

                IF INSTR(',' || REPLACE(V_USER_COLS_UNIQ, ' ', '') || ',', ',' || V_TOKEN || ',') = 0 THEN
                    IF V_USER_COLS_UNIQ IS NULL THEN
                        V_USER_COLS_UNIQ := V_TOKEN;
                    ELSE
                        V_USER_COLS_UNIQ := V_USER_COLS_UNIQ || ', ' || V_TOKEN;
                    END IF;
                END IF;

                V_IDX := V_IDX + 1;
            END LOOP;
        END;

        V_USER_COLS       := V_USER_COLS_UNIQ;
        V_USER_COLS_ORDER := REPLACE(V_USER_COLS, ', UOM', ', UOM DESC');

        V_GAP_USER_COLS   := 'A.' || REPLACE(V_USER_COLS, ', ', ', A.');
        V_GAP_USER_KEYS   := REPLACE(V_GAP_USER_COLS, ', A.', ' || '';'' || A.');

        /*==========================================================================
         * PIVOT COLUMNS
         *========================================================================*/
        /* 정렬 보조 키(BLK) : AS-IS 는 SORT_ORDER_NO 가 같은 칸이 여럿이어서
         *   (같은 주의 주계 칸과 ISO 주계 칸은 값이 같다) 순서가 정해지지 않는다.
         *   MSSQL 은 UNION ALL 을 적은 차례대로 내보내므로 그 차례를 두 번째 키로 둔다. */
        FOR R IN ( SELECT YYYYMMDD
                     FROM ( SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK              AS YYYYMMDD
                                 , A.BASIS_START_DATE || '21'                        AS SORT_ORDER_NO
                                 , 1                                                 AS BLK
                              FROM SCM_SYS_CALENDAR_M A
                             WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY A.BASIS_YYYYMM
                                    , A.ISO_WEEK
                                    , A.BASIS_START_DATE
                             UNION ALL
                            SELECT 'W_' || A.ISO_YYYYMM || A.ISO_WEEK || '_ISO'      AS YYYYMMDD
                                 , MIN(A.BASIS_START_DATE) || '21'                   AS SORT_ORDER_NO
                                 , 2                                                 AS BLK
                              FROM SCM_SYS_CALENDAR_M A
                             WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY A.ISO_YYYYMM
                                    , A.ISO_WEEK
                             UNION ALL
                            SELECT 'M_' || A.BASIS_YYYYMM                            AS YYYYMMDD
                                 , MIN(A.BASIS_START_DATE) || '01'                   AS SORT_ORDER_NO
                                 , 3                                                 AS BLK
                              FROM SCM_SYS_CALENDAR_M A
                             WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY A.BASIS_YYYYMM
                                    , A.MONTH_NAME
                             UNION ALL
                            SELECT 'D_' || A.BASIS_YYYYMMDD                          AS YYYYMMDD
                                 , A.BASIS_YYYYMMDD || '31'                          AS SORT_ORDER_NO
                                 , 4                                                 AS BLK
                              FROM SCM_SYS_CALENDAR_M A
                             WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY A.BASIS_YYYYMMDD
                          )  A
                    ORDER BY SORT_ORDER_NO
                           , BLK
                 )
        LOOP

            /* 결과 칸 이름 목록과, 누계 조회에서 어느 자료의 값을 쓸지 고른 목록
             *   AS-IS 는 일 누계 자료를 만든 뒤 주 칸은 주 누계로, 월 칸은 월 누계로 덮어쓴다.
             *   덮어쓰기는 키가 맞을 때만 일어나므로 키가 없으면 일 누계 값이 남는다.
             *   외부조인 + NVL 로 같은 결과를 낸다. */
            V_PIVOT_COLS := V_PIVOT_COLS || CHR(10) || '     , A.' || R.YYYYMMDD;

            IF SUBSTR(R.YYYYMMDD, 1, 2) = 'D_' THEN
                V_ACC_SEL_COLS := V_ACC_SEL_COLS || CHR(10) || '     , DA.' || R.YYYYMMDD || '  AS ' || R.YYYYMMDD;
            ELSIF SUBSTR(R.YYYYMMDD, 1, 2) = 'W_' THEN
                V_ACC_SEL_COLS := V_ACC_SEL_COLS || CHR(10) || '     , NVL(WA.' || R.YYYYMMDD || ', DA.' || R.YYYYMMDD || ')  AS ' || R.YYYYMMDD;
            ELSE
                V_ACC_SEL_COLS := V_ACC_SEL_COLS || CHR(10) || '     , NVL(MA.' || R.YYYYMMDD || ', DA.' || R.YYYYMMDD || ')  AS ' || R.YYYYMMDD;
            END IF;

            /* 구간 수량 */
            IF SUBSTR(R.YYYYMMDD, 1, 2) = 'M_' THEN

                DBMS_LOB.APPEND(V_SUM_COLS, TO_CLOB(CHR(10) || '     , CAST(NVL(SUM(CASE WHEN YYYYMM = SUBSTR(''' || R.YYYYMMDD || ''', -6) THEN QTY END), 0) AS NUMBER(23,10))  AS ' || R.YYYYMMDD));
                DBMS_LOB.APPEND(V_ACC_DAY_COLS, TO_CLOB(CHR(10) || '     , CAST(NVL(SUM(CASE WHEN YYYYMM = SUBSTR(''' || R.YYYYMMDD || ''', -6) THEN ACC_QTY END), 0) AS NUMBER(23,10))  AS ' || R.YYYYMMDD));
                DBMS_LOB.APPEND(V_ACC_WEEK_COLS, TO_CLOB(CHR(10) || '     , CAST(0 AS NUMBER(23,10))  AS ' || R.YYYYMMDD));
                DBMS_LOB.APPEND(V_ACC_MONTH_COLS, TO_CLOB(CHR(10) || '     , CAST(NVL(SUM(CASE WHEN YYYYMM = SUBSTR(''' || R.YYYYMMDD || ''', -6) THEN ACC_QTY END), 0) AS NUMBER(23,10))  AS ' || R.YYYYMMDD));

            ELSIF SUBSTR(R.YYYYMMDD, 1, 2) = 'W_' THEN

                IF SUBSTR(R.YYYYMMDD, -4) <> '_ISO' THEN
                    DBMS_LOB.APPEND(V_SUM_COLS, TO_CLOB(CHR(10) || '     , CAST(NVL(SUM(CASE WHEN ISO_WEEK = SUBSTR(''' || R.YYYYMMDD || ''', -6) THEN QTY END), 0) AS NUMBER(23,10))  AS ' || R.YYYYMMDD));
                    DBMS_LOB.APPEND(V_ACC_DAY_COLS, TO_CLOB(CHR(10) || '     , CAST(NVL(SUM(CASE WHEN ISO_WEEK = SUBSTR(''' || R.YYYYMMDD || ''', -6) THEN ACC_QTY END), 0) AS NUMBER(23,10))  AS ' || R.YYYYMMDD));
                ELSE
                    DBMS_LOB.APPEND(V_SUM_COLS, TO_CLOB(CHR(10) || '     , CAST(NVL(SUM(CASE WHEN SUBSTR(ISO_WEEK, 1, 2) || SUBSTR(ISO_WEEK, 5, 2) = SUBSTR(''' || R.YYYYMMDD || ''', 5, 2) || SUBSTR(''' || R.YYYYMMDD || ''', 9, 2) THEN QTY END), 0) AS NUMBER(23,10))  AS ' || R.YYYYMMDD));
                    DBMS_LOB.APPEND(V_ACC_DAY_COLS, TO_CLOB(CHR(10) || '     , CAST(NVL(SUM(CASE WHEN SUBSTR(ISO_WEEK, 1, 2) || SUBSTR(ISO_WEEK, 5, 2) = SUBSTR(''' || R.YYYYMMDD || ''', 5, 2) || SUBSTR(''' || R.YYYYMMDD || ''', 9, 2) THEN ACC_QTY END), 0) AS NUMBER(23,10))  AS ' || R.YYYYMMDD));
                END IF;

                DBMS_LOB.APPEND(V_ACC_WEEK_COLS, TO_CLOB(CHR(10) || '     , CAST(NVL(SUM(CASE WHEN ISO_WEEK = SUBSTR(''' || R.YYYYMMDD || ''', 3, 8) THEN ACC_QTY END), 0) AS NUMBER(23,10))  AS ' || R.YYYYMMDD));
                DBMS_LOB.APPEND(V_ACC_MONTH_COLS, TO_CLOB(CHR(10) || '     , CAST(0 AS NUMBER(23,10))  AS ' || R.YYYYMMDD));

            ELSE    /* D_ */

                DBMS_LOB.APPEND(V_SUM_COLS, TO_CLOB(CHR(10) || '     , CAST(NVL(SUM(CASE WHEN YYYYMMDD = ''' || R.YYYYMMDD || ''' THEN QTY END), 0) AS NUMBER(23,10))  AS ' || R.YYYYMMDD));
                /* 누계 yyyymmdd 컬럼은 'D_20230101' 형태가 아닌 '20230101' 형태이므로 RIGHT(YYYYMMDD, 8) 로 비교한다!!! */
                DBMS_LOB.APPEND(V_ACC_DAY_COLS, TO_CLOB(CHR(10) || '     , CAST(NVL(SUM(CASE WHEN YYYYMMDD = ''' || SUBSTR(R.YYYYMMDD, -8) || ''' THEN ACC_QTY END), 0) AS NUMBER(23,10))  AS ' || R.YYYYMMDD));
                DBMS_LOB.APPEND(V_ACC_WEEK_COLS, TO_CLOB(CHR(10) || '     , CAST(0 AS NUMBER(23,10))  AS ' || R.YYYYMMDD));
                DBMS_LOB.APPEND(V_ACC_MONTH_COLS, TO_CLOB(CHR(10) || '     , CAST(0 AS NUMBER(23,10))  AS ' || R.YYYYMMDD));

            END IF;

        END LOOP;


        /*==========================================================================
         * GAP 누계
         *   AS-IS 는 GAP 여부와 상관없이 #..._Final_RAW 를 만들지만
         *   그 자료를 읽는 곳이 GAP 누계 산출뿐이므로 GAP 일 때만 담는다.
         *========================================================================*/
        IF P_GAP = 'Y' THEN

            /* #..._Final_RAW */
            DBMS_LOB.TRIM(V_SQL, 0);
            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                'INSERT INTO GT_0017_FINAL_RAW (' || V_USER_COLS || ', YYYYMM, ISO_WEEK, YYYYMMDD, QTY)' || CHR(10)
             || 'SELECT ' || V_USER_COLS || CHR(10)
             || '     , YYYYMM' || CHR(10)
             || '     , ISO_WEEK' || CHR(10)
             || '     , YYYYMMDD' || CHR(10)
             || '     , SUM(QTY)  AS QTY' || CHR(10)
             || '  FROM GT_0017_RAW_ALL_UOM' || CHR(10)
             || ' GROUP BY ' || V_USER_COLS || CHR(10)
             || '        , YYYYMM' || CHR(10)
             || '        , ISO_WEEK' || CHR(10)
             || '        , YYYYMMDD'));
            EXECUTE IMMEDIATE V_SQL;

            /* #..._Final_RAW_GAP_DAY
             *   AS-IS 는 기간의 모든 날짜 x 키 조합을 만든 뒤(#..._GAP_DAY_KEYS)
             *   GAP 수량을 외부조인해 없는 날은 0 으로 채운다. 한 문장으로 합친다. */
            DBMS_LOB.TRIM(V_SQL, 0);
            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                'INSERT INTO GT_0017_GAP_DAY (' || V_USER_COLS || ', KEY_IDX, YYYYMM, ISO_WEEK, YYYYMMDD, QTY)' || CHR(10)
             || 'SELECT ' || V_GAP_USER_COLS || CHR(10)
             || '     , A.KEY_IDX' || CHR(10)
             || '     , B.YYYYMM' || CHR(10)
             || '     , B.ISO_WEEK' || CHR(10)
             || '     , B.YYYYMMDD' || CHR(10)
             || '     , NVL(C.QTY, 0)  AS QTY' || CHR(10)
             || '  FROM ( SELECT DISTINCT ' || V_USER_COLS || CHR(10)
             || '              , ' || V_GAP_USER_KEYS || '  AS KEY_IDX' || CHR(10)
             || '           FROM GT_0017_FINAL_RAW A' || CHR(10)
             || '          WHERE 1 = 1' || CHR(10)
             || '            AND A.MEASURE = ''GAP''' || CHR(10)
             || '       )  A' || CHR(10)
             || '     , ( SELECT DISTINCT XA.BASIS_YYYYMM                    AS YYYYMM' || CHR(10)
             || '              , XA.BASIS_YYYYMM || XA.ISO_WEEK              AS ISO_WEEK' || CHR(10)
             || '              , XA.BASIS_YYYYMMDD                           AS YYYYMMDD' || CHR(10)
             || '           FROM SCM_SYS_CALENDAR_M XA' || CHR(10)
             || '          WHERE XA.BASIS_YYYYMMDD BETWEEN ''' || P_FROM_YYYYMMDD || ''' AND ''' || P_TO_YYYYMMDD || '''' || CHR(10)
             || '       )  B' || CHR(10)
             || '     , ( SELECT ' || V_GAP_USER_KEYS || '  AS KEY_IDX' || CHR(10)
             || '              , A.YYYYMM' || CHR(10)
             || '              , A.YYYYMM || SUBSTR(A.ISO_WEEK, -2)          AS ISO_WEEK' || CHR(10)
             || '              , SUBSTR(A.YYYYMMDD, -8)                      AS YYYYMMDD' || CHR(10)
             || '              , A.QTY' || CHR(10)
             || '           FROM GT_0017_FINAL_RAW A' || CHR(10)
             || '          WHERE 1 = 1' || CHR(10)
             || '            AND A.MEASURE = ''GAP''' || CHR(10)
             || '       )  C' || CHR(10)
             || ' WHERE A.KEY_IDX  = C.KEY_IDX(+)' || CHR(10)
             || '   AND B.YYYYMM   = C.YYYYMM(+)' || CHR(10)
             || '   AND B.ISO_WEEK = C.ISO_WEEK(+)' || CHR(10)
             || '   AND B.YYYYMMDD = C.YYYYMMDD(+)'));
            EXECUTE IMMEDIATE V_SQL;

            /* #..._Final_RAW_GAP_WEEK */
            DBMS_LOB.TRIM(V_SQL, 0);
            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                'INSERT INTO GT_0017_GAP_WEEK (' || V_USER_COLS || ', KEY_IDX, YYYYMM, ISO_WEEK, QTY)' || CHR(10)
             || 'SELECT ' || V_USER_COLS || CHR(10)
             || '     , KEY_IDX' || CHR(10)
             || '     , YYYYMM' || CHR(10)
             || '     , ISO_WEEK' || CHR(10)
             || '     , SUM(QTY)  AS QTY' || CHR(10)
             || '  FROM GT_0017_GAP_DAY' || CHR(10)
             || ' GROUP BY ' || V_USER_COLS || CHR(10)
             || '        , KEY_IDX' || CHR(10)
             || '        , YYYYMM' || CHR(10)
             || '        , ISO_WEEK'));
            EXECUTE IMMEDIATE V_SQL;

            /* #..._Final_RAW_GAP_MONTH */
            DBMS_LOB.TRIM(V_SQL, 0);
            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                'INSERT INTO GT_0017_GAP_MONTH (' || V_USER_COLS || ', KEY_IDX, YYYYMM, QTY)' || CHR(10)
             || 'SELECT ' || V_USER_COLS || CHR(10)
             || '     , KEY_IDX' || CHR(10)
             || '     , YYYYMM' || CHR(10)
             || '     , SUM(QTY)  AS QTY' || CHR(10)
             || '  FROM GT_0017_GAP_WEEK' || CHR(10)
             || ' GROUP BY ' || V_USER_COLS || CHR(10)
             || '        , KEY_IDX' || CHR(10)
             || '        , YYYYMM'));
            EXECUTE IMMEDIATE V_SQL;

        END IF;

        /*==========================================================================
         * 결과
         *   AS-IS #..._FIANL_SUM = 사용자 칸으로 묶은 구간 합계 + 키
         *   GAP 이면 누계(#..._Final_ACC_DAY)를 같은 칸 구성으로 덧붙인다.
         *========================================================================*/
        DBMS_LOB.TRIM(V_SQL, 0);
        DBMS_LOB.APPEND(V_SQL, TO_CLOB(
            'SELECT * FROM (' || CHR(10)
         || 'SELECT ' || V_GAP_USER_COLS));
        DBMS_LOB.APPEND(V_SQL, V_PIVOT_COLS);
        DBMS_LOB.APPEND(V_SQL, TO_CLOB(
            CHR(10) || '     , ' || V_GAP_USER_KEYS || '  AS KEY_IDX' || CHR(10)
         || '  FROM ( SELECT ' || V_USER_COLS));
        DBMS_LOB.APPEND(V_SQL, V_SUM_COLS);
        DBMS_LOB.APPEND(V_SQL, TO_CLOB(
            CHR(10) || '           FROM GT_0017_RAW_ALL_UOM' || CHR(10)
         || '          GROUP BY ' || V_USER_COLS || CHR(10)
         || '       )  A'));

        IF P_GAP = 'Y' THEN

            /* 누계 : 사용자 칸 가운데 측정값 이름만 Gap(Acc) 로 바꾼다 */
            DECLARE
                V_TOKEN     VARCHAR2(200);
                V_IDX       PLS_INTEGER := 1;
                V_ACC_COLS  VARCHAR2(4000);
                V_ONE       VARCHAR2(400);
            BEGIN
                LOOP
                    V_TOKEN := TRIM(REGEXP_SUBSTR(V_USER_COLS, '[^,]+', 1, V_IDX));
                    EXIT WHEN V_TOKEN IS NULL;

                    IF V_TOKEN = 'MEASURE' THEN
                        V_ONE := '''GAP_ACC''  AS MEASURE';
                    ELSIF V_TOKEN = 'MEASURE_NAME' THEN
                        V_ONE := '''Gap(Acc)''  AS MEASURE_NAME';
                    ELSE
                        V_ONE := 'DA.' || V_TOKEN;
                    END IF;

                    IF V_ACC_COLS IS NULL THEN
                        V_ACC_COLS := V_ONE;
                    ELSE
                        V_ACC_COLS := V_ACC_COLS || CHR(10) || '     , ' || V_ONE;
                    END IF;

                    V_IDX := V_IDX + 1;
                END LOOP;

                DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                    CHR(10) || ' UNION ALL' || CHR(10)
                 || 'SELECT ' || V_ACC_COLS));
            END;

            DBMS_LOB.APPEND(V_SQL, V_ACC_SEL_COLS);
            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                CHR(10) || '     , DA.KEY_IDX' || CHR(10)
             || '  FROM ( SELECT ' || V_USER_COLS || CHR(10)
             || '              , KEY_IDX'));
            DBMS_LOB.APPEND(V_SQL, V_ACC_DAY_COLS);
            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                CHR(10) || '           FROM ( SELECT ' || V_USER_COLS || CHR(10)
             || '                       , KEY_IDX' || CHR(10)
             || '                       , YYYYMM' || CHR(10)
             || '                       , ISO_WEEK' || CHR(10)
             || '                       , YYYYMMDD' || CHR(10)
             || '                       , SUM(QTY) OVER (PARTITION BY KEY_IDX ORDER BY YYYYMM, ISO_WEEK, YYYYMMDD)  AS ACC_QTY' || CHR(10)
             || '                    FROM GT_0017_GAP_DAY' || CHR(10)
             || '                )  IA' || CHR(10)
             || '          GROUP BY ' || V_USER_COLS || CHR(10)
             || '                 , KEY_IDX' || CHR(10)
             || '       )  DA' || CHR(10)
             || '     , ( SELECT KEY_IDX'));
            DBMS_LOB.APPEND(V_SQL, V_ACC_WEEK_COLS);
            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                CHR(10) || '           FROM ( SELECT ' || V_USER_COLS || CHR(10)
             || '                       , KEY_IDX' || CHR(10)
             || '                       , YYYYMM' || CHR(10)
             || '                       , ISO_WEEK' || CHR(10)
             || '                       , SUM(QTY) OVER (PARTITION BY KEY_IDX ORDER BY YYYYMM, ISO_WEEK)  AS ACC_QTY' || CHR(10)
             || '                    FROM GT_0017_GAP_WEEK' || CHR(10)
             || '                )  IA' || CHR(10)
             || '          GROUP BY ' || V_USER_COLS || CHR(10)
             || '                 , KEY_IDX' || CHR(10)
             || '       )  WA' || CHR(10)
             || '     , ( SELECT KEY_IDX'));
            DBMS_LOB.APPEND(V_SQL, V_ACC_MONTH_COLS);
            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                CHR(10) || '           FROM ( SELECT ' || V_USER_COLS || CHR(10)
             || '                       , KEY_IDX' || CHR(10)
             || '                       , YYYYMM' || CHR(10)
             || '                       , SUM(QTY) OVER (PARTITION BY KEY_IDX ORDER BY YYYYMM)  AS ACC_QTY' || CHR(10)
             || '                    FROM GT_0017_GAP_MONTH' || CHR(10)
             || '                )  IA' || CHR(10)
             || '          GROUP BY ' || V_USER_COLS || CHR(10)
             || '                 , KEY_IDX' || CHR(10)
             || '       )  MA' || CHR(10)
             || ' WHERE DA.KEY_IDX = WA.KEY_IDX(+)' || CHR(10)
             || '   AND DA.KEY_IDX = MA.KEY_IDX(+)'));

        END IF;

        DBMS_LOB.APPEND(V_SQL, TO_CLOB(
            CHR(10) || ')' || CHR(10)
         || ' ORDER BY ' || FN_ORDER_EXPR(V_USER_COLS_ORDER)));

        OPEN O_RC1 FOR V_SQL;

        DBMS_LOB.FREETEMPORARY(V_PIVOT_COLS);
        DBMS_LOB.FREETEMPORARY(V_ACC_SEL_COLS);
        DBMS_LOB.FREETEMPORARY(V_SUM_COLS);
        DBMS_LOB.FREETEMPORARY(V_ACC_DAY_COLS);
        DBMS_LOB.FREETEMPORARY(V_ACC_WEEK_COLS);
        DBMS_LOB.FREETEMPORARY(V_ACC_MONTH_COLS);

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;

            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR SELECT NULL AS DIVISION_ID FROM DUAL WHERE 1 = 0;
            END IF;

            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SCP0017_GET_PRODUCTION_PLAN_MODEL_WATERFALL;


    /*******************************************************************************
     * P_SCP0017_GET_PRODUCTION_PLAN_LINE_WATERFALL
     *   AS-IS SCP0017_GET_PRODUCTION_PLAN_LINE_WATERFALL
     *   모델 화면에서 라인 상세를 펼칠 때 쓴다.
     *   조회 기간에 따라 칸 개수가 달라지는 마지막 피벗만 동적으로 둔다.
     *******************************************************************************/
    PROCEDURE P_SCP0017_GET_PRODUCTION_PLAN_LINE_WATERFALL
    (
        P_DIVISION_ID           IN  VARCHAR2
      , P_OPERATION_GROUP       IN  VARCHAR2
      , P_SCM_SITE_ID           IN  VARCHAR2
      , P_ITEM_ID               IN  VARCHAR2
      , P_FROM_YYYYMMDD         IN  VARCHAR2
      , P_TO_YYYYMMDD           IN  VARCHAR2
      , P_VERSION_NO            IN  VARCHAR2
      , P_PROGRAM_ID            IN  VARCHAR2
      , P_SHEET_NAME            IN  VARCHAR2
      , P_USER_ID               IN  VARCHAR2
      , P_ELECTRODE_TYPE        IN  VARCHAR2
      , DEBUG_MODE              IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS

        V_CNT_USR_MEASURE       PLS_INTEGER := 0;
        V_QRY_SUM               CLOB;
        V_SQL                   CLOB;
        V_ERR_MSG               VARCHAR2(4000);

    BEGIN

        DBMS_LOB.CREATETEMPORARY(V_QRY_SUM, TRUE);
        DBMS_LOB.CREATETEMPORARY(V_SQL,     TRUE);

        DELETE FROM GT_0017_LINE;

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE 1 = 1
           AND PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID    = P_USER_ID;

        /*==========================================================================
         * 데이타조회, 임시테이블에 저장
         *========================================================================*/
        INSERT INTO GT_0017_LINE
        (
            DIVISION_ID
          , OPERATION_GROUP
          , SCM_SITE_ID
          , LINE_ID
          , ITEM_ID
          , MEASURE
          , MEASURE_NAME
          , USER_SORT_ORDER_NO
          , OPERATION_ID
          , FROM_YYYYMMDD
          , VERSION_NO
          , YYYYMMDD
          , YYYYMM
          , ISO_WEEK
          , QTY
          , DIVISION_NAME
          , OPERATION_GROUP_NAME
          , SCM_SITE_DESCRIPTION
          , NICK_NAME
          , ORIGIN_DIVISION_ID
          , ELECTRODE_TYPE
        )
        SELECT M.DIVISION_ID
             , M.OPERATION_GROUP
             , M.SCM_SITE_ID
             , M.LINE_ID
             , M.ITEM_ID
             , M.MEASURE
             , M.MEASURE_NAME
             , M.USER_SORT_ORDER_NO
             , M.OPERATION_ID
             , P_FROM_YYYYMMDD                              AS FROM_YYYYMMDD
             , P_VERSION_NO                                 AS VERSION_NO
             , 'D_' || M.YYYYMMDD                           AS YYYYMMDD
             , O.BASIS_YYYYMM                               AS YYYYMM
             , SUBSTR(O.BASIS_YYYYMM, -4) || O.ISO_WEEK     AS ISO_WEEK
             , N.QTY
             , M.DIVISION_NAME
             , M.OPERATION_GROUP_NAME
             , M.SCM_SITE_DESCRIPTION
             , CASE WHEN M.NICK_NAME IS NULL OR M.NICK_NAME = ' ' THEN '-'
                    ELSE M.NICK_NAME END                    AS NICK_NAME
             , M.ORIGIN_DIVISION_ID
             , M.ELECTRODE_TYPE
          FROM ( SELECT C.DIVISION_ID
                      , C.VERSION_NO
                      , C.OPERATION_GROUP
                      , C.SCM_SITE_ID
                      , C.ITEM_ID
                      , C.LINE_ID
                      , C.OPERATION_ID
                      , A.COLUMN_NAME                           AS MEASURE
                      , A.COLUMN_LABEL_NAME                     AS MEASURE_NAME
                      , NVL(B.SORT_ORDER_NO, A.SORT_ORDER_NO)   AS USER_SORT_ORDER_NO
                      , C.YYYYMMDD
                      , C.DIVISION_NAME
                      , C.OPERATION_GROUP_NAME
                      , C.SCM_SITE_DESCRIPTION
                      , C.NICK_NAME
                      , CASE WHEN TRIM(C.ORIGIN_DIVISION_ID) IS NULL THEN '-'
                             ELSE C.ORIGIN_DIVISION_ID END       AS ORIGIN_DIVISION_ID
                      , CASE WHEN TRIM(C.ELECTRODE_TYPE) IS NULL THEN '-'
                             ELSE C.ELECTRODE_TYPE END           AS ELECTRODE_TYPE
                   FROM SCM_MST_SHEET_MEASURE   A
                      , SCM_MST_TITLESET_USER   B
                      , ( SELECT DIVISION_ID
                               , VERSION_NO
                               , OPERATION_GROUP
                               , SCM_SITE_ID
                               , ITEM_ID
                               , LINE_ID
                               , OPERATION_ID
                               , MEASURE
                               , YYYYMMDD
                               , DIVISION_NAME
                               , OPERATION_GROUP_NAME
                               , SCM_SITE_DESCRIPTION
                               , NICK_NAME
                               , ORIGIN_DIVISION_ID
                               , ELECTRODE_TYPE
                            FROM SCP_ANL_PRODUCTION_PLAN_C
                           WHERE 1 = 1
                             AND YYYYMMDD        >= P_FROM_YYYYMMDD
                             AND YYYYMMDD        <= P_TO_YYYYMMDD
                             AND DIVISION_ID      = P_DIVISION_ID
                             AND OPERATION_GROUP  = P_OPERATION_GROUP
                             AND SCM_SITE_ID      = P_SCM_SITE_ID
                             AND ITEM_ID          = P_ITEM_ID
                             AND VERSION_NO       = P_VERSION_NO
                             AND ( TRIM(P_ELECTRODE_TYPE) IS NULL
                                   OR P_ELECTRODE_TYPE = '-'
                                   OR ELECTRODE_TYPE = P_ELECTRODE_TYPE )
                           GROUP BY DIVISION_ID
                                  , VERSION_NO
                                  , OPERATION_GROUP
                                  , SCM_SITE_ID
                                  , ITEM_ID
                                  , LINE_ID
                                  , OPERATION_ID
                                  , MEASURE
                                  , YYYYMMDD
                                  , DIVISION_NAME
                                  , OPERATION_GROUP_NAME
                                  , SCM_SITE_DESCRIPTION
                                  , NICK_NAME
                                  , ORIGIN_DIVISION_ID
                                  , ELECTRODE_TYPE
                        )  C
                  WHERE B.PROGRAM_ID(+)  = A.PROGRAM_ID
                    AND B.SHEET_NAME(+)  = A.SHEET_NAME
                    AND B.COLUMN_NAME(+) = A.COLUMN_NAME
                    AND B.USER_ID(+)     = P_USER_ID
                    AND A.PROGRAM_ID     = P_PROGRAM_ID
                    AND A.SHEET_NAME     = P_SHEET_NAME
                    AND A.VALID_YN       = 'Y'
                    AND ( V_CNT_USR_MEASURE = 0
                          OR EXISTS (SELECT 1
                                       FROM SCM_MST_TITLESET_USER
                                      WHERE PROGRAM_ID  = P_PROGRAM_ID
                                        AND SHEET_NAME  = P_SHEET_NAME
                                        AND USER_ID     = P_USER_ID
                                        AND COLUMN_NAME = A.COLUMN_NAME) )
                  GROUP BY C.DIVISION_ID
                         , C.VERSION_NO
                         , C.OPERATION_GROUP
                         , C.SCM_SITE_ID
                         , C.ITEM_ID
                         , C.LINE_ID
                         , C.OPERATION_ID
                         , A.COLUMN_NAME
                         , A.COLUMN_LABEL_NAME
                         , C.YYYYMMDD
                         , NVL(B.SORT_ORDER_NO, A.SORT_ORDER_NO)
                         , C.DIVISION_NAME
                         , C.OPERATION_GROUP_NAME
                         , C.SCM_SITE_DESCRIPTION
                         , C.NICK_NAME
                         , C.ORIGIN_DIVISION_ID
                         , C.ELECTRODE_TYPE
               )  M
             , ( /* 계획 */
                 SELECT A.DIVISION_ID
                      , A.OPERATION_GROUP
                      , A.SCM_SITE_ID
                      , A.ITEM_ID
                      , A.OPERATION_ID
                      , A.LINE_ID
                      , A.MEASURE
                      , A.YYYYMMDD
                      , CASE WHEN TRIM(A.ORIGIN_DIVISION_ID) IS NULL THEN '-'
                             ELSE A.ORIGIN_DIVISION_ID END  AS ORIGIN_DIVISION_ID
                      , CASE WHEN TRIM(A.ELECTRODE_TYPE) IS NULL THEN '-'
                             ELSE A.ELECTRODE_TYPE END      AS ELECTRODE_TYPE
                      , A.QTY
                   FROM SCP_ANL_PRODUCTION_PLAN_C A
                  WHERE 1 = 1
                    AND A.YYYYMMDD        >= P_FROM_YYYYMMDD
                    AND A.YYYYMMDD        <= P_TO_YYYYMMDD
                    AND A.DIVISION_ID      = P_DIVISION_ID
                    AND A.OPERATION_GROUP  = P_OPERATION_GROUP
                    AND A.SCM_SITE_ID      = P_SCM_SITE_ID
                    AND A.ITEM_ID          = P_ITEM_ID
                    AND A.VERSION_NO       = P_VERSION_NO
                    AND ( TRIM(P_ELECTRODE_TYPE) IS NULL
                          OR P_ELECTRODE_TYPE = '-'
                          OR A.ELECTRODE_TYPE = P_ELECTRODE_TYPE )
               )  N
             , SCM_SYS_CALENDAR_M O
         WHERE M.DIVISION_ID        = N.DIVISION_ID(+)
           AND M.OPERATION_GROUP    = N.OPERATION_GROUP(+)
           AND M.SCM_SITE_ID        = N.SCM_SITE_ID(+)
           AND M.ITEM_ID            = N.ITEM_ID(+)
           AND M.OPERATION_ID       = N.OPERATION_ID(+)
           AND M.LINE_ID            = N.LINE_ID(+)
           AND M.MEASURE            = N.MEASURE(+)
           AND M.YYYYMMDD           = N.YYYYMMDD(+)
           AND M.ORIGIN_DIVISION_ID = N.ORIGIN_DIVISION_ID(+)
           AND M.ELECTRODE_TYPE     = N.ELECTRODE_TYPE(+)
           AND M.YYYYMMDD           = O.BASIS_YYYYMMDD
           /* 조회조건 추가부분 (Model Tab에서만 사용하는 REQUIREMENT , FORMATION_YIELD Measure는 *로 입력되어 Line조회시 제외함) */
           AND M.LINE_ID IS NOT NULL
           AND M.LINE_ID <> '*';

        /*==========================================================================
         * PIVOIT처리 - PIVOIT 대상 날짜문자열 생성
         *========================================================================*/
        FOR R IN ( SELECT YYYYMMDD
                     FROM ( SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK      AS YYYYMMDD
                                 , A.BASIS_START_DATE || '21'                AS SORT_ORDER_NO
                                 , 1                                         AS BLK
                              FROM SCM_SYS_CALENDAR_M A
                             WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY A.BASIS_YYYYMM
                                    , A.ISO_WEEK
                                    , A.BASIS_START_DATE
                             UNION ALL
                            SELECT 'M_' || A.BASIS_YYYYMM                    AS YYYYMMDD
                                 , MIN(A.BASIS_START_DATE) || '01'           AS SORT_ORDER_NO
                                 , 2                                         AS BLK
                              FROM SCM_SYS_CALENDAR_M A
                             WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY A.BASIS_YYYYMM
                                    , A.MONTH_NAME
                             UNION ALL
                            SELECT 'D_' || A.BASIS_YYYYMMDD                  AS YYYYMMDD
                                 , A.BASIS_YYYYMMDD || '31'                  AS SORT_ORDER_NO
                                 , 3                                         AS BLK
                              FROM SCM_SYS_CALENDAR_M A
                             WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY A.BASIS_YYYYMMDD
                          )  A
                    ORDER BY SORT_ORDER_NO
                           , BLK
                 )
        LOOP

            IF SUBSTR(R.YYYYMMDD, 1, 2) = 'M_' THEN
                DBMS_LOB.APPEND(V_QRY_SUM, TO_CLOB(CHR(10) || '     , SUM(CASE WHEN YYYYMM = SUBSTR(''' || R.YYYYMMDD || ''', -6) THEN QTY END)  AS ' || R.YYYYMMDD));
            ELSIF SUBSTR(R.YYYYMMDD, 1, 2) = 'W_' THEN
                DBMS_LOB.APPEND(V_QRY_SUM, TO_CLOB(CHR(10) || '     , SUM(CASE WHEN ISO_WEEK = SUBSTR(''' || R.YYYYMMDD || ''', -6) THEN QTY END)  AS ' || R.YYYYMMDD));
            ELSE
                DBMS_LOB.APPEND(V_QRY_SUM, TO_CLOB(CHR(10) || '     , SUM(CASE WHEN YYYYMMDD = ''' || R.YYYYMMDD || ''' THEN QTY END)  AS ' || R.YYYYMMDD));
            END IF;

        END LOOP;

        DBMS_LOB.APPEND(V_SQL, TO_CLOB(
            'SELECT DIVISION_ID' || CHR(10)
         || '     , DIVISION_NAME' || CHR(10)
         || '     , OPERATION_GROUP' || CHR(10)
         || '     , OPERATION_GROUP_NAME' || CHR(10)
         || '     , SCM_SITE_ID' || CHR(10)
         || '     , SCM_SITE_DESCRIPTION' || CHR(10)
         || '     , LINE_ID' || CHR(10)
         || '     , ITEM_ID' || CHR(10)
         || '     , NICK_NAME' || CHR(10)
         || '     , MEASURE' || CHR(10)
         || '     , MEASURE_NAME' || CHR(10)
         || '     , OPERATION_ID' || CHR(10)
         || '     , VERSION_NO' || CHR(10)
         || '     , FROM_YYYYMMDD' || CHR(10)
         || '     , USER_SORT_ORDER_NO' || CHR(10)
         || '     , ORIGIN_DIVISION_ID' || CHR(10)
         || '     , ELECTRODE_TYPE'));
        DBMS_LOB.APPEND(V_SQL, V_QRY_SUM);
        DBMS_LOB.APPEND(V_SQL, TO_CLOB(
            CHR(10) || '  FROM GT_0017_LINE' || CHR(10)
         || ' GROUP BY DIVISION_ID' || CHR(10)
         || '        , DIVISION_NAME' || CHR(10)
         || '        , OPERATION_GROUP' || CHR(10)
         || '        , OPERATION_GROUP_NAME' || CHR(10)
         || '        , SCM_SITE_ID' || CHR(10)
         || '        , SCM_SITE_DESCRIPTION' || CHR(10)
         || '        , LINE_ID' || CHR(10)
         || '        , ITEM_ID' || CHR(10)
         || '        , NICK_NAME' || CHR(10)
         || '        , MEASURE' || CHR(10)
         || '        , MEASURE_NAME' || CHR(10)
         || '        , OPERATION_ID' || CHR(10)
         || '        , VERSION_NO' || CHR(10)
         || '        , FROM_YYYYMMDD' || CHR(10)
         || '        , USER_SORT_ORDER_NO' || CHR(10)
         || '        , ORIGIN_DIVISION_ID' || CHR(10)
         || '        , ELECTRODE_TYPE' || CHR(10)
         || ' ORDER BY ' || FN_ORDER_EXPR('DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, LINE_ID, ITEM_ID, USER_SORT_ORDER_NO')));

        OPEN O_RC1 FOR V_SQL;

        DBMS_LOB.FREETEMPORARY(V_QRY_SUM);

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;

            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR SELECT NULL AS DIVISION_ID FROM DUAL WHERE 1 = 0;
            END IF;

            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SCP0017_GET_PRODUCTION_PLAN_LINE_WATERFALL;

END PKG_SCP0017;

SCM_MGR|PACKAGE BODY|PKG_SCP0033:
PACKAGE BODY PKG_SCP0033
IS
    /*
     * Program ID   : PKG_SCP0033
     * Description  : SCP0033 Shipment Semi Dept Day 화면 — 조회 · 저장
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2026.09.27   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
     */

/****************************************************************************************************/
/* Program ID  : P_SCP0033_GET_SHIPMENT_SEMI_DEPT_DAY                                               */
/* Description : Shipment Semi Dept Day 조회                                                        */
/****************************************************************************************************/
PROCEDURE P_SCP0033_GET_SHIPMENT_SEMI_DEPT_DAY
(
    P_DIVISION_ID       IN  CLOB
  , P_ITEM_ID           IN  CLOB
  , P_VALID             IN  CLOB
  , O_RC1               OUT SYS_REFCURSOR
  , O_RC2               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS

    V_DIVISION_ID       VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_DIVISION_ID, 1, 4000));
    V_ITEM_ID           VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_ITEM_ID,     1, 4000));
    V_VALID             VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_VALID,       1, 4000));

BEGIN

    OPEN O_RC1 FOR
        SELECT A.DIVISION_ID
             /* , CASE WHEN A.DIVISION_ID IN ('EE','EE_UC') THEN 'E' */
             , CASE WHEN A.DIVISION_ID IN (SELECT COLUMN_VALUE
                                             FROM TABLE(FN_GET_DIVISION_DIV('EE'))) THEN 'E'   /* div_commonization */
                    ELSE (SELECT B.SCP_OPERATION_GROUP   /* 원문 ISNULL(x,'') 은 Oracle 에서 뜻이 없다 */
                            FROM SCM_MST_ITEM_SN B
                           WHERE B.DIVISION_ID = A.DIVISION_ID
                             AND B.ITEM_ID     = A.ITEM_ID
                             AND ROWNUM        = 1)
               END                                                  AS OPERATION_GROUP
             , A.ITEM_ID
             , (SELECT NVL(XA.NICK_NAME, '-')
                  FROM SCM_MST_ITEM_SN XA
                 WHERE XA.ITEM_ID = A.ITEM_ID
                   AND ROWNUM     = 1)                              AS NICK_NAME
             , A.DEPARTURE_DAY
             , A.VALID_YN
             /* 원문 칸 이름은 S_VALUE_YN 이나 화면이 S_VALID_YN 으로 읽는다 — 화면 이름에 맞춘다 */
             , A.VALID_YN                                           AS S_VALID_YN
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
          FROM SCP_MST_SHIPMENT_SEMI_DEPT_DAY A
         WHERE (TRIM(V_DIVISION_ID) IS NULL
            OR  UPPER(V_DIVISION_ID) = 'ALL'                        /* 조회조건 ALL 은 조건 없음 */
            OR  A.DIVISION_ID IN (SELECT UPPER(COLUMN_VALUE)
                                    FROM TABLE(STRING_SPLIT(V_DIVISION_ID, ','))))
           AND (TRIM(V_ITEM_ID) IS NULL
            OR  UPPER(V_ITEM_ID) = 'ALL'                            /* 조회조건 ALL 은 조건 없음 */
            OR  A.ITEM_ID LIKE UPPER(V_ITEM_ID) || '%')
           AND (TRIM(V_VALID) IS NULL
            OR  UPPER(V_VALID) = 'ALL'                              /* 조회조건 ALL 은 조건 없음 */
            OR  A.VALID_YN = UPPER(V_VALID))
         ORDER BY FN_ASIS_SORT_KEY(A.DIVISION_ID) NULLS FIRST
                , FN_ASIS_SORT_KEY(A.ITEM_ID) NULLS FIRST;

    /* validation용 전체조회 */
    OPEN O_RC2 FOR
        SELECT DIVISION_ID
             , ITEM_ID
          FROM SCP_MST_SHIPMENT_SEMI_DEPT_DAY;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

END P_SCP0033_GET_SHIPMENT_SEMI_DEPT_DAY;

/****************************************************************************************************/
/* Program ID  : P_SCP0033_SAVE_SHIPMENT_SEMI_DEPT_DAY                                              */
/* Description : Shipment Semi Dept Day 저장                                                        */
/****************************************************************************************************/
PROCEDURE P_SCP0033_SAVE_SHIPMENT_SEMI_DEPT_DAY
(
    P_ACTIVE_FLAG       IN  CLOB
  , P_DIVISION_ID       IN  CLOB
  , P_ITEM_ID           IN  CLOB
  , P_DEPARTURE_DAY     IN  CLOB
  , P_VALID_YN          IN  CLOB
  , P_S_VALID_YN        IN  CLOB
  , P_USER_ID           IN  CLOB
  , P_CREATED_BY        IN  CLOB
  , P_CREATION_DATE     IN  CLOB
  , P_DEBUG_MODE        IN  CLOB
  , O_RC1               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS

    C_DELIMITER         CONSTANT VARCHAR2(1 CHAR) := '^';

    V_ACTIVE_FLAG       VARCHAR2(4000 CHAR);
    V_DIVISION_ID       VARCHAR2(4000 CHAR);
    V_ITEM_ID           VARCHAR2(4000 CHAR);
    V_DEPARTURE_DAY     VARCHAR2(4000 CHAR);
    V_VALID_YN          VARCHAR2(4000 CHAR);
    V_S_VALID_YN        VARCHAR2(4000 CHAR);
    V_CREATED_BY        VARCHAR2(4000 CHAR);
    V_CREATION_DATE     VARCHAR2(4000 CHAR);
    V_LAST_UPDATED_BY   VARCHAR2(4000 CHAR);

    N_MAX_LOOP_CNT      NUMBER(10) := 0;
    N_MST_LOOP_CNT      NUMBER(10) := 0;

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0033_SAVE_SHIPMENT_SEMI_DEPT_DAY';
    V_LOG_TYPE          VARCHAR2(30 CHAR);      /* START/END/ERROR/... */
    N_LOG_COUNT         NUMBER(10) := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;

    V_SQLCODE           NUMBER;
    V_SQLERRM           VARCHAR2(4000 CHAR);

BEGIN

    SAVEPOINT SP_SCP0033_SAVE;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;

    PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* 프로시저 LOOP 길이를 판단 */
    N_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, C_DELIMITER);

    WHILE N_MST_LOOP_CNT < N_MAX_LOOP_CNT
    LOOP

        /* @mst_loop_cnt 1증가 */
        N_MST_LOOP_CNT := N_MST_LOOP_CNT + 1;

        /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
        V_ACTIVE_FLAG     := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,   C_DELIMITER, N_MST_LOOP_CNT);
        V_DIVISION_ID     := SCM_ARR_SPL_VAL(P_DIVISION_ID,   C_DELIMITER, N_MST_LOOP_CNT);
        V_ITEM_ID         := SCM_ARR_SPL_VAL(P_ITEM_ID,       C_DELIMITER, N_MST_LOOP_CNT);
        V_DEPARTURE_DAY   := SCM_ARR_SPL_VAL(P_DEPARTURE_DAY, C_DELIMITER, N_MST_LOOP_CNT);
        V_VALID_YN        := SCM_ARR_SPL_VAL(P_VALID_YN,      C_DELIMITER, N_MST_LOOP_CNT);
        V_S_VALID_YN      := SCM_ARR_SPL_VAL(P_S_VALID_YN,    C_DELIMITER, N_MST_LOOP_CNT);
        V_CREATED_BY      := SCM_ARR_SPL_VAL(P_CREATED_BY,    C_DELIMITER, N_MST_LOOP_CNT);
        V_CREATION_DATE   := SCM_ARR_SPL_VAL(P_CREATION_DATE, C_DELIMITER, N_MST_LOOP_CNT);
        V_LAST_UPDATED_BY := TO_CHAR(P_USER_ID);

        /* 이력저장 */
        PR_SCP_MST_SHIPMENT_SEMI_DEPT_DAY_HIST(V_DIVISION_ID, V_ITEM_ID, V_DEPARTURE_DAY, V_S_VALID_YN
                                             , V_CREATED_BY, V_CREATION_DATE, V_LAST_UPDATED_BY);

        /* 데이터 저장 */
        IF N_MST_LOOP_CNT > 0
        THEN

            /* SCP_MST_SHIPMENT_SEMI_DEPT_DAY 입력/수정 */
            IF V_ACTIVE_FLAG = 'M'
            THEN

                UPDATE SCP_MST_SHIPMENT_SEMI_DEPT_DAY
                   SET VALID_YN         = V_VALID_YN
                     , DEPARTURE_DAY    = V_DEPARTURE_DAY
                     , LAST_UPDATED_BY  = V_LAST_UPDATED_BY
                     , LAST_UPDATE_DATE = SYSDATE
                 WHERE DIVISION_ID = V_DIVISION_ID
                   AND ITEM_ID     = V_ITEM_ID;

            ELSIF V_ACTIVE_FLAG = 'I'
            THEN

                INSERT INTO SCP_MST_SHIPMENT_SEMI_DEPT_DAY
                            ( DIVISION_ID
                            , ITEM_ID
                            , DEPARTURE_DAY
                            , VALID_YN
                            , CREATED_BY
                            , CREATION_DATE
                            , LAST_UPDATED_BY
                            , LAST_UPDATE_DATE )
                     VALUES ( V_DIVISION_ID
                            , V_ITEM_ID
                            , V_DEPARTURE_DAY
                            , V_VALID_YN
                            , V_CREATED_BY
                            , SYSDATE
                            , V_CREATED_BY
                            , SYSDATE );

            END IF;

        END IF;   /* END OF STMT. IF( @mst_loop_cnt > 0 ) */

    END LOOP;     /* END OF STMT. WHILE LEN(@recv_active_flag) > 0 AND @mst_loop_cnt < @max_loop_cnt */

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;

    PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;

    /* 결과코드, 결과 카운트 반환 */
    OPEN O_RC1 FOR
        SELECT 'S'              AS RESULT_CODE
             , N_MAX_LOOP_CNT   AS RESULT_CNT
          FROM DUAL;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

EXCEPTION
    WHEN OTHERS
    THEN

        V_SQLCODE := SQLCODE;
        V_SQLERRM := SQLERRM;

        ROLLBACK TO SP_SCP0033_SAVE;    /* 입력 데이타 롤백 처리 */

        INSERT INTO SCM_SYS_LOG_BATCH
                    ( PROGRAM_NAME
                    , LOG_TYPE
                    , LOG_COUNT
                    , LOG_MESSAGE
                    , DESCRIPTION
                    , EVENT_DATE
                    , CREATION_DATE
                    , CREATED_BY
                    , LAST_UPDATE_DATE
                    , LAST_UPDATED_BY )
             VALUES ( V_PROGRAM_NAME
                    , 'ERROR'
                    , NULL
                    , V_SQLERRM
                    , NULL
                    , SYSDATE
                    , SYSDATE
                    , V_PROGRAM_NAME
                    , SYSDATE
                    , V_PROGRAM_NAME );

        COMMIT;

        /* error코드, errror 메시지 반환 */
        OPEN O_RC1 FOR
            SELECT 'F'  AS RESULT_CODE
              FROM DUAL;

        OPEN O_RESULT_CURSOR FOR
            SELECT '[' || TO_CHAR(V_SQLCODE) || ']' || V_SQLERRM    AS ERR_MESSAGE
              FROM DUAL;

END P_SCP0033_SAVE_SHIPMENT_SEMI_DEPT_DAY;

END PKG_SCP0033;

SCM_MGR|PACKAGE BODY|PKG_SCP0037:
PACKAGE BODY PKG_SCP0037
IS
    /*
     * Program ID   : PKG_SCP0037
     * Description  : SCP0037 Operation LT 화면 — 공정 리드타임 조회 · 저장
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2026.09.27   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
     */

/****************************************************************************************************/
/* Program ID  : P_SCP0037_GET_OPERATION_LT                                                         */
/* Description : Operation LT 조회                                                                  */
/****************************************************************************************************/
PROCEDURE P_SCP0037_GET_OPERATION_LT
(
    P_DIVISION_ID       IN  CLOB
  , P_SCM_SITE_ID       IN  CLOB
  , P_ITEM_ID           IN  CLOB
  , P_SCM_VALID_YN      IN  CLOB
  , P_LT_OPERATION      IN  CLOB
  , O_RC1               OUT SYS_REFCURSOR
  , O_RC2               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
    V_DIVISION_ID       VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_DIVISION_ID,   1, 4000));
    V_SCM_SITE_ID       VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_SCM_SITE_ID,   1, 4000));
    V_ITEM_ID           VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_ITEM_ID,       1, 4000));
    V_SCM_VALID_YN      VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_SCM_VALID_YN,  1, 4000));
    V_LT_OPERATION      VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_LT_OPERATION,  1, 4000));
BEGIN

    OPEN O_RC1 FOR
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID                                        AS PLANT_SITE_ID
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , IA.NICK_NAME
             , A.LT_OPERATION
             , B.SEGMENT2                                           AS LT_OPERATION_NM
             , A.LT_DAY
             /* ★원문은 사이트 품목의 사용여부를 한 행만 골라 쓰고 차례를 정하지 않았다.
                   가장 작은 값 · 프로젝트 순으로 맞춰 보았으나 어느 것도 AS-IS 와 같지 않아
                   원문처럼 차례를 정하지 않고 둔다 (재현 대상 아님) */
             , (SELECT XA.VALID_YN
                  FROM SCM_MST_SITE_ITEM XA
                 WHERE XA.DIVISION_ID = A.DIVISION_ID
                   AND XA.SCM_SITE_ID = A.SCM_SITE_ID
                   AND XA.ITEM_ID     = A.ITEM_ID
                   AND ROWNUM         = 1)                          AS SITE_ITEM_VALID_YN
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
             , NVL(A.ATTRIBUTE1, 'N')                               AS INV_FLAG
          FROM SCP_MST_OPERATION_LT          A
             , SCM_ADM_LOOKUP_MASTER_DETAIL  B
             , (SELECT XB.ITEM_ID
                     , MAX(XB.NICK_NAME)                            AS NICK_NAME
                  FROM SCM_MST_ITEM_SN XB
                 GROUP BY XB.ITEM_ID) IA
         WHERE B.LOOKUP_TYPE  = 'OPERATION_LT'
           AND B.VALID_YN     = 'Y'
           AND B.SEGMENT1     = A.LT_OPERATION
           AND IA.ITEM_ID     = A.ITEM_ID
           AND (TRIM(V_DIVISION_ID) IS NULL
            OR  UPPER(V_DIVISION_ID) = 'ALL'                        /* 조회조건 ALL 은 조건 없음 */
            OR  A.DIVISION_ID IN (SELECT UPPER(COLUMN_VALUE)
                                    FROM TABLE(STRING_SPLIT(V_DIVISION_ID, ','))))
           AND (TRIM(V_SCM_SITE_ID) IS NULL
            OR  UPPER(V_SCM_SITE_ID) = 'ALL'                        /* 조회조건 ALL 은 조건 없음 */
            OR  UPPER(A.SCM_SITE_ID) IN (SELECT UPPER(COLUMN_VALUE)
                                           FROM TABLE(STRING_SPLIT(V_SCM_SITE_ID, ','))))
           AND (TRIM(V_LT_OPERATION) IS NULL
            OR  UPPER(V_LT_OPERATION) = 'ALL'                       /* 조회조건 ALL 은 조건 없음 */
            OR  A.LT_OPERATION IN (SELECT UPPER(COLUMN_VALUE)
                                     FROM TABLE(STRING_SPLIT(V_LT_OPERATION, ','))))
           /* ★품목은 목록에 있거나 별칭이 그 값으로 시작하면 통과한다(원문과 같다) */
           AND (TRIM(V_ITEM_ID) IS NULL
            OR  UPPER(V_ITEM_ID) = 'ALL'                            /* 조회조건 ALL 은 조건 없음 */
            OR  A.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE)
                                FROM TABLE(STRING_SPLIT(V_ITEM_ID, ',')))
            OR  EXISTS (SELECT 1
                          FROM TABLE(STRING_SPLIT(V_ITEM_ID, ',')) XC
                         WHERE IA.NICK_NAME LIKE UPPER(XC.COLUMN_VALUE) || '%'))
           AND (TRIM(V_SCM_VALID_YN) IS NULL
            OR  UPPER(V_SCM_VALID_YN) = 'ALL'                       /* 조회조건 ALL 은 조건 없음 */
            OR  (SELECT XD.VALID_YN
                   FROM SCM_MST_SITE_ITEM XD
                  WHERE XD.DIVISION_ID = A.DIVISION_ID
                    AND XD.SCM_SITE_ID = A.SCM_SITE_ID
                    AND XD.ITEM_ID     = A.ITEM_ID
                    AND ROWNUM         = 1) = V_SCM_VALID_YN)
         /* 원문에 정렬이 없어 화면 순서가 흔들린다 — 원장 열쇠 순서와 같게 고정 */
         ORDER BY FN_ASIS_SORT_KEY(A.DIVISION_ID)  NULLS FIRST
                , FN_ASIS_SORT_KEY(A.SCM_SITE_ID)  NULLS FIRST
                , FN_ASIS_SORT_KEY(A.ITEM_ID)      NULLS FIRST
                , FN_ASIS_SORT_KEY(A.LT_OPERATION) NULLS FIRST;

    /* validation용 전체조회 */
    OPEN O_RC2 FOR
        SELECT DIVISION_ID
             , SCM_SITE_ID
             , ITEM_ID
             , LT_OPERATION
             , '-'                                                  AS ACTION_FLAG_DIV
          FROM SCP_MST_OPERATION_LT
         /* 원문에 정렬이 없어 화면 순서가 흔들린다 — 원장 열쇠 순서와 같게 고정 */
         ORDER BY FN_ASIS_SORT_KEY(DIVISION_ID)  NULLS FIRST
                , FN_ASIS_SORT_KEY(SCM_SITE_ID)  NULLS FIRST
                , FN_ASIS_SORT_KEY(ITEM_ID)      NULLS FIRST
                , FN_ASIS_SORT_KEY(LT_OPERATION) NULLS FIRST;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

END P_SCP0037_GET_OPERATION_LT;

/****************************************************************************************************/
/* Program ID  : P_SCP0037_SAVE_OPERATION_LT                                                        */
/* Description : Operation LT 등록 · 수정                                                           */
/****************************************************************************************************/
PROCEDURE P_SCP0037_SAVE_OPERATION_LT
(
    P_ACTIVE_FLAG       IN  CLOB
  , P_DIVISION_ID       IN  CLOB
  , P_SCM_SITE_ID       IN  CLOB
  , P_ITEM_ID           IN  CLOB
  , P_LT_OPERATION      IN  CLOB
  , P_LT_DAY            IN  CLOB
  , P_CREATED_BY        IN  CLOB
  , P_CREATION_DATE     IN  CLOB
  , P_LAST_UPDATED_BY   IN  CLOB
  , P_INV_FLAG          IN  CLOB
  , O_RC1               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
    C_DELIMITER         CONSTANT VARCHAR2(1 CHAR) := '^';

    V_ACTIVE_FLAG       VARCHAR2(4000 CHAR);
    V_DIVISION_ID       VARCHAR2(4000 CHAR);
    V_SCM_SITE_ID       VARCHAR2(4000 CHAR);
    V_ITEM_ID           VARCHAR2(4000 CHAR);
    V_LT_OPERATION      VARCHAR2(4000 CHAR);
    V_LT_DAY            VARCHAR2(4000 CHAR);
    V_CREATED_BY        VARCHAR2(4000 CHAR);
    V_CREATION_DATE     VARCHAR2(4000 CHAR);
    V_LAST_UPDATED_BY   VARCHAR2(4000 CHAR);
    V_INV_FLAG          VARCHAR2(4000 CHAR);

    /* 값 없음 대체 표시 — 원문이 값 없음을 빈 문자로 다룬다 */
    V_INV_FLAG_SAVE     VARCHAR2(4000 CHAR);

    V_MAX_LOOP_CNT      NUMBER(10) := 0;
    V_MST_LOOP_CNT      NUMBER(10) := 0;
    V_DATA_NO_CNT       NUMBER(10) := 0;
    V_DATA_NO_MSG       VARCHAR2(4000 CHAR);

    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0037_SAVE_OPERATION_LT';
    V_LOG_TYPE          VARCHAR2(30 CHAR);
    N_LOG_COUNT         NUMBER(10) := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    V_SQLERRM           VARCHAR2(4000 CHAR);
    V_SQLCODE           NUMBER;
BEGIN

    /* 시작 시 임시 자료를 비운다 (TRUNCATE 는 암묵 커밋이라 쓰지 않는다) */
    DELETE FROM GT_SCP0037_CHK;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, C_DELIMITER);

    /* 1. Validation 체크(Project Route) */
    WHILE LENGTH(P_ACTIVE_FLAG) > 0
      AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
    LOOP

        V_MST_LOOP_CNT  := V_MST_LOOP_CNT + 1;

        V_ACTIVE_FLAG   := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,  C_DELIMITER, V_MST_LOOP_CNT);
        V_DIVISION_ID   := SCM_ARR_SPL_VAL(P_DIVISION_ID,  C_DELIMITER, V_MST_LOOP_CNT);
        V_SCM_SITE_ID   := SCM_ARR_SPL_VAL(P_SCM_SITE_ID,  C_DELIMITER, V_MST_LOOP_CNT);
        V_ITEM_ID       := SCM_ARR_SPL_VAL(P_ITEM_ID,      C_DELIMITER, V_MST_LOOP_CNT);

        INSERT INTO GT_SCP0037_CHK
                    ( ACTIVE_FLAG, DIVISION_ID, PLANT_SITE_ID, ITEM_ID )
             VALUES ( V_ACTIVE_FLAG, V_DIVISION_ID, V_SCM_SITE_ID, V_ITEM_ID );

    END LOOP;

    IF V_MST_LOOP_CNT > 0
    THEN

        /* project route 체크 */
        V_DATA_NO_CNT := 0;
        V_DATA_NO_MSG := '';

        SELECT COUNT(*)
          INTO V_DATA_NO_CNT
          FROM GT_SCP0037_CHK A
         WHERE A.ACTIVE_FLAG = 'I'
           AND NOT EXISTS (SELECT 1
                             FROM SCM_MST_SITE_ITEM_PRIORITY B
                            WHERE B.DIVISION_ID   = A.DIVISION_ID
                              AND B.PLANT_SITE_ID = A.PLANT_SITE_ID
                              AND B.ITEM_ID       = A.ITEM_ID
                              AND B.VALID_YN      = 'Y');

        IF V_DATA_NO_CNT > 0
        THEN

            SELECT IA.NO_MSG
              INTO V_DATA_NO_MSG
              FROM (SELECT A.DIVISION_ID || '/' || A.PLANT_SITE_ID || '/' || A.ITEM_ID AS NO_MSG
                      FROM GT_SCP0037_CHK A
                     WHERE A.ACTIVE_FLAG = 'I'
                       AND NOT EXISTS (SELECT 1
                                         FROM SCM_MST_SITE_ITEM_PRIORITY B
                                        WHERE B.DIVISION_ID   = A.DIVISION_ID
                                          AND B.PLANT_SITE_ID = A.PLANT_SITE_ID
                                          AND B.ITEM_ID       = A.ITEM_ID
                                          AND B.VALID_YN      = 'Y')) IA
             WHERE ROWNUM = 1;

            /* ★원문은 검증 오류를 잡아 결과코드 'N' 과 그 문구를 돌려준다(그 밖 오류는 'F').
                  돌려주는 코드가 달라 여기서 바로 'N' 으로 끝낸다 */
            ROLLBACK;

            OPEN O_RC1 FOR
                SELECT 'N'  AS RESULT_CODE
                     , 'Project Route 정보가 없습니다. ' || V_DATA_NO_MSG AS RESULT_CNT
                  FROM DUAL;

            OPEN O_RESULT_CURSOR FOR
                SELECT 'Project Route 정보가 없습니다. ' || V_DATA_NO_MSG AS ERR_MESSAGE
                  FROM DUAL;

            RETURN;

        END IF;

    END IF;

    V_MST_LOOP_CNT := 0;

    WHILE LENGTH(P_ACTIVE_FLAG) > 0
      AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
    LOOP

        V_MST_LOOP_CNT      := V_MST_LOOP_CNT + 1;

        V_ACTIVE_FLAG       := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,     C_DELIMITER, V_MST_LOOP_CNT);
        V_DIVISION_ID       := SCM_ARR_SPL_VAL(P_DIVISION_ID,     C_DELIMITER, V_MST_LOOP_CNT);
        V_SCM_SITE_ID       := SCM_ARR_SPL_VAL(P_SCM_SITE_ID,     C_DELIMITER, V_MST_LOOP_CNT);
        V_ITEM_ID           := SCM_ARR_SPL_VAL(P_ITEM_ID,         C_DELIMITER, V_MST_LOOP_CNT);
        V_LT_OPERATION      := SCM_ARR_SPL_VAL(P_LT_OPERATION,    C_DELIMITER, V_MST_LOOP_CNT);
        V_LT_DAY            := SCM_ARR_SPL_VAL(P_LT_DAY,          C_DELIMITER, V_MST_LOOP_CNT);
        V_CREATED_BY        := SCM_ARR_SPL_VAL(P_CREATED_BY,      C_DELIMITER, V_MST_LOOP_CNT);
        V_CREATION_DATE     := SCM_ARR_SPL_VAL(P_CREATION_DATE,   C_DELIMITER, V_MST_LOOP_CNT);
        V_LAST_UPDATED_BY   := SCM_ARR_SPL_VAL(P_LAST_UPDATED_BY, C_DELIMITER, V_MST_LOOP_CNT);
        V_INV_FLAG          := SCM_ARR_SPL_VAL(P_INV_FLAG,        C_DELIMITER, V_MST_LOOP_CNT);

        /* 재고 표시가 N 이면 값을 넣지 않는다(원문 IIF 와 같다) */
        V_INV_FLAG_SAVE := CASE WHEN V_INV_FLAG = 'N' THEN NULL ELSE V_INV_FLAG END;

        /* 이력저장
           ★원문은 `@v_inv_flag = NULL OR @v_inv_flag = ''` 로 견준다. 앞 조건은 MSSQL 에서 늘 거짓이라
             실제로는 값이 없을 때만 선행 프로시저를 부른다. 원문과 같게 옮겼다 */
        IF V_INV_FLAG IS NULL
        THEN

            PR_SCP_MST_OPERATION_LT_HIST(V_DIVISION_ID, V_SCM_SITE_ID, V_ITEM_ID, V_LT_OPERATION
                                       , V_LT_DAY, V_CREATED_BY, V_CREATION_DATE, V_LAST_UPDATED_BY);

        ELSE

            INSERT INTO SCP_MST_OPERATION_LT_H
                        (
                          HISTORY_SEQ
                        , DIVISION_ID
                        , SCM_SITE_ID
                        , ITEM_ID
                        , LT_OPERATION
                        , LT_DAY
                        , CREATED_BY
                        , CREATION_DATE
                        , LAST_UPDATED_BY
                        , LAST_UPDATE_DATE
                        , ATTRIBUTE1
                        , HISTORY_CREATION_DATE
                        )
                 VALUES (
                          SEQ1_SCP_MST_OPERATION_LT_H.NEXTVAL
                        , V_DIVISION_ID
                        , V_SCM_SITE_ID
                        , V_ITEM_ID
                        , V_LT_OPERATION
                        , TO_NUMBER(V_LT_DAY)
                        , V_CREATED_BY
                        /* ★새 행이면 화면이 빈 값을 보내고 MSSQL 은 빈 문자를 1900-01-01 로 바꾼다.
                              기준 데이터베이스는 칸이 값을 요구해 같은 날짜로 맞춘다 */
                        , CASE WHEN TRIM(V_CREATION_DATE) IS NULL
                               THEN DATE '1900-01-01'
                               ELSE TO_DATE(SUBSTR(V_CREATION_DATE, 1, 19), 'YYYY-MM-DD HH24:MI:SS')
                          END
                        , V_LAST_UPDATED_BY
                        , SYSDATE
                        , V_INV_FLAG_SAVE
                        , SYSDATE
                        );

        END IF;

        /* 데이터 저장
           ★원문은 MERGE 한 문장이다. 온라인 SQL 에서 MERGE 를 쓰지 않는 규칙이라
             먼저 고치고 고친 행이 없으면 넣는 두 문장으로 나눴다 */
        IF V_MST_LOOP_CNT > 0
        THEN

            UPDATE SCP_MST_OPERATION_LT
               SET LT_DAY           = TO_NUMBER(V_LT_DAY)
                 , ATTRIBUTE1       = V_INV_FLAG_SAVE
                 , LAST_UPDATED_BY  = V_LAST_UPDATED_BY
                 , LAST_UPDATE_DATE = SYSDATE
             WHERE DIVISION_ID      = V_DIVISION_ID
               AND SCM_SITE_ID      = V_SCM_SITE_ID
               AND ITEM_ID          = V_ITEM_ID
               AND LT_OPERATION     = V_LT_OPERATION;

            IF SQL%ROWCOUNT = 0
            THEN

                INSERT INTO SCP_MST_OPERATION_LT
                            (
                              DIVISION_ID
                            , SCM_SITE_ID
                            , ITEM_ID
                            , LT_OPERATION
                            , LT_DAY
                            , CREATED_BY
                            , CREATION_DATE
                            , LAST_UPDATED_BY
                            , LAST_UPDATE_DATE
                            , ATTRIBUTE1
                            )
                     VALUES (
                              V_DIVISION_ID
                            , V_SCM_SITE_ID
                            , V_ITEM_ID
                            , V_LT_OPERATION
                            , TO_NUMBER(V_LT_DAY)
                            , V_CREATED_BY
                            , SYSDATE
                            , V_CREATED_BY
                            , SYSDATE
                            , V_INV_FLAG_SAVE
                            );

            END IF;

        END IF;

    END LOOP;

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;

    /* 결과코드, 결과 카운트 반환 */
    OPEN O_RC1 FOR
        SELECT 'S'              AS RESULT_CODE
             , V_MAX_LOOP_CNT   AS RESULT_CNT
          FROM DUAL;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_SQLERRM := SQLERRM;
        V_SQLCODE := SQLCODE;

        ROLLBACK;

        INSERT INTO SCM_SYS_LOG_BATCH
                    (
                      PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                    , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY
                    )
             VALUES (
                      V_PROGRAM_NAME, 'ERROR', NULL, V_SQLERRM, NULL
                    , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME
                    );

        COMMIT;

        OPEN O_RC1 FOR
            SELECT 'F'                          AS RESULT_CODE
                 , SUBSTR(V_SQLERRM, 1, 4000)   AS RESULT_CNT
              FROM DUAL;

        /* 원문은 오류 번호를 대괄호로 감싸 문구 앞에 붙인다 */
        OPEN O_RESULT_CURSOR FOR
            SELECT '[' || TO_CHAR(V_SQLCODE) || ']' || SUBSTR(V_SQLERRM, 1, 4000) AS ERR_MESSAGE
              FROM DUAL;

END P_SCP0037_SAVE_OPERATION_LT;

END PKG_SCP0037;

SCM_MGR|PACKAGE BODY|PKG_SCP0097:
PACKAGE BODY PKG_SCP0097
IS
    /*
     * Program ID   : PKG_SCP0097
     * Description  : SCP0097 SCP BOM Elec 화면 - 전극 BOM 조회 / 저장
     * Program History
     *===================================================================================================
     *   Date       In Charge		Description
     *===================================================================================================
     * 2023/02/16       jahn1501        PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제  Initial Release
     * 2023/03/06       vadabi3         PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제  [컬럼제거 : PLANT_ID, 컬럼추가 : ELECTRODE_TYPE]
     * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
     */

    C_DELIMITER         CONSTANT VARCHAR2(1 CHAR) := '^';

    TYPE T_TOKEN_TAB IS TABLE OF VARCHAR2(32767 CHAR) INDEX BY PLS_INTEGER;

    /* ==============================================================================================
       내부 : 구분자로 문자열을 나눈다 (AS-IS UF_FX_String_Split 과 같은 규칙 · CLOB 대응)
              - 구분자를 찾을 때마다 앞부분을 앞뒤 공백 제거해 담고, 마지막 남은 부분도 담는다
              - 입력이 비어 있으면 AS-IS 도 빈 값 한 자리를 돌려주므로 한 자리를 담는다
                (Oracle 로 이관된 UF_FX_STRING_SPLIT 은 이 경우 0 행이라 AS-IS 와 갈린다)
       ============================================================================================== */
    PROCEDURE P_SPL_ARR
    (
        P_TEXT              IN  CLOB,
        O_TOKEN             OUT T_TOKEN_TAB
    )
    IS
        V_NR                PLS_INTEGER := 0;
        V_OFF               PLS_INTEGER := 1;
        V_POS               PLS_INTEGER;
        V_LEN               PLS_INTEGER;
    BEGIN
        V_LEN := NVL(DBMS_LOB.GETLENGTH(P_TEXT), 0);

        IF V_LEN = 0 THEN
            O_TOKEN(1) := NULL;
            RETURN;
        END IF;

        LOOP
            V_POS := DBMS_LOB.INSTR(P_TEXT, C_DELIMITER, V_OFF, 1);

            EXIT WHEN V_POS = 0;

            V_NR := V_NR + 1;

            IF V_POS > V_OFF THEN
                O_TOKEN(V_NR) := TRIM(DBMS_LOB.SUBSTR(P_TEXT, V_POS - V_OFF, V_OFF));
            ELSE
                O_TOKEN(V_NR) := NULL;
            END IF;

            V_OFF := V_POS + 1;
        END LOOP;

        V_NR := V_NR + 1;

        IF V_OFF <= V_LEN THEN
            O_TOKEN(V_NR) := TRIM(DBMS_LOB.SUBSTR(P_TEXT, V_LEN - V_OFF + 1, V_OFF));
        ELSE
            O_TOKEN(V_NR) := NULL;
        END IF;
    END P_SPL_ARR;

    /* ==============================================================================================
       SCP0097_GET_SCP_BOM_ELEC : SCP BOM ELEC 조회
       ============================================================================================== */
    PROCEDURE P_SCP0097_GET_SCP_BOM_ELEC
    (
        P_DIVISION_ID       IN  VARCHAR2,
        P_PARENT_ID         IN  VARCHAR2,
        P_CHILD_ID          IN  VARCHAR2,
        P_DEBUG_MODE        IN  VARCHAR2,
        O_RC1               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
        V_ERR_MESSAGE       VARCHAR2(1000 CHAR);
    BEGIN

        /* 상위 · 하위 품목 이름은 품목 원장의 별칭을 쓰고, 값이 없으면 '-' 로 채운다
           (AS-IS ISNULL(NULLIF(NICK_NAME,''),'-') - 옛 시스템은 공백만 있는 값도 빈 값으로 본다) */
        OPEN O_RC1 FOR
        SELECT A.DIVISION_ID
             , A.PARENT_ITEM_ID
             , (
                    SELECT NVL(TRIM(SA.NICK_NAME), '-')
                      FROM SCM_MST_ITEM_SN SA
                     WHERE SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.ITEM_ID     = A.PARENT_ITEM_ID
                       AND ROWNUM         = 1
               ) AS PARENT_ITEM_NAME
             , A.CHILD_ITEM_ID
             , (
                    SELECT NVL(TRIM(SA.NICK_NAME), '-')
                      FROM SCM_MST_ITEM_SN SA
                     WHERE SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.ITEM_ID     = A.CHILD_ITEM_ID
                       AND ROWNUM         = 1
               ) AS CHILD_ITEM_NAME
             , ROUND(A.USAGE, 3) AS USAGE
             , A.SCP_YN
             , A.STOCK_SUM
             , A.ELECTRODE_TYPE
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
          FROM SCP_MST_BOM_ELEC A
         /* 옛 시스템은 대문자 · 소문자를 가리지 않고 비교한다.
            사업부 · 상위 품목 · 하위 품목 칸에는 소문자 값이 없으므로(실측 0 건)
            입력값만 대문자로 올려 맞춘다 - 칸에 함수를 씌우지 않아 인덱스를 그대로 쓴다 */
         WHERE 1 = 1
           AND A.DIVISION_ID = UPPER(P_DIVISION_ID)
           AND (
                   TRIM(P_PARENT_ID) IS NULL
                OR A.PARENT_ITEM_ID IN (
                                           SELECT UPPER(TOKEN)
                                             FROM TABLE(UF_FX_STRING_SPLIT(P_PARENT_ID, ','))
                                       )
               )
           AND (
                   TRIM(P_CHILD_ID) IS NULL
                OR A.CHILD_ITEM_ID IN (
                                          SELECT UPPER(TOKEN)
                                            FROM TABLE(UF_FX_STRING_SPLIT(P_CHILD_ID, ','))
                                      )
               )
         /* 옛 시스템 정렬은 하이픈을 빼고 비교하므로 하이픈을 없앤 값을 첫 열쇠로 둔다
            (하이픈을 없앤 값이 같아지는 자리를 위해 원래 값을 뒤 열쇠로 둔다) */
         ORDER BY A.DIVISION_ID
                , REPLACE(A.PARENT_ITEM_ID, '-', '')
                , A.PARENT_ITEM_ID
                , A.ELECTRODE_TYPE
                , REPLACE(A.CHILD_ITEM_ID, '-', '')
                , A.CHILD_ITEM_ID;

        OPEN O_RESULT_CURSOR FOR
        SELECT 'S' AS RESULT_CODE
             , NULL AS RESULT_MSG
          FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            /* 오류 내용은 변수로 받는다 (SQLERRM 은 SQL 문 안에서 바로 쓸 수 없다) */
            V_ERR_MESSAGE := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

            IF O_RC1 IS NOT NULL AND O_RC1%ISOPEN THEN
                CLOSE O_RC1;
            END IF;

            OPEN O_RC1 FOR
            SELECT NULL AS DIVISION_ID
                 , NULL AS PARENT_ITEM_ID
                 , NULL AS PARENT_ITEM_NAME
                 , NULL AS CHILD_ITEM_ID
                 , NULL AS CHILD_ITEM_NAME
                 , NULL AS USAGE
                 , NULL AS SCP_YN
                 , NULL AS STOCK_SUM
                 , NULL AS ELECTRODE_TYPE
                 , NULL AS CREATED_BY
                 , NULL AS CREATION_DATE
                 , NULL AS LAST_UPDATED_BY
                 , NULL AS LAST_UPDATE_DATE
              FROM DUAL
             WHERE 1 = 2;

            OPEN O_RESULT_CURSOR FOR
            SELECT 'F' AS RESULT_CODE
                 , V_ERR_MESSAGE AS RESULT_MSG
              FROM DUAL;

    END P_SCP0097_GET_SCP_BOM_ELEC;

    /* ==============================================================================================
       SCP0097_SAVE_SCP_BOM_ELEC : SCP BOM ELEC 저장
       ============================================================================================== */
    PROCEDURE P_SCP0097_SAVE_SCP_BOM_ELEC
    (
        P_ACTIVE_FLAG       IN  CLOB,
        P_DIVISION_ID       IN  CLOB,
        P_PARENT_ITEM_ID    IN  CLOB,
        P_CHILD_ITEM_ID     IN  CLOB,
        P_SCP_YN            IN  CLOB,
        P_STOCK_YN          IN  CLOB,
        P_USER_ID           IN  VARCHAR2,
        P_DEBUG_MODE        IN  VARCHAR2,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0097_SAVE_SCP_BOM_ELEC';
        V_LOG_TYPE          VARCHAR2(30 CHAR);          /* START/END/ERROR/... */
        N_LOG_COUNT         NUMBER(10)         := 0;
        V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
        V_DESCRIPTION       VARCHAR2(500 CHAR);
        D_EVENT_DATE        DATE;

        /* 결과 반환 변수 설정 */
        V_MOD_CNT           NUMBER(10)         := 0;

        V_DIVISION_ID       T_TOKEN_TAB;
        V_PARENT_ITEM_ID    T_TOKEN_TAB;
        V_CHILD_ITEM_ID     T_TOKEN_TAB;
        V_SCP_YN            T_TOKEN_TAB;
        V_STOCK_YN          T_TOKEN_TAB;

        V_SCP_YN_ALL        VARCHAR2(32767 CHAR);
        V_ERR_MESSAGE       VARCHAR2(1000 CHAR);
    BEGIN

        SAVEPOINT SP_SCP0097_SAVE;

        /* LOG start */
        V_LOG_TYPE          := 'START';
        V_LOG_MESSAGE       := '########## Start of procedure ##########';
        V_DESCRIPTION       := '';
        D_EVENT_DATE        := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 화면이 행별 값을 '^' 로 이어 보내므로 인자마다 같은 자리끼리 짝지어 처리한다
           (AS-IS 는 다섯 인자를 나눈 뒤 자리 번호로 이어 붙인다 - 어느 하나에 없는 자리는 제외) */
        P_SPL_ARR(P_DIVISION_ID,    V_DIVISION_ID);
        P_SPL_ARR(P_PARENT_ITEM_ID, V_PARENT_ITEM_ID);
        P_SPL_ARR(P_CHILD_ITEM_ID,  V_CHILD_ITEM_ID);
        P_SPL_ARR(P_SCP_YN,         V_SCP_YN);
        P_SPL_ARR(P_STOCK_YN,       V_STOCK_YN);

        /* AS-IS 는 보낸 값 전체(@p_scp_yn)를 그대로 비교에 쓴다 - 원문 그대로 둔다 */
        V_SCP_YN_ALL := DBMS_LOB.SUBSTR(P_SCP_YN, 32767, 1);

        FOR I IN 1 .. V_DIVISION_ID.COUNT LOOP

            IF  V_PARENT_ITEM_ID.EXISTS(I)
            AND V_CHILD_ITEM_ID.EXISTS(I)
            AND V_SCP_YN.EXISTS(I)
            AND V_STOCK_YN.EXISTS(I) THEN

                V_MOD_CNT := V_MOD_CNT + 1;

                /* 저장 열쇠도 옛 시스템은 대문자 · 소문자를 가리지 않고 찾는다.
                   세 칸 모두 소문자 값이 없으므로(실측 0 건) 보낸 값만 대문자로 올려 맞춘다.
                   저장되는 값 자체는 보낸 그대로 둔다(옛 시스템도 바꾸지 않는다) */
                UPDATE SCP_MST_BOM_ELEC
                   SET SCP_YN           = V_SCP_YN(I)
                     , STOCK_SUM        = V_STOCK_YN(I)
                     , ATTRIBUTE5       = (CASE WHEN SCP_YN <> UPPER(V_SCP_YN_ALL) THEN 'Y' ELSE '' END)
                     , LAST_UPDATED_BY  = P_USER_ID
                     , LAST_UPDATE_DATE = SYSDATE
                 WHERE DIVISION_ID    = UPPER(V_DIVISION_ID(I))
                   AND PARENT_ITEM_ID = UPPER(V_PARENT_ITEM_ID(I))
                   AND CHILD_ITEM_ID  = UPPER(V_CHILD_ITEM_ID(I));

            END IF;

        END LOOP;

        /* LOG end */
        V_LOG_TYPE          := 'END';
        V_LOG_MESSAGE       := '########## END of procedure ##########';
        V_DESCRIPTION       := '';
        D_EVENT_DATE        := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        COMMIT;

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RESULT_CURSOR FOR
        SELECT 'S' AS RESULT_CODE
             , V_MOD_CNT AS RESULT_CNT
             , NULL AS ERR_MESSAGE
          FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MESSAGE := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

            ROLLBACK TO SP_SCP0097_SAVE;

            INSERT INTO SCM_SYS_LOG_BATCH
            (
                  PROGRAM_NAME
                , LOG_TYPE
                , LOG_COUNT
                , LOG_MESSAGE
                , DESCRIPTION
                , EVENT_DATE
                , CREATION_DATE
                , CREATED_BY
                , LAST_UPDATE_DATE
                , LAST_UPDATED_BY
            )
            VALUES
            (
                  V_PROGRAM_NAME
                , 'ERROR'
                , NULL
                , V_ERR_MESSAGE
                , NULL
                , SYSDATE
                , SYSDATE
                , V_PROGRAM_NAME
                , SYSDATE
                , V_PROGRAM_NAME
            );

            COMMIT;

            /* error코드, errror 메시지 반환 */
            OPEN O_RESULT_CURSOR FOR
            SELECT 'F' AS RESULT_CODE
                 , 0 AS RESULT_CNT
                 , V_ERR_MESSAGE AS ERR_MESSAGE
              FROM DUAL;

    END P_SCP0097_SAVE_SCP_BOM_ELEC;

END PKG_SCP0097;

SCM_MGR|PACKAGE BODY|PKG_SCP0100:
PACKAGE BODY PKG_SCP0100
IS
/*
 * Program ID   : PKG_SCP0100
 * Description  : SCP0100 Global PSI Report
 * Program History
 *===================================================================================================
 * Date         In Charge       Description
 *===================================================================================================
 * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */

    /* 화면 프로그램 · 측정값 시트
       AS-IS 는 측정값 시트명을 'Global PSI NEW' 로 적었고 등록값은 'Global PSI New' 다.
       MSSQL 은 대소문자를 가리지 않아 걸리지만 Oracle 은 갈리므로 견줄 때 UPPER 를 쓴다. */
    C_PROGRAM_ID        CONSTANT VARCHAR2(30)   := 'SCP0100';
    C_SHEET_NAME        CONSTANT VARCHAR2(50)   := 'Global PSI NEW';

    /* 잔량 성격 측정값 : 조회 구간이 모두 0 이어도 행을 남긴다 */
    C_MEASURE_BALANCE   CONSTANT VARCHAR2(400)  :=
        '''AS_INV'',''CELL_CHAR_AVAILABLE'',''CELL_EOH'',''CELL_FORM_PROGRESS'',''INTRANSIT'',''PACK_CELL_EOH'',''PACK_EOH'',''SEMI_INTRANSIT'',''TO_SITE_EOH''';

    /*******************************************************************************
     * FN_ORDER_EXPR
     *   AS-IS 정렬규칙(Latin1_General_CI_AS)은 대소문자와 하이픈을 무시하고
     *   밑줄을 글자·숫자보다 앞에 둔다. Oracle 기본 정렬은 셋 다 다르므로
     *   문자 칸을 UPPER(TRANSLATE(칸,'_-','/')) 로 바꿔 견주고 원본을 2차 키로 둔다.
     *   정렬 칸에 '/' 가 0건인 것을 실측으로 확인했다.
     *   숫자 칸은 바꾸지 않는다.
     *******************************************************************************/
    FUNCTION FN_ORDER_EXPR
    (
        P_COLS  IN VARCHAR2
    )
    RETURN VARCHAR2
    IS

        C_NUMBER_COLS   CONSTANT VARCHAR2(200) := ',SORT_ORDER_NO,CELL_GROUP_SORT_ORDER_NO,DISPLAY_SEQ,INV_SORT,CELL_CF,';

        V_RESULT        VARCHAR2(4000);
        V_TOKEN         VARCHAR2(200);
        V_COL           VARCHAR2(200);
        V_DESC_YN       VARCHAR2(1);
        V_EXPR          VARCHAR2(600);
        V_IDX           PLS_INTEGER := 1;

    BEGIN

        LOOP

            V_TOKEN := TRIM(REGEXP_SUBSTR(P_COLS, '[^,]+', 1, V_IDX));

            EXIT WHEN V_TOKEN IS NULL;

            IF UPPER(V_TOKEN) LIKE '% DESC' THEN
                V_COL     := TRIM(SUBSTR(V_TOKEN, 1, LENGTH(V_TOKEN) - 5));
                V_DESC_YN := 'Y';
            ELSE
                V_COL     := V_TOKEN;
                V_DESC_YN := 'N';
            END IF;

            IF INSTR(C_NUMBER_COLS, ',' || UPPER(V_COL) || ',') > 0 THEN
                /* 숫자 칸 */
                IF V_DESC_YN = 'Y' THEN
                    V_EXPR := V_COL || ' DESC NULLS LAST';
                ELSE
                    V_EXPR := V_COL || ' NULLS FIRST';
                END IF;
            ELSE
                /* 문자 칸 */
                IF V_DESC_YN = 'Y' THEN
                    V_EXPR := 'UPPER(TRANSLATE(' || V_COL || ', ''_-'', ''/'')) DESC NULLS LAST'
                           || ', ' || V_COL || ' DESC NULLS LAST';
                ELSE
                    V_EXPR := 'UPPER(TRANSLATE(' || V_COL || ', ''_-'', ''/'')) NULLS FIRST'
                           || ', ' || V_COL || ' NULLS FIRST';
                END IF;
            END IF;

            IF V_RESULT IS NULL THEN
                V_RESULT := V_EXPR;
            ELSE
                V_RESULT := V_RESULT || CHR(10) || '        , ' || V_EXPR;
            END IF;

            V_IDX := V_IDX + 1;

        END LOOP;

        RETURN V_RESULT;

    END FN_ORDER_EXPR;

    /*******************************************************************************
     * PR_GET_REPORT_TERM_INFO
     *   AS-IS FN_GET_REPORT_TERM_INFO (멀티스테이트먼트 TVF, 한 행 반환)
     *   호출처가 SCP0100 두 프로시저뿐이라 패키지 내부 프로시저로 흡수한다.
     *******************************************************************************/
    PROCEDURE PR_GET_REPORT_TERM_INFO
    (
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2
      , P_FROM_YYYYMMDD         IN  VARCHAR2
      , P_TO_YYYYMMDD           IN  VARCHAR2
      , O_PLAN_FROM_YYYYMMDD    OUT VARCHAR2
      , O_PLAN_TO_YYYYMMDD      OUT VARCHAR2
      , O_PLAN_FROM_YYYYMM      OUT VARCHAR2
      , O_PLAN_TO_YYYYMM        OUT VARCHAR2
      , O_RESULT_FROM_YYYYMMDD  OUT VARCHAR2
      , O_RESULT_TO_YYYYMMDD    OUT VARCHAR2
      , O_PLAN_PARTIAL_FROM_WW  OUT VARCHAR2
      , O_PLAN_PARTIAL_TO_WW    OUT VARCHAR2
      , O_PLAN_ISO_FROM_WW      OUT VARCHAR2
      , O_PLAN_ISOL_TO_WW       OUT VARCHAR2
    )
    IS

        V_PLAN_FROM_YYYYMMDD    VARCHAR2(32);
        V_PLAN_TO_YYYYMMDD      VARCHAR2(32);
        V_PLAN_FROM_YYYYMM      VARCHAR2(32);
        V_PLAN_TO_YYYYMM        VARCHAR2(32);
        V_RESULT_FROM_YYYYMMDD  VARCHAR2(32);
        V_RESULT_TO_YYYYMMDD    VARCHAR2(32);
        V_PLAN_FROM_PARTIAL_WW  VARCHAR2(32);
        V_PLAN_TO_PARTIAL_WW    VARCHAR2(32);
        V_PLAN_FROM_ISO_WW      VARCHAR2(32);
        V_PLAN_TO_ISO_WW        VARCHAR2(32);

    BEGIN

        BEGIN
            SELECT BASIS_START_DATE
              INTO V_PLAN_FROM_YYYYMMDD
              FROM SCM_SYS_CALENDAR_M
             WHERE 1 = 1
               AND BASIS_YYYYMMDD = P_PLAN_START_YYYYMMDD;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_PLAN_FROM_YYYYMMDD := NULL;   /* AS-IS 는 대입이 일어나지 않아 초기값 '' 이 남는다 */
        END;

        BEGIN
            SELECT BASIS_START_DATE
              INTO V_RESULT_FROM_YYYYMMDD
              FROM SCM_SYS_CALENDAR_M
             WHERE 1 = 1
               AND BASIS_YYYYMMDD = P_FROM_YYYYMMDD;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_RESULT_FROM_YYYYMMDD := NULL;
        END;

        BEGIN
            SELECT BASIS_START_DATE
              INTO V_RESULT_TO_YYYYMMDD
              FROM SCM_SYS_CALENDAR_M
             WHERE 1 = 1
               AND BASIS_YYYYMMDD = P_TO_YYYYMMDD;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_RESULT_TO_YYYYMMDD := NULL;
        END;

        /* AS-IS 분기 그대로. 첫 두 갈래가 전 구간을 덮어 뒤 두 갈래는 타지 않는다 */
        IF V_PLAN_FROM_YYYYMMDD > V_RESULT_FROM_YYYYMMDD THEN

            /* 실적 보여줌 */
            V_PLAN_TO_YYYYMMDD     := P_TO_YYYYMMDD;
            V_RESULT_TO_YYYYMMDD   := V_PLAN_FROM_YYYYMMDD;

        ELSIF V_PLAN_FROM_YYYYMMDD <= V_RESULT_FROM_YYYYMMDD THEN

            /* 실적 없음 */
            V_PLAN_TO_YYYYMMDD     := P_TO_YYYYMMDD;
            V_RESULT_FROM_YYYYMMDD := TO_CHAR(ADD_MONTHS(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'),  6), 'YYYYMMDD');
            V_RESULT_TO_YYYYMMDD   := TO_CHAR(ADD_MONTHS(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'), -6), 'YYYYMMDD');

        ELSIF V_PLAN_FROM_YYYYMMDD > V_RESULT_TO_YYYYMMDD THEN

            V_PLAN_FROM_YYYYMMDD   := TO_CHAR(ADD_MONTHS(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'), -6), 'YYYYMMDD');
            V_PLAN_TO_YYYYMMDD     := TO_CHAR(ADD_MONTHS(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'), -6), 'YYYYMMDD');
            V_RESULT_FROM_YYYYMMDD := P_FROM_YYYYMMDD;
            V_RESULT_TO_YYYYMMDD   := P_TO_YYYYMMDD;

        ELSIF V_PLAN_FROM_YYYYMMDD = V_RESULT_TO_YYYYMMDD THEN

            V_PLAN_TO_YYYYMMDD     := V_PLAN_FROM_YYYYMMDD;
            V_RESULT_FROM_YYYYMMDD := P_FROM_YYYYMMDD;
            V_RESULT_TO_YYYYMMDD   := P_TO_YYYYMMDD;

        END IF;

        V_PLAN_FROM_YYYYMM := SUBSTR(P_FROM_YYYYMMDD, 1, 6);
        V_PLAN_TO_YYYYMM   := SUBSTR(P_TO_YYYYMMDD,   1, 6);

        SELECT MIN(WW)
             , MAX(WW)
          INTO V_PLAN_FROM_PARTIAL_WW
             , V_PLAN_TO_PARTIAL_WW
          FROM ( SELECT SUBSTR(ISO_YYYYWW, 1, 4) || SUBSTR(PARTIAL_WEEK_NAME, 2, 3) AS WW
                   FROM SCM_SYS_CALENDAR_M
                  WHERE 1 = 1
                    AND BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                    AND BASIS_YYYYMMDD <= P_TO_YYYYMMDD
                  GROUP BY SUBSTR(ISO_YYYYWW, 1, 4) || SUBSTR(PARTIAL_WEEK_NAME, 2, 3)
               )  IA;

        SELECT MIN(ISO_YYYYWW)
             , MAX(ISO_YYYYWW)
          INTO V_PLAN_FROM_ISO_WW
             , V_PLAN_TO_ISO_WW
          FROM ( SELECT ISO_YYYYWW
                   FROM SCM_SYS_CALENDAR_M
                  WHERE 1 = 1
                    AND BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                    AND BASIS_YYYYMMDD <= P_TO_YYYYMMDD
                  GROUP BY ISO_YYYYWW
               )  IA;

        O_PLAN_FROM_YYYYMMDD   := V_PLAN_FROM_YYYYMMDD;
        O_PLAN_TO_YYYYMMDD     := V_PLAN_TO_YYYYMMDD;
        O_PLAN_FROM_YYYYMM     := V_PLAN_FROM_YYYYMM;
        O_PLAN_TO_YYYYMM       := V_PLAN_TO_YYYYMM;
        O_RESULT_FROM_YYYYMMDD := V_RESULT_FROM_YYYYMMDD;
        O_RESULT_TO_YYYYMMDD   := V_RESULT_TO_YYYYMMDD;
        O_PLAN_PARTIAL_FROM_WW := V_PLAN_FROM_PARTIAL_WW;
        O_PLAN_PARTIAL_TO_WW   := V_PLAN_TO_PARTIAL_WW;
        O_PLAN_ISO_FROM_WW     := V_PLAN_FROM_ISO_WW;
        O_PLAN_ISOL_TO_WW      := V_PLAN_TO_ISO_WW;

    END PR_GET_REPORT_TERM_INFO;

    /*******************************************************************************
     * PR_SET_FINAL_COLS
     *   AS-IS 가 FN_GET_REPORT_USER_COLUMNS 결과로 조회 칸 목록과 정렬 칸 목록을
     *   문자열로 조립하고 치환하는 구간. WW · MM 이 같아 내부 프로시저로 둔다.
     *******************************************************************************/
    PROCEDURE PR_SET_FINAL_COLS
    (
        P_USER_ID           IN  VARCHAR2
      , P_SEARCH_LEVEL      IN  VARCHAR2
      , O_SHEET_NAME        OUT VARCHAR2
      , O_FINAL_COLS        OUT VARCHAR2
      , O_FINAL_ORDER_COLS  OUT VARCHAR2
    )
    IS

        V_SHEET_NAME        VARCHAR2(50);
        V_FINAL_COLS        VARCHAR2(4000);
        V_FINAL_ORDER_COLS  VARCHAR2(4000);

    BEGIN

        IF UPPER(P_SEARCH_LEVEL) IN ('DETAIL', 'AUTO') THEN
            V_SHEET_NAME := 'REPORT';
        ELSE
            V_SHEET_NAME := 'SEARCH_LEVEL';
        END IF;

        /* AS-IS 는 누적 대입 SELECT 로 ',' 를 앞에 붙여 이어 붙인다 */
        FOR R IN ( SELECT COLUMN_NAME
                     FROM TABLE(FN_GET_REPORT_USER_COLUMNS(C_PROGRAM_ID, V_SHEET_NAME, P_USER_ID))
                    ORDER BY USER_SORT_ORDER_NO
                 )
        LOOP
            V_FINAL_COLS       := V_FINAL_COLS       || ',' || R.COLUMN_NAME;
            V_FINAL_ORDER_COLS := V_FINAL_ORDER_COLS || ',' || R.COLUMN_NAME;
        END LOOP;

        /* 맨 앞 ',' 제거 */
        V_FINAL_COLS       := SUBSTR(V_FINAL_COLS,       2, LENGTH(V_FINAL_COLS)       - 1);
        V_FINAL_ORDER_COLS := SUBSTR(V_FINAL_ORDER_COLS, 2, LENGTH(V_FINAL_ORDER_COLS) - 1);

        V_FINAL_COLS := REPLACE(V_FINAL_COLS, 'MEASURE_NAME', 'SORT_ORDER_NO,MEASURE_NAME');
        V_FINAL_COLS := REPLACE(V_FINAL_COLS, ',CELL_GROUP',  ',CELL_GROUP_SORT_ORDER_NO,CELL_GROUP');

        V_FINAL_ORDER_COLS := REPLACE(V_FINAL_ORDER_COLS, ',MEASURE_GROUP',  '');
        V_FINAL_ORDER_COLS := REPLACE(V_FINAL_ORDER_COLS, 'MEASURE_NAME',    'SORT_ORDER_NO,MEASURE_NAME');
        V_FINAL_ORDER_COLS := REPLACE(V_FINAL_ORDER_COLS, 'OPERATION_GROUP', 'OPERATION_GROUP DESC');
        V_FINAL_ORDER_COLS := REPLACE(V_FINAL_ORDER_COLS, 'OPERATION_ID',    'OPERATION_ID DESC');
        V_FINAL_ORDER_COLS := REPLACE(V_FINAL_ORDER_COLS, ',CELL_GROUP',     ',CELL_GROUP_SORT_ORDER_NO,CELL_GROUP');

        IF UPPER(P_SEARCH_LEVEL) IN ('CELL_GROUP', 'CELL_GROUP_DETAIL') THEN
            V_FINAL_ORDER_COLS := REPLACE(V_FINAL_ORDER_COLS, 'DIVISION_ID', 'DIVISION_ID,INV_SORT');
            /* INV_SORT 가 추가되어 필요없어짐 */
            V_FINAL_ORDER_COLS := REPLACE(V_FINAL_ORDER_COLS, ',CELL_GROUP_SORT_ORDER_NO', '');
        END IF;

        IF UPPER(P_SEARCH_LEVEL) IN ('DETAIL', 'AUTO') THEN
            V_FINAL_COLS       := V_FINAL_COLS       || ',DISPLAY_SEQ';
            V_FINAL_ORDER_COLS := V_FINAL_ORDER_COLS || ',DISPLAY_SEQ';
        END IF;

        O_SHEET_NAME       := V_SHEET_NAME;
        O_FINAL_COLS       := V_FINAL_COLS;
        O_FINAL_ORDER_COLS := V_FINAL_ORDER_COLS;

    END PR_SET_FINAL_COLS;

    /*******************************************************************************
     * P_SCP0100_GET_PLAN_DATE
     *   AS-IS SCP0100_GET_PLAN_DATE
     *   AS-IS 는 #TMP_PLAN 을 만든 뒤 버킷 갈래에서 한 번만 참조하므로 인라인 뷰로 옮긴다.
     *******************************************************************************/
    PROCEDURE P_SCP0100_GET_PLAN_DATE
    (
        P_DIVISION_ID           IN  VARCHAR2
      , P_BUCKET                IN  VARCHAR2
      , P_PROGRAM_ID            IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS

        V_ERR_MSG   VARCHAR2(4000);

    BEGIN

        IF UPPER(P_PROGRAM_ID) = 'SCP0100' THEN

            IF UPPER(P_BUCKET) = 'MONTHLY' THEN

                OPEN O_RC1 FOR
                    SELECT CODE
                         , NAME
                      FROM ( SELECT A.PLAN_START_YYYYMMDD AS CODE
                                  , CASE
                                      WHEN XA.FP_TARGET_YN = 'Y'
                                      THEN TO_CHAR(FN_CHAR_TO_DATE(A.PLAN_START_YYYYMMDD), 'YYYY-MM-DD') || ' (' || B.WEEK_NAME || ')'
                                      ELSE TO_CHAR(FN_CHAR_TO_DATE(A.PLAN_START_YYYYMMDD), 'YYYY-MM-DD') || ' (' || B.WEEK_NAME || ')' || ' (No Plan)'
                                    END AS NAME
                               FROM SCP_PLAN_VERSION_V          A
                                  , SCM_SYS_CALENDAR_M          B
                                  , ( SELECT DIVISION_ID                    /* 고도화 */
                                           , PLAN_START_YYYYMMDD
                                           , FP_TARGET_YN
                                           , MRP_TARGET_YN
                                           , DM_RTF_YN
                                        FROM SCP_PLN_INTERFACE_YN
                                       WHERE 1 = 1
                                         AND ( TRIM(P_DIVISION_ID) IS NULL
                                               OR UPPER(DIVISION_ID) IN ( SELECT UPPER(VALUE) FROM TABLE(FN_SPLITSTRING(P_DIVISION_ID, ',')) )
                                             )
                                         AND DIVISION_ID LIKE '81%'
                                    )  XA
                              WHERE B.BASIS_YYYYMMDD            = A.PLAN_START_YYYYMMDD
                                AND XA.PLAN_START_YYYYMMDD(+)   = A.PLAN_START_YYYYMMDD
                                AND XA.FP_TARGET_YN             = 'Y'
                                AND ( TRIM(P_DIVISION_ID) IS NULL OR UPPER(A.DIVISION_ID) = UPPER(P_DIVISION_ID) )
                              GROUP BY A.PLAN_START_YYYYMMDD
                                     , B.WEEK_NAME
                                     , XA.FP_TARGET_YN
                           )  IA
                     WHERE CODE IN ( SELECT DISTINCT PLAN_START_YYYYMMDD
                                       FROM SCP_RPT_GLOBAL_PSI_MD_MM )
                     ORDER BY CODE DESC;

            ELSIF UPPER(P_BUCKET) = 'WEEKLY' THEN

                OPEN O_RC1 FOR
                    SELECT CODE
                         , NAME
                      FROM ( SELECT A.PLAN_START_YYYYMMDD AS CODE
                                  , CASE
                                      WHEN XA.FP_TARGET_YN = 'Y'
                                      THEN TO_CHAR(FN_CHAR_TO_DATE(A.PLAN_START_YYYYMMDD), 'YYYY-MM-DD') || ' (' || B.WEEK_NAME || ')'
                                      ELSE TO_CHAR(FN_CHAR_TO_DATE(A.PLAN_START_YYYYMMDD), 'YYYY-MM-DD') || ' (' || B.WEEK_NAME || ')' || ' (No Plan)'
                                    END AS NAME
                               FROM SCP_PLAN_VERSION_V          A
                                  , SCM_SYS_CALENDAR_M          B
                                  , ( SELECT DIVISION_ID                    /* 고도화 */
                                           , PLAN_START_YYYYMMDD
                                           , FP_TARGET_YN
                                           , MRP_TARGET_YN
                                           , DM_RTF_YN
                                        FROM SCP_PLN_INTERFACE_YN
                                       WHERE 1 = 1
                                         AND ( TRIM(P_DIVISION_ID) IS NULL
                                               OR UPPER(DIVISION_ID) IN ( SELECT UPPER(VALUE) FROM TABLE(FN_SPLITSTRING(P_DIVISION_ID, ',')) )
                                             )
                                         AND DIVISION_ID LIKE '81%'
                                    )  XA
                              WHERE B.BASIS_YYYYMMDD            = A.PLAN_START_YYYYMMDD
                                AND XA.PLAN_START_YYYYMMDD(+)   = A.PLAN_START_YYYYMMDD
                                AND XA.FP_TARGET_YN             = 'Y'
                                AND ( TRIM(P_DIVISION_ID) IS NULL OR UPPER(A.DIVISION_ID) = UPPER(P_DIVISION_ID) )
                              GROUP BY A.PLAN_START_YYYYMMDD
                                     , B.WEEK_NAME
                                     , XA.FP_TARGET_YN
                           )  IA
                     WHERE CODE IN ( SELECT DISTINCT PLAN_START_YYYYMMDD
                                       FROM SCP_RPT_GLOBAL_PSI_MD_WW )
                     ORDER BY CODE DESC;

            END IF;

        END IF;

        OPEN O_RESULT_CURSOR FOR SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;
            OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SCP0100_GET_PLAN_DATE;

    /*******************************************************************************
     * P_SCP0100_GET_SHEET_CALENDAR_3SPAN
     *   AS-IS SCP0100_GET_SHEET_CALENDAR_3SPAN
     *   AS-IS 본문 앞부분의 주석 구간(DEFAULT · 1차 · 2차 · 3차 적용)은 옮기지 않고
     *   실제로 실행되는 마지막 문장만 옮긴다.
     *******************************************************************************/
    PROCEDURE P_SCP0100_GET_SHEET_CALENDAR_3SPAN
    (
        P_START_YYYYMMDD        IN  VARCHAR2
      , P_END_YYYYMMDD          IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS

        V_ERR_MSG   VARCHAR2(4000);

    BEGIN

        OPEN O_RC1 FOR
            SELECT COLUMN_NAME
                 , COLUMN_LABEL_NAME
                 , SMALL_CLASS_LABEL_NAME
                 , LARGE_CLASS_LABEL_NAME
                 , DAY_CODE
                 , SORT_ORDER_NO
              FROM ( SELECT 'W_' || WEEK_KEY   AS COLUMN_NAME
                          , WEEK_KEY           AS COLUMN_LABEL_NAME
                          , SMALL_CLASS_LABEL_NAME
                          , LARGE_CLASS_LABEL_NAME
                          , DAY_CODE
                          , SORT_ORDER_NO
                       FROM ( SELECT SUBSTR(ISO_YYYYWW, 1, 4) || SUBSTR(PARTIAL_WEEK_NAME, 2, 3)  AS WEEK_KEY
                                   , CASE
                                       WHEN MAX(SUBSTR(PARTIAL_WEEK_NAME, 4, 1)) IS NOT NULL
                                       THEN MAX(SUBSTR(PARTIAL_WEEK_NAME, 1, 3) || '_' || SUBSTR(PARTIAL_WEEK_NAME, 4, 1))
                                       ELSE MAX(PARTIAL_WEEK_NAME)
                                     END                                                          AS SMALL_CLASS_LABEL_NAME
                                   , MAX(MONTH_NAME)                                              AS LARGE_CLASS_LABEL_NAME
                                   , MIN(BASIS_START_DATE)                                        AS DAY_CODE
                                   , MIN(BASIS_START_DATE) || '21'                                AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M
                               WHERE BASIS_YYYYMMDD >= P_START_YYYYMMDD
                                 AND BASIS_YYYYMMDD <= P_END_YYYYMMDD
                               GROUP BY SUBSTR(ISO_YYYYWW, 1, 4) || SUBSTR(PARTIAL_WEEK_NAME, 2, 3)
                            )  XA
                     UNION ALL
                     SELECT 'M_' || BASIS_YYYYMM                                                  AS COLUMN_NAME
                          , MONTH_NAME                                                            AS COLUMN_LABEL_NAME
                          , MONTH_NAME                                                            AS SMALL_CLASS_LABEL_NAME
                          , MONTH_NAME                                                            AS LARGE_CLASS_LABEL_NAME
                          , MIN(BASIS_START_DATE)                                                 AS DAY_CODE
                          , MIN(BASIS_START_DATE) || '02'                                         AS SORT_ORDER_NO
                       FROM SCM_SYS_CALENDAR_M
                      WHERE BASIS_YYYYMMDD >= P_START_YYYYMMDD
                        AND BASIS_YYYYMMDD <= P_END_YYYYMMDD
                      GROUP BY BASIS_YYYYMM
                             , MONTH_NAME
                   )  IA
             ORDER BY SORT_ORDER_NO;

        OPEN O_RESULT_CURSOR FOR SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;
            OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SCP0100_GET_SHEET_CALENDAR_3SPAN;

    /*******************************************************************************
     * P_SCP0100_GET_SITE
     *   AS-IS SCP0100_GET_SITE
     *   TO_SITE 는 소문자가 섞인 칸이라(실측 9.1%) 정렬을 AS-IS 규칙으로 맞춘다.
     *   FROM_SITE 는 소문자 0건이지만 하이픈·밑줄이 있어 정렬식은 같게 둔다.
     *******************************************************************************/
    PROCEDURE P_SCP0100_GET_SITE
    (
        P_SITE_TPYE             IN  VARCHAR2
      , P_DIVISION_ID           IN  VARCHAR2
      , P_BUCKET                IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS

        V_ERR_MSG   VARCHAR2(4000);

    BEGIN

        IF UPPER(P_SITE_TPYE) = 'FROM_SITE' THEN

            IF UPPER(P_BUCKET) = 'MONTHLY' THEN

                OPEN O_RC1 FOR
                    SELECT FROM_SITE AS CODE
                         , FROM_SITE AS NAME
                      FROM SCP_RPT_GLOBAL_PSI_MD_MM
                     WHERE 1 = 1
                       AND ( TRIM(P_DIVISION_ID) IS NULL OR DIVISION_ID IN ( SELECT VALUE FROM TABLE(FN_SPLITSTRING(P_DIVISION_ID, ',')) ) )
                       AND DIVISION_ID LIKE '81%'
                     GROUP BY FROM_SITE
                     ORDER BY UPPER(TRANSLATE(FROM_SITE, '_-', '/')) NULLS FIRST
                            , FROM_SITE NULLS FIRST;

            ELSIF UPPER(P_BUCKET) = 'WEEKLY' THEN

                OPEN O_RC1 FOR
                    SELECT FROM_SITE AS CODE
                         , FROM_SITE AS NAME
                      FROM SCP_RPT_GLOBAL_PSI_MD_WW
                     WHERE 1 = 1
                       AND ( TRIM(P_DIVISION_ID) IS NULL OR DIVISION_ID IN ( SELECT VALUE FROM TABLE(FN_SPLITSTRING(P_DIVISION_ID, ',')) ) )
                       AND DIVISION_ID LIKE '81%'
                     GROUP BY FROM_SITE
                     ORDER BY UPPER(TRANSLATE(FROM_SITE, '_-', '/')) NULLS FIRST
                            , FROM_SITE NULLS FIRST;

            END IF;

        ELSIF UPPER(P_SITE_TPYE) = 'TO_SITE' THEN

            IF UPPER(P_BUCKET) = 'MONTHLY' THEN

                OPEN O_RC1 FOR
                    SELECT TO_SITE AS CODE
                         , TO_SITE AS NAME
                      FROM SCP_RPT_GLOBAL_PSI_MD_MM
                     WHERE 1 = 1
                       AND ( TRIM(P_DIVISION_ID) IS NULL OR DIVISION_ID IN ( SELECT VALUE FROM TABLE(FN_SPLITSTRING(P_DIVISION_ID, ',')) ) )
                       AND DIVISION_ID LIKE '81%'
                     GROUP BY TO_SITE
                     ORDER BY UPPER(TRANSLATE(TO_SITE, '_-', '/')) NULLS FIRST
                            , TO_SITE NULLS FIRST;

            ELSIF UPPER(P_BUCKET) = 'WEEKLY' THEN

                OPEN O_RC1 FOR
                    SELECT TO_SITE AS CODE
                         , TO_SITE AS NAME
                      FROM SCP_RPT_GLOBAL_PSI_MD_WW
                     WHERE 1 = 1
                       AND ( TRIM(P_DIVISION_ID) IS NULL OR DIVISION_ID IN ( SELECT VALUE FROM TABLE(FN_SPLITSTRING(P_DIVISION_ID, ',')) ) )
                       AND DIVISION_ID LIKE '81%'
                     GROUP BY TO_SITE
                     ORDER BY UPPER(TRANSLATE(TO_SITE, '_-', '/')) NULLS FIRST
                            , TO_SITE NULLS FIRST;

            END IF;

        END IF;

        OPEN O_RESULT_CURSOR FOR SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;
            OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SCP0100_GET_SITE;

    /*******************************************************************************
     * P_SCP0100_GET_GLOBAL_PSI_REPORT
     *   AS-IS SCP0100_GET_GLOBAL_PSI_REPORT (버킷에 따라 갈라 부르는 프로시저)
     *   AS-IS 는 V1.2.1 에서 only data 옵션을 없애 _WW · _MM 이 아니라
     *   _WW_DATAONLY · _MM_DATAONLY 를 부른다.
     *******************************************************************************/
    PROCEDURE P_SCP0100_GET_GLOBAL_PSI_REPORT
    (
        P_FROM_YYYYMMDD         IN  VARCHAR2
      , P_TO_YYYYMMDD           IN  VARCHAR2
      , P_DIVISION_ID           IN  VARCHAR2
      , P_ITEM_ID               IN  VARCHAR2
      , P_NICK_NAME             IN  VARCHAR2
      , P_FROM_SITE             IN  VARCHAR2
      , P_TO_SITE               IN  VARCHAR2
      , P_PLAN_START_YYYYMMDD   IN  VARCHAR2
      , P_PLAN_TYPE             IN  VARCHAR2
      , P_USER_ID               IN  VARCHAR2
      , P_BUCKET                IN  VARCHAR2
      , P_CELL_GROUP            IN  VARCHAR2
      , P_PROJECT               IN  VARCHAR2
      , P_SEARCH_LEVEL          IN  VARCHAR2
      , P_CHK_CELL_QTY          IN  VARCHAR2
      , P_CHK_AS                IN  VARCHAR2
