                    , PLAN_TYPE
                    , CELL_GROUP
                    , PRODUCT_LEVEL1
                    , OPERATION_GROUP
                    , PRODUCT_LEVEL2
                    , MEASURE;

            INSERT INTO GT_SCP0100_QTY_CELL_GROUP_DETAIL
            (
