              , PLAN_TYPE
              , CELL_GROUP
              , PRODUCT_LEVEL1
              , OPERATION_GROUP
              , PRODUCT_LEVEL2
              , MEASURE_UI
              , QTY
              , FROM_BOH_QTY
              , TO_BOH_QTY
              , CELL_CF
