             || '              , B.MEASURE_GROUP' || CHR(10)
             || '              , B.MEASURE_UI' || CHR(10)
             || '              , B.MEASURE_NAME' || CHR(10)
             || '              , B.SORT_ORDER_NO' || CHR(10)
