             || '              , ''-''  AS PRODUCT_LEVEL2' || CHR(10)
             || '              , ''-''  AS PRODUCT_LEVEL3' || CHR(10)
             || '              , 1      AS CELL_CF' || CHR(10)
             || '              , A.MEASURE' || CHR(10)));
            DBMS_LOB.APPEND(V_SQL, V_QTY_COLS);
            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                CHR(10) || '           FROM GT_SCP0100_RAW_CELL_CF             A' || CHR(10)
