                 , SUM(TO_BOH_QTY)                 AS TO_BOH_QTY
                 , MAX(CELL_CF)                    AS CELL_CF
              FROM GT_SCP0100_RAW
             GROUP BY YYYYPW
                    , DIVISION_ID
                    , PLAN_TYPE
                    , CELL_GROUP
                    , OPERATION_GROUP
                    , PRODUCT_LEVEL1
                    , PRODUCT_LEVEL2
                    , PRODUCT_LEVEL3
                    , MEASURE;

            INSERT INTO GT_SCP0100_RAW_CELL_CF
            (
                DIVISION_ID
              , PLAN_TYPE
              , CELL_GROUP
              , OPERATION_GROUP
              , PRODUCT_LEVEL1
              , PRODUCT_LEVEL2
              , PRODUCT_LEVEL3
              , MEASURE
            )
            SELECT DIVISION_ID
                 , PLAN_TYPE                    /* E20260708-000926 */
                 , CELL_GROUP
                 , OPERATION_GROUP
                 , PRODUCT_LEVEL1
                 , PRODUCT_LEVEL2
                 , PRODUCT_LEVEL3
                 , MEASURE
              FROM GT_SCP0100_RAW
             GROUP BY DIVISION_ID
                    , PLAN_TYPE
                    , CELL_GROUP
                    , OPERATION_GROUP
                    , PRODUCT_LEVEL1
                    , PRODUCT_LEVEL2
                    , PRODUCT_LEVEL3
                    , MEASURE;

            /* 연월별 수량 칸 */
            FOR R IN ( SELECT YYYYPW_NAME
                            , YYYYPW
                         FROM GT_SCP0100_DAYCOLS
                        ORDER BY SORT_ORDER_NO
                     )
            LOOP
                DBMS_LOB.APPEND(V_QTY_COLS, TO_CLOB(
                    CHR(10) || '     , ( SELECT SA.QTY' || CHR(10)
                 || '           FROM GT_SCP0100_QTY_PRODUCT_LEVEL3  SA' || CHR(10)
                 || '          WHERE SA.DIVISION_ID     = A.DIVISION_ID' || CHR(10)
                 || '            AND SA.PLAN_TYPE       = A.PLAN_TYPE' || CHR(10)
                 || '            AND SA.CELL_GROUP      = A.CELL_GROUP' || CHR(10)
                 || '            AND SA.OPERATION_GROUP = A.OPERATION_GROUP' || CHR(10)
                 || '            AND SA.PRODUCT_LEVEL1  = A.PRODUCT_LEVEL1' || CHR(10)
                 || '            AND SA.PRODUCT_LEVEL2  = A.PRODUCT_LEVEL2' || CHR(10)
                 || '            AND SA.PRODUCT_LEVEL3  = A.PRODUCT_LEVEL3' || CHR(10)
                 || '            AND SA.MEASURE_UI      = B.MEASURE_UI' || CHR(10)
                 || '            AND SA.YYYYPW          = ''' || R.YYYYPW || ''' )  AS ' || R.YYYYPW_NAME));
            END LOOP;

            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                'SELECT ' || V_FINAL_COLS || CHR(10)
             || '     , '));
            DBMS_LOB.APPEND(V_SQL, V_FINAL_SUM_COLS);
            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                CHR(10) || '  FROM ( SELECT A.DIVISION_ID' || CHR(10)
             || '              , A.PLAN_TYPE' || CHR(10)
             || '              , A.CELL_GROUP' || CHR(10)
             || '              , CASE WHEN B.MEASURE_UI = ''DIO''' || CHR(10)
             || '                     THEN FN_GET_LOOKUP_CODE_DESC(''OPERATION_GROUP_SCP'', ''C'')' || CHR(10)
             || '                     ELSE FN_GET_LOOKUP_CODE_DESC(''OPERATION_GROUP_SCP'', A.OPERATION_GROUP)' || CHR(10)
             || '                END AS OPERATION_GROUP' || CHR(10)
             || '              , A.PRODUCT_LEVEL1' || CHR(10)
             || '              , A.PRODUCT_LEVEL2' || CHR(10)
             || '              , A.PRODUCT_LEVEL3' || CHR(10)
             || '              , B.MEASURE_GROUP' || CHR(10)
             || '              , B.MEASURE_UI' || CHR(10)
             || '              , B.MEASURE_NAME' || CHR(10)
             || '              , B.SORT_ORDER_NO' || CHR(10)
             || '              , C.CELL_GROUP_SORT_ORDER_NO' || CHR(10)
             || '              , ''-''  AS OPERATION_ID' || CHR(10)
             || '              , ''-''  AS ITEM_ID' || CHR(10)
             || '              , ''-''  AS TO_SITE' || CHR(10)
             || '              , ''-''  AS FROM_SITE' || CHR(10)
             || '              , ''-''  AS INCOTERMS' || CHR(10)
             || '              , ''-''  AS VARIOUS_KEY' || CHR(10)
             || '              , 1      AS CELL_CF' || CHR(10)
             || '              , A.MEASURE' || CHR(10)));
            DBMS_LOB.APPEND(V_SQL, V_QTY_COLS);
            DBMS_LOB.APPEND(V_SQL, TO_CLOB(
                CHR(10) || '           FROM GT_SCP0100_RAW_CELL_CF             A' || CHR(10)
             || '              , GT_SCP0100_MEASURE                 B' || CHR(10)
             || '              , GT_SCP0100_CELL_GROUP_SORT_ORDER    C' || CHR(10)
             || '          WHERE B.MEASURE_UI  = A.MEASURE' || CHR(10)
             || '            AND C.CELL_GROUP  = A.CELL_GROUP' || CHR(10)
             || '            AND C.MEASURE     = A.MEASURE' || CHR(10)
             || '            AND C.DIVISION_ID = A.DIVISION_ID' || CHR(10)
             || '            AND C.PLAN_TYPE   = A.PLAN_TYPE' || CHR(10)
             || '            AND B.MEASURE_UI  NOT LIKE ''%DIO%''' || CHR(10)
             || '       )  IA' || CHR(10)
             || ' GROUP BY ' || V_FINAL_COLS || CHR(10)
             || ' ORDER BY ' || FN_ORDER_EXPR(V_FINAL_ORDER_COLS)));

        END IF;

        /* 되돌리기가 필요한 자리가 없으므로 결과 커서를 바로 연다 */
        IF DBMS_LOB.GETLENGTH(V_SQL) > 0 THEN
            OPEN O_RC1 FOR V_SQL;
        ELSE
            /* AS-IS 는 조립된 문장이 빈 값이면 아무 결과도 돌려주지 않는다 */
            OPEN O_RC1 FOR SELECT NULL AS DIVISION_ID FROM DUAL WHERE 1 = 0;
        END IF;

        DBMS_LOB.FREETEMPORARY(V_FINAL_SUM_COLS);
        DBMS_LOB.FREETEMPORARY(V_QTY_COLS);

        OPEN O_RESULT_CURSOR FOR SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;
            OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SCP0100_GET_GLOBAL_PSI_REPORT_MM_DATAONLY;

END PKG_SCP0100;

SCM_MGR|PACKAGE BODY|PKG_SCP0110:
PACKAGE BODY PKG_SCP0110
IS
/*
 * Program ID   : PKG_SCP0110
 * Description  : SCP0110 화면 (Demand Group Master)
 * Program History
 *===========================================================================================================
 *   Date       Description
 *===========================================================================================================
 * 2026.09.17   MSSQL(SCP0110_* 4개) -> Oracle 패키지 전환
 *
 * 전환 공통 사항
 *   - AS-IS 비교규칙(대소문자 무시 · '=' 비교의 뒤공백 무시)을 원장 값 분포 기준으로 재현
 *     (소문자가 있는 칸 = GROUP_NAME · 상세 PROJECT_CODE · 상세 ITEM_ID 는 칸·입력 모두 UPPER, 나머지는 입력만 UPPER)
 *   - AS-IS 정렬규칙(대소문자 무시 · 하이픈 무시 · 밑줄은 글자/숫자 앞)을 정렬 칸마다
 *     UPPER(TRANSLATE(칸, '_-', '/')) 1차 키 + UPPER(칸) 2차 키로 재현
 *   - AS-IS 의 '' 비교(@p IS NULL OR @p = '')는 RTRIM(p) IS NULL 로 판정
 *   - 저장 빈 토큰('^^')은 NOT NULL 키 칸에서 '-'(이관 채움값)로 비교, 없는 토큰은 NULL(AS-IS 와 같음)
 *   - 저장 실패 시 SAVEPOINT 까지 되돌림, 성공 시 COMMIT
 */

    TYPE T_TOKEN_TAB IS TABLE OF VARCHAR2(4000 CHAR) INDEX BY PLS_INTEGER;

    C_PKG_NAME        CONSTANT VARCHAR2(30 CHAR)  := 'PKG_SCP0110';
    C_MSG_DUP_NAME    CONSTANT VARCHAR2(200 CHAR) := '[99010]이미 존재하는 Group Name 입니다.';
    C_MSG_DUP_PROJECT CONSTANT VARCHAR2(200 CHAR) := '[99010]복수의 Project를 같은 그룹으로 지정 할 수 없습니다. ';


    /*==================================================================================================
     * 내부 : '^' 구분 CLOB 을 토큰 배열로 나눔
     *        AS-IS SCM_ARR_SPL_CNT(토큰 수 = 구분자 수 + 1, 빈 값·NULL 도 1) ·
     *        SCM_ARR_SPL_VAL(토큰 앞뒤 공백 제거) 과 같은 결과
     *==================================================================================================*/
    PROCEDURE P_SPLIT
    (
        P_TEXT   IN  CLOB,
        P_DELIM  IN  VARCHAR2,
        O_TAB    OUT T_TOKEN_TAB,
        O_CNT    OUT PLS_INTEGER
    )
    IS
        V_LEN   PLS_INTEGER;
        V_POS   PLS_INTEGER := 1;
        V_NEXT  PLS_INTEGER;
    BEGIN
        O_CNT := 0;

        IF P_TEXT IS NULL OR DBMS_LOB.GETLENGTH(P_TEXT) = 0 THEN
            O_CNT    := 1;
            O_TAB(1) := NULL;
            RETURN;
        END IF;

        V_LEN := DBMS_LOB.GETLENGTH(P_TEXT);

        LOOP
            V_NEXT := DBMS_LOB.INSTR(P_TEXT, P_DELIM, V_POS, 1);
            O_CNT  := O_CNT + 1;

            IF V_NEXT = 0 THEN
                IF V_POS <= V_LEN THEN
                    O_TAB(O_CNT) := TRIM(DBMS_LOB.SUBSTR(P_TEXT, V_LEN - V_POS + 1, V_POS));
                ELSE
                    O_TAB(O_CNT) := NULL;
                END IF;
                EXIT;
            END IF;

            IF V_NEXT > V_POS THEN
                O_TAB(O_CNT) := TRIM(DBMS_LOB.SUBSTR(P_TEXT, V_NEXT - V_POS, V_POS));
            ELSE
                O_TAB(O_CNT) := NULL;
            END IF;

            V_POS := V_NEXT + 1;
        END LOOP;
    END P_SPLIT;


    /* 내부 : 토큰 꺼내기 (AS-IS SCM_ARR_SPL_VAL — 범위 밖이면 NULL) */
    FUNCTION F_TK
    (
        P_TAB  IN  T_TOKEN_TAB,
        P_IDX  IN  PLS_INTEGER
    )
    RETURN VARCHAR2
    IS
    BEGIN
        IF P_TAB.EXISTS(P_IDX) THEN
            RETURN P_TAB(P_IDX);
        END IF;
        RETURN NULL;
    END F_TK;


    /* 내부 : NOT NULL 키 칸 토큰 — 빈 토큰은 이관 채움값 '-', 범위 밖은 NULL (AS-IS '' / NULL 구분 재현) */
    FUNCTION F_KEY
    (
        P_TAB  IN  T_TOKEN_TAB,
        P_IDX  IN  PLS_INTEGER
    )
    RETURN VARCHAR2
    IS
    BEGIN
        IF P_TAB.EXISTS(P_IDX) THEN
            RETURN NVL(P_TAB(P_IDX), '-');
        END IF;
        RETURN NULL;
    END F_KEY;


    /* 내부 : AS-IS 반복 조건 WHILE LEN(@p_active_flag) > 0 (공백만 있으면 0) */
    FUNCTION F_HAS_TEXT
    (
        P_TEXT  IN  CLOB
    )
    RETURN BOOLEAN
    IS
    BEGIN
        IF P_TEXT IS NULL OR DBMS_LOB.GETLENGTH(P_TEXT) = 0 THEN
            RETURN FALSE;
        END IF;
        IF DBMS_LOB.GETLENGTH(P_TEXT) > 4000 THEN
            RETURN TRUE;
        END IF;
        RETURN TRIM(DBMS_LOB.SUBSTR(P_TEXT, 4000, 1)) IS NOT NULL;
    END F_HAS_TEXT;


    /* 내부 : 입력 인자 요약 (오류 로그용) */
    FUNCTION F_PARA
    (
        P_NAME   IN  VARCHAR2,
        P_VALUE  IN  CLOB
    )
    RETURN VARCHAR2
    IS
    BEGIN
        RETURN P_NAME || '=' || DBMS_LOB.SUBSTR(P_VALUE, 300, 1) || ';';
    END F_PARA;


    /* 내부 : 저장 결과 커서 */
    PROCEDURE P_RESULT_OK
    (
        O_RESULT_CURSOR  OUT SYS_REFCURSOR,
        P_CNT            IN  NUMBER
    )
    IS
    BEGIN
        OPEN O_RESULT_CURSOR FOR
        SELECT '0'       AS CODE
             , 'SUCCESS' AS MSG
             , P_CNT     AS EVENT
             , 'S'       AS RESULT_CODE
             , P_CNT     AS RESULT_CNT
          FROM DUAL;
    END P_RESULT_OK;


    PROCEDURE P_RESULT_ERR
    (
        O_RESULT_CURSOR  OUT SYS_REFCURSOR,
        P_MSG            IN  VARCHAR2
    )
    IS
    BEGIN
        OPEN O_RESULT_CURSOR FOR
        SELECT '-1'                   AS CODE
             , P_MSG                  AS MSG
             , 0                      AS EVENT
             , 'F'                    AS RESULT_CODE
             , CAST(NULL AS NUMBER)   AS RESULT_CNT
          FROM DUAL;
    END P_RESULT_ERR;


    /* 내부 : 오류 로그 (AS-IS CATCH 의 scm_sys_log_batch INSERT) */
    PROCEDURE P_LOG_ERROR
    (
        P_PROGRAM_NAME  IN  VARCHAR2,
        P_MSG           IN  VARCHAR2,
        P_IN_PARA       IN  VARCHAR2,
        P_SQL_CODE      IN  VARCHAR2,
        P_BACKTRACE     IN  VARCHAR2
    )
    IS
    BEGIN
        PR_SCM_SYS_LOG_BATCH(P_PROGRAM_NAME
                           , 'ERROR'
                           , NULL
                           , SUBSTR(P_MSG, 1, 1000)
                           , NULL
                           , SYSDATE
                           , SUBSTR(P_IN_PARA, 1, 2000)
                           , P_SQL_CODE
                           , SUBSTR(P_MSG, 1, 2000)
                           , SUBSTR(P_BACKTRACE, 1, 4000));
    END P_LOG_ERROR;


    /* 내부 : 저장 실패 시 SAVEPOINT 까지 되돌림 — COMMIT 뒤에는 SAVEPOINT 가 없어 ORA-01086 이므로 무시 */
    PROCEDURE P_ROLLBACK_SAVE
    IS
        E_NO_SAVEPOINT  EXCEPTION;
        PRAGMA EXCEPTION_INIT(E_NO_SAVEPOINT, -1086);
    BEGIN
        ROLLBACK TO SP_SCP0110_SAVE;
    EXCEPTION
        WHEN E_NO_SAVEPOINT THEN
            NULL;
    END P_ROLLBACK_SAVE;


    /*
     * Program ID   : SCP0110_GET_GROUP_MASTER
     * Description  : GROUP 조회
     * Program History
     *===================================================================================================
     *   Date       In Charge		Description
     *===================================================================================================
     * 2024/05/22   mrchois    PJ20244573 LGES SCM SCP 생산모델 기반 공급계획 수립체계 구성
     * 2025-08-14   twinlove   PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산 - Only Stock(Y/N) 추가 attribute1
     * 2026.09.17              MSSQL -> Oracle 전환
     *                         - DIVISION_ID · OPERATION_GROUP 비교는 입력 UPPER · 뒤공백 제거(원장 소문자 0건)
     *                         - Group Name 검색은 GROUP_NAME 소문자 117건이 있어 칸·입력 모두 UPPER
     */
    PROCEDURE P_SCP0110_GET_GROUP_MASTER
    (
        P_DIVISION_ID        IN  VARCHAR2,
        P_OPERATION_GROUP    IN  VARCHAR2,
        P_GROUP_NAME         IN  VARCHAR2,
        O_RC                 OUT SYS_REFCURSOR,
        O_RESULT_CURSOR      OUT SYS_REFCURSOR
    )
    IS
        V_DIVISION_ID      VARCHAR2(4000 CHAR) := UPPER(RTRIM(P_DIVISION_ID));
        V_OPERATION_GROUP  VARCHAR2(4000 CHAR) := UPPER(RTRIM(P_OPERATION_GROUP));
        V_GROUP_NAME_YN    VARCHAR2(1 CHAR)    := CASE WHEN RTRIM(P_GROUP_NAME) IS NULL THEN 'N' ELSE 'Y' END;
        V_GROUP_NAME       VARCHAR2(4000 CHAR) := UPPER(P_GROUP_NAME);
    BEGIN

        --GROUP 조회
        OPEN O_RC FOR
        SELECT DIVISION_ID
             , OPERATION_GROUP
             , GROUP_ID
             , GROUP_NAME
             , ATTRIBUTE1 AS ONLY_STOCK  --PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산
          FROM SCP_MST_ITEM_GROUP
         WHERE 1 = 1
           AND DIVISION_ID = V_DIVISION_ID
           AND (V_OPERATION_GROUP IS NULL
                OR OPERATION_GROUP = V_OPERATION_GROUP)
           AND (V_GROUP_NAME_YN = 'N'
                OR GROUP_ID LIKE '%' || V_GROUP_NAME || '%'
                OR UPPER(GROUP_NAME) LIKE '%' || V_GROUP_NAME || '%')
         ORDER BY DIVISION_ID
                , OPERATION_GROUP
                , GROUP_ID;

        OPEN O_RESULT_CURSOR FOR
        SELECT '0'       AS CODE
             , 'SUCCESS' AS MSG
          FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            DECLARE
                V_ERR  VARCHAR2(4000 CHAR) := SUBSTR(SQLERRM, 1, 4000);
            BEGIN
                P_LOG_ERROR(C_PKG_NAME || '.P_SCP0110_GET_GROUP_MASTER'
                          , V_ERR
                          , 'P_DIVISION_ID=' || P_DIVISION_ID || ';P_OPERATION_GROUP=' || P_OPERATION_GROUP
                            || ';P_GROUP_NAME=' || P_GROUP_NAME
                          , TO_CHAR(SQLCODE)
                          , DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                OPEN O_RC FOR SELECT NULL AS DUMMY FROM DUAL WHERE 1 = 0;
                OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR AS MSG FROM DUAL;
            END;
    END P_SCP0110_GET_GROUP_MASTER;


    /*
     * Program ID   : SCP0110_GET_MODEL_LIST
     * Description  : MODEL LIST 조회
     * Program History
     *===================================================================================================
     *   Date       In Charge		Description
     *===================================================================================================
     * 2024/05/22   mrchois    PJ20244573 LGES SCM SCP 생산모델 기반 공급계획 수립체계 구성
     * 2026.09.17              MSSQL -> Oracle 전환
     *                         - LEFT JOIN 3개는 (+) 조인, c.OPERATION_GROUP · c.ATTRIBUTE8 조건은 AS-IS 와 같이 (+) 없이 걸어 거름
     *                         - 상세 PROJECT_CODE · ITEM_ID 에 소문자가 있어 조인·검색은 UPPER(대상 원장은 소문자 0건)
     *                         - 사업부 인자가 비면(NULL) 0건 (AS-IS 화면이 보내는 빈 문자 '' 결과와 같음)
     */
    PROCEDURE P_SCP0110_GET_MODEL_LIST
    (
        P_DIVISION_ID        IN  VARCHAR2,
        P_OPERATION_GROUP    IN  VARCHAR2,
        P_GROUP_ID           IN  VARCHAR2,
        P_GROUP_NAME         IN  VARCHAR2,
        P_PROJECT_ID         IN  VARCHAR2,
        P_ITEM_ID            IN  VARCHAR2,
        O_RC                 OUT SYS_REFCURSOR,
        O_RESULT_CURSOR      OUT SYS_REFCURSOR
    )
    IS
        V_CELL_ATTRIBUTE8  VARCHAR2(4000 CHAR);
        V_DIVISION_ID_C    VARCHAR2(4000 CHAR) := UPPER(RTRIM(P_DIVISION_ID));
        V_OPERATION_GROUP  VARCHAR2(4000 CHAR) := UPPER(RTRIM(P_OPERATION_GROUP));
        V_GROUP_ID         VARCHAR2(4000 CHAR) := UPPER(RTRIM(P_GROUP_ID));
        V_GROUP_NAME_YN    VARCHAR2(1 CHAR)    := CASE WHEN RTRIM(P_GROUP_NAME) IS NULL THEN 'N' ELSE 'Y' END;
        V_GROUP_NAME       VARCHAR2(4000 CHAR) := UPPER(P_GROUP_NAME);
        V_PROJECT_YN       VARCHAR2(1 CHAR)    := CASE WHEN RTRIM(P_PROJECT_ID) IS NULL THEN 'N' ELSE 'Y' END;
        V_ITEM_YN          VARCHAR2(1 CHAR)    := CASE WHEN RTRIM(P_ITEM_ID) IS NULL THEN 'N' ELSE 'Y' END;
    BEGIN

        --Cell(A)의 경우 완제품만 표시하도록
        IF V_OPERATION_GROUP = 'A' THEN
            V_CELL_ATTRIBUTE8 := 'CP';
        END IF;

        -- MODEL LIST 조회
        OPEN O_RC FOR
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , NVL(D.PROJECT_NAME, A.PROJECT_CODE) AS PROJECT_NAME
             , A.ITEM_ID
             , A.GROUP_ID
		--, b.GROUP_NAME
          FROM SCP_MST_ITEM_GROUP_DETAIL A
             , SCP_MST_ITEM_GROUP        B
             , SCP_MST_FINAL_ITEM        C
             , SCM_MST_PROJECT           D
         WHERE B.GROUP_ID(+)     = A.GROUP_ID
           AND C.ITEM_ID(+)      = UPPER(A.ITEM_ID)
           AND D.DIVISION_ID(+)  = A.DIVISION_ID
           AND D.PROJECT_CODE(+) = UPPER(A.PROJECT_CODE)
           AND A.DIVISION_ID IN (SELECT UPPER(SA.COLUMN_VALUE)
                                   FROM TABLE(STRING_SPLIT(P_DIVISION_ID, ',')) SA)
           AND (V_PROJECT_YN = 'N'
                OR UPPER(A.PROJECT_CODE) IN (SELECT UPPER(SB.COLUMN_VALUE)
                                               FROM TABLE(STRING_SPLIT(P_PROJECT_ID, ',')) SB))
           AND (V_ITEM_YN = 'N'
                OR UPPER(A.ITEM_ID) IN (SELECT UPPER(SC.COLUMN_VALUE)
                                          FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC))
           AND C.DIVISION_ID(+)  = V_DIVISION_ID_C
           AND (V_OPERATION_GROUP IS NULL
                OR C.OPERATION_GROUP = V_OPERATION_GROUP)
           AND (V_CELL_ATTRIBUTE8 IS NULL
                OR C.ATTRIBUTE8 = V_CELL_ATTRIBUTE8)
           AND (V_GROUP_ID IS NULL
                OR A.GROUP_ID = V_GROUP_ID)
           AND (V_GROUP_NAME_YN = 'N'
                OR A.GROUP_ID LIKE '%' || V_GROUP_NAME || '%'
                OR UPPER(B.GROUP_NAME) LIKE '%' || V_GROUP_NAME || '%')
	--Group이 지정된 모델에 대하여 정렬 순서를 1순위로 올리고 나머지는 정렬 순서는 그대로 유지
         ORDER BY CASE WHEN RTRIM(A.GROUP_ID) IS NULL THEN 1 ELSE 0 END
                , A.GROUP_ID NULLS FIRST
                , UPPER(TRANSLATE(A.DIVISION_ID, '_-', '/')) NULLS FIRST
                , A.DIVISION_ID
                , UPPER(TRANSLATE(A.PROJECT_CODE, '_-', '/')) NULLS FIRST
                , UPPER(A.PROJECT_CODE)
                , UPPER(TRANSLATE(A.ITEM_ID, '_-', '/')) NULLS FIRST
                , UPPER(A.ITEM_ID);

        OPEN O_RESULT_CURSOR FOR
        SELECT '0'       AS CODE
             , 'SUCCESS' AS MSG
          FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            DECLARE
                V_ERR  VARCHAR2(4000 CHAR) := SUBSTR(SQLERRM, 1, 4000);
            BEGIN
                P_LOG_ERROR(C_PKG_NAME || '.P_SCP0110_GET_MODEL_LIST'
                          , V_ERR
                          , SUBSTR('P_DIVISION_ID=' || P_DIVISION_ID || ';P_OPERATION_GROUP=' || P_OPERATION_GROUP
                                   || ';P_GROUP_ID=' || P_GROUP_ID || ';P_GROUP_NAME=' || P_GROUP_NAME
                                   || ';P_PROJECT_ID=' || SUBSTR(P_PROJECT_ID, 1, 500)
                                   || ';P_ITEM_ID=' || SUBSTR(P_ITEM_ID, 1, 500), 1, 2000)
                          , TO_CHAR(SQLCODE)
                          , DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                OPEN O_RC FOR SELECT NULL AS DUMMY FROM DUAL WHERE 1 = 0;
                OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR AS MSG FROM DUAL;
            END;
    END P_SCP0110_GET_MODEL_LIST;


    /*
     * Program ID   : SCP0110_SAVE_GROUP_MASTER
     * Description  : GROUP 등록,수정
     * Program History
     *===================================================================================================
     *   Date       In Charge		Description
     *===================================================================================================
     * 2024/05/24   mrchois    PJ20244573 LGES SCM SCP 생산모델 기반 공급계획 수립체계 구성
     * 2025-08-14   twinlove   PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산 - Only Stock(Y/N) 추가 attribute1에 저장
     * 2026.09.17              MSSQL -> Oracle 전환
     *                         - 중복체크 NOT (DIVISION_ID = … AND GROUP_ID = …) 는 신규 행(GROUP_ID 빈 값)도 AS-IS 와 같이
     *                           비교되도록 빈 토큰을 '-' 로 비교
     *                         - GROUP_NAME 중복 비교는 대소문자 무시(칸·입력 UPPER)
     *                         - 신규 등록 시 최종변경자·일시도 기록(시스템 속성 기록 기준)
     *                         - 오류 시 앞 행 저장분까지 되돌림(AS-IS 는 트랜잭션 없이 앞 행이 확정됨)
     */
    PROCEDURE P_SCP0110_SAVE_GROUP_MASTER
    (
        P_ACTIVE_FLAG        IN  CLOB,
        P_DIVISION_ID        IN  CLOB,
        P_OPERATION_GROUP    IN  CLOB,
        P_GROUP_ID           IN  CLOB,
        P_GROUP_NAME         IN  CLOB,
        P_VALID_YN           IN  CLOB,
        P_USER_ID            IN  VARCHAR2,
        P_ONLY_STOCK         IN  CLOB,    -- PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산
        O_RESULT_CURSOR      OUT SYS_REFCURSOR
    )
    IS
        -- LOG 용 변수 설정
        V_PROGRAM_NAME       VARCHAR2(150 CHAR) := C_PKG_NAME || '.P_SCP0110_SAVE_GROUP_MASTER';
        -- 예외처리 변수 설정
        V_MSG                VARCHAR2(4000 CHAR);
        V_BACKTRACE          VARCHAR2(4000 CHAR);
        V_IN_PARA            VARCHAR2(4000 CHAR);
        E_USER               EXCEPTION;
        V_MAX_LOOP_CNT       PLS_INTEGER := 0;
        V_N                  PLS_INTEGER;
        V_DATA_DUP_CNT       PLS_INTEGER := 0;
        V_MAX_NUM            VARCHAR2(4000 CHAR);

        T_ACTIVE_FLAG        T_TOKEN_TAB;
        T_DIVISION_ID        T_TOKEN_TAB;
        T_OPERATION_GROUP    T_TOKEN_TAB;
        T_GROUP_ID           T_TOKEN_TAB;
        T_GROUP_NAME         T_TOKEN_TAB;
        T_VALID_YN           T_TOKEN_TAB;
        T_ONLY_STOCK         T_TOKEN_TAB;

        V_ACTIVE_FLAG        VARCHAR2(4000 CHAR);
        V_DIVISION_ID        VARCHAR2(4000 CHAR);
        V_OPERATION_GROUP    VARCHAR2(4000 CHAR);
        V_GROUP_ID           VARCHAR2(4000 CHAR);
        V_GROUP_NAME         VARCHAR2(4000 CHAR);
        V_GROUP_NAME_EMPTY   VARCHAR2(1 CHAR);
        V_VALID_YN           VARCHAR2(4000 CHAR);
        V_ONLY_STOCK         VARCHAR2(4000 CHAR);    -- PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산
    BEGIN

        SAVEPOINT SP_SCP0110_SAVE;

        V_IN_PARA := SUBSTR(F_PARA('P_ACTIVE_FLAG', P_ACTIVE_FLAG)
                         || F_PARA('P_DIVISION_ID', P_DIVISION_ID)
                         || F_PARA('P_OPERATION_GROUP', P_OPERATION_GROUP)
                         || F_PARA('P_GROUP_ID', P_GROUP_ID)
                         || F_PARA('P_GROUP_NAME', P_GROUP_NAME)
                         || F_PARA('P_VALID_YN', P_VALID_YN)
                         || 'P_USER_ID=' || P_USER_ID || ';'
                         || F_PARA('P_ONLY_STOCK', P_ONLY_STOCK), 1, 4000);

        -- 시작 LOG
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'START', 0, '########## Start of procedure ##########', '', SYSDATE);

        -- 프로시저 LOOP 길이를 판단
        P_SPLIT(P_ACTIVE_FLAG,     '^', T_ACTIVE_FLAG,     V_MAX_LOOP_CNT);
        P_SPLIT(P_DIVISION_ID,     '^', T_DIVISION_ID,     V_N);
        P_SPLIT(P_OPERATION_GROUP, '^', T_OPERATION_GROUP, V_N);
        P_SPLIT(P_GROUP_ID,        '^', T_GROUP_ID,        V_N);
        P_SPLIT(P_GROUP_NAME,      '^', T_GROUP_NAME,      V_N);
        P_SPLIT(P_VALID_YN,        '^', T_VALID_YN,        V_N);
        P_SPLIT(P_ONLY_STOCK,      '^', T_ONLY_STOCK,      V_N);

        IF F_HAS_TEXT(P_ACTIVE_FLAG) THEN

            FOR I IN 1 .. V_MAX_LOOP_CNT LOOP

                -- 각 컬럼들에 대한 스플릿처리로직 스타트
                V_ACTIVE_FLAG      := UPPER(F_KEY(T_ACTIVE_FLAG, I));
                V_DIVISION_ID      := F_KEY(T_DIVISION_ID, I);
                V_OPERATION_GROUP  := F_KEY(T_OPERATION_GROUP, I);
                V_GROUP_ID         := F_KEY(T_GROUP_ID, I);
                V_GROUP_NAME       := F_TK(T_GROUP_NAME, I);
                V_GROUP_NAME_EMPTY := CASE WHEN T_GROUP_NAME.EXISTS(I) AND T_GROUP_NAME(I) IS NULL THEN 'Y' ELSE 'N' END;
                V_VALID_YN         := F_KEY(T_VALID_YN, I);
                V_ONLY_STOCK       := F_TK(T_ONLY_STOCK, I);    -- PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산

                IF V_ACTIVE_FLAG <> 'D' THEN

                    -- GROUP NAME 중복체크
                    SELECT COUNT(*)
                      INTO V_DATA_DUP_CNT
                      FROM SCP_MST_ITEM_GROUP
                     WHERE DIVISION_ID = UPPER(V_DIVISION_ID)
                       AND (UPPER(GROUP_NAME) = UPPER(V_GROUP_NAME)
                            OR (V_GROUP_NAME_EMPTY = 'Y' AND GROUP_NAME IS NULL))
                       AND NOT (DIVISION_ID = UPPER(V_DIVISION_ID)   -- PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산
                            AND GROUP_ID = UPPER(V_GROUP_ID))        -- PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산
                       AND ROWNUM = 1;

                    IF V_DATA_DUP_CNT > 0 THEN
                        V_MSG := C_MSG_DUP_NAME;
                        RAISE E_USER;    --예외발생
                    END IF;

                END IF;

                --데이터 저장
                -- GROUP_NAME 수정
                IF V_ACTIVE_FLAG = 'M' THEN

                    UPDATE SCP_MST_ITEM_GROUP
                       SET GROUP_NAME       = V_GROUP_NAME
                         , OPERATION_GROUP  = V_OPERATION_GROUP
                         , ATTRIBUTE1       = V_ONLY_STOCK          -- PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산
                         , LAST_UPDATED_BY  = P_USER_ID
                         , LAST_UPDATE_DATE = SYSDATE
                     WHERE DIVISION_ID = UPPER(V_DIVISION_ID)
                       AND GROUP_ID    = UPPER(V_GROUP_ID);

                ELSIF V_ACTIVE_FLAG = 'I' THEN

                    -- GROUP_ID 채번값 구하기
                    -- 내부번호를 위한 카운트 설정-- 키값에 'G'에 0으로 4자리 채우고 1씩 증가시킴?
                    SELECT TO_CHAR(TO_NUMBER(MAX(SUBSTR(GROUP_ID, 2, 5))) + 1)
                      INTO V_MAX_NUM
                      FROM SCP_MST_ITEM_GROUP;

                    V_GROUP_ID := CASE WHEN V_MAX_NUM IS NOT NULL
                                       THEN 'G' || LPAD(V_MAX_NUM, 5, '0')
                                  END;

                    INSERT INTO SCP_MST_ITEM_GROUP
                    (
                        DIVISION_ID
                      , OPERATION_GROUP
                      , GROUP_ID
                      , GROUP_NAME
                      , VALID_YN
                      , ATTRIBUTE1      -- PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                    )
                    VALUES
                    (
                        V_DIVISION_ID
                      , V_OPERATION_GROUP
                      , V_GROUP_ID
                      , V_GROUP_NAME
                      , V_VALID_YN
                      , V_ONLY_STOCK    -- PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산
                      , P_USER_ID
                      , SYSDATE
                      , P_USER_ID
                      , SYSDATE
                    );

                ELSIF V_ACTIVE_FLAG = 'D' THEN

                    --Group 삭제 시 Group - model Mapping 정보 삭제
                    UPDATE SCP_MST_ITEM_GROUP_DETAIL
                       SET GROUP_ID         = NULL
                         , LAST_UPDATED_BY  = P_USER_ID
                         , LAST_UPDATE_DATE = SYSDATE
                     WHERE DIVISION_ID = UPPER(V_DIVISION_ID)
                       AND GROUP_ID    = UPPER(V_GROUP_ID);

                    DELETE FROM SCP_MST_ITEM_GROUP
                     WHERE DIVISION_ID = UPPER(V_DIVISION_ID)
                       AND GROUP_ID    = UPPER(V_GROUP_ID);

                END IF;

            END LOOP;

        END IF;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', '', SYSDATE);

        COMMIT;

        -- 결과코드, 결과 카운트 반환
        P_RESULT_OK(O_RESULT_CURSOR, V_MAX_LOOP_CNT);

    EXCEPTION
        WHEN E_USER THEN
            P_ROLLBACK_SAVE;
            P_LOG_ERROR(V_PROGRAM_NAME, V_MSG, V_IN_PARA, '99010', NULL);
            -- error코드, errror 메시지 반환
            P_RESULT_ERR(O_RESULT_CURSOR, V_MSG);
        WHEN OTHERS THEN
            V_MSG       := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;
            V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            P_ROLLBACK_SAVE;
            P_LOG_ERROR(V_PROGRAM_NAME, V_MSG, V_IN_PARA, TO_CHAR(SQLCODE), V_BACKTRACE);
            -- error코드, errror 메시지 반환
            P_RESULT_ERR(O_RESULT_CURSOR, V_MSG);
    END P_SCP0110_SAVE_GROUP_MASTER;


    /*
     * Program ID   : [SCP0110_SAVE_MODEL_LIST]
     * Description  : Model List의 GROUP 지정(수정)
     * Program History
     *===================================================================================================
     *   Date       In Charge		Description
     *===================================================================================================
     * 2024/05/24   mrchois    PJ20244573 LGES SCM SCP 생산모델 기반 공급계획 수립체계 구성
     * 2026.09.17              MSSQL -> Oracle 전환
     *                         - PROJECT_CODE · ITEM_ID 비교는 소문자 행이 있어 칸·입력 모두 UPPER
     *                         - 오류 시 앞 행 저장분까지 되돌림(AS-IS 는 트랜잭션 없이 앞 행이 확정됨)
     */
    PROCEDURE P_SCP0110_SAVE_MODEL_LIST
    (
        P_ACTIVE_FLAG        IN  CLOB,
        P_DIVISION_ID        IN  CLOB,
        P_PROJECT_CODE       IN  CLOB,
        P_ITEM_ID            IN  CLOB,
        P_GROUP_ID           IN  CLOB,
        P_USER_ID            IN  VARCHAR2,
        O_RESULT_CURSOR      OUT SYS_REFCURSOR
    )
    IS
        -- LOG 용 변수 설정
        V_PROGRAM_NAME       VARCHAR2(150 CHAR) := C_PKG_NAME || '.P_SCP0110_SAVE_MODEL_LIST';
        -- 예외처리 변수 설정
        V_MSG                VARCHAR2(4000 CHAR);
        V_BACKTRACE          VARCHAR2(4000 CHAR);
        V_IN_PARA            VARCHAR2(4000 CHAR);
        E_USER               EXCEPTION;
        V_MAX_LOOP_CNT       PLS_INTEGER := 0;
        V_N                  PLS_INTEGER;
        V_DATA_DUP_CNT       PLS_INTEGER := 0;

        T_ACTIVE_FLAG        T_TOKEN_TAB;
        T_DIVISION_ID        T_TOKEN_TAB;
        T_PROJECT_CODE       T_TOKEN_TAB;
        T_ITEM_ID            T_TOKEN_TAB;
        T_GROUP_ID           T_TOKEN_TAB;

        V_ACTIVE_FLAG        VARCHAR2(4000 CHAR);
        V_DIVISION_ID        VARCHAR2(4000 CHAR);
        V_PROJECT_CODE       VARCHAR2(4000 CHAR);
        V_ITEM_ID            VARCHAR2(4000 CHAR);
        V_GROUP_ID           VARCHAR2(4000 CHAR);
    BEGIN

        SAVEPOINT SP_SCP0110_SAVE;

        V_IN_PARA := SUBSTR(F_PARA('P_ACTIVE_FLAG', P_ACTIVE_FLAG)
                         || F_PARA('P_DIVISION_ID', P_DIVISION_ID)
                         || F_PARA('P_PROJECT_CODE', P_PROJECT_CODE)
                         || F_PARA('P_ITEM_ID', P_ITEM_ID)
                         || F_PARA('P_GROUP_ID', P_GROUP_ID)
                         || 'P_USER_ID=' || P_USER_ID || ';', 1, 4000);

        -- 시작 LOG
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'START', 0, '########## Start of procedure ##########', '', SYSDATE);

        -- 프로시저 LOOP 길이를 판단
        P_SPLIT(P_ACTIVE_FLAG,  '^', T_ACTIVE_FLAG,  V_MAX_LOOP_CNT);
        P_SPLIT(P_DIVISION_ID,  '^', T_DIVISION_ID,  V_N);
        P_SPLIT(P_PROJECT_CODE, '^', T_PROJECT_CODE, V_N);
        P_SPLIT(P_ITEM_ID,      '^', T_ITEM_ID,      V_N);
        P_SPLIT(P_GROUP_ID,     '^', T_GROUP_ID,     V_N);

        IF F_HAS_TEXT(P_ACTIVE_FLAG) THEN

            FOR I IN 1 .. V_MAX_LOOP_CNT LOOP

                -- 각 컬럼들에 대한 스플릿처리로직 스타트
                V_ACTIVE_FLAG  := UPPER(F_KEY(T_ACTIVE_FLAG, I));
                V_DIVISION_ID  := F_KEY(T_DIVISION_ID, I);
                V_PROJECT_CODE := F_KEY(T_PROJECT_CODE, I);
                V_ITEM_ID      := F_KEY(T_ITEM_ID, I);
                --공백일 경우 NULL로 변경 -> 정렬때문에
                V_GROUP_ID     := F_TK(T_GROUP_ID, I);

                -- GROUP 중복체크(Project 가 다른 아이템을 서로 한 개 Group으로 지정 불가)
                SELECT COUNT(*)
                  INTO V_DATA_DUP_CNT
                  FROM SCP_MST_ITEM_GROUP_DETAIL
                 WHERE DIVISION_ID         = UPPER(V_DIVISION_ID)
                   AND UPPER(PROJECT_CODE) <> UPPER(V_PROJECT_CODE)
                   AND GROUP_ID            = UPPER(V_GROUP_ID)
                   AND ROWNUM = 1;

                IF V_DATA_DUP_CNT > 0 THEN
                    V_MSG := C_MSG_DUP_PROJECT;
                    RAISE E_USER;    --예외발생
                END IF;

                --데이터 저장
                -- GROUP_ID 수정
                IF V_ACTIVE_FLAG = 'M' THEN

                    UPDATE SCP_MST_ITEM_GROUP_DETAIL
                       SET GROUP_ID         = V_GROUP_ID
                         , LAST_UPDATED_BY  = P_USER_ID
                         , LAST_UPDATE_DATE = SYSDATE
                     WHERE DIVISION_ID         = UPPER(V_DIVISION_ID)
                       AND UPPER(PROJECT_CODE) = UPPER(V_PROJECT_CODE)
                       AND UPPER(ITEM_ID)      = UPPER(V_ITEM_ID);

                END IF;

            END LOOP;

        END IF;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', '', SYSDATE);

        COMMIT;

        -- 결과코드, 결과 카운트 반환
        P_RESULT_OK(O_RESULT_CURSOR, V_MAX_LOOP_CNT);

    EXCEPTION
        WHEN E_USER THEN
            P_ROLLBACK_SAVE;
            P_LOG_ERROR(V_PROGRAM_NAME, V_MSG, V_IN_PARA, '99010', NULL);
            -- error코드, errror 메시지 반환
            P_RESULT_ERR(O_RESULT_CURSOR, V_MSG);
        WHEN OTHERS THEN
            V_MSG       := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;
            V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            P_ROLLBACK_SAVE;
            P_LOG_ERROR(V_PROGRAM_NAME, V_MSG, V_IN_PARA, TO_CHAR(SQLCODE), V_BACKTRACE);
            -- error코드, errror 메시지 반환
            P_RESULT_ERR(O_RESULT_CURSOR, V_MSG);
    END P_SCP0110_SAVE_MODEL_LIST;

END PKG_SCP0110;

