        || '<th>' || 'Div' || '</th>'
        || '<th width=''100px''>' || 'From Site' || '</th>'
        || '<th>' || 'Model' || '</th>'
        || '<th>' || 'Nick Name' || '</th>'
        || '<th>' || 'Requestor' || '</th>'
        || '<th>' || 'To Site*' || '</th>'
        || '<th>' || 'End Customer*' || '</th>'
        || '<th>' || 'FCST Type*' || '</th>'
        || '<th>' || 'Incoterms*' || '</th>'
        || '<th>' || 'Trans Mode*' || '</th>'
        || '<th width=''100px''>' || 'Date' || '</th>'
        || '<th width=''90px''>' || 'Qty' || '</th>'
        || '</tr>';

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    FOR RCV IN ( SELECT   MAIL_RECEIVER
                   FROM   SSP_MAIL_SHIP_REQ_DELETE_V
                  WHERE   COMPANY_ID = P_COMPANY_ID1
                  GROUP BY MAIL_RECEIVER
                  ORDER BY MAIL_RECEIVER ) LOOP


        IF V_MAILSENDCNT = 10 THEN
            DBMS_SESSION.SLEEP(5);
            V_MAILSENDCNT := 0;
        END IF;

        V_TO_MAIL := RCV.MAIL_RECEIVER || '@lgensol.com';

        V_TABLE_BODY := '
			<html>
				<head>
					<title>Untitled Document</title>
					<meta charset="UTF-8">
					<style>
						* {margin:0;padding:0;}
						body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
						table {border-collapse:collapse;width:100%;}
						table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
						table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
						table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
						table tbody td {padding:6px 8px;font-size:12px}
						table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
						.hori-table table thead td {text-align:center;padding:3px;}
						.hori-table table tbody td {text-align:center;padding:3px;}
						.vertical-table, .hori-table {margin-bottom:20px;}
					</style>
				</head>
				<body>' || '</br>' ||
            '<b>' || REPLACE(NVL(V_BODY_TEXT, ' '), CHR(10), '<br>') || '</b>' ||
            '<div id="divBody" style="width: 100%; overflow-x: auto; overflow-y: auto; font-size: 9pt; line-break: auto;">' ||
            '<table style=''border-top:2px solid #c8294b; width:1200px;''>
								<thead>' || NVL(V_HEAD_CONT, ' ') || '</thead> ';

        FOR D IN ( SELECT   DIVISION_ID
                          , FROM_SITE_DESCRIPTION
                          , ITEM_ID
                          , NICK_NAME
                          , REQUESTOR
                          , TO_SITE_DESCRIPTION
                          , END_CUSTOMER
                          , FCST_TYPE
                          , INCOTERMS
                          , TRANSPORT_MODE
                          , SUBSTR(YYYYMMDD, 1, 4) || '-' || SUBSTR(YYYYMMDD, 5, 2) || '-' || SUBSTR(YYYYMMDD, 7, 2) AS YMD_FMT
                          , QTY
                     FROM   SSP_MAIL_SHIP_REQ_DELETE_V
                    WHERE   1 = 1
                      AND   COMPANY_ID    = P_COMPANY_ID1
                      AND   MAIL_RECEIVER = RCV.MAIL_RECEIVER
                    ORDER BY DIVISION_ID, FROM_SITE, ITEM_ID, REQUESTOR, TO_SITE, END_CUSTOMER, FCST_TYPE, INCOTERMS, TRANSPORT_MODE, YYYYMMDD ) LOOP

            V_BODY_CONT := '<tr>' || CHR(13)
                || '<td>' || REPLACE(NVL(D.DIVISION_ID, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.FROM_SITE_DESCRIPTION, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.ITEM_ID, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.NICK_NAME, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.REQUESTOR, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.TO_SITE_DESCRIPTION, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.END_CUSTOMER, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.FCST_TYPE, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.INCOTERMS, ' '), CHR(10), ' ') || '</td>'
                || '<td>' || REPLACE(NVL(D.TRANSPORT_MODE, ' '), CHR(10), ' ') || '</td>'
                || '<td align=''center''>' || REPLACE(NVL(D.YMD_FMT, ' '), CHR(10), ' ') || '</td>'
                || '<td align=''right''>' || REPLACE(NVL(REPLACE(TO_CHAR(D.QTY, 'FM999,999,999,990.00'), '.00', ''), ' '), CHR(10), ' ') || '</td>'
                || '</tr>';

            V_TABLE_BODY := V_TABLE_BODY || NVL(V_BODY_CONT, ' ') || CHR(13);

            V_DIVISION_ID           := D.DIVISION_ID;
            V_FROM_SITE_DESCRIPTION := D.FROM_SITE_DESCRIPTION;
            V_ITEM_ID               := D.ITEM_ID;
            V_NICK_NAME             := D.NICK_NAME;
        END LOOP;

        V_TABLE_BODY := V_TABLE_BODY || '</br></tbody> </div> </body> </html>';


        PKG_SEND_MAIL.P_SEND_MAIL(V_TO_MAIL, V_MAIL_TITLE, DBMS_LOB.SUBSTR(V_TABLE_BODY, 32767, 1), 'Y');

        /* MAIL 발송 LOG 저장 */
        SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', NULL, V_PROGRAM_NAME, V_MAIL_TITLE, V_DIVISION_ID, V_FROM_SITE_DESCRIPTION, V_ITEM_ID, V_NICK_NAME, NULL, NULL, NULL, NULL, NULL, V_TO_MAIL);

        V_MAILSENDCNT := V_MAILSENDCNT + 1;
    END LOOP;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN
        V_ERROR_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

        V_DESCRIPTION := V_PROGRAM_NAME || 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 400);

        INSERT INTO SCM_SYS_LOG_BATCH
               ( PROGRAM_NAME
               , LOG_TYPE
               , LOG_COUNT
               , LOG_MESSAGE
               , DESCRIPTION
               , EVENT_DATE
               , CREATION_DATE
               , CREATED_BY
               , LAST_UPDATE_DATE
               , LAST_UPDATED_BY )
        VALUES ( V_PROGRAM_NAME
               , 'ERROR'
               , NULL
               , V_ERROR_MESSAGE
               , V_DESCRIPTION
               , SYSDATE
               , SYSDATE
               , V_PROGRAM_NAME
               , SYSDATE
               , V_PROGRAM_NAME );
        COMMIT;

        /* MAIL 발송 LOG 저장 (원본 CATCH 두번째 블록) */
        SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL', NULL, V_PROGRAM_NAME, V_MAIL_TITLE, V_DIVISION_ID, V_FROM_SITE_DESCRIPTION, V_ITEM_ID, V_NICK_NAME, NULL, NULL, NULL, NULL, NULL, V_TO_MAIL);
        COMMIT;


        P_LOG_MESSGE := V_ERROR_MESSAGE;
END PR_SSP_MAIL_SEND_SHIP_REQ_DELETE;

SCM_MGR|PROCEDURE|SCM0001_GET_DIVISION:
PROCEDURE           "SCM0001_GET_DIVISION" 
(
    O_RC1             OUT SYS_REFCURSOR,
    O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
/*
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2026.05.19  최용훈           MS-SQL -> Oracle 변환
 *
 */
AS
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
BEGIN

    OPEN O_RC1 FOR
    SELECT DIVISION_ID   AS CODE
         , DIVISION_NAME AS NAME
    FROM SCM_MST_DIVISION;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        V_SQL_CODE   := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG := SQLERRM;
        V_PROC_INPUT := '';
        V_BACKTRACE  := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                $$PLSQL_UNIT, 'ERROR', N_LOG_COUNT, 'EXCEPTION',
                '', SYSDATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        RAISE_APPLICATION_ERROR(-20001,
            '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
        RAISE;

END SCM0001_GET_DIVISION;

SCM_MGR|PROCEDURE|SCM_SSP_MAIL_SEND:
PROCEDURE SCM_SSP_MAIL_SEND
(
  P_REQUEST_NO      IN VARCHAR2
, P_REQUEST_STATUS  IN VARCHAR2
)
IS
/*
 * Program ID   : SCM_SSP_MAIL_SEND
 * Description  : 출하 변경 요청 상태별 메일 발송
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    V_TO_MAIL               VARCHAR2(4000 CHAR);
    V_CATEGORY_ID           NUMBER := 0;
    V_APPROVAL_ID           VARCHAR2(4000 CHAR);
    V_REQUEST_ID            VARCHAR2(4000 CHAR);
    V_MAIL_TITLE            VARCHAR2(4000 CHAR);
    V_BODY_CONTENTS         VARCHAR2(32767 CHAR);
    V_BODY_TEXT             VARCHAR2(32767 CHAR);
    V_HEAD_CONT             VARCHAR2(32767 CHAR);
    V_A_BODY_CONTENTS       VARCHAR2(32767 CHAR);
    V_TABLE_BODY            VARCHAR2(32767 CHAR);
    V_HTML_YN               VARCHAR2(1 CHAR);
    V_DIVISION_ID           VARCHAR2(120 CHAR);
    V_DELEGATEE             VARCHAR2(4000 CHAR);

    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'SCM_SSP_MAIL_SEND';
    V_LOG_TYPE              VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    V_N_LOG_COUNT           NUMBER := 0;
    V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
    V_DESCRIPTION           VARCHAR2(500 CHAR);
    V_EVENT_DATE            DATE;

    V_CHK                   PLS_INTEGER := 0;   /* 쿼리결과 총 건수 */
    V_MAIL_CHK_CNT          PLS_INTEGER := 0;

    /* AS-IS #TblSSPApprovedMailSend — 한 번 읽어 순서대로 쓰므로 컬렉션으로 옮긴다 */
    TYPE T_MAIL_REC IS RECORD
    (
        DIVISION_ID             VARCHAR2(4000 CHAR)
      , ITEM_ID                 VARCHAR2(4000 CHAR)
      , NICK_NAME               VARCHAR2(4000 CHAR)
      , FROM_SITE               VARCHAR2(4000 CHAR)
      , FROM_SITE_DESCRIPTION   VARCHAR2(4000 CHAR)
      , TO_SITE                 VARCHAR2(4000 CHAR)
      , TO_SITE_DESCRIPTION     VARCHAR2(4000 CHAR)
      , MTK_OWNER               VARCHAR2(4000 CHAR)
      , INCOTERMS               VARCHAR2(4000 CHAR)
      , YYYYMMDD                VARCHAR2(4000 CHAR)
      , QTY                     VARCHAR2(4000 CHAR)
      , TRANSPORT_MODE          VARCHAR2(4000 CHAR)
      , NEW_YYYYMMDD            VARCHAR2(4000 CHAR)
      , NEW_QTY                 VARCHAR2(4000 CHAR)
      , NEW_TRANSPORT_MODE      VARCHAR2(4000 CHAR)
      , CONFIRM_ID              VARCHAR2(4000 CHAR)
      , ERP_DO_NO               VARCHAR2(4000 CHAR)
      , VALID                   VARCHAR2(4000 CHAR)
      , LAST_UPDATE_DATE        VARCHAR2(4000 CHAR)
      , LAST_UPDATED_BY         VARCHAR2(4000 CHAR)
    );
    TYPE T_MAIL_TAB IS TABLE OF T_MAIL_REC INDEX BY PLS_INTEGER;
    V_MAIL                  T_MAIL_TAB;
BEGIN

    IF P_REQUEST_STATUS = 'Q' THEN        /*출하 계획 요청*/
        V_CATEGORY_ID := 14;
    ELSIF P_REQUEST_STATUS = 'A' THEN     /*출하 계획 승인*/
        V_CATEGORY_ID := 15;
    ELSIF P_REQUEST_STATUS = 'R' THEN     /*출하 계획 반려*/
        V_CATEGORY_ID := 16;
    ELSIF P_REQUEST_STATUS = 'S' THEN     /*출하 계획 자가반려*/
        V_CATEGORY_ID := 13;
    ELSIF P_REQUEST_STATUS = 'O' THEN     /*출하 계획 D/O 반려*/
        V_CATEGORY_ID := 11;
    ELSIF P_REQUEST_STATUS = 'E' THEN     /*출하 계획 ERP 반려*/
        V_CATEGORY_ID := 9;
    ELSIF P_REQUEST_STATUS = 'P' THEN     /*출하 계획 부분 승인 (2024.04.24, 'P' 추가)*/
        V_CATEGORY_ID := 10;
    END IF;

    BEGIN
        SELECT APPROVAL_USER
             , REQUEST_USER
             , MAIL_TITLE
             , BODY_CONTENTS
          INTO V_APPROVAL_ID
             , V_REQUEST_ID
             , V_MAIL_TITLE
             , V_BODY_CONTENTS
          FROM (SELECT A.APPROVAL_USER
                     , A.REQUEST_USER
                     , A.MAIL_TITLE || '[' || A.CHANGE_REQ_NO || ']' AS MAIL_TITLE
                     , A.BODY_CONTENTS
                  FROM (SELECT IA.APPROVAL_USER
                             , IA.REQUEST_USER
                             , IA.CHANGE_REQ_NO
                             , IA.CHANGE_REQ_STATUS
                             , XA.MAIL_TITLE
                             , XA.BODY_CONTENTS
                          FROM (SELECT A.APPROVAL_USER
                                     , A.REQUEST_USER
                                     , A.CHANGE_REQ_NO
                                     , A.CHANGE_REQ_STATUS
                                     , 'KO' AS LANGUAGE
                                  FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ A
                                     , SCM_ADM_USER_M B
                                 WHERE B.USER_ID = A.REQUEST_USER
                                   AND B.USE_YN = 'Y') IA
                             , (SELECT B.LANGUAGE_CODE
                                     , B.MAIL_TITLE
                                     , CASE A.USE_TYPE_CODE WHEN 'MAIL' THEN REPLACE(B.MESSAGE_CONTENT, CHR(10), '<br><br>')
                                                            WHEN 'SMS' THEN B.MESSAGE_CONTENT
                                       END AS BODY_CONTENTS
                                  FROM SCM_ADM_RECIPIENT_LIST A
                                     , SCM_ADM_RECIPIENT_MESSAGE B
                                     , SCM_ADM_RECIPIENT_ASSIGN C
                                     , SCM_ADM_LOOKUP_MASTER_DETAIL D
                                     , SCM_ADM_USER_M E
                                 WHERE B.CATEGORY_ID = A.CATEGORY_ID
                                   AND C.CATEGORY_ID(+) = B.CATEGORY_ID
                                   AND D.SEGMENT1 = B.LANGUAGE_CODE
                                   AND D.LOOKUP_TYPE = 'MAIL_HEADER_FOOT'
                                   AND D.VALID_YN = 'Y'
                                   AND E.LANG_CD(+) = B.LANGUAGE_CODE
                                   AND E.USER_ID(+) = C.USER_ID
                                   AND A.CATEGORY_ID = TO_CHAR(V_CATEGORY_ID)
                                   AND A.VALID_YN = 'Y') XA
                         WHERE IA.LANGUAGE = XA.LANGUAGE_CODE) A
                 WHERE A.CHANGE_REQ_NO = P_REQUEST_NO
                   AND A.CHANGE_REQ_STATUS = P_REQUEST_STATUS)
         WHERE ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_APPROVAL_ID := NULL;
            V_REQUEST_ID := NULL;
            V_MAIL_TITLE := NULL;
            V_BODY_CONTENTS := NULL;
    END;

    SELECT A.DIVISION_ID
         , A.ITEM_ID
         , A.NICK_NAME
         , A.FROM_SITE
         , A.FROM_SITE_DESCRIPTION
         , A.TO_SITE
         , A.TO_SITE_DESCRIPTION
         , A.MTK_OWNER
         , A.INCOTERMS
         , A.YYYYMMDD
         , A.QTY
         , A.TRANSPORT_MODE
         , A.NEW_YYYYMMDD
         , A.NEW_QTY
         , A.NEW_TRANSPORT_MODE
         , A.CONFIRM_ID
         , A.ERP_DO_NO
         , A.VALID
         , A.LAST_UPDATE_DATE
         , A.LAST_UPDATED_BY
      BULK COLLECT INTO V_MAIL
      FROM (SELECT IA.DIVISION_ID
                 , IA.ITEM_ID
                 , IA.NICK_NAME
                 , IA.FROM_SITE
                 , IA.FROM_SITE_DESCRIPTION
                 , IA.TO_SITE
                 , IA.TO_SITE_DESCRIPTION
                 , IA.MTK_OWNER
                 , IA.INCOTERMS
                 , IA.YYYYMMDD
                 , IA.QTY
                 , IA.TRANSPORT_MODE
                 , IA.NEW_YYYYMMDD
                 , IA.NEW_QTY
                 , IA.NEW_TRANSPORT_MODE
                 , IA.CONFIRM_ID
                 , IA.ERP_DO_NO
                 , IA.VALID
                 , TO_CHAR(IA.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS') || '.000' AS LAST_UPDATE_DATE
                 /* AS-IS 는 문자 결합이라 이름이 없으면 전체가 빈 값이 된다 */
                 , CASE WHEN FN_GET_USER_NAME(IA.LAST_UPDATED_BY) IS NULL OR IA.LAST_UPDATED_BY IS NULL THEN NULL
                        ELSE FN_GET_USER_NAME(IA.LAST_UPDATED_BY) || '(' || IA.LAST_UPDATED_BY || ')'
                   END AS LAST_UPDATED_BY
              FROM (SELECT B.DIVISION_ID
                         , B.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(B.DIVISION_ID, B.ITEM_ID) AS NICK_NAME
                         , B.FROM_SITE
                         , FN_GET_SCM_SITE_DESCRIPTION(B.DIVISION_ID, B.FROM_SITE) AS FROM_SITE_DESCRIPTION
                         , B.TO_SITE
                         , FN_GET_SCM_SITE_DESCRIPTION(B.DIVISION_ID, B.TO_SITE) AS TO_SITE_DESCRIPTION
                         /* 담당자 이름 목록은 CLOB 으로 돌아와 GROUP BY 에 쓸 수 없다 — 문자형으로 바꾼다 */
                         , DBMS_LOB.SUBSTR(FN_GET_SSP_MKT_OWNER_NAME(C.OWNER, ',', 'KO'), 4000, 1) AS MTK_OWNER
                         , B.INCOTERMS
                         , SUBSTR(B.YYYYMMDD, 1, 4) || '-' || SUBSTR(B.YYYYMMDD, 5, 2) || '-' || SUBSTR(B.YYYYMMDD, 7, 2) AS YYYYMMDD
                         , NVL(REPLACE(TRIM(TO_CHAR(B.QTY, 'FM999,999,999,999,990.00')), '.00', ''), '') AS QTY
                         , B.TRANSPORT_MODE
                         , SUBSTR(B.NEW_YYYYMMDD, 1, 4) || '-' || SUBSTR(B.NEW_YYYYMMDD, 5, 2) || '-' || SUBSTR(B.NEW_YYYYMMDD, 7, 2) AS NEW_YYYYMMDD
                         , NVL(REPLACE(TRIM(TO_CHAR(B.NEW_QTY, 'FM999,999,999,999,990.00')), '.00', ''), '') AS NEW_QTY
                         , B.NEW_TRANSPORT_MODE
                         , NVL(D.CONFIRM_ID, '-') AS CONFIRM_ID
                         , NVL(D.ERP_DO_NO, '-') AS ERP_DO_NO
                         , B.VALID_YN AS VALID
                         , CASE WHEN P_REQUEST_STATUS = 'A' THEN A.APPROVAL_TIME
                                WHEN P_REQUEST_STATUS = 'R' THEN A.APPROVAL_TIME
                                ELSE A.LAST_UPDATE_DATE
                           END AS LAST_UPDATE_DATE
                         , CASE WHEN P_REQUEST_STATUS = 'A' THEN CASE WHEN A.DELEGATEE_USER IS NULL THEN A.APPROVAL_USER ELSE A.DELEGATEE_USER END
                                WHEN P_REQUEST_STATUS = 'R' THEN CASE WHEN A.DELEGATEE_USER IS NULL THEN A.APPROVAL_USER ELSE A.DELEGATEE_USER END
                                ELSE A.LAST_UPDATED_BY
                           END AS LAST_UPDATED_BY
                      FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ A
                         , SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE B
                         , SCM_MST_SITE_ITEM C
                         , SSP_ANL_SHIP_CONFIRM D
                     WHERE B.CHANGE_REQ_NO = A.CHANGE_REQ_NO
                       AND C.DIVISION_ID(+) = CASE WHEN B.DIVISION_ID = 'EE' THEN B.ORIGIN_TO_DIVISION_ID ELSE B.DIVISION_ID END
                       AND C.SCM_SITE_ID(+) = B.TO_SITE
                       AND C.ITEM_ID(+) = B.ITEM_ID
                       AND C.PROJECT_CODE(+) = B.PROJECT_CODE
                       AND D.CONFIRM_ID(+) = B.CONFIRM_ID
                       AND A.CHANGE_REQ_STATUS = P_REQUEST_STATUS
                       AND A.CHANGE_REQ_NO = P_REQUEST_NO) IA
             GROUP BY IA.DIVISION_ID
                    , IA.ITEM_ID
                    , IA.NICK_NAME
                    , IA.FROM_SITE
                    , IA.FROM_SITE_DESCRIPTION
                    , IA.TO_SITE
                    , IA.TO_SITE_DESCRIPTION
                    , IA.MTK_OWNER
                    , IA.INCOTERMS
                    , IA.YYYYMMDD
                    , IA.QTY
                    , IA.TRANSPORT_MODE
                    , IA.NEW_YYYYMMDD
                    , IA.NEW_QTY
                    , IA.NEW_TRANSPORT_MODE
                    , IA.CONFIRM_ID
                    , IA.ERP_DO_NO
                    , IA.VALID
                    , IA.LAST_UPDATE_DATE
                    , IA.LAST_UPDATED_BY
             ORDER BY IA.DIVISION_ID
                    , IA.ITEM_ID
                    , IA.FROM_SITE
                    , IA.TO_SITE
                    , IA.YYYYMMDD
                    , IA.TRANSPORT_MODE) A;

    V_CHK := V_MAIL.COUNT;

    V_HEAD_CONT := '';
    V_HEAD_CONT := V_HEAD_CONT || '<tr>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Div' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Model' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Nick Name' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'From Site' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'To Site' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'MKT Owner' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th rowspan=''2''>' || 'Incoterms' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th colspan=''3''>' || 'Old' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th colspan=''3''>' || 'New' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th colspan=''3''>' || 'Common' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '</tr>';
    V_HEAD_CONT := V_HEAD_CONT || '<tr>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Date' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Qty' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Trans Mode' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Date' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''90px''>' || 'Shipment Qty' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Trans Mode' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Confirm Id' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Delivery Order' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '<th width=''80px''>' || 'Approved List' || '</th>';
    V_HEAD_CONT := V_HEAD_CONT || '</tr>';

    V_A_BODY_CONTENTS := '';
    V_BODY_TEXT := '';

    V_MAIL_CHK_CNT := 1;   /* 한 행 FETCH시 마다 +1 */

    IF V_MAIL.EXISTS(1) THEN
        V_DIVISION_ID := V_MAIL(1).DIVISION_ID;
    END IF;

    WHILE V_MAIL_CHK_CNT <= V_CHK + 1 LOOP
        IF V_MAIL_CHK_CNT = 1 AND V_MAIL.EXISTS(1) THEN
            V_BODY_TEXT := V_BODY_TEXT || 'Last updated by : ' || V_MAIL(1).LAST_UPDATED_BY
                                       || '    Last update Date : ' || V_MAIL(1).LAST_UPDATE_DATE || '</br>';
        END IF;

        IF V_MAIL_CHK_CNT = V_CHK + 1 THEN
            V_TABLE_BODY := '';
            V_TABLE_BODY := ' <html>
                        <head>
                        <title>Untitled Document</title>
                        <style>
                          * {margin:0;padding:0;}
                          body {font-family:Malgun Gothic, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.8;color:#333333;}
                          table {border-collapse:collapse;width:100%;}
                          table th {background:#f5f5f5;border-bottom:1px solid #e1e1e1;}
                          table td {background:#fff;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1;border-bottom:1px solid #e1e1e1;}
                          table tbody th {border-left:1px solid #e1e1e1;text-align:right;padding:6px 8px;font-size:12px}
                          table tbody td {padding:6px 8px;font-size:12px}
                          table thead th {text-align:center;padding:3px;border-right:1px solid #e1e1e1;border-left:1px solid #e1e1e1; border-bottom:1px solid #d1d1d1;font-size:12px}
                          .hori-table table thead td {text-align:center;padding:3px;}
                          .hori-table table tbody td {text-align:center;padding:3px;}
                          .vertical-table, .hori-table {margin-bottom:20px;}
                        </style>
                        </head>
                        <body>' || '</br>'
                || '<b>' || REPLACE(NVL(V_BODY_CONTENTS, ''), CHR(10), '<br>') || '</b>' || '</br>' || '</br>'
                || '<b>' || REPLACE(NVL(V_BODY_TEXT, ''), CHR(10), '<br>') || '</b>'
                || '<table style=''border-top:2px solid #c8294b; width:1200px;''>
                      <thead>' || NVL(V_HEAD_CONT, '') || '</thead>
                      <tbody>' || NVL(V_A_BODY_CONTENTS, '') || '</tbody>
                      </div>
                    </body>
                </html>';

            EXIT;
        END IF;

        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<tr>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).DIVISION_ID, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).ITEM_ID, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).NICK_NAME, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).FROM_SITE_DESCRIPTION, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).TO_SITE_DESCRIPTION, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).MTK_OWNER, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).INCOTERMS, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''center''>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).YYYYMMDD, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''right''>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).QTY, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).TRANSPORT_MODE, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''center''>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).NEW_YYYYMMDD, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td align=''right''>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).NEW_QTY, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).NEW_TRANSPORT_MODE, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).CONFIRM_ID, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).ERP_DO_NO, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '<td>' || REPLACE(NVL(V_MAIL(V_MAIL_CHK_CNT).VALID, ''), CHR(10), ' ') || '</td>';
        V_A_BODY_CONTENTS := V_A_BODY_CONTENTS || '</tr>';

        V_MAIL_CHK_CNT := V_MAIL_CHK_CNT + 1;
    END LOOP;

    BEGIN
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        V_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

        IF P_REQUEST_STATUS = 'Q' THEN                              /*출하 계획 요청*/
            V_TO_MAIL := V_APPROVAL_ID || '@lgensol.com';
        ELSIF P_REQUEST_STATUS IN ('A', 'P') THEN                   /*출하 계획 승인(2024.04.24, 'P' 추가)*/
            V_TO_MAIL := V_REQUEST_ID || '@lgensol.com';
        ELSIF P_REQUEST_STATUS = 'R' OR P_REQUEST_STATUS = 'O' OR P_REQUEST_STATUS = 'E' THEN   /*출하 계획 반려*/
            V_TO_MAIL := V_REQUEST_ID || '@lgensol.com';
        ELSIF P_REQUEST_STATUS = 'S' THEN                           /*출하 계획 자가반려*/
            V_TO_MAIL := V_APPROVAL_ID || '@lgensol.com';
        END IF;

        V_BODY_CONTENTS := V_TABLE_BODY;
        V_HTML_YN := 'Y';

        SCM_ADM_MAIL_SEND(V_TO_MAIL, V_MAIL_TITLE, V_BODY_CONTENTS, V_HTML_YN);

        IF P_REQUEST_STATUS = 'Q' OR P_REQUEST_STATUS = 'S' THEN    /*출하 계획 요청 or 출하 계획 자가반려*/
            V_DELEGATEE := NULL;

            BEGIN
                SELECT DELEGATEE_ID
                  INTO V_DELEGATEE
                  FROM (SELECT DELEGATEE_ID
                          FROM SSP_MST_DELEGATE
                         WHERE DIVISION_ID = V_DIVISION_ID
                           AND USER_ID = V_APPROVAL_ID
                           AND VALID_YN = 'Y'
                           AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_DATE AND TO_DATE
                         GROUP BY DELEGATEE_ID)
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_DELEGATEE := NULL;
            END;

            IF LENGTH(RTRIM(V_DELEGATEE)) IS NOT NULL THEN
                V_TO_MAIL := V_DELEGATEE || '@lgensol.com';
                SCM_ADM_MAIL_SEND(V_TO_MAIL, V_MAIL_TITLE, V_BODY_CONTENTS, V_HTML_YN);
            END IF;
        END IF;

        SCM_ADM_SAVE_MAIL_SEND_BATCH_LOG('MAIL'
                                       , V_CATEGORY_ID
                                       , V_MAIL_TITLE
                                       , V_BODY_CONTENTS
                                       , ''
                                       , ''
                                       , ''
                                       , ''
                                       , ''
                                       , ''
                                       , ''
                                       , ''
                                       , ''   /*p_send_pgm*/
                                       , V_TO_MAIL);

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        V_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
    EXCEPTION
        WHEN OTHERS THEN
            /* AS-IS CATCH 는 이력만 남기고 확정한다 — 부르는 쪽으로 오류를 넘기지 않는다 */
            PR_SSP_LOG_ERROR(V_PROGRAM_NAME, SUBSTR(SQLERRM, 1, 1000));
    END;

END SCM_SSP_MAIL_SEND;

SCM_MGR|VIEW|SSP_DNM_SHIP_RESULT_ERP_COM:
SELECT /*
 * Program ID   : SSP_DNM_SHIP_RESULT_ERP_COMMON_SCM_V
 * Description  : ERP 출하실적을 전사 SCM 에 제공한다
                  소속 DIVISION_ID 정보를 조회 하기 위해서
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2025.05.14 _ERP_DW_V에서 복사하여 전사SCM용으로 신규 생성 (심재만 책임 요청)
 * 2025.06.19 ssp 출하실적 view 기준으로 수정
 * 2026.02.12	강주용		E20260211-001000 SSP ERP 출하실적 차이 수정
 * 2026.07.06  ZIONEX   [PJ202650304]  NextSCM Migration
*/
	   D.ATTRIBUTE3		AS DIVISION_ID
	  ,X.COMPANY_ID
	  ,X.PLANT_ID
	  ,X.ORDER_NO
	  ,X.DELIVERY_NO
	  ,X.DELIVERY_ITEM_SEQ
	  ,X.ITEM_ID
	  ,X.PROJET_CODE
	  ,X.FROM_SITE
	  ,X.TO_SITE
	  ,X.YYYYMMDD
	  ,X.RESULT_QTY
	  ,X.SHIPTO_CODE
	  ,X.TRANSPORT_MODE
	  ,X.INCOTERMS
	  ,X.CONFIRM_ID
	  ,X.FCST_TYPE
	  ,X.CURRENCY_CODE
	  ,X.NET_PRICE
	  ,X.SALES_AMOUNT
	  ,X.KRW_XRATE
	  ,X.SALES_KRW_AMOUNT
	  ,X.DIVISION_ID	AS SCM_DIVISION_ID
	  ,X.ORDER_TYPE_CODE
  FROM (
		SELECT  E.DIVISION_ID             AS DIVISION_ID
		,       E.COMPANY_ID              AS COMPANY_ID
		,       E.PLANT_ID                AS PLANT_ID
		,       E.ORDER_NO                AS ORDER_NO
		,       E.DELIVERY_NO             AS DELIVERY_NO
		,       E.DELIVERY_ITEM_SEQ       AS DELIVERY_ITEM_SEQ
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
        /* ,       C.ITEM_ID                 AS ITEM_ID */
		,       E.ITEM_ID                 AS ITEM_ID
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
		,       CASE WHEN E.DIVISION_ID = '40' THEN '-'
		             ELSE NVL(E.PROJECT_CODE,'-') END     AS PROJET_CODE
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
        /* ,       C.FROM_SITE               AS FROM_SITE */
        /* ,       C.TO_SITE                 AS TO_SITE */
		,       E.FROM_SCM_SITE_ID        AS FROM_SITE
		,       E.TO_SCM_SITE_ID          AS TO_SITE
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
		,       E.EXFACTORY_DATE          AS YYYYMMDD
		,       E.EXFACTORY_QTY           AS RESULT_QTY
		,       E.SHIPTO_CODE             AS SHIPTO_CODE
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
		/* ,       C.TRANSPORT_MODE          AS TRANSPORT_MODE */
		/* ,       C.INCOTERMS               AS INCOTERMS */
		,       E.TRANSPORT_MODE          AS TRANSPORT_MODE
		,       E.INCOTERMS               AS INCOTERMS
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
		,       E.CONFIRM_ID              AS CONFIRM_ID
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
		/* ,       C.FCST_TYPE               AS FCST_TYPE */
		,       '-'							AS FCST_TYPE
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
		,       E.CURRENCY_CODE
		,       E.NET_PRICE
		,       E.SALES_AMOUNT
		,       E.KRW_XRATE
		,       E.SALES_KRW_AMOUNT
		, E.ORDER_TYPE_CODE AS ORDER_TYPE_CODE
		FROM SCM_DNM_EXFACTORY_RESULT E
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
		/* JOIN SSP_ANL_SHIP_CONFIRM C WITH(NOLOCK) */
		/* ON C.CONFIRM_ID = E.CONFIRM_ID */
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
			JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
				ON L.LOOKUP_TYPE = 'ERP_SSP_TYPE'  /* LOOKUP에 등록된 공정만 */
			AND L.VALID_YN = 'Y'
			AND L.SEGMENT1    = E.SSP_TYPE
		JOIN SCM_MST_SITE S
			ON E.FROM_SCM_SITE_ID	= S.SCM_SITE_ID
		   AND E.DIVISION_ID	= S.DIVISION_ID
		   AND S.SITE_TYPE		= 'PLANT'
		JOIN SCM_MST_ITEM_SN T
			ON E.ITEM_ID		= T.ITEM_ID
		   AND E.DIVISION_ID	= T.DIVISION_ID
		   AND S.COMPANY_ID		= T.COMPANY_ID
		   AND T.ITEM_TYPE		NOT IN ('Q','R')
		WHERE 1=1
		AND   NVL(E.EXFACTORY_STATUS,'D90') NOT IN ('D90' ,'D10')  /* D90: DO삭제 , D10:DO생성 */
		AND   E.CONFIRM_ID LIKE 'C%'
		AND   E.DIVISION_ID <> '40'  /* E20260211-001000 SSP ERP 출하실적 차이 수정. 소형제외 */
		/* AND   E.EXFACTORY_DATE BETWEEN @p_from_yyyymmdd  AND @p_to_yyyymmdd */

		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 : 페커 제외 */
        /* 2025-07-02 PACKER 추가 시작 */
	/* UNION ALL */
	/* SELECT S.DIVISION_ID     AS DIVISION_ID */
	/* ,NULL AS COMPANY_ID */
	/* ,NULL AS PLANT_ID */
	/* ,      S.ERP_SO_NO       AS ORDER_NO */
	/* , NULL AS DELIVERY_NO */
	/* , 0       AS DELIVERY_ITEM_SEQ */
	/* ,      S.ITEM_ID         AS ITEM_ID */
	/* , NULL          AS PROJECT_CODE */
	/* ,      S.FROM_SITE       AS FROM_SITE */
	/* ,      S.TO_SITE         AS TO_SITE */
	/* ,      S.YYYYMMDD        AS YYYYMMDD */
	/* ,      SUM(S.RESULT_QTY) AS RESULT_QTY */
	/* ,      S.SHIP_TO         AS SHIPTO_CODE */
	/* ,      S.TRANSPORT_MODE  AS TRANSPORT_MODE */
	/* ,      S.INCOTERMS       AS INCOTERMS */
	/* , CONFIRM_ID AS CONFIRM_ID */
	/* , '' AS FCST_TYPE */
	/* , '0' AS CURRENCY_CODE */
	/* ,NULL AS NET_PRICE */
	/* ,NULL AS SALES_AMOUNT */
	/* ,NULL AS KRW_XRATE */
	/* ,NULL AS SALES_KRW_AMOUNT */
	/* ,'' AS ORDER_TYPE_CODE */
	/* --,      NULL              AS END_CUSTOMER */
	/* --,      SUM(S.RESULT_QTY) AS QTY */
	/* --,      S.YYYYMMDD        AS YYYYMMDD */
	/* --,      S.TRANSPORT_MODE  AS TRANSPORT_MODE */
	/* --,      S.INCOTERMS       AS INCOTERMS */
	/* --,      S.ETD_DATE        AS ETD_DATE */
	/* --,      S.ETA_DATE        AS ETA_DATE */
	/* --,      NULL				 AS SHIP_TYPE */
	/* -- 20211126  SMS  추가 Ship to */
	/* --,      S.SHIP_TO         AS SHIP_TO */
	/* --============================================= */
	/* FROM  ( */

	/* -- SCS 출하실적에서 CONFIRM_ID 존재 */
	/* SELECT  E.DIVISION_ID             AS DIVISION_ID */
	/* ,       E.ATTRIBUTE5              AS CONFIRM_ID */
	/* ,       C.ERP_SO_NO				  AS ERP_SO_NO */
	/* ,       E.SHIP_DATE		          AS YYYYMMDD */
	/* ,       C.TRANSPORT_MODE		  AS TRANSPORT_MODE */
	/* ,       C.INCOTERMS				  AS INCOTERMS */
	/* ,		C.ETA_DATE				  AS ETA_DATE */
	/* ,		C.ETD_DATE				  AS ETD_DATE */
	/* ,       E.SCM_SITE_ID			  AS FROM_SITE */
	/* ,		E.TO_SITE				  AS TO_SITE */
	/* ,		E.ITEM_ID				  AS ITEM_ID */
	/* -- 20211126  SMS  추가  Ship to */
	/* ,		E.ATTRIBUTE4			  AS SHIP_TO */
	/* --====================================================== */
	/* ,       SUM(E.SHIP_QTY )		  AS RESULT_QTY */
	/* FROM SCM_DNM_SCS_SHIP_RESULT E WITH(NOLOCK) */
	/* LEFT OUTER JOIN SSP_ANL_SHIP_CONFIRM C WITH(NOLOCK) */
	/* ON E.DIVISION_ID = C.DIVISION_ID */
	/* AND E.ATTRIBUTE5 = C.CONFIRM_ID */
	/* WHERE 1=1 */
	/* AND E.DIVISION_ID = '40' */
	/* --AND   E.ATTRIBUTE5 LIKE 'R%' -- not to ESS DATA Duplicattion */
	/* --AND   E.SHIP_DATE BETWEEN @p_from_yyyymmdd  AND @p_to_yyyymmdd */

	/* GROUP BY E.DIVISION_ID */
	/* ,        E.ATTRIBUTE5 */
	/* ,        C.ERP_SO_NO */
	/* ,        E.SHIP_DATE */
	/* ,		 C.TRANSPORT_MODE */
	/* ,        C.INCOTERMS */
	/* ,		 C.ETA_DATE */
	/* ,        C.ETD_DATE */
	/* ,        E.SCM_SITE_ID */
	/* ,		 E.TO_SITE */
	/* ,		 E.ITEM_ID */
	/* -- 20211126  SMS  추가 */
	/* ,		 E.ATTRIBUTE4 */
	/* --================================ */

	/* ) S */
	/* --LEFT OUTER JOIN PLAN_SSP P */
	/* -- ON S.CONFIRM_ID = P.CONFIRM_ID */
	/* GROUP BY S.DIVISION_ID */
	/* ,		 S.ERP_SO_NO */
	/* ,        S.FROM_SITE */
	/* ,        S.TO_SITE */
	/* ,        S.ITEM_ID */
	/* ,		 S.TRANSPORT_MODE */
	/* ,		 S.INCOTERMS */
	/* ,		 S.ETD_DATE */
	/* ,		 S.ETA_DATE */
	/* ,        S.YYYYMMDD */
	/* ,        S.CONFIRM_ID */
	/* -- 20211126  SMS  추가 Ship to */
	/* ,        S.SHIP_TO */

		/* 2025-07-02 PACKER 추가 종료 */

		UNION ALL
		/* 소형제외, 컴펌아이디 없는 건 */
		SELECT  E.DIVISION_ID             AS DIVISION_ID
		,       E.COMPANY_ID              AS COMPANY_ID
		,       E.PLANT_ID                AS PLANT_ID
		,       E.ORDER_NO                AS ORDER_NO
		,       E.DELIVERY_NO             AS DELIVERY_NO
		,       E.DELIVERY_ITEM_SEQ       AS DELIVERY_ITEM_SEQ
        ,       E.ITEM_ID                 AS ITEM_ID
		,       CASE WHEN E.DIVISION_ID = '40' THEN '-'
		             ELSE NVL(E.PROJECT_CODE,'-') END     AS PROJET_CODE
		,       E.FROM_SCM_SITE_ID        AS FROM_SITE
		,       E.TO_SCM_SITE_ID          AS TO_SITE
		,       E.EXFACTORY_DATE          AS YYYYMMDD
		,       E.EXFACTORY_QTY           AS RESULT_QTY
		,       E.SHIPTO_CODE             AS SHIPTO_CODE
		,       E.TRANSPORT_MODE          AS TRANSPORT_MODE
		,       E.INCOTERMS               AS INCOTERMS
		,       E.CONFIRM_ID              AS CONFIRM_ID
		,       '-'                       AS FCST_TYPE
		,       E.CURRENCY_CODE
		,       E.NET_PRICE
		,       E.SALES_AMOUNT
		,       E.KRW_XRATE
		,       E.SALES_KRW_AMOUNT
		,       E.ORDER_TYPE_CODE AS ORDER_TYPE_CODE
		FROM SCM_DNM_EXFACTORY_RESULT E
		JOIN SCM_MST_SITE S
			ON E.FROM_SCM_SITE_ID	= S.SCM_SITE_ID
		   AND E.DIVISION_ID	= S.DIVISION_ID
		   AND S.SITE_TYPE		= 'PLANT'

		JOIN SCM_MST_ITEM_SN T
			ON E.ITEM_ID		= T.ITEM_ID
		   AND E.DIVISION_ID	= T.DIVISION_ID
		   AND S.COMPANY_ID		= T.COMPANY_ID
		   AND T.ITEM_TYPE		NOT IN ('Q','R')
		JOIN  SCP_MST_FINAL_ITEM F  /* SCP 대상 ITEM만 */
			ON F.ITEM_ID = E.ITEM_ID
			AND F.DIVISION_ID = E.DIVISION_ID
		LEFT JOIN   SCM_MST_SITE FS
			ON FS.SCM_SITE_ID = E.FROM_SCM_SITE_ID
			AND FS.DIVISION_ID = E.DIVISION_ID
			/* 2025-07-02 PACKER 제외 적용 */
			/* AND ISNULL(FS.OSP_YN,'N') <> 'Y' --- [C20200121-000352]-2 : FROM_SITE PACKER포함(OSP_YN <> 'Y' 조건제외) */
		/* 2020.09.18 김광희 책임 요청으로 주석처리 */
		/* 2021.04.15 김광희 책임 요청으로 주석해제 */
		JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
			ON L.LOOKUP_TYPE = 'ERP_ORDER_TYPE'  /* LOOKUP에 등록된 ORDER_TYPE만 대상으로 함 */
		AND L.VALID_YN = 'Y'
		AND L.SEGMENT1    = E.ORDER_TYPE_CODE
		LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L3
				ON L3.LOOKUP_TYPE = 'SHIP_RESULT_TO_SITE_MAPPING'  /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
			AND L3.SEGMENT1    = E.DIVISION_ID
			AND L3.SEGMENT2    = E.SOLDTO_CODE
			AND L3.SEGMENT3    = E.SHIPTO_CODE
		WHERE 1=1
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
		/* AND ISNULL(FS.OSP_YN,'N') ='Y' */
		AND NVL(FS.DIVISION_ID,' ') <> '40'  /* 소형제외 */
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
		AND   NVL(E.EXFACTORY_STATUS,'D90') NOT IN ('D90' ,'D10')  /* D90: DO삭제 , D10:DO생성 */
		AND   NVL(E.CONFIRM_ID,' ') NOT LIKE  'C%'
		/* AND   E.EXFACTORY_DATE BETWEEN  @p_from_yyyymmdd  AND @p_to_yyyymmdd */
		/* [C20210330-000402] */
		/* AND   E.FROM_SCM_SITE_ID IS NOT NULL */
		/* AND   E.TO_SCM_SITE_ID IS NOT NULL */
		AND   E.STORAGE_ID NOT IN ('6000' ,'799A')  /* 상품창고제외 */
		/* [C20200403-000062] */
		AND   E.STORAGE_ID NOT IN (SELECT SEGMENT1
								FROM SCM_ADM_LOOKUP_MASTER_DETAIL
								WHERE LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_STORAGE'
									AND VALID_YN = 'Y'
								)  /* 사외 창고 제외 LOOKUP 관리 */

		UNION ALL
		/* 소형 컴펌아이디 있는 부분 */
		SELECT  E.DIVISION_ID             AS DIVISION_ID
		,       E.COMPANY_ID              AS COMPANY_ID
		,       E.PLANT_ID                AS PLANT_ID
		,       E.ORDER_NO                AS ORDER_NO
		,       E.DELIVERY_NO             AS DELIVERY_NO
		,       E.DELIVERY_ITEM_SEQ       AS DELIVERY_ITEM_SEQ
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
        /* ,       C.ITEM_ID                 AS ITEM_ID */
		,       E.ITEM_ID                 AS ITEM_ID
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
		,       CASE WHEN E.DIVISION_ID = '40' THEN '-'
		             ELSE NVL(E.PROJECT_CODE,'-') END     AS PROJET_CODE
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
        /* ,       C.FROM_SITE               AS FROM_SITE */
        /* ,       C.TO_SITE                 AS TO_SITE */
		,       E.FROM_SCM_SITE_ID        AS FROM_SITE
		,       E.TO_SCM_SITE_ID          AS TO_SITE
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
		,       E.EXFACTORY_DATE          AS YYYYMMDD
		,       E.EXFACTORY_QTY           AS RESULT_QTY
		,       E.SHIPTO_CODE             AS SHIPTO_CODE
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
		/* ,       C.TRANSPORT_MODE          AS TRANSPORT_MODE */
		/* ,       C.INCOTERMS               AS INCOTERMS */
		,       E.TRANSPORT_MODE          AS TRANSPORT_MODE
		,       E.INCOTERMS               AS INCOTERMS
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
		,       E.CONFIRM_ID              AS CONFIRM_ID
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
		/* ,       C.FCST_TYPE               AS FCST_TYPE */
		,       '-'							AS FCST_TYPE
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
		,       E.CURRENCY_CODE
		,       E.NET_PRICE
		,       E.SALES_AMOUNT
		,       E.KRW_XRATE
		,       E.SALES_KRW_AMOUNT
		, E.ORDER_TYPE_CODE AS ORDER_TYPE_CODE
		FROM SCM_DNM_EXFACTORY_RESULT E
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
		/* JOIN SSP_ANL_SHIP_CONFIRM C WITH(NOLOCK) */
		/* ON C.CONFIRM_ID = E.CONFIRM_ID */
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
			JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
				ON L.LOOKUP_TYPE = 'ERP_SSP_TYPE'  /* LOOKUP에 등록된 공정만 */
			AND L.VALID_YN = 'Y'
			AND L.SEGMENT1    = E.SSP_TYPE
		WHERE 1=1
		AND   NVL(E.EXFACTORY_STATUS,'D90') NOT IN ('D90' ,'D10')  /* D90: DO삭제 , D10:DO생성 */
		AND   E.CONFIRM_ID LIKE 'C%'
		AND   E.DIVISION_ID = '40'
		/* AND   E.EXFACTORY_DATE BETWEEN @p_from_yyyymmdd  AND @p_to_yyyymmdd */

		UNION ALL
		/* 소형 컴펌아이디 없는 부분 */
		SELECT  E.DIVISION_ID             AS DIVISION_ID
		,       E.COMPANY_ID              AS COMPANY_ID
		,       E.PLANT_ID                AS PLANT_ID
		,       E.ORDER_NO                AS ORDER_NO
		,       E.DELIVERY_NO             AS DELIVERY_NO
		,       E.DELIVERY_ITEM_SEQ       AS DELIVERY_ITEM_SEQ
        ,       E.ITEM_ID                 AS ITEM_ID
		,       CASE WHEN E.DIVISION_ID = '40' THEN '-'
		             ELSE NVL(E.PROJECT_CODE,'-') END     AS PROJET_CODE
		,       E.FROM_SCM_SITE_ID        AS FROM_SITE
		,       E.TO_SCM_SITE_ID          AS TO_SITE
		,       E.EXFACTORY_DATE          AS YYYYMMDD
		,       E.EXFACTORY_QTY           AS RESULT_QTY
		,       E.SHIPTO_CODE             AS SHIPTO_CODE
		,       E.TRANSPORT_MODE          AS TRANSPORT_MODE
		,       E.INCOTERMS               AS INCOTERMS
		,       E.CONFIRM_ID              AS CONFIRM_ID
		,       '-'                       AS FCST_TYPE
		,       E.CURRENCY_CODE
		,       E.NET_PRICE
		,       E.SALES_AMOUNT
		,       E.KRW_XRATE
		,       E.SALES_KRW_AMOUNT
		,       E.ORDER_TYPE_CODE AS ORDER_TYPE_CODE
		FROM SCM_DNM_EXFACTORY_RESULT E
		JOIN  SCP_MST_FINAL_ITEM F  /* SCP 대상 ITEM만 */
			ON F.ITEM_ID = E.ITEM_ID
			AND F.DIVISION_ID = E.DIVISION_ID
		LEFT JOIN   SCM_MST_SITE FS
			ON FS.SCM_SITE_ID = E.FROM_SCM_SITE_ID
			AND FS.DIVISION_ID = E.DIVISION_ID
			/* 2025-07-02 PACKER 제외 적용 */
			/* AND ISNULL(FS.OSP_YN,'N') <> 'Y' --- [C20200121-000352]-2 : FROM_SITE PACKER포함(OSP_YN <> 'Y' 조건제외) */
		/* 2020.09.18 김광희 책임 요청으로 주석처리 */
		/* 2021.04.15 김광희 책임 요청으로 주석해제 */
		JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
			ON L.LOOKUP_TYPE = 'ERP_ORDER_TYPE'  /* LOOKUP에 등록된 ORDER_TYPE만 대상으로 함 */
		AND L.VALID_YN = 'Y'
		AND L.SEGMENT1    = E.ORDER_TYPE_CODE
		LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L3
				ON L3.LOOKUP_TYPE = 'SHIP_RESULT_TO_SITE_MAPPING'  /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
			AND L3.SEGMENT1    = E.DIVISION_ID
			AND L3.SEGMENT2    = E.SOLDTO_CODE
			AND L3.SEGMENT3    = E.SHIPTO_CODE
		WHERE 1=1
		/* START E20260211-001000 SSP ERP 출하실적 차이 수정 */
		/* AND ISNULL(FS.OSP_YN,'N') ='Y' */
		AND NVL(FS.DIVISION_ID,' ') = '40'
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */
		AND   NVL(E.EXFACTORY_STATUS,'D90') NOT IN ('D90' ,'D10')  /* D90: DO삭제 , D10:DO생성 */
		AND   NVL(E.CONFIRM_ID,' ') NOT LIKE  'C%'
		/* AND   E.EXFACTORY_DATE BETWEEN  @p_from_yyyymmdd  AND @p_to_yyyymmdd */
		/* [C20210330-000402] */
		/* AND   E.FROM_SCM_SITE_ID IS NOT NULL */
		/* AND   E.TO_SCM_SITE_ID IS NOT NULL */
		/* AND   E.STORAGE_ID NOT IN ('6000' ,'799A') --상품창고제외 */
		/* [C20200403-000062] */
		AND   E.STORAGE_ID NOT IN (SELECT SEGMENT1
								FROM SCM_ADM_LOOKUP_MASTER_DETAIL
								WHERE LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_STORAGE'
									AND VALID_YN = 'Y'
								)  /* 사외 창고 제외 LOOKUP 관리 */
		/* END E20260211-001000 SSP ERP 출하실적 차이 수정 */

       ) X
       JOIN SCM_MST_DIVISION D
    ON X.DIVISION_ID = D.DIVISION_ID
